async def send_v3_entry_alert(setup_data: dict, current_price: float = 0) -> bool:
    """
    Send Telegram alert for V3 ENTRY_READY signal.
    
    ONLY sends alerts when:
    - V3 signal phase = ENTRY_READY
    - Setup has not already been alerted (deduplication)
    
    Does NOT send alerts for:
    - NO_TRADE, WATCH, SETUP_DETECTED, WAITING_FOR_RETEST
    
    Args:
        setup_data: V3 setup dictionary with all signal details
        current_price: Current BTC price
        
    Returns:
        True if alert sent successfully, False otherwise
    """
    global v3_alerts_sent
    
    try:
        setup_id = setup_data.get("setup_id")
        phase = setup_data.get("phase")
        
        # CRITICAL: Only send for ENTRY_READY phase
        if phase != "ENTRY_READY":
            logger.debug(f"[V3 Alert] Skipping - phase is {phase}, not ENTRY_READY")
            return False
        
        # Check if V3 notifications are enabled in settings
        tg_settings = await get_telegram_settings()
        if tg_settings and not tg_settings.get("notify_v3_entry_ready", True):
            logger.debug("[V3 Alert] Skipping - V3 notifications disabled in settings")
            return False
        
        # Deduplication: Check if already alerted for this setup
        if setup_id and setup_id in v3_alerts_sent:
            time_since_alert = (datetime.now(timezone.utc) - v3_alerts_sent[setup_id]).seconds
            if time_since_alert < 3600:  # Don't repeat within 1 hour
                logger.debug(f"[V3 Alert] Skipping - already sent for setup {setup_id[:8]} ({time_since_alert}s ago)")
                return False
        
        direction = setup_data.get("direction", "")
        if direction not in ["LONG", "SHORT"]:
            logger.debug(f"[V3 Alert] Skipping - invalid direction: {direction}")
            return False
        
        # Calculate risk level based on quality score and R:R
        quality = setup_data.get("quality_score", 50)
        rr = setup_data.get("risk_reward_ratio", 1.0)
        
        if quality >= 80 and rr >= 1.5:
            risk_level = "LOW"
        elif quality >= 60 and rr >= 1.2:
            risk_level = "MEDIUM"
        else:
            risk_level = "HIGH"
        
        # Format confirmation type
        confirmation = setup_data.get("confirmation_type", "unknown")
        confirmation_labels = {
            "rejection_candle": "Rejection Candle",
            "stabilization": "Stabilization",
            "micro_structure_break": "Micro-Break"
        }
        confirmation_display = confirmation_labels.get(confirmation, confirmation.replace("_", " ").title())
        
        # Format setup type
        event_type = setup_data.get("event_type", "unknown")
        setup_labels = {
            "resistance_breakout": "Resistance Breakout",
            "support_breakout": "Support Breakout",
            "liquidity_sweep_high": "Sweep High",
            "liquidity_sweep_low": "Sweep Low",
            "trend_continuation": "Trend Continuation"
        }
        setup_display = setup_labels.get(event_type, event_type.replace("_", " ").title())
        
        # Prepare data for template
        data = {
            "direction": direction,
            "direction_emoji": "📈" if direction == "LONG" else "📉",
            "price": current_price or setup_data.get("entry_price", 0),
            "entry_low": setup_data.get("zone_low", 0),
            "entry_high": setup_data.get("zone_high", 0),
            "stop_loss": setup_data.get("stop_loss", 0),
            "stop_type": setup_data.get("stop_type", "structure").title(),
            "target_1": setup_data.get("target_1", 0),
            "target_2": setup_data.get("target_2", 0),
            "confidence": setup_data.get("confidence", quality),  # Use quality as confidence proxy
            "risk_level": risk_level,
            "rr": rr,
            "quality": quality,
            "setup_type": setup_display,
            "regime": setup_data.get("market_regime", "UNKNOWN"),
            "confirmation": confirmation_display
        }
        
        # Send notification
        success = await send_telegram_notification("v3_entry_ready", data)
        
        if success and setup_id:
            # Track successful send for deduplication
            v3_alerts_sent[setup_id] = datetime.now(timezone.utc)
            logger.info(f"[V3 Alert] ENTRY_READY alert sent for setup {setup_id[:8]} - {direction}")
            
            # Cleanup old entries (keep only last 50)
            if len(v3_alerts_sent) > 50:
                sorted_alerts = sorted(v3_alerts_sent.items(), key=lambda x: x[1], reverse=True)
                v3_alerts_sent = dict(sorted_alerts[:50])
        
        return success
        
    except Exception as e:
        logger.error(f"[V3 Alert] Error sending alert: {e}")
        return False


# V3 Signal History Tracking - Deduplication
v3_signals_recorded = {}  # {setup_id: signal_id}


async def record_v3_entry_signal(setup_data: dict, current_price: float, market_context: dict = None) -> dict:
    """
    Record a V3 ENTRY_READY signal to the main signal_history collection.
    
    CRITICAL FIX: Now includes:
    1. Hash-based deduplication (blocks same setup within 10 minutes)
    2. Automatic shadow outcome tracking registration
    
    This ensures V3 signals:
    - Are tracked in the same collection as V2 signals
    - Are NOT duplicated within the dedup window
    - Are automatically tracked for outcome detection
    - Appear in performance statistics
    
    Args:
        setup_data: V3 setup dictionary with all signal details
        current_price: Current BTC price
        market_context: Additional market context (regime, bias, etc.)
        
    Returns:
        Dict with recording result
    """
    global v3_signals_recorded
    
    try:
        setup_id = setup_data.get("setup_id")
        phase = setup_data.get("phase")
        
        # Only record ENTRY_READY signals
        if phase != "ENTRY_READY":
            return {"recorded": False, "reason": f"Phase is {phase}, not ENTRY_READY"}
        
        direction = setup_data.get("direction", "")
        if direction not in ["LONG", "SHORT"]:
            return {"recorded": False, "reason": f"Invalid direction: {direction}"}
        
        # Extract signal parameters for hash
        entry_zone_low = setup_data.get("zone_low", 0)
        entry_zone_high = setup_data.get("zone_high", 0)
        stop_loss = setup_data.get("stop_loss", 0)
        event_type = setup_data.get("event_type", "unknown")
        target_1 = setup_data.get("target_1", 0)
        target_2 = setup_data.get("target_2", 0)
        
        # ═══════════════════════════════════════════════════════════════════
        # HASH-BASED DEDUPLICATION CHECK
        # ═══════════════════════════════════════════════════════════════════
        signal_hash = generate_signal_hash(direction, entry_zone_low, entry_zone_high, stop_loss, event_type)
        
        if is_duplicate_signal(signal_hash):
            logger.warning(f"[V3 Signal] BLOCKED - Duplicate signal detected: {direction} hash={signal_hash[:8]}")
            return {"recorded": False, "reason": "DUPLICATE_BLOCKED", "signal_hash": signal_hash}
        
        # Legacy setup_id deduplication (backup check)
        if setup_id and setup_id in v3_signals_recorded:
            logger.warning(f"[V3 Signal] BLOCKED - Already recorded for setup {setup_id[:8]}")
            return {"recorded": False, "reason": "Already recorded", "signal_id": v3_signals_recorded[setup_id]}
        
        # ═══════════════════════════════════════════════════════════════════
        # SAME-DIRECTION SIGNAL LOCK CHECK
        # Execution constraint: Cannot have multiple OPEN signals in same direction
        # 
        # OPEN statuses (trade still active, blocks new signals):
        #   - ENTRY_READY, ACTIVE, PENDING, T1_HIT_WAITING_T2, PARTIAL_WIN
        # 
        # CLOSED statuses (trade complete, unlocks direction):
        #   - WIN, LOSS, EXPIRED, CANCELLED, FULL_WIN
        #
        # NOTE: PARTIAL_WIN = T1 hit but still holding for T2 = STILL OPEN
        # ═══════════════════════════════════════════════════════════════════
        OPEN_SIGNAL_STATUSES = ["ENTRY_READY", "ACTIVE", "PENDING", "T1_HIT_WAITING_T2", "PARTIAL_WIN"]
        
        # Check if there's an existing OPEN signal in the same direction
        existing_open_signal = await signal_history_collection.find_one({
            "signal_engine_version": "v3",
            "direction": direction,
            "outcome": {"$in": OPEN_SIGNAL_STATUSES}
        }, sort=[("timestamp", -1)])
        
        if existing_open_signal:
            existing_signal_id = existing_open_signal.get("signal_id", "unknown")[:8]
            existing_outcome = existing_open_signal.get("outcome", "UNKNOWN")
            existing_timestamp = existing_open_signal.get("timestamp", "N/A")
            
            logger.warning(
                f"[V3 Signal] 🔒 SAME_DIRECTION_LOCKED - {direction} signal blocked. "
                f"Previous signal still open: {existing_signal_id} (status={existing_outcome}, created={existing_timestamp})"
            )
            
            return {
                "recorded": False, 
                "reason": "SAME_DIRECTION_LOCKED",
                "blocked_direction": direction,
                "existing_signal_id": existing_open_signal.get("signal_id"),
                "existing_status": existing_outcome,
                "existing_timestamp": str(existing_timestamp),
                "message": f"Cannot create {direction} signal - previous {direction} signal still open (status: {existing_outcome})"
            }
        
        # ═══════════════════════════════════════════════════════════════════
        # V3.4 CRITICAL VALIDATION - LAST DEFENSIVE LAYER
        # This is the final safeguard before signal recording.
        # Even if upstream validation fails, this MUST block invalid signals.
        # 
        # V3.5 CONTRARIAN: If blocked, evaluate contrarian opportunity
        # ═══════════════════════════════════════════════════════════════════
        
        # Helper function to handle block and check contrarian
        async def handle_block_with_contrarian(block_reason: str, block_details: dict) -> dict:
            """
            Handle a V3.4 block and evaluate V3.5 contrarian opportunity.
            Returns block result with optional contrarian signal.
            """
            # Evaluate V3.5 contrarian opportunity
            contrarian_result = await evaluate_v3_5_contrarian_opportunity(
                blocked_direction=direction,
                block_reason=block_reason,
                current_price=current_price,
                setup_data=setup_data,
                market_context=market_context
            )
            
            if contrarian_result:
                # Record contrarian signal
                record_result = await record_v3_5_contrarian_signal(
                    contrarian_data=contrarian_result,
                    setup_data=setup_data,
                    current_price=current_price
                )
                
                # Return block result with contrarian info
                block_details["contrarian_generated"] = True
                block_details["contrarian_signal"] = contrarian_result
                block_details["contrarian_recorded"] = record_result.get("recorded", False)
                block_details["contrarian_signal_id"] = record_result.get("signal_id")
                
                logger.info(f"[V3.5 Contrarian] Generated {contrarian_result.get('contrarian_direction')} "
                           f"from blocked {direction}")
            else:
                block_details["contrarian_generated"] = False
                block_details["contrarian_reason"] = "Conditions not met for contrarian signal"
            
            return block_details
        
        # 1. CHECK: Upstream block reason (from create_setup_event)
        target_block_reason = setup_data.get("target_block_reason")
        if target_block_reason:
            logger.warning(f"[V3 Signal] ❌ BLOCKED_SIGNAL - Upstream block: {target_block_reason}")
            block_result = {
                "recorded": False,
                "reason": f"BLOCKED_UPSTREAM_{target_block_reason}",
                "block_source": "create_setup_event",
                "message": f"Signal blocked due to: {target_block_reason}"
            }
            return await handle_block_with_contrarian(block_result["reason"], block_result)
        
        # 2. CHECK: R:R Minimum (HARD BLOCK: R:R < 0.5)
        MIN_RR_THRESHOLD = 0.5
        risk_reward_ratio = setup_data.get("risk_reward_ratio", 0)
        if risk_reward_ratio < MIN_RR_THRESHOLD:
            logger.warning(f"[V3 Signal] ❌ BLOCKED_SIGNAL - LOW_RR: {risk_reward_ratio:.2f} < {MIN_RR_THRESHOLD}")
            block_result = {
                "recorded": False,
                "reason": f"BLOCKED_LOW_RR_{risk_reward_ratio:.2f}",
                "block_source": "record_v3_entry_signal",
                "rr_ratio": risk_reward_ratio,
                "min_required": MIN_RR_THRESHOLD,
                "message": f"R:R {risk_reward_ratio:.2f} below minimum {MIN_RR_THRESHOLD}"
            }
            # LOW_RR is not eligible for contrarian (not a directional conflict)
            block_result["contrarian_generated"] = False
            block_result["contrarian_reason"] = "LOW_RR blocks are not eligible for contrarian signals"
            return block_result
        
        # 3. CHECK: Magnet Direction Conflict
        # If magnet points UP, don't SHORT. If magnet points DOWN, don't LONG.
        magnet_direction = market_context.get("magnet_direction") if market_context else None
        if magnet_direction and magnet_direction not in ["BALANCED", "NONE", None]:
            signal_wants_up = direction == "LONG"
            magnet_points_up = magnet_direction == "UP"
            
            if signal_wants_up != magnet_points_up:
                logger.warning(f"[V3 Signal] ❌ BLOCKED_SIGNAL - MAGNET_CONFLICT: {direction} vs magnet {magnet_direction}")
                block_result = {
                    "recorded": False,
                    "reason": f"BLOCKED_MAGNET_CONFLICT_{direction}_vs_{magnet_direction}",
                    "block_source": "record_v3_entry_signal",
                    "signal_direction": direction,
                    "magnet_direction": magnet_direction,
                    "message": f"Cannot {direction} when liquidity magnet points {magnet_direction}"
                }
                return await handle_block_with_contrarian(block_result["reason"], block_result)
        
        # 4. CHECK: Squeeze Risk (Funding + Positioning overcrowding)
        # Block same-direction trades when that side is overcrowded
        derivatives_context = market_context.get("derivatives_context") if market_context else None
        if derivatives_context and derivatives_context.get("data_available"):
            ls_ratio = derivatives_context.get("long_short_ratio", {})
            funding_rate = derivatives_context.get("funding_rate")
            
            if ls_ratio:
                global_ratio = ls_ratio.get("global_ratio", 1.0)
                
                # Shorts overcrowded: global_ratio > 1.5 (more shorts than longs)
                # Longs overcrowded: global_ratio < 0.67 (more longs than shorts)
                shorts_overcrowded = global_ratio > 1.5
                longs_overcrowded = global_ratio < 0.67
                
                # Extreme funding indicates overcrowding
                extreme_negative_funding = funding_rate is not None and funding_rate < -0.05
                extreme_positive_funding = funding_rate is not None and funding_rate > 0.05
                
                if direction == "SHORT" and (shorts_overcrowded or extreme_negative_funding):
                    squeeze_detail = f"ratio={global_ratio:.2f}" if shorts_overcrowded else f"funding={funding_rate:.4f}"
                    logger.warning(f"[V3 Signal] ❌ BLOCKED_SIGNAL - SQUEEZE_RISK: SHORT but shorts overcrowded ({squeeze_detail})")
                    block_result = {
                        "recorded": False,
                        "reason": f"BLOCKED_SQUEEZE_RISK_SHORTS_OVERCROWDED",
                        "block_source": "record_v3_entry_signal",
                        "direction": direction,
                        "global_ratio": global_ratio,
                        "funding_rate": funding_rate,
                        "message": f"Cannot SHORT when shorts are overcrowded ({squeeze_detail}) - squeeze risk"
                    }
                    return await handle_block_with_contrarian(block_result["reason"], block_result)
                
                elif direction == "LONG" and (longs_overcrowded or extreme_positive_funding):
                    squeeze_detail = f"ratio={global_ratio:.2f}" if longs_overcrowded else f"funding={funding_rate:.4f}"
                    logger.warning(f"[V3 Signal] ❌ BLOCKED_SIGNAL - SQUEEZE_RISK: LONG but longs overcrowded ({squeeze_detail})")
                    block_result = {
                        "recorded": False,
                        "reason": f"BLOCKED_SQUEEZE_RISK_LONGS_OVERCROWDED",
                        "block_source": "record_v3_entry_signal",
                        "direction": direction,
                        "global_ratio": global_ratio,
                        "funding_rate": funding_rate,
                        "message": f"Cannot LONG when longs are overcrowded ({squeeze_detail}) - squeeze risk"
                    }
                    return await handle_block_with_contrarian(block_result["reason"], block_result)
        
        # 5. CHECK: Has Valid Targets
        has_valid_targets = setup_data.get("has_valid_targets", True)
        if not has_valid_targets:
            logger.warning(f"[V3 Signal] ❌ BLOCKED_SIGNAL - NO_VALID_TARGETS")
            block_result = {
                "recorded": False,
                "reason": "BLOCKED_NO_VALID_TARGETS",
                "block_source": "record_v3_entry_signal",
                "message": "No valid liquidity cluster targets found"
            }
            # NO_VALID_TARGETS is not eligible for contrarian
            block_result["contrarian_generated"] = False
            block_result["contrarian_reason"] = "No targets available for contrarian evaluation"
            return block_result
        
        # ═══════════════════════════════════════════════════════════════════
        # V3.4 VALIDATION PASSED - Signal is valid for recording
        # ═══════════════════════════════════════════════════════════════════
        logger.info(f"[V3 Signal] ✅ V3.4 Validation PASSED: {direction}, R:R={risk_reward_ratio:.2f}")
        
        # Generate signal ID
        signal_id = str(uuid.uuid4())
        
        # Calculate validity based on event type
        validity_hours = 8 if event_type in ["liquidity_sweep_high", "liquidity_sweep_low"] else 12
        
        # Build comprehensive history entry matching V2 format
        history_entry = {
            "signal_id": signal_id,
            "signal_hash": signal_hash,  # NEW: Store hash for future reference
            "timestamp": datetime.now(timezone.utc),
            "direction": direction,
            "confidence": setup_data.get("quality_score", 50),  # Use quality as confidence
            "estimated_move": 0.5,  # Default, could be calculated
            "entry_zone_low": entry_zone_low,
            "entry_zone_high": entry_zone_high,
            "stop_loss": stop_loss,
            "target_1": target_1,
            "target_2": target_2,
            "risk_reward_ratio": setup_data.get("risk_reward_ratio", 1.0),
            "setup_type": event_type,
            "signal_engine_version": "v3",
            "timeframe": "4H+5M",  # Multi-timeframe
            "btc_price": current_price,
            
            # V3-specific fields
            "v3_setup_id": setup_id,
            "v3_confirmation_type": setup_data.get("confirmation_type"),
            "v3_stop_type": setup_data.get("stop_type"),
            "v3_target_1_type": setup_data.get("target_1_type"),
            "v3_target_2_type": setup_data.get("target_2_type"),
            "v3_swing_high": setup_data.get("swing_high"),
            "v3_swing_low": setup_data.get("swing_low"),
            
            # Market context snapshot
            "market_bias": market_context.get("market_bias") if market_context else None,
            "whale_direction": market_context.get("whale_direction") if market_context else None,
            "whale_strength": market_context.get("whale_strength") if market_context else None,
            "liquidity_direction": market_context.get("liquidity_direction") if market_context else None,
            "magnet_direction": market_context.get("magnet_direction") if market_context else None,
            "magnet_score": market_context.get("magnet_score") if market_context else None,
            "energy_score": market_context.get("energy_score") if market_context else None,
            "compression_level": market_context.get("compression_level") if market_context else None,
            "market_regime": setup_data.get("market_regime"),
            
            "warnings": [],
            "reasoning_summary": setup_data.get("reasoning", "V3 ENTRY_READY signal"),
            "signal_state": "OPERATIONAL",
            
            # Outcome tracking fields - initialized for V3
            "outcome": "PENDING",
            "outcome_timestamp": None,
            "outcome_price": None,
            "pnl_percent": None,
            "target_1_hit": False,
            "target_2_hit": False,
            "stop_hit": False,
            "validity_hours": validity_hours,
            "price_at_check": None,
            "outcome_notes": "",
            "shadow_tracked": True  # NEW: Mark as shadow tracked
        }
        
        # Insert into signal history
        await signal_history_collection.insert_one(history_entry)
        
        # Register signal hash in dedup cache
        register_signal_hash(signal_hash, signal_id, direction)
        
        # Track for legacy deduplication
        v3_signals_recorded[setup_id] = signal_id
        
        # Cleanup old entries (keep only last 100)
        if len(v3_signals_recorded) > 100:
            v3_signals_recorded = dict(list(v3_signals_recorded.items())[-100:])
        
        logger.info(f"[V3 Signal] ✅ Recorded ENTRY_READY signal {signal_id[:8]} hash={signal_hash[:8]} - {direction}")
        
        # ═══════════════════════════════════════════════════════════════════
        # SHADOW OUTCOME TRACKING - Register for real-time monitoring
        # This ensures every signal is tracked until outcome is determined
        # ═══════════════════════════════════════════════════════════════════
        try:
            await register_signal_for_shadow_tracking(
                signal_id=signal_id,
                direction=direction,
                entry_price=current_price,
                stop_loss=stop_loss,
                target_1=target_1,
                target_2=target_2,
                created_at=datetime.now(timezone.utc)
            )
            logger.info(f"[V3 Signal] Registered {signal_id[:8]} for shadow outcome tracking")
        except Exception as track_err:
            logger.error(f"[V3 Signal] Error registering for tracking: {track_err}")
        
        # ═══════════════════════════════════════════════════════════════════
        # SHADOW LIQUIDITY TARGET ENGINE - Calculate in parallel (non-blocking)
        # This does NOT affect the live signal - purely for data collection
        # ═══════════════════════════════════════════════════════════════════
        try:
            asyncio.create_task(_calculate_and_store_shadow_targets(
                signal_id=signal_id,
                direction=direction,
                entry_price=current_price,
                standard_targets={
                    "target_1": target_1,
                    "target_2": target_2,
                    "target_1_type": setup_data.get("target_1_type"),
                    "target_2_type": setup_data.get("target_2_type"),
                    "stop_loss": stop_loss
                },
                market_context=market_context
            ))
            logger.debug(f"[Shadow Liquidity] Queued shadow target calculation for {signal_id[:8]}")
        except Exception as shadow_err:
            logger.debug(f"[Shadow Liquidity] Non-critical error queuing shadow calc: {shadow_err}")
        
        # ═══════════════════════════════════════════════════════════════════
        # SHADOW VALIDATION ENGINE - Full signal analysis (non-blocking)
        # Evaluates R:R, conflicts, quality classification WITHOUT affecting live
        # ═══════════════════════════════════════════════════════════════════
        try:
            asyncio.create_task(_perform_full_shadow_validation(
                signal_id=signal_id,
                setup_data=setup_data,
                current_price=current_price,
                market_context=market_context
            ))
            logger.debug(f"[Shadow Validation] Queued validation for {signal_id[:8]}")
        except Exception as val_err:
            logger.debug(f"[Shadow Validation] Non-critical error queuing validation: {val_err}")
        
        # ═══════════════════════════════════════════════════════════════════
        # V3 CLUSTER TARGET VALIDATION ENGINE - Track cluster-based targets
        # Specifically validates the NEW cluster target system performance
        # ═══════════════════════════════════════════════════════════════════
        try:
            # Determine if signal is operational (has valid clusters)
            has_valid_targets = setup_data.get("has_valid_targets", True)
            block_reason = setup_data.get("target_block_reason")
            
            # Get cluster metadata
            t1_cluster = setup_data.get("target_1_cluster")
            t2_cluster = setup_data.get("target_2_cluster")
            
            # Calculate R:R at creation
            risk = abs(current_price - stop_loss) if stop_loss else 0
            reward = abs(target_1 - current_price) if target_1 else 0
            rr_at_creation = reward / risk if risk > 0 else 0
            
            await register_cluster_target_signal(
                signal_id=signal_id,
                direction=direction,
                entry_price=current_price,
                stop_loss=stop_loss,
                target_1=target_1,
                target_2=target_2,
                target_1_cluster=t1_cluster,
                target_2_cluster=t2_cluster,
                rr_at_creation=round(rr_at_creation, 2),
                is_operational=has_valid_targets and not block_reason,
                block_reason=block_reason,
                created_at=datetime.now(timezone.utc)
            )
            logger.info(f"[Cluster Validate] Registered {signal_id[:8]} for cluster target validation "
                       f"(operational={has_valid_targets}, R:R={rr_at_creation:.2f})")
        except Exception as cluster_err:
            logger.error(f"[Cluster Validate] Error registering for validation: {cluster_err}")
        
        return {
            "recorded": True, 
            "signal_id": signal_id,
            "signal_hash": signal_hash,
            "setup_id": setup_id,
            "direction": direction,
            "engine": "v3",
            "shadow_tracking": True,
            "cluster_validation": True
        }
        
    except Exception as e:
        logger.error(f"[V3 Signal] Error recording signal: {e}")
        return {"recorded": False, "error": str(e)}


