# ============== ANALYSIS ENGINES ==============

def calculate_support_resistance_enhanced(candles: List[dict], current_price: float, aggregated_orderbook: dict = None) -> List[SupportResistanceLevel]:
    """
    Calculate support and resistance levels from 4H price data and aggregated multi-exchange order book.
    Enhanced with exchange information and detailed explanations.
    
    FILTERING RULES (for 4H BTC trading):
    - Minimum distance between levels: 0.3% ($210+ at $70k)
    - Levels within 0.3% are merged, keeping the strongest
    - Maximum 8 levels returned (4 support, 4 resistance ideally)
    """
    if not candles or len(candles) < 20:
        return []
    
    MIN_LEVEL_DISTANCE_PCT = 0.3  # Minimum 0.3% between levels for meaningful 4H trading
    
    levels = []
    highs = [c["high"] for c in candles]
    lows = [c["low"] for c in candles]
    
    # Find recent highs (potential resistance) using pivot detection
    for i in range(2, len(highs) - 2):
        if highs[i] > highs[i-1] and highs[i] > highs[i-2] and highs[i] > highs[i+1] and highs[i] > highs[i+2]:
            distance = ((highs[i] - current_price) / current_price) * 100
            touches = sum(1 for h in highs if abs(h - highs[i]) / highs[i] < 0.005)
            strength = "strong" if touches >= 3 else "moderate" if touches >= 2 else "weak"
            
            explanation = f"Prezzo respinto a ${highs[i]:,.0f} in {touches} occasioni. "
            if strength == "strong":
                explanation += "Alta probabilità di rigetto se testato di nuovo."
            elif strength == "moderate":
                explanation += "Probabile pressione di vendita a questo livello."
            else:
                explanation += "Potrebbe cedere con forte momentum."
            
            levels.append(SupportResistanceLevel(
                price=round(highs[i], 2),
                level_type="resistance",
                strength=strength,
                timeframe="4H",  # Fixed: Now correctly labeled as 4H
                distance_percent=round(distance, 2),
                explanation=explanation
            ))
    
    # Find recent lows (potential support) using pivot detection
    for i in range(2, len(lows) - 2):
        if lows[i] < lows[i-1] and lows[i] < lows[i-2] and lows[i] < lows[i+1] and lows[i] < lows[i+2]:
            distance = ((lows[i] - current_price) / current_price) * 100
            touches = sum(1 for l in lows if abs(l - lows[i]) / lows[i] < 0.005)
            strength = "strong" if touches >= 3 else "moderate" if touches >= 2 else "weak"
            
            explanation = f"I compratori sono intervenuti a ${lows[i]:,.0f} in {touches} occasioni. "
            if strength == "strong":
                explanation += "Zona di domanda forte - alta probabilità di rimbalzo."
            elif strength == "moderate":
                explanation += "Probabile interesse d'acquisto a questo livello."
            else:
                explanation += "Potrebbe cedere con forte pressione di vendita."
            
            levels.append(SupportResistanceLevel(
                price=round(lows[i], 2),
                level_type="support",
                strength=strength,
                timeframe="4H",  # Fixed: Now correctly labeled as 4H
                distance_percent=round(distance, 2),
                explanation=explanation
            ))
    
    # Add order book walls as S/R levels (with multi-exchange info)
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        exchange_stats = aggregated_orderbook.get("exchange_stats", {})
        active_exchanges = list(exchange_stats.keys())
        
        # Find significant bid walls (support)
        bid_volumes = [(float(b[0]), float(b[1])) for b in bids[:50]]
        if bid_volumes:
            avg_bid_vol = sum(v[1] for v in bid_volumes) / len(bid_volumes)
            for price, vol in bid_volumes:
                if vol > avg_bid_vol * 2.5:  # Significant wall
                    distance = ((price - current_price) / current_price) * 100
                    strength = "strong" if vol > avg_bid_vol * 4 else "moderate"
                    volume_btc = vol
                    volume_usd = price * vol
                    
                    explanation = f"${volume_usd:,.0f} ({volume_btc:.2f} BTC) in ordini di acquisto su {len(active_exchanges)} exchange. "
                    if strength == "strong":
                        explanation += "Muro di supporto importante - difficile da rompere."
                    else:
                        explanation += "Interesse d'acquisto moderato a questo livello."
                    
                    levels.append(SupportResistanceLevel(
                        price=round(price, 2),
                        level_type="support",
                        strength=strength,
                        timeframe="Multi-Exchange",
                        distance_percent=round(distance, 2),
                        exchanges=active_exchanges,
                        volume_at_level=round(volume_usd, 0),
                        explanation=explanation
                    ))
        
        # Find significant ask walls (resistance)
        ask_volumes = [(float(a[0]), float(a[1])) for a in asks[:50]]
        if ask_volumes:
            avg_ask_vol = sum(v[1] for v in ask_volumes) / len(ask_volumes)
            for price, vol in ask_volumes:
                if vol > avg_ask_vol * 2.5:
                    distance = ((price - current_price) / current_price) * 100
                    strength = "strong" if vol > avg_ask_vol * 4 else "moderate"
                    volume_btc = vol
                    volume_usd = price * vol
                    
                    explanation = f"${volume_usd:,.0f} ({volume_btc:.2f} BTC) in ordini di vendita su {len(active_exchanges)} exchange. "
                    if strength == "strong":
                        explanation += "Muro di resistenza importante - attendersi forte vendita qui."
                    else:
                        explanation += "Pressione di vendita moderata a questo livello."
                    
                    levels.append(SupportResistanceLevel(
                        price=round(price, 2),
                        level_type="resistance",
                        strength=strength,
                        timeframe="Multi-Exchange",
                        distance_percent=round(distance, 2),
                        exchanges=active_exchanges,
                        volume_at_level=round(volume_usd, 0),
                        explanation=explanation
                    ))
    
    # IMPROVED FILTERING: Merge levels that are too close together (within MIN_LEVEL_DISTANCE_PCT)
    # Sort by price for merging
    levels_sorted = sorted(levels, key=lambda x: x.price)
    
    merged_levels = []
    for level in levels_sorted:
        if not merged_levels:
            merged_levels.append(level)
            continue
        
        last_level = merged_levels[-1]
        distance_between = abs(level.price - last_level.price) / last_level.price * 100
        
        if distance_between < MIN_LEVEL_DISTANCE_PCT:
            # Levels too close - keep the stronger one
            strength_rank = {"strong": 3, "moderate": 2, "weak": 1}
            if strength_rank.get(level.strength, 0) > strength_rank.get(last_level.strength, 0):
                merged_levels[-1] = level
            elif strength_rank.get(level.strength, 0) == strength_rank.get(last_level.strength, 0):
                # Same strength - keep Multi-Exchange over 4H
                if level.timeframe == "Multi-Exchange" and last_level.timeframe != "Multi-Exchange":
                    merged_levels[-1] = level
        else:
            merged_levels.append(level)
    
    # Sort by distance from current price and return top levels
    # Prioritize: strong levels, then by distance
    def level_priority(lvl):
        strength_score = {"strong": 0, "moderate": 1, "weak": 2}.get(lvl.strength, 2)
        return (strength_score, abs(lvl.distance_percent))
    
    final_levels = sorted(merged_levels, key=level_priority)
    
    # Return max 8 levels (balanced between support and resistance)
    supports = [l for l in final_levels if l.level_type == "support"][:4]
    resistances = [l for l in final_levels if l.level_type == "resistance"][:4]
    
    result = supports + resistances
    return sorted(result, key=lambda x: abs(x.distance_percent))[:8]

# Keep old function for backward compatibility
def calculate_support_resistance(candles: List[dict], current_price: float, orderbook: dict = None) -> List[SupportResistanceLevel]:
    """Calculate support and resistance levels from price data and order book"""
    return calculate_support_resistance_enhanced(candles, current_price, orderbook)

def calculate_market_bias(candles: List[dict], orderbook: dict = None, derivatives_context: dict = None, lang: str = "it") -> MarketBias:
    """
    Calculate market bias from multiple indicators including real order book.
    
    V3.3 ENHANCEMENT: Now integrates CoinGlass derivatives positioning:
    - Global long/short ratio (crowd positioning - contrarian signal when extreme)
    - Top trader long/short ratio (smart money - follow)
    - Top position long/short ratio (institutional positioning)
    """
    if not candles or len(candles) < 20:
        return MarketBias(
            bias="NEUTRAL",
            confidence=50.0,
            estimated_move=0.0,
            trap_risk="low",
            squeeze_probability=0.0,
            inputs={}
        )
    
    # Trend analysis using EMAs
    closes = [c["close"] for c in candles[-50:]]
    
    def ema(data, period):
        if len(data) < period:
            return sum(data) / len(data)
        multiplier = 2 / (period + 1)
        ema_val = sum(data[:period]) / period
        for price in data[period:]:
            ema_val = (price - ema_val) * multiplier + ema_val
        return ema_val
    
    ema_7 = ema(closes, 7)
    ema_21 = ema(closes, 21)
    current_price = closes[-1]
    
    trend_score = 0
    if current_price > ema_7 > ema_21:
        trend_score = 2  # Strong bullish
    elif current_price > ema_7:
        trend_score = 1  # Weak bullish
    elif current_price < ema_7 < ema_21:
        trend_score = -2  # Strong bearish
    elif current_price < ema_7:
        trend_score = -1  # Weak bearish
    
    # Volume analysis
    volumes = [c["volume"] for c in candles[-20:]]
    avg_volume = sum(volumes) / len(volumes) if volumes else 0
    recent_volume = volumes[-1] if volumes else 0
    volume_score = 1 if recent_volume > avg_volume * 1.5 else -1 if recent_volume < avg_volume * 0.5 else 0
    
    # Price momentum (RSI-like)
    gains = []
    losses = []
    for i in range(1, len(closes)):
        change = closes[i] - closes[i-1]
        if change > 0:
            gains.append(change)
            losses.append(0)
        else:
            gains.append(0)
            losses.append(abs(change))
    
    avg_gain = sum(gains[-14:]) / 14 if len(gains) >= 14 else 0
    avg_loss = sum(losses[-14:]) / 14 if len(losses) >= 14 else 0
    rs = avg_gain / avg_loss if avg_loss > 0 else 100
    rsi = 100 - (100 / (1 + rs))
    
    momentum_score = 1 if rsi > 60 else -1 if rsi < 40 else 0
    
    # Order book imbalance (REAL DATA)
    ob_score = 0
    ob_imbalance = 0
    if orderbook:
        bids = orderbook.get("bids", [])
        asks = orderbook.get("asks", [])
        
        # Calculate total depth in USD
        bid_depth = sum([float(b[0]) * float(b[1]) for b in bids[:30]])
        ask_depth = sum([float(a[0]) * float(a[1]) for a in asks[:30]])
        
        total_depth = bid_depth + ask_depth
        if total_depth > 0:
            ob_imbalance = ((bid_depth - ask_depth) / total_depth) * 100
            
            if ob_imbalance > 15:
                ob_score = 2  # Strong buying pressure
            elif ob_imbalance > 5:
                ob_score = 1  # Moderate buying pressure
            elif ob_imbalance < -15:
                ob_score = -2  # Strong selling pressure
            elif ob_imbalance < -5:
                ob_score = -1  # Moderate selling pressure
    
    # Calculate total score
    total_score = trend_score + volume_score + momentum_score + ob_score
    max_score = 7
    
    if total_score >= 3:
        bias = "BULLISH"
        confidence = min(50 + (total_score / max_score) * 50, 95)
    elif total_score <= -3:
        bias = "BEARISH"
        confidence = min(50 + (abs(total_score) / max_score) * 50, 95)
    else:
        bias = "NEUTRAL"
        confidence = 50 + abs(total_score) * 5
    
    # Calculate ATR for estimated move
    highs = [c["high"] for c in candles[-14:]]
    lows = [c["low"] for c in candles[-14:]]
    tr_list = [highs[i] - lows[i] for i in range(len(highs))]
    atr = sum(tr_list) / len(tr_list) if tr_list else 0
    estimated_move = (atr / current_price) * 100 if current_price > 0 else 0
    
    # Risk analysis
    recent_range = max(highs[-7:]) - min(lows[-7:]) if len(highs) >= 7 else 0
    volatility_ratio = recent_range / atr if atr > 0 else 1
    
    trap_risk = "high" if volatility_ratio > 2 or abs(ob_imbalance) > 30 else "moderate" if volatility_ratio > 1.5 else "low"
    
    # Squeeze probability (low volatility = high squeeze probability)
    squeeze_prob = max(0, min(80, (1 - (volatility_ratio / 3)) * 100)) if volatility_ratio < 3 else 0
    
    # Calculate next target based on S/R levels
    next_target = current_price
    if bias == "BULLISH":
        # Look for nearest resistance
        recent_high = max(highs[-20:]) if len(highs) >= 20 else current_price * 1.02
        next_target = recent_high if recent_high > current_price else current_price * 1.02
    elif bias == "BEARISH":
        # Look for nearest support
        recent_low = min(lows[-20:]) if len(lows) >= 20 else current_price * 0.98
        next_target = recent_low if recent_low < current_price else current_price * 0.98
    
    # Generate analysis text using translations
    analysis_parts = []
    if bias == "BULLISH":
        if ob_imbalance > 10:
            analysis_parts.append(get_translation("strong_buying_pressure", lang))
        if rsi > 50:
            analysis_parts.append(get_translation("momentum_favors_bulls", lang))
        if squeeze_prob > 40:
            analysis_parts.append(get_translation("short_squeeze_prob", lang, squeeze_prob))
    elif bias == "BEARISH":
        if ob_imbalance < -10:
            analysis_parts.append(get_translation("heavy_selling_pressure", lang))
        if rsi < 50:
            analysis_parts.append(get_translation("momentum_favors_bears", lang))
        if squeeze_prob > 40:
            analysis_parts.append(get_translation("long_squeeze_prob", lang, squeeze_prob))
    else:
        analysis_parts.append(get_translation("market_indecision", lang))
    
    analysis_text = " ".join(analysis_parts) if analysis_parts else get_translation("analyzing_conditions", lang)
    
    # Generate per-exchange consensus if aggregated data available
    exchange_consensus = None
    if orderbook and orderbook.get("exchange_stats"):
        exchange_consensus = {}
        for exchange, stats in orderbook["exchange_stats"].items():
            ex_imbalance = ((stats["bid_depth"] - stats["ask_depth"]) / stats["total_depth"] * 100) if stats["total_depth"] > 0 else 0
            if ex_imbalance > 10:
                exchange_consensus[exchange] = "BULLISH"
            elif ex_imbalance < -10:
                exchange_consensus[exchange] = "BEARISH"
            else:
                exchange_consensus[exchange] = "NEUTRAL"
    
    # ══════════════════════════════════════════════════════════════════════
    # V3.3: DERIVATIVES POSITIONING INTEGRATION
    # Combines exchange consensus with CoinGlass derivatives data
    # ══════════════════════════════════════════════════════════════════════
    derivatives_bias = None
    derivatives_strength = 0
    crowd_positioning = None
    top_accounts_bias = None
    top_positions_bias = None
    derivatives_explanation = None
    
    if derivatives_context and derivatives_context.get("data_available"):
        deriv_signals = []
        deriv_score = 0
        
        ls_ratio = derivatives_context.get("long_short_ratio", {})
        
        # 1. Global Long/Short Ratio (crowd positioning - contrarian when extreme)
        if ls_ratio:
            global_ratio = ls_ratio.get("global_ratio", 1.0)
            
            if global_ratio > 1.5:
                crowd_positioning = "overcrowded_long"
                deriv_score -= 20  # Contrarian: crowd too long = bearish signal
                deriv_signals.append(get_translation("crowd_overcrowded_long", lang) if lang != "en" else f"Crowd overcrowded LONG ({global_ratio:.2f}) - contrarian bearish")
            elif global_ratio < 0.67:
                crowd_positioning = "overcrowded_short"
                deriv_score += 20  # Contrarian: crowd too short = bullish signal
                deriv_signals.append(get_translation("crowd_overcrowded_short", lang) if lang != "en" else f"Crowd overcrowded SHORT ({global_ratio:.2f}) - contrarian bullish")
            elif global_ratio > 1.2:
                crowd_positioning = "leaning_long"
                deriv_score -= 10
                deriv_signals.append(get_translation("crowd_leaning_long", lang) if lang != "en" else "Crowd leaning long")
            elif global_ratio < 0.83:
                crowd_positioning = "leaning_short"
                deriv_score += 10
                deriv_signals.append(get_translation("crowd_leaning_short", lang) if lang != "en" else "Crowd leaning short")
            else:
                crowd_positioning = "balanced"
        
        # 2. Top Trader Long/Short Ratio (follow smart money)
        if ls_ratio:
            top_ratio = ls_ratio.get("top_trader_ratio", 1.0)
            
            if top_ratio > 1.3:
                top_accounts_bias = "BULLISH"
                deriv_score += 25
                deriv_signals.append(get_translation("top_traders_bullish", lang) if lang != "en" else f"Top traders BULLISH ({top_ratio:.2f})")
            elif top_ratio < 0.77:
                top_accounts_bias = "BEARISH"
                deriv_score -= 25
                deriv_signals.append(get_translation("top_traders_bearish", lang) if lang != "en" else f"Top traders BEARISH ({top_ratio:.2f})")
            else:
                top_accounts_bias = "NEUTRAL"
        
        # 3. Top Position Long/Short Ratio (institutional positioning)
        if ls_ratio:
            pos_ratio = ls_ratio.get("top_position_ratio", 1.0)
            
            if pos_ratio > 1.25:
                top_positions_bias = "BULLISH"
                deriv_score += 15
                deriv_signals.append(get_translation("top_positions_bullish", lang) if lang != "en" else "Top positions bullish")
            elif pos_ratio < 0.8:
                top_positions_bias = "BEARISH"
                deriv_score -= 15
                deriv_signals.append(get_translation("top_positions_bearish", lang) if lang != "en" else "Top positions bearish")
            else:
                top_positions_bias = "NEUTRAL"
        
        # Calculate derivatives bias
        if deriv_score > 20:
            derivatives_bias = "BULLISH"
            derivatives_strength = min(abs(deriv_score), 100)
        elif deriv_score < -20:
            derivatives_bias = "BEARISH"
            derivatives_strength = min(abs(deriv_score), 100)
        else:
            derivatives_bias = "NEUTRAL"
            derivatives_strength = abs(deriv_score)
        
        # Build explanation
        if deriv_signals:
            derivatives_explanation = ". ".join(deriv_signals[:3])
        
        # Adjust main bias confidence based on derivatives alignment
        if derivatives_bias == bias:
            confidence = min(100, confidence + 10)  # Aligned - boost confidence
        elif derivatives_bias != "NEUTRAL" and bias != "NEUTRAL" and derivatives_bias != bias:
            confidence = max(30, confidence - 15)  # Conflicting - reduce confidence
    
    return MarketBias(
        bias=bias,
        confidence=round(confidence, 1),
        estimated_move=round(estimated_move, 2),
        trap_risk=trap_risk,
        squeeze_probability=round(squeeze_prob, 1),
        next_target=round(next_target, 2),
        bias_score=total_score,
        analysis_text=analysis_text,
        inputs={
            "trend_score": trend_score,
            "volume_score": volume_score,
            "momentum_score": momentum_score,
            "orderbook_score": ob_score,
            "rsi": round(rsi, 1),
            "orderbook_imbalance": round(ob_imbalance, 2)
        },
        exchange_consensus=exchange_consensus,
        # V3.3: Derivatives positioning
        derivatives_bias=derivatives_bias,
        derivatives_strength=round(derivatives_strength, 1) if derivatives_strength else None,
        crowd_positioning=crowd_positioning,
        top_accounts_bias=top_accounts_bias,
        top_positions_bias=top_positions_bias,
        derivatives_explanation=derivatives_explanation
    )

def detect_patterns(candles: List[dict]) -> List[PatternDetection]:
    """Detect chart patterns in price data with detailed explanations"""
    if not candles or len(candles) < 30:
        return []
    
    patterns = []
    closes = [c["close"] for c in candles]
    highs = [c["high"] for c in candles]
    lows = [c["low"] for c in candles]
    current_price = closes[-1]
    
    # Double Top Detection (look for M pattern)
    recent_highs = []
    for i in range(-25, -2):
        if i >= -len(highs):
            if highs[i] > highs[i-1] and highs[i] > highs[i+1]:
                recent_highs.append((i, highs[i]))
    
    if len(recent_highs) >= 2:
        h1, h2 = recent_highs[-2], recent_highs[-1]
        price_diff_pct = abs(h1[1] - h2[1]) / h1[1] * 100
        if price_diff_pct < 1.5 and h2[0] - h1[0] >= 5:  # Within 1.5% and separated
            neckline = min(lows[h1[0]:h2[0]]) if h1[0] < h2[0] else min(lows)
            target = neckline - (h1[1] - neckline)
            stop_loss = h2[1] * 1.01  # 1% above second top
            patterns.append(PatternDetection(
                pattern="Double Top",
                direction="BEARISH",
                confidence=75.0 - price_diff_pct * 5,
                estimated_move=round(((target - current_price) / current_price) * 100, 2),
                timeframe="1H",
                start_price=h1[1],
                target_price=round(target, 2),
                timestamp=datetime.now(timezone.utc),
                stop_loss=round(stop_loss, 2),
                explanation=f"M-shaped reversal pattern. Two failed attempts to break ${h1[1]:,.0f}. Neckline at ${neckline:,.0f}. Break below neckline confirms bearish target.",
                pattern_strength="confirmed" if current_price < neckline else "forming"
            ))
    
    # Double Bottom Detection (look for W pattern)
    recent_lows = []
    for i in range(-25, -2):
        if i >= -len(lows):
            if lows[i] < lows[i-1] and lows[i] < lows[i+1]:
                recent_lows.append((i, lows[i]))
    
    if len(recent_lows) >= 2:
        l1, l2 = recent_lows[-2], recent_lows[-1]
        price_diff_pct = abs(l1[1] - l2[1]) / l1[1] * 100
        if price_diff_pct < 1.5 and l2[0] - l1[0] >= 5:
            neckline = max(highs[l1[0]:l2[0]]) if l1[0] < l2[0] else max(highs)
            target = neckline + (neckline - l1[1])
            stop_loss = l2[1] * 0.99  # 1% below second bottom
            patterns.append(PatternDetection(
                pattern="Double Bottom",
                direction="BULLISH",
                confidence=75.0 - price_diff_pct * 5,
                estimated_move=round(((target - current_price) / current_price) * 100, 2),
                timeframe="1H",
                start_price=l1[1],
                target_price=round(target, 2),
                timestamp=datetime.now(timezone.utc),
                stop_loss=round(stop_loss, 2),
                explanation=f"W-shaped reversal pattern. Two successful defenses of ${l1[1]:,.0f}. Neckline at ${neckline:,.0f}. Break above neckline confirms bullish target.",
                pattern_strength="confirmed" if current_price > neckline else "forming"
            ))
    
    # Bull Flag Detection
    if len(closes) >= 25:
        pole_start = closes[-25]
        pole_end = max(closes[-25:-15])
        pole_move = (pole_end - pole_start) / pole_start * 100
        
        flag_high = max(closes[-10:])
        flag_low = min(closes[-10:])
        flag_range = (flag_high - flag_low) / current_price * 100
        
        if pole_move > 3 and flag_range < 2:
            target = current_price + (pole_end - pole_start)
            stop_loss = flag_low * 0.99
            patterns.append(PatternDetection(
                pattern="Bull Flag",
                direction="BULLISH",
                confidence=70.0,
                estimated_move=round(pole_move * 0.7, 2),
                timeframe="1H",
                start_price=pole_start,
                target_price=round(target, 2),
                timestamp=datetime.now(timezone.utc),
                stop_loss=round(stop_loss, 2),
                explanation=f"Strong {pole_move:.1f}% rally followed by consolidation. Flag pattern suggests continuation. Expect breakout to ${target:,.0f}.",
                pattern_strength="forming"
            ))
    
    # Bear Flag Detection
    if len(closes) >= 25:
        pole_start = closes[-25]
        pole_end = min(closes[-25:-15])
        pole_move = (pole_start - pole_end) / pole_start * 100
        
        flag_high = max(closes[-10:])
        flag_low = min(closes[-10:])
        flag_range = (flag_high - flag_low) / current_price * 100
        
        if pole_move > 3 and flag_range < 2:
            target = current_price - (pole_start - pole_end)
            stop_loss = flag_high * 1.01
            patterns.append(PatternDetection(
                pattern="Bear Flag",
                direction="BEARISH",
                confidence=68.0,
                estimated_move=round(-pole_move * 0.7, 2),
                timeframe="1H",
                start_price=pole_start,
                target_price=round(target, 2),
                timestamp=datetime.now(timezone.utc),
                stop_loss=round(stop_loss, 2),
                explanation=f"Sharp {pole_move:.1f}% decline followed by consolidation. Bear flag suggests continuation lower. Target ${target:,.0f}.",
                pattern_strength="forming"
            ))
    
    # Triangle Detection
    if len(highs) >= 20 and len(lows) >= 20:
        recent_highs_vals = highs[-20:]
        recent_lows_vals = lows[-20:]
        
        high_slope = (recent_highs_vals[-1] - recent_highs_vals[0]) / 20
        low_slope = (recent_lows_vals[-1] - recent_lows_vals[0]) / 20
        
        if high_slope < 0 and low_slope > 0:  # Converging
            patterns.append(PatternDetection(
                pattern="Symmetrical Triangle",
                direction="NEUTRAL",
                confidence=65.0,
                estimated_move=2.5,
                timeframe="1H",
                start_price=closes[-20],
                target_price=round(current_price * 1.025, 2),
                timestamp=datetime.now(timezone.utc),
                explanation="Converging highs and lows forming triangle. Breakout direction uncertain - wait for confirmation. Usually breaks in trend direction.",
                pattern_strength="forming"
            ))
    
    return patterns

def detect_candlestick_patterns(candles: List[dict]) -> List[CandlestickPattern]:
    """Detect candlestick patterns"""
    if not candles or len(candles) < 5:
        return []
    
    patterns = []
    
    for i in range(-5, 0):
        if i >= -len(candles):
            c = candles[i]
            body = abs(c["close"] - c["open"])
            upper_wick = c["high"] - max(c["close"], c["open"])
            lower_wick = min(c["close"], c["open"]) - c["low"]
            total_range = c["high"] - c["low"]
            
            if total_range == 0:
                continue
            
            is_bullish = c["close"] > c["open"]
            body_pct = body / total_range
            
            # Doji
            if body_pct < 0.1:
                patterns.append(CandlestickPattern(
                    pattern="Doji",
                    signal="NEUTRAL",
                    confidence=65.0,
                    candle_time=c["time"],
                    explanation="Doji indicates market indecision. Equal buying and selling pressure. Watch for direction confirmation on next candle."
                ))
            
            # Hammer (bullish reversal)
            elif lower_wick > body * 2.5 and upper_wick < body * 0.5 and is_bullish:
                patterns.append(CandlestickPattern(
                    pattern="Hammer",
                    signal="BULLISH",
                    confidence=72.0,
                    candle_time=c["time"],
                    explanation="Hammer shows strong rejection of lower prices. Buyers stepped in aggressively. Potential bullish reversal signal."
                ))
            
            # Inverted Hammer
            elif upper_wick > body * 2.5 and lower_wick < body * 0.5 and is_bullish:
                patterns.append(CandlestickPattern(
                    pattern="Inverted Hammer",
                    signal="BULLISH",
                    confidence=65.0,
                    candle_time=c["time"],
                    explanation="Inverted Hammer at support can signal bullish reversal. Confirmation needed."
                ))
            
            # Shooting Star (bearish reversal)
            elif upper_wick > body * 2.5 and lower_wick < body * 0.5 and not is_bullish:
                patterns.append(CandlestickPattern(
                    pattern="Shooting Star",
                    signal="BEARISH",
                    confidence=70.0,
                    candle_time=c["time"],
                    explanation="Shooting Star shows rejection of higher prices. Sellers overwhelmed buyers. Potential bearish reversal."
                ))
            
            # Hanging Man
            elif lower_wick > body * 2.5 and upper_wick < body * 0.5 and not is_bullish:
                patterns.append(CandlestickPattern(
                    pattern="Hanging Man",
                    signal="BEARISH",
                    confidence=65.0,
                    candle_time=c["time"],
                    explanation="Hanging Man at resistance warns of potential reversal. Selling pressure emerging."
                ))
            
            # Engulfing patterns
            if i > -len(candles) + 1:
                prev = candles[i-1]
                prev_body = abs(prev["close"] - prev["open"])
                prev_is_bullish = prev["close"] > prev["open"]
                
                # Bullish Engulfing
                if not prev_is_bullish and is_bullish:
                    if c["open"] <= prev["close"] and c["close"] >= prev["open"] and body > prev_body * 1.2:
                        patterns.append(CandlestickPattern(
                            pattern="Bullish Engulfing",
                            signal="BULLISH",
                            confidence=78.0,
                            candle_time=c["time"],
                            explanation="Bullish Engulfing shows strong buying momentum completely overwhelming prior selling. High probability reversal signal."
                        ))
                
                # Bearish Engulfing
                if prev_is_bullish and not is_bullish:
                    if c["open"] >= prev["close"] and c["close"] <= prev["open"] and body > prev_body * 1.2:
                        patterns.append(CandlestickPattern(
                            pattern="Bearish Engulfing",
                            signal="BEARISH",
                            confidence=78.0,
                            candle_time=c["time"],
                            explanation="Bearish Engulfing shows strong selling momentum completely overwhelming prior buying. High probability reversal signal."
                        ))
    
    return patterns[-6:]

def analyze_orderbook(orderbook: dict, current_price: float) -> OrderBookAnalysis:
    """Analyze real order book for walls and imbalance"""
    if not orderbook:
        return OrderBookAnalysis(
            top_bid_wall={"price": 0, "quantity": 0},
            top_ask_wall={"price": 0, "quantity": 0},
            imbalance=0.0,
            imbalance_direction="balanced",
            bid_depth=0,
            ask_depth=0,
            data_source="Unavailable"
        )
    
    bids = orderbook.get("bids", [])
    asks = orderbook.get("asks", [])
    
    # Find largest bid wall
    bid_walls = [(float(b[0]), float(b[1])) for b in bids]
    bid_walls_sorted = sorted(bid_walls, key=lambda x: x[1], reverse=True)
    top_bid = bid_walls_sorted[0] if bid_walls_sorted else (0, 0)
    
    # Find largest ask wall
    ask_walls = [(float(a[0]), float(a[1])) for a in asks]
    ask_walls_sorted = sorted(ask_walls, key=lambda x: x[1], reverse=True)
    top_ask = ask_walls_sorted[0] if ask_walls_sorted else (0, 0)
    
    # Calculate depth in USD (price * quantity)
    bid_depth = sum([float(b[0]) * float(b[1]) for b in bids[:50]])
    ask_depth = sum([float(a[0]) * float(a[1]) for a in asks[:50]])
    
    total_depth = bid_depth + ask_depth
    imbalance = ((bid_depth - ask_depth) / total_depth * 100) if total_depth > 0 else 0
    
    if imbalance > 15:
        direction = "bullish"
    elif imbalance < -15:
        direction = "bearish"
    else:
        direction = "balanced"
    
    return OrderBookAnalysis(
        top_bid_wall={"price": round(top_bid[0], 2), "quantity": round(top_bid[1], 4)},
        top_ask_wall={"price": round(top_ask[0], 2), "quantity": round(top_ask[1], 4)},
        imbalance=round(imbalance, 2),
        imbalance_direction=direction,
        bid_depth=round(bid_depth, 2),
        ask_depth=round(ask_depth, 2),
        data_source="Kraken"
    )

def generate_liquidity_clusters_enhanced(candles: List[dict], current_price: float, aggregated_orderbook: dict = None, lang: str = "it") -> tuple:
    """
    Generate liquidity cluster data from aggregated multi-exchange order book analysis.
    
    V2.0 IMPROVEMENTS:
    - Minimum distance filter: ignore clusters < 0.5% (too close = noise)
    - Dynamic volume filtering: use top 30% strongest by volume percentile
    - Magnet strength scoring: volume * log(distance + 1)
    - Zone separation: near (ignore), mid (T1 candidates), far (T2 candidates)
    - Direction consistency: LONG only sees ABOVE, SHORT only sees BELOW
    
    ZONE DEFINITIONS:
    - Near zone: < 0.5% distance → IGNORED (noise)
    - Mid zone: 0.5% - 2.0% → T1 CANDIDATES (ideal for first target)
    - Far zone: 2.0% - 5.0% → T2 CANDIDATES (extended targets)
    """
    import math
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONFIGURATION CONSTANTS
    # ═══════════════════════════════════════════════════════════════════════════
    MIN_DISTANCE_PCT = 0.5      # HARD minimum - ignore anything closer
    MID_ZONE_MAX_PCT = 2.0      # Mid zone upper bound (T1 candidates)
    FAR_ZONE_MAX_PCT = 5.0      # Far zone upper bound (T2 candidates)
    VOLUME_PERCENTILE_CUTOFF = 70  # Only keep top 30% by volume (70th percentile+)
    
    raw_clusters = []
    
    # Get active exchanges from aggregated data
    active_exchanges = None
    if aggregated_orderbook and aggregated_orderbook.get("exchange_stats"):
        active_exchanges = list(aggregated_orderbook["exchange_stats"].keys())
    
    # Debug: Log orderbook size
    ob_bids = aggregated_orderbook.get("bids", []) if aggregated_orderbook else []
    ob_asks = aggregated_orderbook.get("asks", []) if aggregated_orderbook else []
    logger.info(f"[Liquidity Clusters V2] Input: price=${current_price:,.0f}, "
               f"orderbook_bids={len(ob_bids)}, orderbook_asks={len(ob_asks)}, "
               f"exchanges={active_exchanges}")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STEP 1: EXTRACT ALL POTENTIAL CLUSTERS FROM ORDER BOOK
    # ═══════════════════════════════════════════════════════════════════════════
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        
        # Process bid levels (liquidity BELOW current price)
        for bid in bids[:100]:  # Analyze more levels
            price = float(bid[0])
            volume_btc = float(bid[1])
            value_usd = price * volume_btc
            
            # Only consider if below current price
            if price >= current_price:
                continue
            
            distance_pct = abs((price - current_price) / current_price) * 100
            
            # Skip if too close (< MIN_DISTANCE)
            if distance_pct < MIN_DISTANCE_PCT:
                continue
            
            # Skip if too far (> FAR_ZONE_MAX)
            if distance_pct > FAR_ZONE_MAX_PCT:
                continue
            
            raw_clusters.append({
                "price": price,
                "value_usd": value_usd,
                "volume_btc": volume_btc,
                "distance_pct": distance_pct,
                "side": "below",
                "source": "orderbook_bid"
            })
        
        # Process ask levels (liquidity ABOVE current price)
        for ask in asks[:100]:
            price = float(ask[0])
            volume_btc = float(ask[1])
            value_usd = price * volume_btc
            
            # Only consider if above current price
            if price <= current_price:
                continue
            
            distance_pct = abs((price - current_price) / current_price) * 100
            
            # Skip if too close (< MIN_DISTANCE)
            if distance_pct < MIN_DISTANCE_PCT:
                continue
            
            # Skip if too far (> FAR_ZONE_MAX)
            if distance_pct > FAR_ZONE_MAX_PCT:
                continue
            
            raw_clusters.append({
                "price": price,
                "value_usd": value_usd,
                "volume_btc": volume_btc,
                "distance_pct": distance_pct,
                "side": "above",
                "source": "orderbook_ask"
            })
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STEP 2: ADD HISTORICAL S/R LEVELS AS CLUSTERS (with synthetic volume)
    # ═══════════════════════════════════════════════════════════════════════════
    if candles and len(candles) >= 20:
        highs = [c["high"] for c in candles[-50:]]
        lows = [c["low"] for c in candles[-50:]]
        
        # Calculate typical volume for synthetic estimates
        avg_candle_volume = sum(c.get("volume", 0) for c in candles[-50:]) / 50 if candles else 1
        synthetic_volume = avg_candle_volume * current_price * 0.1  # 10% of avg candle value
        
        # Recent resistance levels (above)
        seen_highs = set()
        for h in sorted(set(highs), reverse=True)[:5]:
            if h > current_price:
                distance_pct = ((h - current_price) / current_price) * 100
                rounded_h = round(h, -1)
                
                if MIN_DISTANCE_PCT <= distance_pct <= FAR_ZONE_MAX_PCT and rounded_h not in seen_highs:
                    seen_highs.add(rounded_h)
                    touches = sum(1 for x in highs if abs(x - h) / h < 0.003)
                    raw_clusters.append({
                        "price": h,
                        "value_usd": synthetic_volume * (1 + touches * 0.5),  # More touches = stronger
                        "volume_btc": 0,
                        "distance_pct": distance_pct,
                        "side": "above",
                        "source": "historical_resistance"
                    })
        
        # Recent support levels (below)
        seen_lows = set()
        for l in sorted(set(lows))[:5]:
            if l < current_price:
                distance_pct = abs((l - current_price) / current_price) * 100
                rounded_l = round(l, -1)
                
                if MIN_DISTANCE_PCT <= distance_pct <= FAR_ZONE_MAX_PCT and rounded_l not in seen_lows:
                    seen_lows.add(rounded_l)
                    touches = sum(1 for x in lows if abs(x - l) / l < 0.003)
                    raw_clusters.append({
                        "price": l,
                        "value_usd": synthetic_volume * (1 + touches * 0.5),
                        "volume_btc": 0,
                        "distance_pct": distance_pct,
                        "side": "below",
                        "source": "historical_support"
                    })
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STEP 3: DYNAMIC VOLUME FILTERING (Top 30% by volume percentile)
    # ═══════════════════════════════════════════════════════════════════════════
    if len(raw_clusters) == 0:
        # No valid clusters found
        liq_direction = LiquidityDirection(
            direction="BALANCED",
            next_target=current_price,
            distance_percent=0,
            imbalance_ratio=1.0,
            explanation=get_translation("no_significant_liquidity", lang) if get_translation("no_significant_liquidity", lang) else "No significant liquidity clusters detected"
        )
        return [], liq_direction
    
    # Calculate volume percentile for each cluster
    all_volumes = sorted([c["value_usd"] for c in raw_clusters])
    
    for cluster in raw_clusters:
        # Find percentile position
        rank = sum(1 for v in all_volumes if v <= cluster["value_usd"])
        cluster["volume_percentile"] = (rank / len(all_volumes)) * 100
        
        # Calculate MAGNET STRENGTH: volume * log(distance + 1)
        # Higher distance = more meaningful target, volume = attraction power
        cluster["magnet_strength"] = cluster["value_usd"] * math.log(cluster["distance_pct"] + 1)
    
    # Filter to top 30% by volume (70th percentile and above)
    filtered_clusters = [c for c in raw_clusters if c["volume_percentile"] >= VOLUME_PERCENTILE_CUTOFF]
    
    # If filtering removes everything, keep at least top 5 by magnet strength
    if len(filtered_clusters) < 3 and len(raw_clusters) > 0:
        filtered_clusters = sorted(raw_clusters, key=lambda x: x["magnet_strength"], reverse=True)[:5]
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STEP 4: ZONE CLASSIFICATION AND FINAL CLUSTER CREATION
    # ═══════════════════════════════════════════════════════════════════════════
    final_clusters = []
    
    for c in filtered_clusters:
        # Determine zone type
        if c["distance_pct"] < MIN_DISTANCE_PCT:
            zone_type = "near"  # Should have been filtered, but safety check
            continue
        elif c["distance_pct"] <= MID_ZONE_MAX_PCT:
            zone_type = "mid"  # T1 candidate
        else:
            zone_type = "far"  # T2 candidate
        
        # Determine strength based on volume percentile
        if c["volume_percentile"] >= 90:
            strength = "high"
        elif c["volume_percentile"] >= 80:
            strength = "medium"
        else:
            strength = "low"
        
        # Build explanation
        zone_label = {
            "mid": get_translation("t1_candidate_zone", lang) if get_translation("t1_candidate_zone", lang) else "T1 candidate zone",
            "far": get_translation("t2_candidate_zone", lang) if get_translation("t2_candidate_zone", lang) else "T2 candidate zone"
        }.get(zone_type, "")
        
        if c["side"] == "above":
            base_explanation = get_translation("sell_orders_at_level", lang, c["value_usd"]) if c["value_usd"] > 0 else f"Resistance at ${c['price']:,.0f}"
        else:
            base_explanation = get_translation("buy_orders_at_level", lang, c["value_usd"]) if c["value_usd"] > 0 else f"Support at ${c['price']:,.0f}"
        
        explanation = f"{base_explanation} {zone_label}".strip()
        
        final_clusters.append(LiquidityCluster(
            price=round(c["price"], 2),
            strength=strength,
            distance_percent=round(c["distance_pct"], 3),
            side=c["side"],
            estimated_value=round(c["value_usd"], 0),
            exchanges=active_exchanges,
            explanation=explanation,
            magnet_strength=round(c["magnet_strength"], 2),
            zone_type=zone_type,
            volume_percentile=round(c["volume_percentile"], 1)
        ))
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STEP 5: DEDUPLICATE (merge clusters within 0.2% of each other)
    # ═══════════════════════════════════════════════════════════════════════════
    deduped_clusters = []
    for c in sorted(final_clusters, key=lambda x: x.magnet_strength or 0, reverse=True):
        is_dup = False
        for existing in deduped_clusters:
            if c.side == existing.side:
                price_diff_pct = abs(c.price - existing.price) / existing.price * 100
                if price_diff_pct < 0.2:
                    is_dup = True
                    break
        if not is_dup:
            deduped_clusters.append(c)
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STEP 6: CALCULATE LIQUIDITY DIRECTION
    # ═══════════════════════════════════════════════════════════════════════════
    above_clusters = [c for c in deduped_clusters if c.side == "above"]
    below_clusters = [c for c in deduped_clusters if c.side == "below"]
    
    above_value = sum(c.estimated_value for c in above_clusters)
    below_value = sum(c.estimated_value for c in below_clusters)
    above_magnet = sum(c.magnet_strength or 0 for c in above_clusters)
    below_magnet = sum(c.magnet_strength or 0 for c in below_clusters)
    
    # Use magnet strength for direction (more meaningful than raw volume)
    if above_magnet > below_magnet * 1.3:
        direction = "UP"
        # Find nearest mid-zone cluster above
        mid_above = [c for c in above_clusters if c.zone_type == "mid"]
        next_target = min(c.price for c in mid_above) if mid_above else (min(c.price for c in above_clusters) if above_clusters else current_price)
        dir_explanation = get_translation("more_liquidity_above", lang, above_value, below_value) if get_translation("more_liquidity_above", lang, above_value, below_value) else f"More significant liquidity above (${above_value:,.0f} vs ${below_value:,.0f})"
    elif below_magnet > above_magnet * 1.3:
        direction = "DOWN"
        mid_below = [c for c in below_clusters if c.zone_type == "mid"]
        next_target = max(c.price for c in mid_below) if mid_below else (max(c.price for c in below_clusters) if below_clusters else current_price)
        dir_explanation = get_translation("more_liquidity_below", lang, below_value, above_value) if get_translation("more_liquidity_below", lang, below_value, above_value) else f"More significant liquidity below (${below_value:,.0f} vs ${above_value:,.0f})"
    else:
        direction = "BALANCED"
        next_target = current_price
        dir_explanation = get_translation("balanced_liquidity_distribution", lang) if get_translation("balanced_liquidity_distribution", lang) else "Balanced liquidity distribution"
    
    imbalance_ratio = (above_magnet / below_magnet) if below_magnet > 0 else 1.0
    
    liq_direction = LiquidityDirection(
        direction=direction,
        next_target=round(next_target, 2),
        distance_percent=round(((next_target - current_price) / current_price) * 100, 2),
        imbalance_ratio=round(imbalance_ratio, 2),
        explanation=dir_explanation
    )
    
    # Sort by magnet strength (strongest first) and limit to 12
    sorted_clusters = sorted(deduped_clusters, key=lambda x: x.magnet_strength or 0, reverse=True)[:12]
    
    logger.info(f"[Liquidity Clusters V2] Price=${current_price:,.0f}, Raw candidates={len(raw_clusters)}, "
                f"After percentile filter={len(filtered_clusters)}, After dedup={len(deduped_clusters)}, "
                f"Final={len(sorted_clusters)} (above:{len([c for c in sorted_clusters if c.side == 'above'])}, "
                f"below:{len([c for c in sorted_clusters if c.side == 'below'])}) Dir={direction}")
    
    return sorted_clusters, liq_direction

# Keep old function for backward compatibility
def generate_liquidity_clusters(candles: List[dict], current_price: float, orderbook: dict = None, lang: str = "it") -> tuple:
    """Generate liquidity cluster data from order book analysis"""
    return generate_liquidity_clusters_enhanced(candles, current_price, orderbook, lang)

def generate_whale_alerts_enhanced(candles: List[dict], current_price: float, aggregated_orderbook: dict = None, lang: str = "it") -> List[WhaleAlert]:
    """Generate whale alert signals based on volume and multi-exchange order book analysis"""
    if not candles or len(candles) < 20:
        return []
    
    alerts = []
    volumes = [c["volume"] for c in candles[-30:]]
    avg_volume = sum(volumes) / len(volumes) if volumes else 0
    
    # Get active exchanges if available
    exchanges_detected = None
    if aggregated_orderbook and aggregated_orderbook.get("exchange_stats"):
        exchanges_detected = list(aggregated_orderbook["exchange_stats"].keys())
    
    # Detect volume spikes
    for i in range(-7, 0):
        if i >= -len(candles):
            c = candles[i]
            if c["volume"] > avg_volume * 2.5:  # Significant volume spike
                is_bullish = c["close"] > c["open"]
                signal = "LONG" if is_bullish else "SHORT"
                entry = c["close"]
                
                # Calculate target based on volume intensity
                volume_ratio = c["volume"] / avg_volume
                move_pct = min(3.0, 1.5 + (volume_ratio - 2.5) * 0.5)
                if not is_bullish:
                    move_pct = -move_pct
                
                target = entry * (1 + move_pct / 100)
                confidence = min(85, 60 + (volume_ratio - 2) * 8)
                
                # Calculate stop loss and risk/reward
                recent_low = min(c["low"] for c in candles[-10:])
                recent_high = max(c["high"] for c in candles[-10:])
                stop_loss = recent_low * 0.995 if is_bullish else recent_high * 1.005
                
                risk = abs(entry - stop_loss)
                reward = abs(target - entry)
                risk_reward = reward / risk if risk > 0 else 0
                
                # Localized reason
                pressure_type = "buying" if is_bullish else "selling"
                reason = get_translation("volume_spike_reason", lang, volume_ratio, pressure_type)
                
                alerts.append(WhaleAlert(
                    signal=signal,
                    entry=round(entry, 2),
                    target=round(target, 2),
                    confidence=round(confidence, 1),
                    estimated_move=round(move_pct, 2),
                    timeframe="1H",
                    timestamp=datetime.fromtimestamp(c["time"], tz=timezone.utc),
                    reason=reason,
                    stop_loss=round(stop_loss, 2),
                    risk_reward=round(risk_reward, 2),
                    exchanges_detected=exchanges_detected
                ))
    
    # Detect large order book imbalances from aggregated data
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        
        bid_depth = sum([float(b[0]) * float(b[1]) for b in bids[:20]])
        ask_depth = sum([float(a[0]) * float(a[1]) for a in asks[:20]])
        
        imbalance = ((bid_depth - ask_depth) / (bid_depth + ask_depth) * 100) if (bid_depth + ask_depth) > 0 else 0
        
        if abs(imbalance) > 20:  # Lowered threshold with aggregated data
            is_bullish = imbalance > 0
            signal = "LONG" if is_bullish else "SHORT"
            move_pct = abs(imbalance) / 12
            if not is_bullish:
                move_pct = -move_pct
            
            target = current_price * (1 + move_pct / 100)
            
            # Calculate stop loss
            atr = sum(c["high"] - c["low"] for c in candles[-14:]) / 14 if len(candles) >= 14 else current_price * 0.01
            stop_loss = current_price - atr if is_bullish else current_price + atr
            
            risk = abs(current_price - stop_loss)
            reward = abs(target - current_price)
            risk_reward = reward / risk if risk > 0 else 0
            
            # Count how many exchanges agree
            exchange_stats = aggregated_orderbook.get("exchange_stats", {})
            agreeing_exchanges = 0
            for ex, stats in exchange_stats.items():
                ex_imbalance = ((stats["bid_depth"] - stats["ask_depth"]) / stats["total_depth"] * 100) if stats["total_depth"] > 0 else 0
                if (is_bullish and ex_imbalance > 10) or (not is_bullish and ex_imbalance < -10):
                    agreeing_exchanges += 1
            
            # Localized reason
            pressure_type = "buying" if is_bullish else "selling"
            reason = get_translation("multi_exchange_imbalance", lang, imbalance, agreeing_exchanges, len(exchange_stats), pressure_type)
            
            alerts.append(WhaleAlert(
                signal=signal,
                entry=round(current_price, 2),
                target=round(target, 2),
                confidence=round(min(85, 55 + abs(imbalance) / 2 + agreeing_exchanges * 5), 1),
                estimated_move=round(move_pct, 2),
                timeframe="Current",
                timestamp=datetime.now(timezone.utc),
                reason=reason,
                stop_loss=round(stop_loss, 2),
                risk_reward=round(risk_reward, 2),
                exchanges_detected=exchanges_detected
            ))
    
    return alerts[-5:]

# Keep old function for backward compatibility
def generate_whale_alerts(candles: List[dict], current_price: float, orderbook: dict = None, lang: str = "it") -> List[WhaleAlert]:
    """Generate whale alert signals based on volume and order book analysis"""
    return generate_whale_alerts_enhanced(candles, current_price, orderbook, lang)

# ============== COINGLASS API HELPERS ==============

async def fetch_coinglass_open_interest():
    """Fetch real Open Interest data from CoinGlass"""
    try:
        # Check cache
        if market_data_cache["coinglass_oi"] and market_data_cache["coinglass_oi_time"]:
            if (datetime.now(timezone.utc) - market_data_cache["coinglass_oi_time"]).seconds < COINGLASS_CACHE_TTL:
                return market_data_cache["coinglass_oi"]
        
        if not COINGLASS_API_KEY:
            logger.warning("CoinGlass API key not configured")
            return None
        
        headers = {"CG-API-KEY": COINGLASS_API_KEY, "accept": "application/json"}
        
        async with httpx.AsyncClient(timeout=15.0) as http_client:
            # Get aggregated OI history
            response = await http_client.get(
                f"{COINGLASS_API_URL}/futures/open-interest/aggregated-history",
                params={"symbol": "BTC", "interval": "4h", "limit": 30},
                headers=headers
            )
            
            if response.status_code == 200:
                data = response.json()
                logger.info(f"CoinGlass OI response code: {data.get('code')}, has data: {bool(data.get('data'))}")
                if data.get("code") == "0" and data.get("data"):
                    oi_data = data["data"]
                    
                    # Calculate changes from historical data
                    if len(oi_data) >= 2:
                        # API returns "close" not "c"
                        latest = float(oi_data[-1].get("close", oi_data[-1].get("c", 0)))
                        prev_1h = float(oi_data[-2].get("close", oi_data[-2].get("c", latest))) if len(oi_data) >= 2 else latest
                        prev_4h = float(oi_data[-2].get("close", oi_data[-2].get("c", latest))) if len(oi_data) >= 2 else latest
                        prev_24h = float(oi_data[-7].get("close", oi_data[-7].get("c", latest))) if len(oi_data) >= 7 else latest
                        
                        logger.info(f"CoinGlass OI raw values - latest: {latest}, prev_24h: {prev_24h}")
                        
                        total_oi_usd = latest / 1e9  # Convert to billions
                        
                        change_1h = ((latest - prev_1h) / prev_1h * 100) if prev_1h > 0 else 0
                        change_4h = ((latest - prev_4h) / prev_4h * 100) if prev_4h > 0 else 0
                        change_24h = ((latest - prev_24h) / prev_24h * 100) if prev_24h > 0 else 0
                        
                        result = {
                            "total_oi": round(total_oi_usd, 2),
                            "change_1h": round(change_1h, 2),
                            "change_4h": round(change_4h, 2),
                            "change_24h": round(change_24h, 2),
                            "raw_data": oi_data[-10:]  # Keep last 10 for trend
                        }
                        
                        market_data_cache["coinglass_oi"] = result
                        market_data_cache["coinglass_oi_time"] = datetime.now(timezone.utc)
                        logger.info(f"CoinGlass OI processed: total_oi={result['total_oi']}B, change_24h={result['change_24h']}%")
                        return result
                else:
                    logger.error(f"CoinGlass OI error: {data}")
            else:
                logger.error(f"CoinGlass OI HTTP error: {response.status_code}")
    except Exception as e:
        logger.error(f"Error fetching CoinGlass OI: {e}")
    return None

async def fetch_coinglass_liquidation():
    """Fetch real Liquidation data from CoinGlass"""
    try:
        # Check cache
        if market_data_cache["coinglass_liquidation"] and market_data_cache["coinglass_liquidation_time"]:
            if (datetime.now(timezone.utc) - market_data_cache["coinglass_liquidation_time"]).seconds < COINGLASS_CACHE_TTL:
                return market_data_cache["coinglass_liquidation"]
        
        if not COINGLASS_API_KEY:
            return None
        
        headers = {"CG-API-KEY": COINGLASS_API_KEY, "accept": "application/json"}
        
        async with httpx.AsyncClient(timeout=15.0) as http_client:
            response = await http_client.get(
                f"{COINGLASS_API_URL}/futures/liquidation/coin-list",
                headers=headers
            )
            
            if response.status_code == 200:
                data = response.json()
                if data.get("code") == "0" and data.get("data"):
                    # Find BTC data
                    btc_data = next((x for x in data["data"] if x.get("symbol") == "BTC"), None)
                    if btc_data:
                        result = {
                            "liquidation_24h": btc_data.get("liquidation_usd_24h", 0),
                            "long_liquidation_24h": btc_data.get("long_liquidation_usd_24h", 0),
                            "short_liquidation_24h": btc_data.get("short_liquidation_usd_24h", 0),
                            "liquidation_12h": btc_data.get("liquidation_usd_12h", 0),
                            "long_liquidation_12h": btc_data.get("long_liquidation_usd_12h", 0),
                            "short_liquidation_12h": btc_data.get("short_liquidation_usd_12h", 0),
                            "liquidation_4h": btc_data.get("liquidation_usd_4h", 0),
                            "long_liquidation_4h": btc_data.get("long_liquidation_usd_4h", 0),
                            "short_liquidation_4h": btc_data.get("short_liquidation_usd_4h", 0),
                            "liquidation_1h": btc_data.get("liquidation_usd_1h", 0),
                            "long_liquidation_1h": btc_data.get("long_liquidation_usd_1h", 0),
                            "short_liquidation_1h": btc_data.get("short_liquidation_usd_1h", 0),
                        }
                        market_data_cache["coinglass_liquidation"] = result
                        market_data_cache["coinglass_liquidation_time"] = datetime.now(timezone.utc)
                        
                        # Update data freshness tracker
                        update_data_freshness("liquidation", True, "CoinGlass")
                        
                        return result
    except Exception as e:
        logger.error(f"Error fetching CoinGlass liquidation: {e}")
    
    update_data_freshness("liquidation", False)
    return None


async def fetch_coinglass_liquidation_heatmap(current_price: float = None):
    """
    Fetch Liquidation Heatmap data from CoinGlass with actual price levels.
    This returns the actual liquidation clusters at specific price points.
    
    CRITICAL: This is what provides 'liquidation_levels' for the magnet/zone engines.
    
    Correct endpoint: /api/futures/liquidation/heatmap/model2
    """
    try:
        if not COINGLASS_API_KEY:
            logger.warning("[CoinGlass Heatmap] No API key configured")
            return None
        
        headers = {"CG-API-KEY": COINGLASS_API_KEY, "accept": "application/json"}
        
        async with httpx.AsyncClient(timeout=20.0) as http_client:
            # Correct endpoint: heatmap/model2
            response = await http_client.get(
                f"{COINGLASS_API_URL}/futures/liquidation/heatmap/model2",
                params={"symbol": "BTC", "range": "3"},  # 3% range, can be 1, 3, 5
                headers=headers
            )
            
            logger.info(f"[CoinGlass Heatmap] Request URL: {response.request.url}")
            logger.info(f"[CoinGlass Heatmap] Response status: {response.status_code}")
            
            if response.status_code == 200:
                data = response.json()
                logger.info(f"[CoinGlass Heatmap] Response code: {data.get('code')}, has data: {bool(data.get('data'))}")
                
                if data.get("code") == "0" and data.get("data"):
                    raw_data = data["data"]
                    
                    # Debug: log raw data structure
                    if isinstance(raw_data, list) and len(raw_data) > 0:
                        logger.info(f"[CoinGlass Heatmap] Raw data type: list, count: {len(raw_data)}")
                        if isinstance(raw_data[0], dict):
                            logger.info(f"[CoinGlass Heatmap] Sample entry keys: {list(raw_data[0].keys())[:10]}")
                    elif isinstance(raw_data, dict):
                        logger.info(f"[CoinGlass Heatmap] Raw data type: dict, keys: {list(raw_data.keys())[:10]}")
                    
                    # Parse liquidation levels from heatmap
                    liquidation_levels = []
                    
                    # Model2 typically returns: {"y": [price_levels], "liqData": [[values_per_price]]}
                    # Or: list of {"price": x, "liq": y} objects
                    
                    if isinstance(raw_data, dict):
                        # Format 1: {y: [prices], liqData: [[values]]} or similar
                        prices = raw_data.get("y") or raw_data.get("prices") or raw_data.get("priceList") or []
                        liq_values = raw_data.get("liqData") or raw_data.get("data") or raw_data.get("liquidations") or []
                        
                        if prices and liq_values:
                            # liqData may be 2D array (multiple exchanges) - sum them
                            for i, price in enumerate(prices):
                                try:
                                    price_float = float(price)
                                    
                                    # Sum all exchange values at this price level
                                    if isinstance(liq_values, list) and len(liq_values) > 0:
                                        if isinstance(liq_values[0], list):
                                            # 2D array - each row is an exchange
                                            total_value = sum(float(row[i]) if i < len(row) else 0 for row in liq_values)
                                        else:
                                            # 1D array
                                            total_value = float(liq_values[i]) if i < len(liq_values) else 0
                                    else:
                                        total_value = 0
                                    
                                    if total_value > 100000:  # Min $100k to be relevant
                                        liquidation_levels.append({
                                            "price": price_float,
                                            "value": total_value,
                                            "source": "coinglass_heatmap"
                                        })
                                except (ValueError, TypeError, IndexError) as e:
                                    continue
                        
                        # Also check for longs/shorts format
                        for side_key in ["longs", "shorts", "longLiquidations", "shortLiquidations"]:
                            side_data = raw_data.get(side_key, [])
                            if isinstance(side_data, list):
                                for item in side_data:
                                    if isinstance(item, dict):
                                        price = item.get("price") or item.get("p")
                                        value = item.get("liq") or item.get("vol") or item.get("value") or item.get("amount")
                                        if price and value:
                                            try:
                                                liquidation_levels.append({
                                                    "price": float(price),
                                                    "value": float(value),
                                                    "source": f"coinglass_{side_key}"
                                                })
                                            except (ValueError, TypeError):
                                                continue
                    
                    elif isinstance(raw_data, list):
                        # Format 2: list of objects
                        for item in raw_data:
                            if isinstance(item, dict):
                                price = item.get("price") or item.get("p") or item.get("priceLevel")
                                value = item.get("liquidation") or item.get("liq") or item.get("vol") or item.get("value") or item.get("amount")
                                
                                if price and value:
                                    try:
                                        price_float = float(price)
                                        value_float = float(value)
                                        if value_float > 100000:  # Min $100k
                                            liquidation_levels.append({
                                                "price": price_float,
                                                "value": value_float,
                                                "source": "coinglass_heatmap"
                                            })
                                    except (ValueError, TypeError):
                                        continue
                    
                    logger.info(f"[CoinGlass Heatmap] Parsed {len(liquidation_levels)} liquidation levels")
                    
                    if liquidation_levels:
                        # Sort by value (highest first)
                        liquidation_levels.sort(key=lambda x: x["value"], reverse=True)
                        
                        # Log top 5 for debugging
                        for i, lv in enumerate(liquidation_levels[:5]):
                            logger.info(f"[CoinGlass Heatmap] Level {i+1}: ${lv['price']:,.0f} = ${lv['value']/1e6:.2f}M")
                        
                        return {
                            "liquidation_levels": liquidation_levels,
                            "total_levels": len(liquidation_levels),
                            "source": "coinglass_heatmap_model2",
                            "timestamp": datetime.now(timezone.utc).isoformat()
                        }
                    else:
                        # Log raw data structure for debugging
                        logger.warning(f"[CoinGlass Heatmap] No levels parsed. Raw data sample: {str(raw_data)[:500]}")
                else:
                    logger.error(f"[CoinGlass Heatmap] API error: code={data.get('code')}, msg={data.get('msg', 'no message')}")
            else:
                logger.error(f"[CoinGlass Heatmap] HTTP error: {response.status_code}")
                logger.error(f"[CoinGlass Heatmap] Response: {response.text[:500]}")
        
    except Exception as e:
        logger.error(f"[CoinGlass Heatmap] Exception: {type(e).__name__}: {e}")
    
    return None


async def get_full_liquidation_data(current_price: float = None):
    """
    Get complete liquidation data combining totals AND price levels.
    This is the main function that should be called by magnet/zone engines.
    """
    # Get basic liquidation stats (24h totals etc)
    basic_data = await fetch_coinglass_liquidation() or {}
    
    # Get heatmap with price levels
    heatmap_data = await fetch_coinglass_liquidation_heatmap(current_price)
    
    # Combine results
    result = {
        **basic_data,
        "liquidation_levels": heatmap_data.get("liquidation_levels", []) if heatmap_data else [],
        "heatmap_source": heatmap_data.get("source") if heatmap_data else None,
        "levels_count": len(heatmap_data.get("liquidation_levels", [])) if heatmap_data else 0
    }
    
    logger.info(f"[Full Liquidation] Returning {result.get('levels_count', 0)} levels")
    return result


