# NEW V3.3 COINGLASS DATA FETCHERS - Long/Short Ratios, Buy/Sell Volume
# ═══════════════════════════════════════════════════════════════════════════════

async def fetch_coinglass_long_short_ratio():
    """
    Fetch Global Long/Short Account Ratio from CoinGlass.
    This shows what percentage of accounts are long vs short across exchanges.
    
    Returns:
    - global_ratio: Overall long/short ratio (>1 = more longs, <1 = more shorts)
    - long_account_percent: % of accounts that are long
    - short_account_percent: % of accounts that are short
    - top_trader_ratio: Top traders' long/short ratio
    - top_position_ratio: Top positions' long/short ratio
    """
    try:
        if not COINGLASS_API_KEY:
            logger.warning("[CoinGlass L/S Ratio] No API key configured")
            return None
        
        headers = {"CG-API-KEY": COINGLASS_API_KEY, "accept": "application/json"}
        result = {}
        
        async with httpx.AsyncClient(timeout=15.0) as http_client:
            # 1. Global Long/Short Account Ratio
            try:
                response = await http_client.get(
                    f"{COINGLASS_API_URL}/futures/global-long-short-account-ratio/history",
                    params={"symbol": "BTC", "interval": "1h", "limit": 5},
                    headers=headers
                )
                if response.status_code == 200:
                    data = response.json()
                    if data.get("code") == "0" and data.get("data"):
                        latest = data["data"][-1] if data["data"] else {}
                        result["global_ratio"] = float(latest.get("longShortRatio", 1.0))
                        result["long_account_percent"] = float(latest.get("longAccount", 50))
                        result["short_account_percent"] = float(latest.get("shortAccount", 50))
                        logger.info(f"[CoinGlass L/S Ratio] Global: {result['global_ratio']:.2f} (Long: {result['long_account_percent']:.1f}%)")
                    else:
                        logger.warning(f"[CoinGlass L/S Ratio] Global API returned code: {data.get('code')} - may be rate limited")
                elif response.status_code == 429:
                    logger.warning("[CoinGlass L/S Ratio] Rate limited (429) on global ratio")
                else:
                    logger.warning(f"[CoinGlass L/S Ratio] Global API returned status: {response.status_code}")
            except Exception as e:
                logger.debug(f"[CoinGlass L/S Ratio] Global ratio error: {e}")
            
            # Small delay to avoid rate limiting
            await asyncio.sleep(0.2)
            
            # 2. Top Trader Long/Short Account Ratio
            try:
                response = await http_client.get(
                    f"{COINGLASS_API_URL}/futures/top-long-short-account-ratio/history",
                    params={"symbol": "BTC", "interval": "1h", "limit": 5},
                    headers=headers
                )
                if response.status_code == 200:
                    data = response.json()
                    if data.get("code") == "0" and data.get("data"):
                        latest = data["data"][-1] if data["data"] else {}
                        result["top_trader_ratio"] = float(latest.get("longShortRatio", 1.0))
                        result["top_long_percent"] = float(latest.get("longAccount", 50))
                        result["top_short_percent"] = float(latest.get("shortAccount", 50))
                        logger.info(f"[CoinGlass L/S Ratio] Top Traders: {result['top_trader_ratio']:.2f}")
                    else:
                        logger.warning(f"[CoinGlass L/S Ratio] Top trader API returned code: {data.get('code')}")
                elif response.status_code == 429:
                    logger.warning("[CoinGlass L/S Ratio] Rate limited (429) on top traders")
            except Exception as e:
                logger.debug(f"[CoinGlass L/S Ratio] Top trader error: {e}")
            
            await asyncio.sleep(0.2)
            
            # 3. Top Position Long/Short Ratio
            try:
                response = await http_client.get(
                    f"{COINGLASS_API_URL}/futures/top-long-short-position-ratio/history",
                    params={"symbol": "BTC", "interval": "1h", "limit": 5},
                    headers=headers
                )
                if response.status_code == 200:
                    data = response.json()
                    if data.get("code") == "0" and data.get("data"):
                        latest = data["data"][-1] if data["data"] else {}
                        result["top_position_ratio"] = float(latest.get("longShortRatio", 1.0))
                        logger.info(f"[CoinGlass L/S Ratio] Top Positions: {result['top_position_ratio']:.2f}")
            except Exception as e:
                logger.debug(f"[CoinGlass L/S Ratio] Top position error: {e}")
        
        if result:
            return result
        logger.warning("[CoinGlass L/S Ratio] No data retrieved - possibly rate limited")
        return None
        
    except Exception as e:
        logger.error(f"[CoinGlass L/S Ratio] Error: {e}")
        return None


async def fetch_coinglass_taker_buy_sell():
    """
    Fetch Aggregated Taker Buy/Sell Volume from CoinGlass.
    This shows aggressive buying vs selling activity (market orders).
    
    Returns:
    - buy_ratio: Percentage of volume that is aggressive buying
    - sell_ratio: Percentage of volume that is aggressive selling
    - buy_volume: Absolute buy volume
    - sell_volume: Absolute sell volume
    - net_flow: buy_volume - sell_volume (positive = buying pressure)
    """
    try:
        if not COINGLASS_API_KEY:
            return None
        
        headers = {"CG-API-KEY": COINGLASS_API_KEY, "accept": "application/json"}
        
        async with httpx.AsyncClient(timeout=15.0) as http_client:
            response = await http_client.get(
                f"{COINGLASS_API_URL}/futures/aggregated-taker-buy-sell-volume/history",
                params={"symbol": "BTC", "interval": "1h", "limit": 5},
                headers=headers
            )
            
            if response.status_code == 200:
                data = response.json()
                if data.get("code") == "0" and data.get("data"):
                    latest = data["data"][-1] if data["data"] else {}
                    
                    buy_vol = float(latest.get("buyVol", 0))
                    sell_vol = float(latest.get("sellVol", 0))
                    total_vol = buy_vol + sell_vol
                    
                    result = {
                        "buy_volume": buy_vol,
                        "sell_volume": sell_vol,
                        "buy_ratio": (buy_vol / total_vol * 100) if total_vol > 0 else 50,
                        "sell_ratio": (sell_vol / total_vol * 100) if total_vol > 0 else 50,
                        "net_flow": buy_vol - sell_vol,
                        "pressure_direction": "BUY" if buy_vol > sell_vol * 1.1 else ("SELL" if sell_vol > buy_vol * 1.1 else "BALANCED")
                    }
                    
                    logger.info(f"[CoinGlass Buy/Sell] Ratio: {result['buy_ratio']:.1f}% buy / {result['sell_ratio']:.1f}% sell, "
                               f"Pressure: {result['pressure_direction']}")
                    return result
        
        return None
        
    except Exception as e:
        logger.error(f"[CoinGlass Buy/Sell] Error: {e}")
        return None


async def fetch_coinglass_derivatives_context():
    """
    Fetch complete derivatives context for V3 intelligence modules.
    Combines: Long/Short Ratios, Buy/Sell Volume, OI, Liquidations.
    
    This is the main function that modules should call for derivatives data.
    """
    try:
        # Fetch all data in parallel
        ls_ratio_task = fetch_coinglass_long_short_ratio()
        buy_sell_task = fetch_coinglass_taker_buy_sell()
        oi_task = fetch_coinglass_open_interest()
        liq_task = fetch_coinglass_liquidation()
        
        ls_ratio, buy_sell, oi_data, liq_data = await asyncio.gather(
            ls_ratio_task, buy_sell_task, oi_task, liq_task,
            return_exceptions=True
        )
        
        # Handle exceptions
        ls_ratio = ls_ratio if not isinstance(ls_ratio, Exception) else None
        buy_sell = buy_sell if not isinstance(buy_sell, Exception) else None
        oi_data = oi_data if not isinstance(oi_data, Exception) else None
        liq_data = liq_data if not isinstance(liq_data, Exception) else None
        
        # Calculate derivatives bias
        derivatives_bias = "NEUTRAL"
        derivatives_strength = 0
        
        bias_signals = []
        
        # Long/Short Ratio Analysis
        if ls_ratio:
            global_ratio = ls_ratio.get("global_ratio", 1.0)
            top_ratio = ls_ratio.get("top_trader_ratio", 1.0)
            
            # Crowd positioning (contrarian signal when extreme)
            if global_ratio > 1.5:
                bias_signals.append(("BEARISH", 20, "crowd_overcrowded_long"))
            elif global_ratio < 0.67:
                bias_signals.append(("BULLISH", 20, "crowd_overcrowded_short"))
            elif global_ratio > 1.2:
                bias_signals.append(("BEARISH", 10, "crowd_leaning_long"))
            elif global_ratio < 0.83:
                bias_signals.append(("BULLISH", 10, "crowd_leaning_short"))
            
            # Top traders (follow the smart money)
            if top_ratio > 1.3:
                bias_signals.append(("BULLISH", 25, "top_traders_long"))
            elif top_ratio < 0.77:
                bias_signals.append(("BEARISH", 25, "top_traders_short"))
        
        # Buy/Sell Pressure Analysis
        if buy_sell:
            pressure = buy_sell.get("pressure_direction", "BALANCED")
            buy_ratio = buy_sell.get("buy_ratio", 50)
            
            if pressure == "BUY" and buy_ratio > 55:
                bias_signals.append(("BULLISH", 15, "aggressive_buying"))
            elif pressure == "SELL" and buy_ratio < 45:
                bias_signals.append(("BEARISH", 15, "aggressive_selling"))
        
        # OI Trend Analysis
        if oi_data:
            oi_change = oi_data.get("change_24h", 0)
            if oi_change > 5:
                bias_signals.append(("FOLLOW_TREND", 10, "oi_expansion"))
            elif oi_change < -5:
                bias_signals.append(("REVERSAL", 10, "oi_contraction"))
        
        # Liquidation Pressure Analysis
        if liq_data:
            long_liq = liq_data.get("long_liquidation_24h", 0)
            short_liq = liq_data.get("short_liquidation_24h", 0)
            total_liq = long_liq + short_liq
            
            if total_liq > 0:
                long_pct = (long_liq / total_liq) * 100
                if long_pct > 65:
                    bias_signals.append(("BEARISH", 15, "long_liquidation_cascade"))
                elif long_pct < 35:
                    bias_signals.append(("BULLISH", 15, "short_squeeze"))
        
        # Calculate final bias
        bullish_score = sum(s[1] for s in bias_signals if s[0] == "BULLISH")
        bearish_score = sum(s[1] for s in bias_signals if s[0] == "BEARISH")
        
        if bullish_score > bearish_score + 15:
            derivatives_bias = "BULLISH"
            derivatives_strength = min(bullish_score, 100)
        elif bearish_score > bullish_score + 15:
            derivatives_bias = "BEARISH"
            derivatives_strength = min(bearish_score, 100)
        else:
            derivatives_bias = "NEUTRAL"
            derivatives_strength = max(bullish_score, bearish_score)
        
        return {
            "long_short_ratio": ls_ratio,
            "buy_sell": buy_sell,
            "open_interest": oi_data,
            "liquidation": liq_data,
            "derivatives_bias": derivatives_bias,
            "derivatives_strength": derivatives_strength,
            "bias_signals": [s[2] for s in bias_signals],
            "data_available": bool(ls_ratio or buy_sell or oi_data or liq_data)
        }
        
    except Exception as e:
        logger.error(f"[CoinGlass Derivatives Context] Error: {e}")
        return {
            "derivatives_bias": "NEUTRAL",
            "derivatives_strength": 0,
            "data_available": False
        }


async def generate_open_interest(current_price: float, candles: List[dict] = None, lang: str = "it") -> OpenInterest:
    """Generate Open Interest data from CoinGlass API"""
    
    # Try to get real CoinGlass data
    cg_data = await fetch_coinglass_open_interest()
    
    if cg_data:
        total_oi = cg_data["total_oi"]
        change_1h = cg_data["change_1h"]
        change_4h = cg_data["change_4h"]
        change_24h = cg_data["change_24h"]
        
        # Determine trend with translated signal
        if change_24h > 3:
            trend = "increasing"
            signal = get_translation("oi_increasing", lang)
        elif change_24h < -3:
            trend = "decreasing"
            signal = get_translation("oi_decreasing", lang)
        else:
            trend = "stable"
            signal = get_translation("oi_stable", lang)
        
        # Estimate exchange distribution based on typical market share
        exchanges = [
            {"name": "Binance", "oi": round(total_oi * 0.42, 2), "share": 42},
            {"name": "CME", "oi": round(total_oi * 0.22, 2), "share": 22},
            {"name": "Bybit", "oi": round(total_oi * 0.15, 2), "share": 15},
            {"name": "OKX", "oi": round(total_oi * 0.12, 2), "share": 12},
            {"name": "Others", "oi": round(total_oi * 0.09, 2), "share": 9},
        ]
        
        update_data_freshness("open_interest", True, "CoinGlass")
        
        return OpenInterest(
            total_oi=total_oi,
            change_1h=change_1h,
            change_4h=change_4h,
            change_24h=change_24h,
            trend=trend,
            exchanges=exchanges,
            signal=signal,
            data_source="CoinGlass",
            data_available=True,
            freshness_status="fresh",
            age_seconds=0
        )
    
    # DATA UNAVAILABLE - No random fallback
    # Return explicit "unavailable" state instead of fake data
    update_data_freshness("open_interest", False)
    
    return OpenInterest(
        total_oi=0,
        change_1h=0,
        change_4h=0,
        change_24h=0,
        trend="unknown",
        exchanges=[],
        signal=get_translation("api_unavailable", lang) + " - Open Interest data not available",
        data_source="Unavailable",
        data_available=False,
        freshness_status="unavailable",
        age_seconds=None
    )

async def generate_funding_rate(orderbook: dict = None, liquidation_data: dict = None, lang: str = "it") -> FundingRate:
    """Generate Funding Rate data based on liquidation imbalance from CoinGlass"""
    
    # Get liquidation data to infer funding sentiment
    liq_data = liquidation_data or await fetch_coinglass_liquidation()
    
    if liq_data:
        long_liq = liq_data.get("long_liquidation_24h", 0)
        short_liq = liq_data.get("short_liquidation_24h", 0)
        total_liq = long_liq + short_liq
        
        # Infer funding from liquidation imbalance
        if total_liq > 0:
            long_ratio = long_liq / total_liq
            short_ratio = short_liq / total_liq
            
            # If more longs liquidated, market was bearish, funding likely negative
            # If more shorts liquidated, market was bullish, funding likely positive
            if long_ratio > 0.55:
                current_rate = -0.005 - (long_ratio - 0.5) * 0.02
                payer = "shorts"
                sentiment = "bearish"
                overcrowded = "shorts" if long_ratio > 0.65 else None
                signal_text = get_translation("more_longs_liquidated", lang, long_ratio * 100)
            elif short_ratio > 0.55:
                current_rate = 0.005 + (short_ratio - 0.5) * 0.02
                payer = "longs"
                sentiment = "bullish"
                overcrowded = "longs" if short_ratio > 0.65 else None
                signal_text = get_translation("more_shorts_liquidated", lang, short_ratio * 100)
            else:
                current_rate = 0.001
                payer = "longs"
                sentiment = "neutral"
                overcrowded = None
                signal_text = get_translation("balanced_liquidations", lang)
            
            update_data_freshness("funding_rate", True, "CoinGlass")
            
            return FundingRate(
                current_rate=round(current_rate, 4),
                annualized_rate=round(current_rate * 3 * 365, 2),
                payer=payer,
                sentiment=sentiment,
                overcrowded=overcrowded,
                signal_text=signal_text,
                data_source="CoinGlass (Liquidation-derived)",
                data_available=True,
                freshness_status="fresh",
                age_seconds=0
            )
    
    # DATA UNAVAILABLE - No random fallback
    # Return explicit "unavailable" state instead of fake data
    update_data_freshness("funding_rate", False)
    
    return FundingRate(
        current_rate=0,
        annualized_rate=0,
        payer="unknown",
        sentiment="unknown",
        overcrowded=None,
        signal_text=get_translation("api_unavailable", lang) + " - Funding Rate data not available",
        data_source="Unavailable",
        data_available=False,
        freshness_status="unavailable",
        age_seconds=None
    )

# ============== MARKET ENERGY / COMPRESSION DETECTOR ==============

def analyze_market_energy(
    candles: List[dict],
    current_price: float,
    aggregated_orderbook: dict,
    open_interest_data: dict = None,
    liquidity_clusters: List = None,
    derivatives_context: dict = None,  # V3.3: New parameter for derivatives data
    lang: str = "it"
) -> MarketEnergy:
    """
    Market Energy / Compression Detector v2.0 (Enhanced)
    
    V3.3 ENHANCEMENTS:
    - Integrates CoinGlass buy/sell ratio for aggressive participation detection
    - Integrates liquidation pressure for squeeze/acceleration potential
    - Calculates overall "fuel" score based on derivatives pressure
    
    Detects when BTC is building energy before a significant move by analyzing:
    1. Price range compression
    2. Volatility compression
    3. Open Interest behavior during compression
    4. Liquidity build-up on both sides
    5. Order book pressure build-up
    6. [V3.3] Buy/Sell aggression pressure
    7. [V3.3] Liquidation acceleration/pressure
    
    Returns energy score, compression level, fuel state, and breakout probability.
    """
    
    signals = []
    energy_score = 0
    
    # ======== 1. PRICE RANGE COMPRESSION ========
    range_width_percent = 0
    compression_score = 0
    compression_threshold = 3.0  # Default threshold (percentage)
    expansion_readiness = "LOW"
    
    if candles and len(candles) >= 20:
        # Calculate recent trading range (last 20 candles = ~80 hours on 4H)
        recent_highs = [c["high"] for c in candles[-20:]]
        recent_lows = [c["low"] for c in candles[-20:]]
        
        period_high = max(recent_highs)
        period_low = min(recent_lows)
        range_width = period_high - period_low
        range_width_percent = (range_width / current_price) * 100
        
        # Compare to longer-term range (last 50 candles)
        if len(candles) >= 50:
            longer_highs = [c["high"] for c in candles[-50:]]
            longer_lows = [c["low"] for c in candles[-50:]]
            longer_range = max(longer_highs) - min(longer_lows)
            longer_range_pct = (longer_range / current_price) * 100
            
            # Calculate dynamic compression threshold (50% of longer range = HIGH compression zone)
            compression_threshold = round(longer_range_pct * 0.5, 2)
            
            # Compression ratio: if recent range is much smaller than longer range
            if longer_range_pct > 0:
                compression_ratio = range_width_percent / longer_range_pct
                
                if compression_ratio < 0.3:
                    compression_score = 100
                    signals.append(get_translation("extreme_compression", lang, range_width_percent))
                elif compression_ratio < 0.5:
                    compression_score = 75
                    signals.append(get_translation("high_compression", lang, range_width_percent))
                elif compression_ratio < 0.7:
                    compression_score = 50
                    signals.append(get_translation("moderate_compression", lang, range_width_percent))
                else:
                    compression_score = 25
                
                # ======== EXPANSION READINESS ========
                # Measures how close the market is to volatility expansion
                # Based on: compression_ratio (lower = more compressed = closer to expansion)
                # Also considers time in compression and energy buildup
                if compression_ratio < 0.3:
                    # Extremely compressed - expansion is imminent
                    expansion_readiness = "HIGH"
                elif compression_ratio < 0.5:
                    # Significantly compressed - expansion is building
                    expansion_readiness = "MEDIUM"
                else:
                    # Not yet in compression zone
                    expansion_readiness = "LOW"
        
        # Also check very recent compression (last 5 candles)
        if len(candles) >= 5:
            very_recent_range = max(c["high"] for c in candles[-5:]) - min(c["low"] for c in candles[-5:])
            very_recent_pct = (very_recent_range / current_price) * 100
            
            if very_recent_pct < 0.5:
                compression_score += 20
                signals.append(get_translation("tight_recent_range", lang, very_recent_pct))
                # Ultra-tight recent range boosts expansion readiness
                if expansion_readiness == "MEDIUM":
                    expansion_readiness = "HIGH"
    
    energy_score += compression_score * 0.25  # 25% weight
    
    # ======== 2. VOLATILITY COMPRESSION ========
    volatility_compression = 0
    
    if candles and len(candles) >= 20:
        # Calculate ATR-style volatility (True Range)
        recent_tr = []
        for i in range(-14, 0):
            if i >= -len(candles):
                c = candles[i]
                prev_close = candles[i-1]["close"] if i > -len(candles) else c["open"]
                tr = max(
                    c["high"] - c["low"],
                    abs(c["high"] - prev_close),
                    abs(c["low"] - prev_close)
                )
                recent_tr.append(tr / current_price * 100)  # As percentage
        
        if recent_tr:
            current_atr = sum(recent_tr) / len(recent_tr)
            
            # Compare to longer-term volatility
            if len(candles) >= 50:
                longer_tr = []
                for i in range(-50, -14):
                    if i >= -len(candles):
                        c = candles[i]
                        prev_close = candles[i-1]["close"] if i > -len(candles) else c["open"]
                        tr = max(
                            c["high"] - c["low"],
                            abs(c["high"] - prev_close),
                            abs(c["low"] - prev_close)
                        )
                        longer_tr.append(tr / current_price * 100)
                
                if longer_tr:
                    avg_longer_atr = sum(longer_tr) / len(longer_tr)
                    
                    if avg_longer_atr > 0:
                        vol_ratio = current_atr / avg_longer_atr
                        
                        if vol_ratio < 0.4:
                            volatility_compression = 100
                            signals.append(get_translation("extreme_vol_compression", lang))
                        elif vol_ratio < 0.6:
                            volatility_compression = 75
                            signals.append(get_translation("high_vol_compression", lang))
                        elif vol_ratio < 0.8:
                            volatility_compression = 50
                        else:
                            volatility_compression = 25
    
    energy_score += volatility_compression * 0.20  # 20% weight
    
    # ======== 3. OPEN INTEREST BEHAVIOR ========
    oi_trend = "STABLE"
    oi_change_percent = 0
    oi_score = 0
    
    if open_interest_data:
        oi_change_1h = open_interest_data.get("change_1h", 0)
        oi_change_24h = open_interest_data.get("change_24h", 0)
        oi_change_percent = oi_change_24h
        
        # Rising OI during compression = positioning building = energy
        if oi_change_24h > 2:
            oi_trend = "RISING"
            oi_score = 100
            signals.append(get_translation("oi_rising_compression", lang, oi_change_24h))
        elif oi_change_24h > 0.5:
            oi_trend = "RISING"
            oi_score = 60
        elif oi_change_24h < -2:
            oi_trend = "FALLING"
            oi_score = 20
        elif oi_change_24h < -0.5:
            oi_trend = "FALLING"
            oi_score = 30
        else:
            oi_trend = "STABLE"
            oi_score = 40
        
        # Extra bonus if OI is rising while price is compressed
        if oi_trend == "RISING" and compression_score >= 50:
            oi_score += 20
            signals.append(get_translation("oi_building_during_compression", lang))
    
    energy_score += oi_score * 0.25  # 25% weight
    
    # ======== 4. LIQUIDITY BUILD-UP ========
    liquidity_buildup = "NONE"
    liquidity_above = 0
    liquidity_below = 0
    liquidity_score = 0
    
    if liquidity_clusters:
        above_clusters = [c for c in liquidity_clusters if hasattr(c, 'side') and c.side == "above"]
        below_clusters = [c for c in liquidity_clusters if hasattr(c, 'side') and c.side == "below"]
        
        liquidity_above = sum(c.estimated_value for c in above_clusters if hasattr(c, 'estimated_value'))
        liquidity_below = sum(c.estimated_value for c in below_clusters if hasattr(c, 'estimated_value'))
        
        total_liquidity = liquidity_above + liquidity_below
        
        # Check for liquidity on both sides (squeeze setup)
        if liquidity_above > 0 and liquidity_below > 0:
            # Balance check: if liquidity is building on both sides
            if liquidity_above > 1000000 and liquidity_below > 1000000:
                balance_ratio = min(liquidity_above, liquidity_below) / max(liquidity_above, liquidity_below)
                
                if balance_ratio > 0.6:  # Relatively balanced
                    liquidity_buildup = "STRONG"
                    liquidity_score = 100
                    signals.append(get_translation("strong_liquidity_both_sides", lang, liquidity_above/1000000, liquidity_below/1000000))
                elif balance_ratio > 0.3:
                    liquidity_buildup = "MODERATE"
                    liquidity_score = 60
                    signals.append(get_translation("moderate_liquidity_buildup", lang))
                else:
                    liquidity_buildup = "WEAK"
                    liquidity_score = 30
            elif total_liquidity > 500000:
                liquidity_buildup = "WEAK"
                liquidity_score = 30
    
    energy_score += liquidity_score * 0.15  # 15% weight
    
    # ======== 5. ORDER BOOK PRESSURE BUILD-UP ========
    orderbook_pressure = "NONE"
    orderbook_score = 0
    
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        total_bid_depth = aggregated_orderbook.get("total_bid_depth", 0)
        total_ask_depth = aggregated_orderbook.get("total_ask_depth", 0)
        
        total_depth = total_bid_depth + total_ask_depth
        
        if total_depth > 0:
            # Check for large orders stacking on both sides
            if bids and asks:
                bid_volumes = [float(b[1]) for b in bids[:30]]
                ask_volumes = [float(a[1]) for a in asks[:30]]
                
                avg_bid = sum(bid_volumes) / len(bid_volumes) if bid_volumes else 0
                avg_ask = sum(ask_volumes) / len(ask_volumes) if ask_volumes else 0
                
                # Count large orders (walls)
                large_bids = sum(1 for v in bid_volumes if v > avg_bid * 3)
                large_asks = sum(1 for v in ask_volumes if v > avg_ask * 3)
                
                if large_bids >= 3 and large_asks >= 3:
                    orderbook_pressure = "STRONG"
                    orderbook_score = 100
                    signals.append(get_translation("strong_orderbook_buildup", lang, large_bids, large_asks))
                elif large_bids >= 2 or large_asks >= 2:
                    orderbook_pressure = "BUILDING"
                    orderbook_score = 50
                else:
                    orderbook_score = 20
    
    energy_score += orderbook_score * 0.15  # 15% weight
    
    # ======== 6. DETERMINE COMPRESSION LEVEL ========
    avg_compression = (compression_score + volatility_compression) / 2
    
    if avg_compression >= 75:
        compression_level = "HIGH"
    elif avg_compression >= 50:
        compression_level = "MEDIUM"
    else:
        compression_level = "LOW"
    
    # ======== 7. DETERMINE BREAKOUT PROBABILITY ========
    if energy_score >= 70:
        breakout_probability = "HIGH"
    elif energy_score >= 45:
        breakout_probability = "MEDIUM"
    else:
        breakout_probability = "LOW"
    
    # ======== 8. DETERMINE EXPECTED DIRECTION ========
    expected_direction = None
    
    if aggregated_orderbook:
        total_bid_depth = aggregated_orderbook.get("total_bid_depth", 0)
        total_ask_depth = aggregated_orderbook.get("total_ask_depth", 0)
        
        if total_bid_depth + total_ask_depth > 0:
            imbalance = (total_bid_depth - total_ask_depth) / (total_bid_depth + total_ask_depth) * 100
            
            if imbalance > 20:
                expected_direction = "UP"
            elif imbalance < -20:
                expected_direction = "DOWN"
            else:
                expected_direction = "UNCLEAR"
    
    # Check liquidity direction as secondary indicator
    if expected_direction == "UNCLEAR" and liquidity_above > 0 and liquidity_below > 0:
        if liquidity_above > liquidity_below * 1.5:
            expected_direction = "UP"  # More liquidity above = price seeks it
        elif liquidity_below > liquidity_above * 1.5:
            expected_direction = "DOWN"
    
    # ======== 9. EXPANSION WARNING ========
    expansion_warning = False
    
    if compression_level == "HIGH" and breakout_probability in ["HIGH", "MEDIUM"]:
        if oi_trend == "RISING" or liquidity_buildup in ["STRONG", "MODERATE"]:
            expansion_warning = True
            signals.append(get_translation("expansion_likely", lang))
    
    # ======== 10. V3.3 DERIVATIVES FUEL ANALYSIS ========
    energy_state = "LOW"
    fuel_score = 0
    buy_sell_pressure = "BALANCED"
    buy_sell_ratio = 50.0
    liquidation_acceleration = "NONE"
    liquidation_pressure_side = "BALANCED"
    fuel_explanation = None
    
    if derivatives_context and derivatives_context.get("data_available"):
        # Buy/Sell Aggression Analysis
        buy_sell_data = derivatives_context.get("buy_sell", {})
        if buy_sell_data:
            buy_sell_ratio = buy_sell_data.get("buy_ratio", 50)
            bs_pressure = buy_sell_data.get("pressure_direction", "BALANCED")
            buy_sell_pressure = bs_pressure
            
            # Strong buy/sell imbalance = fuel for move
            if buy_sell_ratio > 58:
                fuel_score += 25
                signals.append(get_translation("aggressive_buying_detected", lang) if lang != "en" else f"Aggressive buying detected ({buy_sell_ratio:.0f}%)")
            elif buy_sell_ratio < 42:
                fuel_score += 25
                signals.append(get_translation("aggressive_selling_detected", lang) if lang != "en" else f"Aggressive selling detected ({100-buy_sell_ratio:.0f}%)")
            elif buy_sell_ratio > 53 or buy_sell_ratio < 47:
                fuel_score += 10
        
        # Liquidation Pressure Analysis
        liq_data = derivatives_context.get("liquidation", {})
        if liq_data:
            long_liq = liq_data.get("long_liquidation_24h", 0)
            short_liq = liq_data.get("short_liquidation_24h", 0)
            total_liq = long_liq + short_liq
            
            # High liquidation activity = acceleration potential
            if total_liq > 100000000:  # >$100M liquidated
                liquidation_acceleration = "ACTIVE"
                fuel_score += 30
                
                if total_liq > 0:
                    long_pct = (long_liq / total_liq) * 100
                    if long_pct > 60:
                        liquidation_pressure_side = "LONG"
                        signals.append(get_translation("long_liquidation_pressure", lang) if lang != "en" else f"Long liquidation pressure ({long_pct:.0f}%)")
                    elif long_pct < 40:
                        liquidation_pressure_side = "SHORT"
                        signals.append(get_translation("short_squeeze_building", lang) if lang != "en" else f"Short squeeze building ({100-long_pct:.0f}%)")
            elif total_liq > 50000000:  # >$50M
                liquidation_acceleration = "BUILDING"
                fuel_score += 15
        
        # OI Expansion (new positioning = fuel)
        oi_data = derivatives_context.get("open_interest", {})
        if oi_data:
            oi_24h_change = oi_data.get("change_24h", 0)
            if oi_24h_change > 3:
                fuel_score += 25
                signals.append(get_translation("oi_expansion_fuel", lang) if lang != "en" else f"OI expansion adds fuel (+{oi_24h_change:.1f}%)")
            elif oi_24h_change > 1:
                fuel_score += 10
            elif oi_24h_change < -3:
                fuel_score -= 15  # OI contraction = less fuel
        
        # Calculate final fuel/energy state
        fuel_score = max(0, min(100, fuel_score))
        
        if fuel_score >= 60:
            energy_state = "HIGH"
        elif fuel_score >= 30:
            energy_state = "MEDIUM"
        else:
            energy_state = "LOW"
        
        # Build fuel explanation
        fuel_parts = []
        if energy_state == "HIGH":
            fuel_parts.append(get_translation("high_fuel_available", lang) if lang != "en" else "High fuel available for move")
            if buy_sell_pressure != "BALANCED":
                fuel_parts.append(f"({buy_sell_pressure} pressure)")
            if liquidation_acceleration != "NONE":
                fuel_parts.append(f"+ liquidation {liquidation_acceleration.lower()}")
        elif energy_state == "MEDIUM":
            fuel_parts.append(get_translation("moderate_fuel", lang) if lang != "en" else "Moderate fuel - move possible")
        else:
            fuel_parts.append(get_translation("low_fuel_choppy", lang) if lang != "en" else "Low fuel - expect choppy action")
        
        fuel_explanation = " ".join(fuel_parts)
    
    # ======== 11. BUILD EXPLANATION ========
    explanation = _build_energy_explanation(
        energy_score, compression_level, range_width_percent,
        oi_trend, oi_change_percent, liquidity_buildup,
        orderbook_pressure, breakout_probability, expected_direction,
        expansion_warning, lang
    )
    
    return MarketEnergy(
        energy_score=round(energy_score, 1),
        compression_level=compression_level,
        range_width_percent=round(range_width_percent, 2),
        compression_threshold=round(compression_threshold, 2),
        expansion_readiness=expansion_readiness,
        volatility_compression=round(volatility_compression, 1),
        oi_trend=oi_trend,
        oi_change_percent=round(oi_change_percent, 2),
        liquidity_buildup=liquidity_buildup,
        liquidity_above=round(liquidity_above, 0),
        liquidity_below=round(liquidity_below, 0),
        orderbook_pressure_buildup=orderbook_pressure,
        breakout_probability=breakout_probability,
        expected_direction=expected_direction,
        explanation=explanation,
        signals=signals[:5],
        expansion_warning=expansion_warning,
        data_source="Multi-Exchange + CoinGlass",
        # V3.3: Enhanced fuel analysis
        energy_state=energy_state,
        fuel_score=round(fuel_score, 1),
        buy_sell_pressure=buy_sell_pressure,
        buy_sell_ratio=round(buy_sell_ratio, 1),
        liquidation_acceleration=liquidation_acceleration,
        liquidation_pressure_side=liquidation_pressure_side,
        fuel_explanation=fuel_explanation
    )


def _build_energy_explanation(
    energy_score: float, compression_level: str, range_width: float,
    oi_trend: str, oi_change: float, liq_buildup: str,
    ob_pressure: str, breakout_prob: str, direction: str,
    expansion_warning: bool, lang: str
) -> str:
    """Build comprehensive explanation for market energy."""
    
    if expansion_warning:
        if direction == "UP":
            return get_translation("energy_expansion_bullish", lang, range_width, oi_change)
        elif direction == "DOWN":
            return get_translation("energy_expansion_bearish", lang, range_width, oi_change)
        else:
            return get_translation("energy_expansion_unclear", lang, range_width)
    
    if compression_level == "HIGH":
        if oi_trend == "RISING" and liq_buildup in ["STRONG", "MODERATE"]:
            return get_translation("energy_high_building", lang, range_width)
        elif oi_trend == "RISING":
            return get_translation("energy_high_oi_rising", lang, range_width, oi_change)
        else:
            return get_translation("energy_high_compressed", lang, range_width)
    
    elif compression_level == "MEDIUM":
        if oi_trend == "RISING":
            return get_translation("energy_medium_building", lang)
        else:
            return get_translation("energy_medium_consolidating", lang)
    
    else:  # LOW
        if breakout_prob == "LOW":
            return get_translation("energy_low_ranging", lang)
        else:
            return get_translation("energy_low_normal", lang)


# ============== MARKET REGIME DETECTION ==============

def detect_market_regime(
    market_bias: MarketBias,
    market_energy: MarketEnergy,
    liquidity_magnet: LiquidityMagnet,
    liquidity_ladder: LiquidityLadder,
    whale_activity: WhaleActivity,
    open_interest_data: dict,
    expected_move: float,
    trap_risk_detected: bool,
    current_price: float,
    supports: List,
    resistances: List,
    lang: str = "it"
) -> MarketRegime:
    """
    Market Regime Detection v1.0 - Classifies current market context.
    
    Regimes:
    - TREND: Strong directional bias, aligned factors, clear path
    - RANGE: Neutral/mixed bias, price between S/R, no clean breakout
    - COMPRESSION: Low volatility, OI rising, liquidity both sides, pre-breakout
    - EXPANSION: High energy, strong move, dominant direction, breakout active
    
    This module improves interpretation without forcing trades.
    """
    
    signals = []
    
    # ======== 1. EXTRACT KEY METRICS ========
    
    # Bias metrics
    bias_direction = market_bias.bias if market_bias else "NEUTRAL"
    bias_confidence = market_bias.confidence if market_bias else 50
    bias_strong = bias_confidence >= 60 and bias_direction in ["BULLISH", "BEARISH"]
    
    # Energy metrics
    energy_score = market_energy.energy_score if market_energy else 50
    compression_level = market_energy.compression_level if market_energy else "MEDIUM"
    breakout_prob = market_energy.breakout_probability if market_energy else "LOW"
    expansion_ready = market_energy.expansion_readiness if market_energy else "LOW"
    energy_state = compression_level  # Use compression level as energy state
    
    # Liquidity metrics
    magnet_direction = liquidity_magnet.target_direction if liquidity_magnet else "BALANCED"
    magnet_score = liquidity_magnet.magnet_score if liquidity_magnet else 50
    sweep_expectation = liquidity_magnet.sweep_expectation if liquidity_magnet else "NO_CLEAR_SWEEP"
    liq_above = liquidity_magnet.liquidity_above_total if liquidity_magnet else 0
    liq_below = liquidity_magnet.liquidity_below_total if liquidity_magnet else 0
    liq_balanced = abs(liq_above - liq_below) / max(liq_above + liq_below, 1) < 0.3
    
    # Whale metrics
    whale_direction = whale_activity.direction if whale_activity else "NEUTRAL"
    whale_strength = whale_activity.strength if whale_activity else 0
    whale_aligned = whale_direction in ["BUY", "SELL"] and whale_strength >= 40
    
    # OI metrics
    oi_change_1h = open_interest_data.get("change_1h", 0) if open_interest_data else 0
    oi_change_24h = open_interest_data.get("change_24h", 0) if open_interest_data else 0
    oi_rising = oi_change_1h > 0.5 or oi_change_24h > 2
    oi_falling = oi_change_1h < -0.5 or oi_change_24h < -2
    
    # Distance to S/R
    nearest_support = supports[0].price if supports else current_price * 0.95
    nearest_resistance = resistances[0].price if resistances else current_price * 1.05
    dist_to_support = ((current_price - nearest_support) / current_price) * 100
    dist_to_resistance = ((nearest_resistance - current_price) / current_price) * 100
    price_in_middle = dist_to_support > 0.5 and dist_to_resistance > 0.5
    near_sr = dist_to_support < 0.3 or dist_to_resistance < 0.3
    
    distance_to_sr = "NEAR" if near_sr else ("MEDIUM" if dist_to_support < 1 or dist_to_resistance < 1 else "FAR")
    
    # ======== 2. CALCULATE REGIME SCORES ========
    
    trend_score = 0
    range_score = 0
    compression_score = 0
    expansion_score = 0
    
    # ----- TREND Score -----
    # Strong directional bias
    if bias_strong:
        trend_score += 25
        signals.append(f"Strong {bias_direction} bias ({bias_confidence:.0f}%)")
    
    # Whales aligned with direction
    whale_bias_aligned = (
        (bias_direction == "BULLISH" and whale_direction == "BUY") or
        (bias_direction == "BEARISH" and whale_direction == "SELL")
    )
    if whale_bias_aligned and whale_strength >= 40:
        trend_score += 20
        signals.append(f"Whales aligned ({whale_direction})")
    
    # Liquidity aligned (clear path in trend direction)
    liq_bias_aligned = (
        (bias_direction == "BULLISH" and magnet_direction == "UP") or
        (bias_direction == "BEARISH" and magnet_direction == "DOWN")
    )
    if liq_bias_aligned:
        trend_score += 20
        signals.append(f"Liquidity path aligned ({magnet_direction})")
    
    # OI supportive (rising in trend)
    if oi_rising and bias_strong:
        trend_score += 15
    
    # No major trap conflict
    if not trap_risk_detected:
        trend_score += 10
    
    # Expected move decent
    if abs(expected_move) >= 0.5:
        trend_score += 10
    
    # ----- RANGE Score -----
    # Neutral or mixed bias
    if bias_direction == "NEUTRAL" or bias_confidence < 55:
        range_score += 25
        signals.append("Neutral/mixed market bias")
    
    # Moderate/low energy
    if compression_level in ["LOW", "MEDIUM"] and breakout_prob == "LOW":
        range_score += 20
    
    # Unclear magnet direction
    if magnet_direction == "BALANCED" or liq_balanced:
        range_score += 20
        signals.append("Balanced liquidity (no clear direction)")
    
    # Price between S/R
    if price_in_middle:
        range_score += 20
        signals.append(f"Price in range ({dist_to_support:.1f}% from support, {dist_to_resistance:.1f}% from resistance)")
    
    # No clean breakout
    if breakout_prob == "LOW":
        range_score += 15
    
    # ----- COMPRESSION Score -----
    # Low/medium volatility with energy building
    if compression_level == "LOW" or (compression_level == "MEDIUM" and expansion_ready in ["MEDIUM", "HIGH"]):
        compression_score += 25
        signals.append(f"Compression detected ({compression_level})")
    
    # OI increasing (positions building)
    if oi_rising:
        compression_score += 20
        signals.append(f"OI rising (+{oi_change_24h:.1f}% 24h)")
    
    # Whales active (preparing for move)
    if whale_strength >= 30:
        compression_score += 15
    
    # Liquidity above AND below (both sides loaded)
    if liq_above > 0 and liq_below > 0 and liq_balanced:
        compression_score += 20
        signals.append("Liquidity loaded both sides")
    
    # Price trapped before breakout
    if near_sr and breakout_prob in ["MEDIUM", "HIGH"]:
        compression_score += 20
        signals.append("Price near key level, breakout likely")
    
    # ----- EXPANSION Score -----
    # High energy
    if energy_score >= 65 or compression_level == "HIGH":
        expansion_score += 25
        signals.append(f"High market energy ({energy_score:.0f})")
    
    # Strong expected move
    if abs(expected_move) >= 1.0:
        expansion_score += 20
        signals.append(f"Strong expected move ({expected_move:.2f}%)")
    
    # Dominant liquidity direction
    if magnet_direction in ["UP", "DOWN"] and magnet_score >= 60:
        expansion_score += 20
        signals.append(f"Dominant liquidity direction ({magnet_direction})")
    
    # Whales confirm
    if whale_aligned:
        expansion_score += 15
    
    # Breaking or reclaiming key level
    if near_sr and (breakout_prob == "HIGH" or expansion_ready == "HIGH"):
        expansion_score += 20
        signals.append("Price at key level with high breakout probability")
    
    # ======== 3. DETERMINE REGIME ========
    
    scores = {
        "TREND": trend_score,
        "RANGE": range_score,
        "COMPRESSION": compression_score,
        "EXPANSION": expansion_score
    }
    
    # Find dominant regime
    regime = max(scores, key=scores.get)
    regime_strength = scores[regime]
    
    # Normalize strength (cap at 100)
    regime_strength = min(regime_strength, 100)
    
    # ======== 4. DETERMINE DIRECTIONAL BIAS ========
    
    if bias_direction == "BULLISH" and bias_confidence >= 55:
        directional_bias = "BULLISH"
    elif bias_direction == "BEARISH" and bias_confidence >= 55:
        directional_bias = "BEARISH"
    else:
        directional_bias = "NEUTRAL"
    
    # ======== 5. SUGGEST SETUP ========
    
    setup_suggestions = {
        "it": {
            "TREND": {
                "setup": "Preferire Trend Continuation",
                "explanation": "Mercato in trend: seguire la direzione dominante con setup di continuazione. Evitare controtrend."
            },
            "RANGE": {
                "setup": "Preferire Sweep Reversal",
                "explanation": "Mercato in range: cercare sweep ai confini del range per inversioni. Evitare breakout prematuri."
            },
            "COMPRESSION": {
                "setup": "Attendere Breakout / Conferma Sweep",
                "explanation": "Mercato in compressione: energia in accumulo. Attendere rottura chiara prima di entrare."
            },
            "EXPANSION": {
                "setup": "Continuazione Favorita, Evitare Entry Tardive",
                "explanation": "Mercato in espansione: movimento forte in corso. Se già dentro, gestire posizione. Se fuori, attendere pullback."
            }
        },
        "en": {
            "TREND": {
                "setup": "Prefer Trend Continuation",
                "explanation": "Trending market: follow the dominant direction with continuation setups. Avoid counter-trend."
            },
            "RANGE": {
                "setup": "Prefer Sweep Reversal",
                "explanation": "Ranging market: look for sweeps at range boundaries for reversals. Avoid premature breakouts."
            },
            "COMPRESSION": {
                "setup": "Wait for Breakout / Sweep Confirmation",
                "explanation": "Compressing market: energy building up. Wait for clear breakout before entering."
            },
            "EXPANSION": {
                "setup": "Continuation Favored, Avoid Late Entries",
                "explanation": "Expanding market: strong move in progress. If already in, manage position. If out, wait for pullback."
            }
        },
        "de": {
            "TREND": {
                "setup": "Trend Continuation bevorzugen",
                "explanation": "Trendender Markt: der dominanten Richtung mit Fortsetzungs-Setups folgen."
            },
            "RANGE": {
                "setup": "Sweep Reversal bevorzugen",
                "explanation": "Range-Markt: nach Sweeps an den Range-Grenzen für Umkehrungen suchen."
            },
            "COMPRESSION": {
                "setup": "Auf Breakout / Sweep-Bestätigung warten",
                "explanation": "Komprimierender Markt: Energie baut sich auf. Auf klaren Ausbruch warten."
            },
            "EXPANSION": {
                "setup": "Fortsetzung bevorzugt, späte Einstiege vermeiden",
                "explanation": "Expandierender Markt: starke Bewegung läuft. Auf Pullback warten."
            }
        },
        "pl": {
            "TREND": {
                "setup": "Preferuj Trend Continuation",
                "explanation": "Rynek w trendzie: podążaj za dominującym kierunkiem z setupami kontynuacji."
            },
            "RANGE": {
                "setup": "Preferuj Sweep Reversal",
                "explanation": "Rynek w zakresie: szukaj sweepów na granicach zakresu dla odwróceń."
            },
            "COMPRESSION": {
                "setup": "Czekaj na Breakout / Potwierdzenie Sweep",
                "explanation": "Kompresja rynku: energia się gromadzi. Czekaj na wyraźne wybicie."
            },
            "EXPANSION": {
                "setup": "Kontynuacja preferowana, unikaj późnych wejść",
                "explanation": "Rynek w ekspansji: silny ruch w toku. Czekaj na korektę."
            }
        }
    }
    
    lang_suggestions = setup_suggestions.get(lang, setup_suggestions["en"])
    suggested_setup = lang_suggestions[regime]["setup"]
    setup_explanation = lang_suggestions[regime]["explanation"]
    
    # ======== 6. BUILD EXPLANATION ========
    
    regime_names = {
        "it": {"TREND": "TREND", "RANGE": "RANGE", "COMPRESSION": "COMPRESSIONE", "EXPANSION": "ESPANSIONE"},
        "en": {"TREND": "TREND", "RANGE": "RANGE", "COMPRESSION": "COMPRESSION", "EXPANSION": "EXPANSION"},
        "de": {"TREND": "TREND", "RANGE": "RANGE", "COMPRESSION": "KOMPRESSION", "EXPANSION": "EXPANSION"},
        "pl": {"TREND": "TREND", "RANGE": "ZAKRES", "COMPRESSION": "KOMPRESJA", "EXPANSION": "EKSPANSJA"}
    }
    
    regime_display = regime_names.get(lang, regime_names["en"]).get(regime, regime)
    
    explanation_templates = {
        "it": f"Regime di mercato: {regime_display} (forza {regime_strength}%). {setup_explanation}",
        "en": f"Market regime: {regime_display} (strength {regime_strength}%). {setup_explanation}",
        "de": f"Marktregime: {regime_display} (Stärke {regime_strength}%). {setup_explanation}",
        "pl": f"Reżim rynkowy: {regime_display} (siła {regime_strength}%). {setup_explanation}"
    }
    
    explanation = explanation_templates.get(lang, explanation_templates["en"])
    
    # ======== 7. CALCULATE ALIGNMENT FLAGS ========
    
    bias_alignment = bias_strong
    whale_alignment = whale_bias_aligned if bias_strong else False
    liquidity_alignment = liq_bias_aligned if bias_strong else (magnet_direction != "BALANCED")
    oi_supportive = oi_rising if regime in ["TREND", "COMPRESSION"] else not oi_falling
    trap_risk_level = "HIGH" if trap_risk_detected else ("MEDIUM" if range_score > 60 else "LOW")
    
    # ======== 8. V3.3 TARGET PERMISSIVENESS ========
    # Regime determines how far targets can be set
    
    target_profile = "BALANCED"  # Default
    max_target_distance_pct = 2.0  # Default 2%
    target_constraint_reason = None
    
    if regime == "COMPRESSION":
        # Compression: only allow extended targets if breakout confirmed
        if breakout_prob == "HIGH" and (energy_score >= 60 or expansion_ready == "HIGH"):
            target_profile = "EXTENDED"
            max_target_distance_pct = 3.5
            target_constraint_reason = get_translation("compression_breakout_extended", lang) if lang != "en" else "Compression with high breakout probability - extended targets allowed"
        else:
            target_profile = "CONSERVATIVE"
            max_target_distance_pct = 1.5
            target_constraint_reason = get_translation("compression_wait_breakout", lang) if lang != "en" else "Compression without clear breakout - conservative targets only"
    
    elif regime == "RANGE":
        # Range: prefer bounded targets within range
        target_profile = "CONSERVATIVE"
        max_target_distance_pct = 1.5
        # Allow slightly more if strong pressure exists
        if energy_score >= 55 and (magnet_direction in ["UP", "DOWN"]):
            target_profile = "BALANCED"
            max_target_distance_pct = 2.0
            target_constraint_reason = get_translation("range_pressure_balanced", lang) if lang != "en" else "Range market with directional pressure - balanced targets"
        else:
            target_constraint_reason = get_translation("range_bounded_targets", lang) if lang != "en" else "Ranging market - targets bounded within range structure"
    
    elif regime == "TREND":
        # Trend: allow extended if bias and energy aligned
        if bias_alignment and energy_score >= 50:
            target_profile = "EXTENDED"
            max_target_distance_pct = 4.0
            target_constraint_reason = get_translation("trend_aligned_extended", lang) if lang != "en" else "Trending market with aligned bias and energy - extended targets allowed"
        elif bias_alignment:
            target_profile = "BALANCED"
            max_target_distance_pct = 2.5
            target_constraint_reason = get_translation("trend_balanced", lang) if lang != "en" else "Trending market - balanced targets"
        else:
            target_profile = "CONSERVATIVE"
            max_target_distance_pct = 1.5
            target_constraint_reason = get_translation("trend_weak_bias", lang) if lang != "en" else "Trend without strong bias alignment - conservative targets"
    
    elif regime == "EXPANSION":
        # Expansion: follow the move but don't chase
        if whale_alignment and liquidity_alignment:
            target_profile = "EXTENDED"
            max_target_distance_pct = 4.5
            target_constraint_reason = get_translation("expansion_fully_aligned", lang) if lang != "en" else "Expansion with full alignment - extended targets"
        else:
            target_profile = "BALANCED"
            max_target_distance_pct = 2.5
            target_constraint_reason = get_translation("expansion_partial_aligned", lang) if lang != "en" else "Expansion in progress - balanced targets, don't chase"
    
    return MarketRegime(
        regime=regime,
        regime_strength=regime_strength,
        directional_bias=directional_bias,
        suggested_setup=suggested_setup,
        setup_explanation=setup_explanation,
        trend_score=trend_score,
        range_score=range_score,
        compression_score=compression_score,
        expansion_score=expansion_score,
        bias_alignment=bias_alignment,
        whale_alignment=whale_alignment,
        liquidity_alignment=liquidity_alignment,
        energy_state=energy_state,
        oi_supportive=oi_supportive,
        trap_risk=trap_risk_level,
        distance_to_sr=distance_to_sr,
        signals=signals[:5],  # Limit to top 5 signals
        explanation=explanation,
        data_source="Multi-Factor Analysis",
        # V3.3: Target permissiveness
        target_profile=target_profile,
        max_target_distance_pct=round(max_target_distance_pct, 2),
        target_constraint_reason=target_constraint_reason
    )


# ============== SIGNAL ENGINE V3 - MULTI-TIMEFRAME ==============

# V3 Configuration
V3_SETUP_VALIDITY_HOURS = 8  # Setup expires after 8 hours (2 x 4H candles)
V3_5M_CACHE_TTL = 30  # 5M data cache: 30 seconds
V3_RETEST_ZONE_TOLERANCE = 0.002  # 0.2% tolerance for zone retest
V3_STOP_BUFFER_MIN = 0.001  # 0.1% minimum buffer
V3_STOP_BUFFER_MAX = 0.0025  # 0.25% maximum buffer

# 5M candles cache
v3_5m_cache = {
    "candles": None,
    "last_update": None
}


async def fetch_5m_candles() -> List[dict]:
    """
    Fetch 5-minute candles for V3 execution timing.
    Uses separate cache with 30s TTL for fresher data.
    """
    global v3_5m_cache
    
    try:
        # Check cache
        if (v3_5m_cache["candles"] and v3_5m_cache["last_update"] and
            (datetime.now(timezone.utc) - v3_5m_cache["last_update"]).seconds < V3_5M_CACHE_TTL):
            return v3_5m_cache["candles"]
        
        # Fetch fresh 5M candles from Kraken
        candles = await fetch_kraken_ohlc(interval=5)  # 5-minute interval
        
        if candles and len(candles) > 0:
            v3_5m_cache["candles"] = candles
            v3_5m_cache["last_update"] = datetime.now(timezone.utc)
            logger.info(f"[V3] Fetched {len(candles)} 5M candles")
            return candles
    except Exception as e:
        logger.error(f"[V3] Error fetching 5M candles: {e}")
    
    return v3_5m_cache.get("candles") or []


def detect_4h_events(
    candles_4h: List[dict],
    current_price: float,
    supports: List,
    resistances: List,
    liquidity_above: float,
    liquidity_below: float,
    market_regime: str,
    market_bias: str,
    lang: str = "it"
) -> List[Dict[str, Any]]:
    """
    Detect significant 4H events that could trigger setups:
    - Resistance breakout
    - Support breakout
    - Liquidity sweep (high/low)
    - Strong trend continuation
    
    V3 Logic (user requirements):
    1. Detect structural levels from recent swing highs/lows (PRIMARY)
    2. Check whether those levels are reinforced by liquidity/volume (SECONDARY)
    3. Use combined levels for breakout/sweep event detection
    
    Structure must remain the primary reference.
    
    Returns list of detected events with details.
    """
    events = []
    
    if not candles_4h or len(candles_4h) < 10:
        return events
    
    # Get recent candles for analysis
    recent_candles = candles_4h[-20:]
    last_candle = recent_candles[-1]
    prev_candle = recent_candles[-2] if len(recent_candles) >= 2 else None
    
    # ===== STRUCTURE DETECTION (PRIMARY) =====
    # Calculate recent swing high/low using pivot detection (last 10-20 candles)
    swing_high = max(c["high"] for c in recent_candles[-10:])
    swing_low = min(c["low"] for c in recent_candles[-10:])
    
    # Find the actual pivot candles for more precise level detection
    pivot_highs = []
    pivot_lows = []
    for i in range(2, len(recent_candles) - 2):
        # Pivot high: higher than 2 candles before and after
        if (recent_candles[i]["high"] > recent_candles[i-1]["high"] and 
            recent_candles[i]["high"] > recent_candles[i-2]["high"] and
            recent_candles[i]["high"] > recent_candles[i+1]["high"] and 
            recent_candles[i]["high"] > recent_candles[i+2]["high"]):
            pivot_highs.append(recent_candles[i]["high"])
        # Pivot low: lower than 2 candles before and after
        if (recent_candles[i]["low"] < recent_candles[i-1]["low"] and 
            recent_candles[i]["low"] < recent_candles[i-2]["low"] and
            recent_candles[i]["low"] < recent_candles[i+1]["low"] and 
            recent_candles[i]["low"] < recent_candles[i+2]["low"]):
            pivot_lows.append(recent_candles[i]["low"])
    
    # Use the most recent pivot as the key structural level
    structural_resistance = pivot_highs[-1] if pivot_highs else swing_high
    structural_support = pivot_lows[-1] if pivot_lows else swing_low
    
    # ===== LIQUIDITY REINFORCEMENT (SECONDARY) =====
    # Check if structural levels are reinforced by S/R levels (from orderbook/volume)
    resistance_reinforced = False
    support_reinforced = False
    reinforcement_strength = 0
    
    # Check if any resistance level is close to structural_resistance (within 0.3%)
    for r in resistances:
        if abs(r.price - structural_resistance) / structural_resistance < 0.003:
            resistance_reinforced = True
            reinforcement_strength = 30 if r.strength == "strong" else (20 if r.strength == "moderate" else 10)
            # If orderbook-backed, add more weight
            if r.volume_at_level and r.volume_at_level > 0:
                reinforcement_strength += 20
            break
    
    # Check if any support level is close to structural_support (within 0.3%)
    for s in supports:
        if abs(s.price - structural_support) / structural_support < 0.003:
            support_reinforced = True
            reinforcement_strength = 30 if s.strength == "strong" else (20 if s.strength == "moderate" else 10)
            if s.volume_at_level and s.volume_at_level > 0:
                reinforcement_strength += 20
            break
    
    # Volatility for buffer calculation
    atr = sum(c["high"] - c["low"] for c in recent_candles[-14:]) / 14
    volatility_percent = (atr / current_price) * 100
    
    # ===== 1. RESISTANCE BREAKOUT =====
    # Use structural_resistance as primary level, check for breakout
    if (last_candle["close"] > structural_resistance and 
        prev_candle and prev_candle["close"] <= structural_resistance):
        
        base_strength = 50  # Structure-based
        if resistance_reinforced:
            base_strength += reinforcement_strength  # Volume/liquidity reinforcement
        
        # Additional strength from move magnitude
        move_percent = ((last_candle["close"] - structural_resistance) / structural_resistance) * 100
        base_strength = min(100, base_strength + move_percent * 10)
        
        reinforcement_note = " (RINFORZATO da liquidità)" if resistance_reinforced else ""
        events.append({
            "type": SetupEventType.RESISTANCE_BREAKOUT.value,
            "direction": "LONG",
            "event_price": current_price,
            "zone_high": structural_resistance * 1.002,  # Slightly above
            "zone_low": structural_resistance * 0.998,   # Slightly below
            "swing_high": swing_high,
            "swing_low": swing_low,
            "breakout_level": structural_resistance,
            "strength": base_strength,
            "reinforced_by_liquidity": resistance_reinforced,
            "signal": f"Breakout sopra resistenza strutturale ${structural_resistance:,.0f}{reinforcement_note}"
        })
    
    # ===== 2. SUPPORT BREAKOUT =====
    # Use structural_support as primary level, check for breakout
    if (last_candle["close"] < structural_support and 
        prev_candle and prev_candle["close"] >= structural_support):
        
        base_strength = 50  # Structure-based
        if support_reinforced:
            base_strength += reinforcement_strength  # Volume/liquidity reinforcement
        
        # Additional strength from move magnitude
        move_percent = ((structural_support - last_candle["close"]) / structural_support) * 100
        base_strength = min(100, base_strength + move_percent * 10)
        
        reinforcement_note = " (RINFORZATO da liquidità)" if support_reinforced else ""
        events.append({
            "type": SetupEventType.SUPPORT_BREAKOUT.value,
            "direction": "SHORT",
            "event_price": current_price,
            "zone_high": structural_support * 1.002,
            "zone_low": structural_support * 0.998,
            "swing_high": swing_high,
            "swing_low": swing_low,
            "breakout_level": structural_support,
            "strength": base_strength,
            "reinforced_by_liquidity": support_reinforced,
            "signal": f"Breakout sotto supporto strutturale ${structural_support:,.0f}{reinforcement_note}"
        })
    
    # ===== 3. LIQUIDITY SWEEP HIGH (Stop Hunt Above) =====
    # Price spiked above recent swing high but closed back inside
    # This is a STRUCTURAL pattern - swing high is primary, liquidity reinforces
    if (last_candle["high"] > swing_high * 1.001 and 
        last_candle["close"] < swing_high):
        sweep_level = last_candle["high"]
        
        # Base strength from structure (sweep of swing high)
        base_strength = 50
        
        # Liquidity reinforcement
        liq_reinforced = liquidity_above > 5000000  # $5M+ in liquidity above
        if liq_reinforced:
            # More liquidity = stronger sweep signal
            liq_factor = min(30, liquidity_above / 10000000 * 30)  # Max +30 from liquidity
            base_strength += liq_factor
        
        # Move magnitude
        sweep_depth = ((sweep_level - swing_high) / swing_high) * 100
        base_strength = min(100, base_strength + sweep_depth * 20)
        
        events.append({
            "type": SetupEventType.LIQUIDITY_SWEEP_HIGH.value,
            "direction": "SHORT",  # Sweep above = potential short
            "event_price": current_price,
            "zone_high": sweep_level,
            "zone_low": swing_high * 0.998,
            "swing_high": swing_high,
            "swing_low": swing_low,
            "sweep_level": sweep_level,
            "strength": base_strength,
            "reinforced_by_liquidity": liq_reinforced,
            "liquidity_swept": liquidity_above,
            "signal": f"Sweep liquidità sopra ${sweep_level:,.0f} - potenziale inversione SHORT" + 
                      (f" (liquidità ${liquidity_above/1000000:.1f}M)" if liq_reinforced else "")
        })
    
    # ===== 4. LIQUIDITY SWEEP LOW (Stop Hunt Below) =====
    # Price spiked below recent swing low but closed back inside
    # This is a STRUCTURAL pattern - swing low is primary, liquidity reinforces
    if (last_candle["low"] < swing_low * 0.999 and 
        last_candle["close"] > swing_low):
        sweep_level = last_candle["low"]
        
        # Base strength from structure (sweep of swing low)
        base_strength = 50
        
        # Liquidity reinforcement
        liq_reinforced = liquidity_below > 5000000  # $5M+ in liquidity below
        if liq_reinforced:
            liq_factor = min(30, liquidity_below / 10000000 * 30)
            base_strength += liq_factor
        
        # Move magnitude
        sweep_depth = ((swing_low - sweep_level) / swing_low) * 100
        base_strength = min(100, base_strength + sweep_depth * 20)
        
        events.append({
            "type": SetupEventType.LIQUIDITY_SWEEP_LOW.value,
            "direction": "LONG",  # Sweep below = potential long
            "event_price": current_price,
            "zone_high": swing_low * 1.002,
            "zone_low": sweep_level,
            "swing_high": swing_high,
            "swing_low": swing_low,
            "sweep_level": sweep_level,
            "strength": base_strength,
            "reinforced_by_liquidity": liq_reinforced,
            "liquidity_swept": liquidity_below,
            "signal": f"Sweep liquidità sotto ${sweep_level:,.0f} - potenziale inversione LONG" +
                      (f" (liquidità ${liquidity_below/1000000:.1f}M)" if liq_reinforced else "")
        })
    
    # ===== 5. TREND CONTINUATION (Strong move in trend direction) =====
    if market_regime == "TREND" and market_bias in ["BULLISH", "BEARISH"]:
        # Check for strong momentum candle in trend direction
        candle_body = abs(last_candle["close"] - last_candle["open"])
        candle_range = last_candle["high"] - last_candle["low"]
        body_ratio = candle_body / candle_range if candle_range > 0 else 0
        
        if body_ratio > 0.7:  # Strong body candle
            if market_bias == "BULLISH" and last_candle["close"] > last_candle["open"]:
                events.append({
                    "type": SetupEventType.TREND_CONTINUATION.value,
                    "direction": "LONG",
                    "event_price": current_price,
                    "zone_high": last_candle["close"],
                    "zone_low": last_candle["open"],
                    "swing_high": swing_high,
                    "swing_low": swing_low,
                    "strength": min(100, body_ratio * 100),
                    "signal": "Trend continuation LONG - candela momentum forte"
                })
            elif market_bias == "BEARISH" and last_candle["close"] < last_candle["open"]:
                events.append({
                    "type": SetupEventType.TREND_CONTINUATION.value,
                    "direction": "SHORT",
                    "event_price": current_price,
                    "zone_high": last_candle["open"],
                    "zone_low": last_candle["close"],
                    "swing_high": swing_high,
                    "swing_low": swing_low,
                    "strength": min(100, body_ratio * 100),
                    "signal": "Trend continuation SHORT - candela momentum forte"
                })
    
    return events


def detect_5m_confirmation(
    candles_5m: List[dict],
    setup: SetupEvent,
    current_price: float
) -> Optional[Dict[str, Any]]:
    """
    Detect 5M confirmation patterns for entry:
    - Rejection candle (wick > body)
    - Stabilization (2-3 candles in zone)
    - Micro-structure break
    
    Returns confirmation details or None if not confirmed.
    """
    if not candles_5m or len(candles_5m) < 5:
        return None
    
    # Get recent 5M candles
    recent_5m = candles_5m[-10:]
    last_candle = recent_5m[-1]
    
    zone_high = setup.zone_high
    zone_low = setup.zone_low
    
    # Check if price is in the retest zone
    in_zone = zone_low <= current_price <= zone_high
    
    if not in_zone:
        # Check if price was recently in zone
        candles_in_zone = [c for c in recent_5m[-5:] 
                          if zone_low <= c["close"] <= zone_high or
                             zone_low <= c["open"] <= zone_high]
        if len(candles_in_zone) < 2:
            return None  # Not in retest zone
    
    confirmation = None
    
    # ===== 1. REJECTION CANDLE =====
    # For LONG: Lower wick > body + upper wick (bullish rejection)
    # For SHORT: Upper wick > body + lower wick (bearish rejection)
    body = abs(last_candle["close"] - last_candle["open"])
    upper_wick = last_candle["high"] - max(last_candle["close"], last_candle["open"])
    lower_wick = min(last_candle["close"], last_candle["open"]) - last_candle["low"]
    
    if setup.direction == "LONG":
        if lower_wick > body + upper_wick and lower_wick > 0:
            rejection_strength = (lower_wick / (body + upper_wick + 0.01)) * 100
            confirmation = {
                "type": ConfirmationType.REJECTION_CANDLE.value,
                "strength": min(100, rejection_strength),
                "price": current_price,
                "details": {
                    "body": body,
                    "lower_wick": lower_wick,
                    "upper_wick": upper_wick,
                    "candle_close": last_candle["close"]
                },
                "signal": f"Candela di rifiuto LONG al supporto - wick inferiore {lower_wick:.0f}"
            }
    else:  # SHORT
        if upper_wick > body + lower_wick and upper_wick > 0:
            rejection_strength = (upper_wick / (body + lower_wick + 0.01)) * 100
            confirmation = {
                "type": ConfirmationType.REJECTION_CANDLE.value,
                "strength": min(100, rejection_strength),
                "price": current_price,
                "details": {
                    "body": body,
                    "lower_wick": lower_wick,
                    "upper_wick": upper_wick,
                    "candle_close": last_candle["close"]
                },
                "signal": f"Candela di rifiuto SHORT alla resistenza - wick superiore {upper_wick:.0f}"
            }
    
    if confirmation:
        return confirmation
    
    # ===== 2. STABILIZATION (2-3 candles in zone) =====
    candles_in_zone = []
    for c in recent_5m[-5:]:
        candle_mid = (c["high"] + c["low"]) / 2
        if zone_low * 0.998 <= candle_mid <= zone_high * 1.002:
            candles_in_zone.append(c)
    
    if len(candles_in_zone) >= 2:
        # Check if candles are tightening (compression in zone)
        ranges = [c["high"] - c["low"] for c in candles_in_zone]
        if len(ranges) >= 2 and ranges[-1] < ranges[0]:  # Tightening
            confirmation = {
                "type": ConfirmationType.STABILIZATION.value,
                "strength": min(100, len(candles_in_zone) * 30),
                "price": current_price,
                "details": {
                    "candles_in_zone": len(candles_in_zone),
                    "zone_center": (zone_high + zone_low) / 2,
                    "compression": True
                },
                "signal": f"Stabilizzazione in zona ({len(candles_in_zone)} candele) - compressione rilevata"
            }
            return confirmation
    
    # ===== 3. MICRO-STRUCTURE BREAK =====
    # For LONG: Break above recent 5M swing high
    # For SHORT: Break below recent 5M swing low
    micro_swing_high = max(c["high"] for c in recent_5m[-5:])
    micro_swing_low = min(c["low"] for c in recent_5m[-5:])
    
    if setup.direction == "LONG":
        if last_candle["close"] > micro_swing_high and in_zone:
            confirmation = {
                "type": ConfirmationType.MICRO_STRUCTURE_BREAK.value,
                "strength": min(100, 70),
                "price": current_price,
                "details": {
                    "micro_high": micro_swing_high,
                    "break_level": last_candle["close"],
                    "break_percent": (last_candle["close"] - micro_swing_high) / micro_swing_high * 100
                },
                "signal": f"Rottura micro-struttura 5M sopra ${micro_swing_high:,.0f}"
            }
    else:  # SHORT
        if last_candle["close"] < micro_swing_low and in_zone:
            confirmation = {
                "type": ConfirmationType.MICRO_STRUCTURE_BREAK.value,
                "strength": min(100, 70),
                "price": current_price,
                "details": {
                    "micro_low": micro_swing_low,
                    "break_level": last_candle["close"],
                    "break_percent": (micro_swing_low - last_candle["close"]) / micro_swing_low * 100
                },
                "signal": f"Rottura micro-struttura 5M sotto ${micro_swing_low:,.0f}"
            }
    
    return confirmation


def calculate_v3_stop_loss(
    direction: str,
    swing_high: float,
    swing_low: float,
    sweep_level: Optional[float],
    current_price: float,
    volatility_percent: float = 0.5
) -> Dict[str, Any]:
    """
    Calculate structure-based stop loss for V3.
    
    LONG: stop = min(swing_low, sweep_low) - buffer
    SHORT: stop = max(swing_high, sweep_high) + buffer
    
    Buffer: 0.1% – 0.25% depending on volatility
    """
    # Calculate adaptive buffer based on volatility
    buffer_percent = min(V3_STOP_BUFFER_MAX, max(V3_STOP_BUFFER_MIN, volatility_percent / 200))
    
    if direction == "LONG":
        # Use the lower of swing_low and sweep_level (if available)
        base_stop = swing_low
        stop_type = "swing"
        
        if sweep_level and sweep_level < swing_low:
            base_stop = sweep_level
            stop_type = "sweep"
        elif sweep_level:
            base_stop = min(swing_low, sweep_level)
            stop_type = "combined"
        
        stop_loss = base_stop * (1 - buffer_percent)
        
    else:  # SHORT
        # Use the higher of swing_high and sweep_level (if available)
        base_stop = swing_high
        stop_type = "swing"
        
        if sweep_level and sweep_level > swing_high:
            base_stop = sweep_level
            stop_type = "sweep"
        elif sweep_level:
            base_stop = max(swing_high, sweep_level)
            stop_type = "combined"
        
        stop_loss = base_stop * (1 + buffer_percent)
    
    return {
        "stop_loss": round(stop_loss, 2),
        "stop_type": stop_type,
        "buffer_percent": buffer_percent * 100,
        "base_level": base_stop,
        "swing_used": swing_low if direction == "LONG" else swing_high,
        "sweep_used": sweep_level
    }


def calculate_v3_targets(
    direction: str,
    entry_price: float,
    liquidity_above: float,
    liquidity_below: float,
    resistances: List,
    supports: List,
    swing_high: float,
    swing_low: float,
    liquidity_clusters: List = None,
    aggregated_orderbook: dict = None
) -> Dict[str, Any]:
    """
    V3 Target Selection - LIQUIDITY CLUSTER BASED (v2.1 STRICT)
    
    CRITICAL: Targets MUST come from real liquidity clusters.
    NO FALLBACK to percentage-based targets.
    
    If no valid clusters found → signal is NON-OPERATIONAL.
    
    Strict Filters:
    - Minimum distance: 0.5% (ignore micro-targets)
    - Minimum volume: $500K (ignore noise)
    - Preferred range: 0.5% - 2.5%
    - Preferred volume: > $1M
    """
    import math
    
    # ═══════════════════════════════════════════════════════════════════════════
    # STRICT FILTER CONSTANTS (v2.1)
    # ═══════════════════════════════════════════════════════════════════════════
    MIN_DISTANCE_PCT = 0.5      # HARD minimum - ignore anything closer
    MAX_DISTANCE_PCT = 5.0      # Maximum reasonable distance
    PREFERRED_MIN_DIST = 0.5    # Preferred range start
    PREFERRED_MAX_DIST = 2.5    # Preferred range end
    MIN_VOLUME_USD = 500000     # HARD minimum $500K
    PREFERRED_VOLUME_USD = 1000000  # Preferred $1M+
    
    all_targets = []
    debug_log = {
        "clusters_raw": 0,
        "clusters_after_direction_filter": 0,
        "clusters_after_distance_filter": 0,
        "clusters_after_volume_filter": 0,
        "clusters_final": 0,
        "rejection_reasons": [],
        "selected_t1": None,
        "selected_t2": None
    }
    
    # ═══════════════════════════════════════════════════════════════════════════
    # 1. EXTRACT CLUSTERS FROM AGGREGATED ORDERBOOK
    # ═══════════════════════════════════════════════════════════════════════════
    if aggregated_orderbook:
        asks = aggregated_orderbook.get("asks", [])
        bids = aggregated_orderbook.get("bids", [])
        
        # For LONG: look at asks (resistance levels above)
        # For SHORT: look at bids (support levels below)
        levels_to_analyze = asks[:200] if direction == "LONG" else bids[:200]
        debug_log["clusters_raw"] = len(levels_to_analyze)
        
        # Group nearby levels into clusters (within 0.1% of each other)
        clusters_grouped = []
        for level in levels_to_analyze:
            price = float(level[0])
            volume_btc = float(level[1])
            value_usd = price * volume_btc
            
            # Check direction validity FIRST
            is_valid_direction = (
                (direction == "LONG" and price > entry_price) or
                (direction == "SHORT" and price < entry_price)
            )
            
            if not is_valid_direction:
                continue
            
            debug_log["clusters_after_direction_filter"] += 1
            
            # Calculate distance
            if direction == "LONG":
                distance_pct = ((price - entry_price) / entry_price) * 100
            else:
                distance_pct = ((entry_price - price) / entry_price) * 100
            
            # STRICT DISTANCE FILTER
            if distance_pct < MIN_DISTANCE_PCT:
                debug_log["rejection_reasons"].append(f"${price:,.0f}: dist {distance_pct:.2f}% < {MIN_DISTANCE_PCT}% min")
                continue
            
            if distance_pct > MAX_DISTANCE_PCT:
                continue  # Too far, not relevant
            
            debug_log["clusters_after_distance_filter"] += 1
            
            # STRICT VOLUME FILTER
            if value_usd < MIN_VOLUME_USD:
                debug_log["rejection_reasons"].append(f"${price:,.0f}: vol ${value_usd:,.0f} < ${MIN_VOLUME_USD:,.0f} min")
                continue
            
            debug_log["clusters_after_volume_filter"] += 1
            
            # Calculate strength score
            strength = 0
            
            # Volume scoring (primary factor)
            if value_usd >= PREFERRED_VOLUME_USD * 2:  # $2M+
                strength += 50
            elif value_usd >= PREFERRED_VOLUME_USD:  # $1M+
                strength += 35
            else:  # $500K - $1M
                strength += 20
            
            # Distance scoring (prefer 0.5% - 2.5% range)
            if PREFERRED_MIN_DIST <= distance_pct <= PREFERRED_MAX_DIST:
                strength += 30  # Ideal range bonus
            elif distance_pct <= 3.5:
                strength += 15  # Acceptable range
            else:
                strength += 5   # Extended range
            
            # Log volume bonus
            strength += math.log10(max(1, value_usd / 100000)) * 5
            
            all_targets.append({
                "price": round(price, 2),
                "value_usd": value_usd,
                "distance_pct": round(distance_pct, 3),
                "strength": round(strength, 1),
                "source": "orderbook_cluster",
                "volume_btc": volume_btc
            })
    
    # ═══════════════════════════════════════════════════════════════════════════
    # 2. ADD PRE-COMPUTED LIQUIDITY CLUSTERS (if available)
    # ═══════════════════════════════════════════════════════════════════════════
    if liquidity_clusters:
        for cluster in liquidity_clusters:
            # Handle both dict and object formats
            if hasattr(cluster, 'price'):
                c_price = cluster.price
                c_side = cluster.side
                c_value = getattr(cluster, 'estimated_value', 0)
                c_strength_str = getattr(cluster, 'strength', 'medium')
            else:
                c_price = cluster.get('price', 0)
                c_side = cluster.get('side', '')
                c_value = cluster.get('estimated_value', 0)
                c_strength_str = cluster.get('strength', 'medium')
            
            # Direction filter
            is_valid = (
                (direction == "LONG" and c_side == "above") or
                (direction == "SHORT" and c_side == "below")
            )
            
            if not is_valid or c_price <= 0:
                continue
            
            # Calculate distance
            if direction == "LONG":
                distance_pct = ((c_price - entry_price) / entry_price) * 100
            else:
                distance_pct = ((entry_price - c_price) / entry_price) * 100
            
            # STRICT FILTERS
            if distance_pct < MIN_DISTANCE_PCT:
                continue
            if distance_pct > MAX_DISTANCE_PCT:
                continue
            if c_value < MIN_VOLUME_USD:
                continue
            
            # Strength scoring
            strength_map = {"high": 40, "medium": 25, "low": 10}
            strength = strength_map.get(c_strength_str, 15)
            
            if c_value >= PREFERRED_VOLUME_USD:
                strength += 20
            
            if PREFERRED_MIN_DIST <= distance_pct <= PREFERRED_MAX_DIST:
                strength += 15
            
            all_targets.append({
                "price": round(c_price, 2),
                "value_usd": c_value,
                "distance_pct": round(distance_pct, 3),
                "strength": round(strength, 1),
                "source": "liquidity_cluster",
                "volume_btc": c_value / c_price if c_price > 0 else 0
            })
    
    # ═══════════════════════════════════════════════════════════════════════════
    # 3. DEDUPLICATE AND SORT
    # ═══════════════════════════════════════════════════════════════════════════
    deduped = []
    for t in all_targets:
        is_dup = False
        for existing in deduped:
            if abs(t["price"] - existing["price"]) / existing["price"] < 0.002:  # Within 0.2%
                # Keep the stronger one
                if t["strength"] > existing["strength"]:
                    deduped.remove(existing)
                    deduped.append(t)
                is_dup = True
                break
        if not is_dup:
            deduped.append(t)
    
    debug_log["clusters_final"] = len(deduped)
    
    # Sort by distance for T1 selection, by strength for T2
    deduped_by_distance = sorted(deduped, key=lambda x: x["distance_pct"])
    deduped_by_strength = sorted(deduped, key=lambda x: x["strength"], reverse=True)
    
    # ═══════════════════════════════════════════════════════════════════════════
    # 4. TARGET SELECTION - NO FALLBACK TO PERCENTAGE
    # ═══════════════════════════════════════════════════════════════════════════
    t1 = None
    t1_type = "NO_VALID_CLUSTERS"
    t1_cluster = None
    
    t2 = None
    t2_type = "NO_VALID_CLUSTERS"
    t2_cluster = None
    
    # T1: Nearest valid cluster (must be in preferred range if possible)
    preferred_clusters = [c for c in deduped_by_distance if c["distance_pct"] <= PREFERRED_MAX_DIST]
    if preferred_clusters:
        t1_cluster = preferred_clusters[0]
        t1 = t1_cluster["price"]
        t1_type = "liquidity_cluster"
        debug_log["selected_t1"] = f"${t1:,.0f} (dist={t1_cluster['distance_pct']:.2f}%, vol=${t1_cluster['value_usd']:,.0f})"
    elif deduped_by_distance:
        # Fall back to any valid cluster
        t1_cluster = deduped_by_distance[0]
        t1 = t1_cluster["price"]
        t1_type = "liquidity_cluster_extended"
        debug_log["selected_t1"] = f"${t1:,.0f} (extended, dist={t1_cluster['distance_pct']:.2f}%)"
    
    # T2: Strongest cluster beyond T1
    if t1 is not None:
        t1_distance = t1_cluster["distance_pct"]
        for target in deduped_by_strength:
            if target["distance_pct"] > t1_distance + 0.3:  # Must be meaningfully further
                t2_cluster = target
                t2 = t2_cluster["price"]
                t2_type = "liquidity_cluster"
                debug_log["selected_t2"] = f"${t2:,.0f} (dist={t2_cluster['distance_pct']:.2f}%, strength={t2_cluster['strength']})"
                break
        
        # If no T2 found, extend T1
        if t2 is None and t1 is not None:
            if direction == "LONG":
                t2 = t1 * 1.01  # 1% beyond T1
            else:
                t2 = t1 * 0.99
            t2_type = "extended_from_t1"
            debug_log["selected_t2"] = f"${t2:,.0f} (extended from T1)"
    
    # ═══════════════════════════════════════════════════════════════════════════
    # 5. BUILD RESULT - MARK AS NON-OPERATIONAL IF NO CLUSTERS
    # ═══════════════════════════════════════════════════════════════════════════
    has_valid_targets = t1 is not None and t1_type != "NO_VALID_CLUSTERS"
    
    # Log the full debug info
    logger.info(f"[V3 TARGETS] Direction={direction}, Entry=${entry_price:,.0f}")
    logger.info(f"[V3 TARGETS] Raw clusters: {debug_log['clusters_raw']}, "
               f"After filters: {debug_log['clusters_final']}, "
               f"Valid targets: {has_valid_targets}")
    
    if not has_valid_targets:
        logger.warning(f"[V3 TARGETS] NO_VALID_CLUSTERS - Signal will be non-operational")
        if debug_log["rejection_reasons"]:
            logger.warning(f"[V3 TARGETS] Rejection samples: {debug_log['rejection_reasons'][:5]}")
    else:
        logger.info(f"[V3 TARGETS] T1: {debug_log['selected_t1']}")
        logger.info(f"[V3 TARGETS] T2: {debug_log['selected_t2']}")
    
    result = {
        "target_1": round(t1, 2) if t1 else entry_price,
        "target_1_type": t1_type,
        "target_2": round(t2, 2) if t2 else entry_price,
        "target_2_type": t2_type,
        
        # Cluster metadata for UI
        "target_1_cluster": {
            "price": t1_cluster["price"],
            "value_usd": t1_cluster["value_usd"],
            "distance_pct": t1_cluster["distance_pct"],
            "strength": t1_cluster["strength"],
            "source": t1_cluster["source"]
        } if t1_cluster else None,
        
        "target_2_cluster": {
            "price": t2_cluster["price"],
            "value_usd": t2_cluster["value_usd"],
            "distance_pct": t2_cluster["distance_pct"],
            "strength": t2_cluster["strength"],
            "source": t2_cluster["source"]
        } if t2_cluster else None,
        
        # Status flags
        "clusters_analyzed": debug_log["clusters_final"],
        "targets_from_clusters": has_valid_targets,
        "has_valid_targets": has_valid_targets,
        "no_clusters_reason": "NO_VALID_CLUSTERS" if not has_valid_targets else None
    }
    
    return result


# ═══════════════════════════════════════════════════════════════════════════════
# SHADOW LIQUIDITY TARGET ENGINE (v0.2)
# 
# This module runs IN PARALLEL with the live V3 targets.
# It does NOT replace or modify live targets.
# Purpose: Data collection and analysis for liquidity-based exit optimization.
#
# v0.2 Changes:
# - Targets based on STRENGTH, not proximity
# - Primary, Secondary, Extended targets with strength scores
# - Validation tracking for outcome comparison
# ═══════════════════════════════════════════════════════════════════════════════

def calculate_liquidity_strength_score(
    value: float,
    distance_pct: float,
    source: str,
    direction: str
) -> float:
    """
    Calculate a unified strength score for a liquidity target.
    
    Higher score = more attractive target.
    
    Factors:
    - Value/volume at the level (primary factor)
    - Distance from entry (moderate distance preferred)
    - Source reliability (liquidation > orderbook > cluster > magnet)
    
    Returns: 0-100 score
    """
    # Base score from value (logarithmic scale)
    import math
    value_score = min(50, math.log10(max(1, value)) * 8)  # Max 50 points from value
    
    # Distance score (0.5-2% is ideal, too close or too far penalized)
    if 0.5 <= distance_pct <= 2.0:
        distance_score = 25  # Ideal range
    elif 0.3 <= distance_pct < 0.5:
        distance_score = 15  # Too close, might not give enough profit
    elif 2.0 < distance_pct <= 3.5:
        distance_score = 20  # Acceptable
    elif 3.5 < distance_pct <= 5.0:
        distance_score = 10  # Far but reachable
    else:
        distance_score = 5  # Too close or too far
    
    # Source reliability score
    source_scores = {
        "liquidation_cluster": 25,    # Most reliable - actual stop losses
        "orderbook_wall": 20,         # Visible walls but can be spoofed
        "historical_cluster": 15,     # Historical significance
        "magnet_attraction": 15,      # Derived metric
        "combined": 22,               # Multiple sources = higher confidence
    }
    
    # Check for combined sources
    if "+" in source:
        source_score = source_scores.get("combined", 18)
    else:
        source_score = source_scores.get(source, 10)
    
    return min(100, value_score + distance_score + source_score)


async def calculate_shadow_liquidity_targets(
    direction: str,
    entry_price: float,
    current_price: float,
    standard_targets: Dict[str, Any],
    magnet_data: Optional[Dict[str, Any]] = None,
    liquidation_levels: Optional[List[Dict]] = None,
    orderbook_data: Optional[Dict[str, Any]] = None,
    liquidity_clusters: Optional[List[Dict]] = None
) -> Dict[str, Any]:
    """
    SHADOW MODE v0.2: Calculate liquidity-based targets by STRENGTH, not proximity.
    
    Key change from v0.1: Targets are ranked by how STRONG the liquidity is,
    not how CLOSE it is to entry. This tests the hypothesis that price moves
    to where the most liquidity is, regardless of distance.
    
    Hierarchy:
    1. Primary Magnet: Strongest liquidity level (highest score)
    2. Secondary Zone: Second strongest level
    3. Extended Target: Third strongest (for runners)
    
    Returns shadow target analysis with strength-based scoring.
    """
    shadow_result = {
        "engine_version": "shadow_liquidity_v0.2",
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "direction": direction,
        "entry_price": entry_price,
        "current_price": current_price,
        
        # Standard targets (for comparison)
        "standard_targets": standard_targets,
        
        # Shadow liquidity targets - Now strength-based
        "liquidity_targets": {
            # Primary Magnet - Strongest level
            "primary_magnet": {
                "price": None,
                "strength_score": 0,
                "source": None,
                "liquidity_value": 0,
                "distance_pct": 0,
                "expected_fill_probability": 0
            },
            # Secondary Zone - Second strongest
            "secondary_zone": {
                "price": None,
                "strength_score": 0,
                "source": None,
                "liquidity_value": 0,
                "distance_pct": 0,
                "expected_fill_probability": 0
            },
            # Extended Target - Third strongest (runners)
            "extended_target": {
                "price": None,
                "strength_score": 0,
                "source": None,
                "liquidity_value": 0,
                "distance_pct": 0,
                "expected_fill_probability": 0
            },
            
            # Legacy format for backward compatibility
            "target_1": None,
            "target_1_source": None,
            "target_1_confidence": 0,
            "target_1_liquidity_value": 0,
            "target_2": None,
            "target_2_source": None,
            "target_2_confidence": 0,
            "target_2_liquidity_value": 0,
            "target_3": None,
            "target_3_source": None,
            "target_3_confidence": 0
        },
        
        # Exit strategy suggestion
        "suggested_exit_plan": {
            "partial_at_t1_percent": 50,
            "partial_at_t2_percent": 30,
            "runner_percent": 20,
            "confidence": 0,
            "reasoning": "",
            "aggressive_vs_conservative": "balanced"  # aggressive / conservative / balanced
        },
        
        # Data quality metrics
        "data_quality": {
            "has_liquidation_data": False,
            "has_orderbook_data": False,
            "has_cluster_data": False,
            "has_magnet_data": False,
            "overall_quality": 0,
            "missing_sources": [],
            "sources_used": []
        },
        
        # Comparison with standard targets
        "comparison": {
            "t1_difference_percent": 0,
            "t2_difference_percent": 0,
            "shadow_more_conservative": False,
            "shadow_more_aggressive": False,
            "expected_rr_improvement": 0,
            "notes": []
        },
        
        # NEW: Validation tracking fields (populated after signal closes)
        "validation": {
            "status": "pending",  # pending / completed
            "standard_t1_hit": None,
            "standard_t2_hit": None,
            "shadow_t1_hit": None,
            "shadow_t2_hit": None,
            "mfe_percent": None,  # Max favorable excursion
            "mae_percent": None,  # Max adverse excursion
            "final_outcome": None,  # win / loss / expired / breakeven
            "profit_standard_percent": None,
            "profit_shadow_percent": None,
            "shadow_outperformed": None  # True/False/None
        }
    }
    
    try:
        quality_score = 0
        missing = []
        sources_used = []
        
        # Collect all potential targets with strength scoring
        all_targets = []
        
        # ═══════════════════════════════════════════════════════════════════
        # 1. ANALYZE LIQUIDATION DATA (Highest weight for strength)
        # ═══════════════════════════════════════════════════════════════════
        if liquidation_levels and len(liquidation_levels) > 0:
            shadow_result["data_quality"]["has_liquidation_data"] = True
            quality_score += 30
            sources_used.append("CoinGlass Liquidation")
            
            for level in liquidation_levels:
                price = level.get("price", 0)
                value = level.get("value", 0)
                
                # Skip tiny levels
                if value < 100000:  # < $100K
                    continue
                
                is_valid_direction = (
                    (direction == "LONG" and price > entry_price) or
                    (direction == "SHORT" and price < entry_price)
                )
                
                if is_valid_direction:
                    if direction == "LONG":
                        distance_pct = ((price - entry_price) / entry_price) * 100
                    else:
                        distance_pct = ((entry_price - price) / entry_price) * 100
                    
                    if 0.2 < distance_pct < 6:  # Extended range for strength-based
                        strength = calculate_liquidity_strength_score(
                            value, distance_pct, "liquidation_cluster", direction
                        )
                        all_targets.append({
                            "price": price,
                            "value": value,
                            "distance_pct": distance_pct,
                            "source": "liquidation_cluster",
                            "strength_score": strength
                        })
        else:
            missing.append("liquidation_data")
        
        # ═══════════════════════════════════════════════════════════════════
        # 2. ANALYZE ORDER BOOK WALLS
        # ═══════════════════════════════════════════════════════════════════
        if orderbook_data:
            shadow_result["data_quality"]["has_orderbook_data"] = True
            quality_score += 25
            sources_used.append("Aggregated Orderbook")
            
            asks = orderbook_data.get("asks", [])
            bids = orderbook_data.get("bids", [])
            
            levels_to_check = asks[:30] if direction == "LONG" else bids[:30]
            
            for level in levels_to_check:
                price = float(level[0])
                volume = float(level[1])
                value_usd = price * volume
                
                if value_usd < 300000:  # < $300K
                    continue
                
                is_valid_direction = (
                    (direction == "LONG" and price > entry_price) or
                    (direction == "SHORT" and price < entry_price)
                )
                
                if is_valid_direction:
                    if direction == "LONG":
                        distance_pct = ((price - entry_price) / entry_price) * 100
                    else:
                        distance_pct = ((entry_price - price) / entry_price) * 100
                    
                    if 0.1 < distance_pct < 5:
                        strength = calculate_liquidity_strength_score(
                            value_usd, distance_pct, "orderbook_wall", direction
                        )
                        all_targets.append({
                            "price": price,
                            "value": value_usd,
                            "distance_pct": distance_pct,
                            "source": "orderbook_wall",
                            "strength_score": strength
                        })
        else:
            missing.append("orderbook_data")
        
        # ═══════════════════════════════════════════════════════════════════
        # 3. ANALYZE LIQUIDITY CLUSTERS (Historical zones)
        # ═══════════════════════════════════════════════════════════════════
        if liquidity_clusters and len(liquidity_clusters) > 0:
            shadow_result["data_quality"]["has_cluster_data"] = True
            quality_score += 20
            sources_used.append("Historical Clusters")
            
            for cluster in liquidity_clusters:
                price = cluster.get("price", 0)
                cluster_strength = cluster.get("strength", 0)
                value = cluster_strength * 500000  # Normalize to comparable scale
                
                is_valid_direction = (
                    (direction == "LONG" and price > entry_price) or
                    (direction == "SHORT" and price < entry_price)
                )
                
                if is_valid_direction:
                    if direction == "LONG":
                        distance_pct = ((price - entry_price) / entry_price) * 100
                    else:
                        distance_pct = ((entry_price - price) / entry_price) * 100
                    
                    if 0.2 < distance_pct < 5:
                        strength = calculate_liquidity_strength_score(
                            value, distance_pct, "historical_cluster", direction
                        )
                        all_targets.append({
                            "price": price,
                            "value": value,
                            "distance_pct": distance_pct,
                            "source": "historical_cluster",
                            "strength_score": strength
                        })
        else:
            missing.append("cluster_data")
        
        # ═══════════════════════════════════════════════════════════════════
        # 4. ANALYZE MAGNET DATA
        # ═══════════════════════════════════════════════════════════════════
        if magnet_data and magnet_data.get("nearest_magnet_price"):
            shadow_result["data_quality"]["has_magnet_data"] = True
            quality_score += 25
            sources_used.append("Liquidity Magnet")
            
            magnet_price = magnet_data.get("nearest_magnet_price", 0)
            magnet_strength = magnet_data.get("magnet_score", 0)
            value = magnet_strength * 100000
            
            is_valid_direction = (
                (direction == "LONG" and magnet_price > entry_price) or
                (direction == "SHORT" and magnet_price < entry_price)
            )
            
            if is_valid_direction and magnet_price > 0:
                if direction == "LONG":
                    distance_pct = ((magnet_price - entry_price) / entry_price) * 100
                else:
                    distance_pct = ((entry_price - magnet_price) / entry_price) * 100
                
                if 0.2 < distance_pct < 6:
                    strength = calculate_liquidity_strength_score(
                        value, distance_pct, "magnet_attraction", direction
                    )
                    all_targets.append({
                        "price": magnet_price,
                        "value": value,
                        "distance_pct": distance_pct,
                        "source": "magnet_attraction",
                        "strength_score": strength
                    })
        else:
            missing.append("magnet_data")
        
        # ═══════════════════════════════════════════════════════════════════
        # 5. SORT BY STRENGTH (not distance!) and deduplicate
        # ═══════════════════════════════════════════════════════════════════
        # THIS IS THE KEY CHANGE: Sort by strength score, highest first
        all_targets.sort(key=lambda x: x["strength_score"], reverse=True)
        
        # Deduplicate similar prices (within 0.15%)
        deduped_targets = []
        for t in all_targets:
            is_duplicate = False
            for existing in deduped_targets:
                price_diff = abs(t["price"] - existing["price"]) / existing["price"]
                if price_diff < 0.0015:  # Within 0.15%
                    # Merge: combine sources, keep higher strength
                    if t["strength_score"] > existing["strength_score"]:
                        existing["strength_score"] = (existing["strength_score"] + t["strength_score"]) / 2 + 5  # Bonus for confluence
                    existing["value"] += t["value"]
                    if t["source"] not in existing["source"]:
                        existing["source"] = f"{existing['source']}+{t['source']}"
                    is_duplicate = True
                    break
            if not is_duplicate:
                deduped_targets.append(t)
        
        # Re-sort after merging
        deduped_targets.sort(key=lambda x: x["strength_score"], reverse=True)
        
        # ═══════════════════════════════════════════════════════════════════
        # 6. ASSIGN SHADOW TARGETS BY STRENGTH
        # ═══════════════════════════════════════════════════════════════════
        def calc_fill_probability(strength: float, distance: float) -> float:
            """Estimate probability of price reaching this level"""
            base_prob = min(85, strength)
            # Penalty for very far targets
            if distance > 3:
                base_prob *= (1 - (distance - 3) * 0.1)
            return max(10, min(95, base_prob))
        
        if len(deduped_targets) >= 1:
            t1 = deduped_targets[0]
            shadow_result["liquidity_targets"]["primary_magnet"] = {
                "price": round(t1["price"], 2),
                "strength_score": round(t1["strength_score"], 1),
                "source": t1["source"],
                "liquidity_value": t1["value"],
                "distance_pct": round(t1["distance_pct"], 2),
                "expected_fill_probability": calc_fill_probability(t1["strength_score"], t1["distance_pct"])
            }
            # Legacy format
            shadow_result["liquidity_targets"]["target_1"] = round(t1["price"], 2)
            shadow_result["liquidity_targets"]["target_1_source"] = t1["source"]
            shadow_result["liquidity_targets"]["target_1_confidence"] = round(t1["strength_score"], 1)
            shadow_result["liquidity_targets"]["target_1_liquidity_value"] = t1["value"]
        
        if len(deduped_targets) >= 2:
            t2 = deduped_targets[1]
            shadow_result["liquidity_targets"]["secondary_zone"] = {
                "price": round(t2["price"], 2),
                "strength_score": round(t2["strength_score"], 1),
                "source": t2["source"],
                "liquidity_value": t2["value"],
                "distance_pct": round(t2["distance_pct"], 2),
                "expected_fill_probability": calc_fill_probability(t2["strength_score"], t2["distance_pct"])
            }
            # Legacy format
            shadow_result["liquidity_targets"]["target_2"] = round(t2["price"], 2)
            shadow_result["liquidity_targets"]["target_2_source"] = t2["source"]
            shadow_result["liquidity_targets"]["target_2_confidence"] = round(t2["strength_score"], 1)
            shadow_result["liquidity_targets"]["target_2_liquidity_value"] = t2["value"]
        
        if len(deduped_targets) >= 3:
            t3 = deduped_targets[2]
            shadow_result["liquidity_targets"]["extended_target"] = {
                "price": round(t3["price"], 2),
                "strength_score": round(t3["strength_score"], 1),
                "source": t3["source"],
                "liquidity_value": t3["value"],
                "distance_pct": round(t3["distance_pct"], 2),
                "expected_fill_probability": calc_fill_probability(t3["strength_score"], t3["distance_pct"])
            }
            # Legacy format
            shadow_result["liquidity_targets"]["target_3"] = round(t3["price"], 2)
            shadow_result["liquidity_targets"]["target_3_source"] = t3["source"]
            shadow_result["liquidity_targets"]["target_3_confidence"] = round(t3["strength_score"], 1)
        
        # ═══════════════════════════════════════════════════════════════════
        # 7. GENERATE EXIT PLAN SUGGESTION
        # ═══════════════════════════════════════════════════════════════════
        exit_confidence = min(100, quality_score)
        
        if len(deduped_targets) >= 2:
            t1_strength = deduped_targets[0]["strength_score"]
            t2_strength = deduped_targets[1]["strength_score"]
            t1_distance = deduped_targets[0]["distance_pct"]
            
            if t1_strength > 75 and t1_distance < 2:
                # Very strong T1, close by = aggressive take profit
                shadow_result["suggested_exit_plan"]["partial_at_t1_percent"] = 65
                shadow_result["suggested_exit_plan"]["partial_at_t2_percent"] = 25
                shadow_result["suggested_exit_plan"]["runner_percent"] = 10
                shadow_result["suggested_exit_plan"]["aggressive_vs_conservative"] = "aggressive"
                shadow_result["suggested_exit_plan"]["reasoning"] = f"Strong liquidity (score {t1_strength:.0f}) at {t1_distance:.1f}% - take majority early"
                
            elif t2_strength > t1_strength * 0.9:
                # T2 almost as strong as T1 = balanced approach
                shadow_result["suggested_exit_plan"]["partial_at_t1_percent"] = 40
                shadow_result["suggested_exit_plan"]["partial_at_t2_percent"] = 40
                shadow_result["suggested_exit_plan"]["runner_percent"] = 20
                shadow_result["suggested_exit_plan"]["aggressive_vs_conservative"] = "balanced"
                shadow_result["suggested_exit_plan"]["reasoning"] = "Strong liquidity at both levels - balanced exit"
                
            elif t1_distance > 2.5:
                # T1 is far but strong = let it run
                shadow_result["suggested_exit_plan"]["partial_at_t1_percent"] = 50
                shadow_result["suggested_exit_plan"]["partial_at_t2_percent"] = 30
                shadow_result["suggested_exit_plan"]["runner_percent"] = 20
                shadow_result["suggested_exit_plan"]["aggressive_vs_conservative"] = "conservative"
                shadow_result["suggested_exit_plan"]["reasoning"] = f"Strong magnet at {t1_distance:.1f}% - standard exit with runners"
            else:
                shadow_result["suggested_exit_plan"]["reasoning"] = "Standard liquidity distribution"
        else:
            shadow_result["suggested_exit_plan"]["reasoning"] = "Limited liquidity data - use standard targets"
            exit_confidence = max(20, exit_confidence - 30)
        
        shadow_result["suggested_exit_plan"]["confidence"] = exit_confidence
        
        # ═══════════════════════════════════════════════════════════════════
        # 8. COMPARE WITH STANDARD TARGETS
        # ═══════════════════════════════════════════════════════════════════
        std_t1 = standard_targets.get("target_1", 0)
        std_t2 = standard_targets.get("target_2", 0)
        liq_t1 = shadow_result["liquidity_targets"]["target_1"]
        liq_t2 = shadow_result["liquidity_targets"]["target_2"]
        
        if std_t1 and liq_t1:
            diff_pct = ((liq_t1 - std_t1) / std_t1) * 100
            shadow_result["comparison"]["t1_difference_percent"] = round(diff_pct, 2)
            
            if direction == "LONG":
                shadow_result["comparison"]["shadow_more_aggressive"] = liq_t1 > std_t1
                shadow_result["comparison"]["shadow_more_conservative"] = liq_t1 < std_t1
                if liq_t1 > std_t1:
                    shadow_result["comparison"]["notes"].append(f"Shadow T1 +{diff_pct:.1f}% higher (more aggressive)")
                else:
                    shadow_result["comparison"]["notes"].append(f"Shadow T1 {diff_pct:.1f}% lower (more conservative)")
            else:
                shadow_result["comparison"]["shadow_more_aggressive"] = liq_t1 < std_t1
                shadow_result["comparison"]["shadow_more_conservative"] = liq_t1 > std_t1
                if liq_t1 < std_t1:
                    shadow_result["comparison"]["notes"].append(f"Shadow T1 extends {abs(diff_pct):.1f}% further")
                else:
                    shadow_result["comparison"]["notes"].append(f"Shadow T1 {diff_pct:.1f}% closer (more conservative)")
        
        if std_t2 and liq_t2:
            diff_pct = ((liq_t2 - std_t2) / std_t2) * 100
            shadow_result["comparison"]["t2_difference_percent"] = round(diff_pct, 2)
        
        # Calculate expected R:R improvement
        stop_loss = standard_targets.get("stop_loss", entry_price * 0.99 if direction == "LONG" else entry_price * 1.01)
        if std_t1 and liq_t1 and stop_loss:
            std_rr = abs(std_t1 - entry_price) / abs(entry_price - stop_loss) if abs(entry_price - stop_loss) > 0 else 0
            liq_rr = abs(liq_t1 - entry_price) / abs(entry_price - stop_loss) if abs(entry_price - stop_loss) > 0 else 0
            shadow_result["comparison"]["expected_rr_improvement"] = round((liq_rr - std_rr), 2)
        
        # Update data quality
        shadow_result["data_quality"]["overall_quality"] = quality_score
        shadow_result["data_quality"]["missing_sources"] = missing
        shadow_result["data_quality"]["sources_used"] = sources_used
        
        return shadow_result
        
    except Exception as e:
        logger.error(f"[Shadow Liquidity Engine v0.2] Error calculating targets: {e}")
        import traceback
        logger.error(traceback.format_exc())
        shadow_result["data_quality"]["overall_quality"] = 0
        shadow_result["data_quality"]["missing_sources"].append(f"error: {str(e)}")
        return shadow_result


async def store_shadow_targets(signal_id: str, shadow_data: Dict[str, Any]) -> bool:
    """
    Store shadow liquidity targets in database for analysis.
    Uses a separate collection to avoid polluting live data.
    """
    try:
        collection = db["shadow_liquidity_targets"]
        
        doc = {
            "signal_id": signal_id,
            "created_at": datetime.now(timezone.utc),
            **shadow_data
        }
        
        # Upsert to avoid duplicates
        await collection.update_one(
            {"signal_id": signal_id},
            {"$set": doc},
            upsert=True
        )
        
        logger.debug(f"[Shadow Liquidity] Stored shadow targets for signal {signal_id[:8]}...")
        return True
        
    except Exception as e:
        logger.error(f"[Shadow Liquidity] Error storing shadow targets: {e}")
        return False


# ═══════════════════════════════════════════════════════════════════════════════
# SHADOW TARGET VALIDATION SYSTEM
# Tracks and compares actual outcomes vs predictions
# ═══════════════════════════════════════════════════════════════════════════════

async def validate_shadow_target_outcome(
    signal_id: str,
    price_history: List[Dict[str, Any]],  # List of {timestamp, price} during signal lifetime
    final_outcome: str,  # WIN / LOSS / PARTIAL_WIN / EXPIRED
    outcome_price: float
) -> Dict[str, Any]:
    """
    Validate shadow target predictions against actual price action.
    
    Computes:
    - Which targets were actually hit (standard vs shadow)
    - MFE (Max Favorable Excursion) - best price reached
    - MAE (Max Adverse Excursion) - worst price reached
    - Profit comparison between standard and shadow exits
    
    Returns validation results for storage and analysis.
    """
    try:
        # Get the shadow target data
        collection = db["shadow_liquidity_targets"]
        shadow_doc = await collection.find_one({"signal_id": signal_id}, {"_id": 0})
        
        if not shadow_doc:
            return {"error": "Shadow targets not found for this signal"}
        
        direction = shadow_doc.get("direction", "LONG")
        entry_price = shadow_doc.get("entry_price", 0)
        
        # Standard targets
        std_targets = shadow_doc.get("standard_targets", {})
        std_t1 = std_targets.get("target_1", 0)
        std_t2 = std_targets.get("target_2", 0)
        stop_loss = std_targets.get("stop_loss", 0)
        
        # Shadow targets
        liq_targets = shadow_doc.get("liquidity_targets", {})
        shadow_t1 = liq_targets.get("target_1", 0)
        shadow_t2 = liq_targets.get("target_2", 0)
        
        # Calculate MFE/MAE from price history
        if price_history and len(price_history) > 0:
            prices = [p.get("price", 0) for p in price_history if p.get("price", 0) > 0]
            
            if prices:
                if direction == "LONG":
                    mfe = max(prices)  # Best price for LONG
                    mae = min(prices)  # Worst price for LONG
                    mfe_pct = ((mfe - entry_price) / entry_price) * 100
                    mae_pct = ((mae - entry_price) / entry_price) * 100
                else:
                    mfe = min(prices)  # Best price for SHORT
                    mae = max(prices)  # Worst price for SHORT
                    mfe_pct = ((entry_price - mfe) / entry_price) * 100
                    mae_pct = ((entry_price - mae) / entry_price) * 100
            else:
                mfe_pct = 0
                mae_pct = 0
        else:
            mfe_pct = 0
            mae_pct = 0
        
        # Check which targets were hit
        def was_target_hit(target_price: float, direction: str, prices: List[float]) -> bool:
            if not target_price or not prices:
                return False
            if direction == "LONG":
                return any(p >= target_price for p in prices)
            else:
                return any(p <= target_price for p in prices)
        
        prices_list = [p.get("price", 0) for p in price_history] if price_history else []
        
        std_t1_hit = was_target_hit(std_t1, direction, prices_list)
        std_t2_hit = was_target_hit(std_t2, direction, prices_list)
        shadow_t1_hit = was_target_hit(shadow_t1, direction, prices_list)
        shadow_t2_hit = was_target_hit(shadow_t2, direction, prices_list)
        
        # Calculate hypothetical profits
        def calc_profit_pct(entry: float, exit: float, direction: str) -> float:
            if direction == "LONG":
                return ((exit - entry) / entry) * 100
            else:
                return ((entry - exit) / entry) * 100
        
        # Standard profit (based on final outcome)
        if final_outcome in ["WIN"]:
            profit_standard = calc_profit_pct(entry_price, std_t2, direction) if std_t2 else 0
        elif final_outcome in ["PARTIAL_WIN"]:
            profit_standard = calc_profit_pct(entry_price, std_t1, direction) if std_t1 else 0
        elif final_outcome == "LOSS":
            profit_standard = calc_profit_pct(entry_price, stop_loss, direction) if stop_loss else 0
        else:
            profit_standard = 0
        
        # Shadow profit (what would have happened with shadow targets)
        if shadow_t2_hit:
            profit_shadow = calc_profit_pct(entry_price, shadow_t2, direction) if shadow_t2 else 0
        elif shadow_t1_hit:
            profit_shadow = calc_profit_pct(entry_price, shadow_t1, direction) if shadow_t1 else 0
        elif final_outcome == "LOSS":
            profit_shadow = calc_profit_pct(entry_price, stop_loss, direction) if stop_loss else 0
        else:
            profit_shadow = 0
        
        # Determine which system performed better
        shadow_outperformed = profit_shadow > profit_standard
        
        validation_result = {
            "status": "completed",
            "validated_at": datetime.now(timezone.utc).isoformat(),
            "standard_t1_hit": std_t1_hit,
            "standard_t2_hit": std_t2_hit,
            "shadow_t1_hit": shadow_t1_hit,
            "shadow_t2_hit": shadow_t2_hit,
            "mfe_percent": round(mfe_pct, 2),
            "mae_percent": round(mae_pct, 2),
            "final_outcome": final_outcome,
            "profit_standard_percent": round(profit_standard, 2),
            "profit_shadow_percent": round(profit_shadow, 2),
            "shadow_outperformed": shadow_outperformed,
            "profit_difference": round(profit_shadow - profit_standard, 2)
        }
        
        # Update the shadow targets document with validation
        await collection.update_one(
            {"signal_id": signal_id},
            {"$set": {"validation": validation_result}}
        )
        
        logger.info(f"[Shadow Validation] Signal {signal_id[:8]}: Standard={profit_standard:.2f}% vs Shadow={profit_shadow:.2f}%")
        
        return validation_result
        
    except Exception as e:
        logger.error(f"[Shadow Validation] Error validating signal {signal_id}: {e}")
        return {"error": str(e)}


async def get_shadow_performance_comparison() -> Dict[str, Any]:
    """
    Calculate aggregate performance comparison between standard and shadow targets.
    
    Returns comprehensive metrics for decision-making:
    - Win rates for both systems
    - Average profits
    - % of trades where shadow outperformed
    - Statistical significance indicators
    """
    try:
        collection = db["shadow_liquidity_targets"]
        
        # Get all validated signals
        validated_signals = await collection.find(
            {"validation.status": "completed"},
            {"_id": 0, "validation": 1, "direction": 1, "data_quality": 1, "comparison": 1}
        ).to_list(500)
        
        if not validated_signals or len(validated_signals) == 0:
            return {
                "status": "insufficient_data",
                "message": "No validated signals yet. Continue collecting data.",
                "signals_analyzed": 0,
                "minimum_required": 20
            }
        
        total = len(validated_signals)
        
        # Aggregate metrics
        standard_wins = 0
        shadow_wins = 0
        standard_profits = []
        shadow_profits = []
        shadow_outperformed_count = 0
        standard_outperformed_count = 0
        
        by_direction = {"LONG": {"standard": [], "shadow": []}, "SHORT": {"standard": [], "shadow": []}}
        
        for sig in validated_signals:
            val = sig.get("validation", {})
            direction = sig.get("direction", "LONG")
            
            std_profit = val.get("profit_standard_percent", 0)
            shadow_profit = val.get("profit_shadow_percent", 0)
            
            standard_profits.append(std_profit)
            shadow_profits.append(shadow_profit)
            
            by_direction[direction]["standard"].append(std_profit)
            by_direction[direction]["shadow"].append(shadow_profit)
            
            if std_profit > 0:
                standard_wins += 1
            if shadow_profit > 0:
                shadow_wins += 1
                
            if val.get("shadow_outperformed", False):
                shadow_outperformed_count += 1
            elif std_profit > shadow_profit:
                standard_outperformed_count += 1
        
        # Calculate averages
        avg_standard = sum(standard_profits) / total if total > 0 else 0
        avg_shadow = sum(shadow_profits) / total if total > 0 else 0
        
        # Win rates
        standard_win_rate = (standard_wins / total) * 100 if total > 0 else 0
        shadow_win_rate = (shadow_wins / total) * 100 if total > 0 else 0
        
        # Calculate average R:R achieved (need more context, simplified here)
        avg_mfe = sum(v.get("validation", {}).get("mfe_percent", 0) for v in validated_signals) / total if total > 0 else 0
        avg_mae = sum(abs(v.get("validation", {}).get("mae_percent", 0)) for v in validated_signals) / total if total > 0 else 0
        
        # Statistical significance check (simplified - proper test would use t-test)
        is_statistically_significant = total >= 30 and abs(avg_shadow - avg_standard) > 0.5
        
        return {
            "status": "complete",
            "signals_analyzed": total,
            "minimum_for_confidence": 30,
            "has_sufficient_data": total >= 30,
            
            # Primary comparison metrics
            "comparison": {
                "standard_avg_profit_pct": round(avg_standard, 2),
                "shadow_avg_profit_pct": round(avg_shadow, 2),
                "profit_difference_pct": round(avg_shadow - avg_standard, 2),
                
                "standard_win_rate_pct": round(standard_win_rate, 1),
                "shadow_win_rate_pct": round(shadow_win_rate, 1),
                
                "shadow_outperformed_pct": round((shadow_outperformed_count / total) * 100, 1) if total > 0 else 0,
                "standard_outperformed_pct": round((standard_outperformed_count / total) * 100, 1) if total > 0 else 0,
                "ties_pct": round(((total - shadow_outperformed_count - standard_outperformed_count) / total) * 100, 1) if total > 0 else 0
            },
            
            # Risk metrics
            "risk_metrics": {
                "avg_mfe_pct": round(avg_mfe, 2),
                "avg_mae_pct": round(avg_mae, 2),
                "risk_reward_achieved": round(avg_mfe / avg_mae, 2) if avg_mae > 0 else 0
            },
            
            # By direction breakdown
            "by_direction": {
                "LONG": {
                    "count": len(by_direction["LONG"]["standard"]),
                    "standard_avg": round(sum(by_direction["LONG"]["standard"]) / len(by_direction["LONG"]["standard"]), 2) if by_direction["LONG"]["standard"] else 0,
                    "shadow_avg": round(sum(by_direction["LONG"]["shadow"]) / len(by_direction["LONG"]["shadow"]), 2) if by_direction["LONG"]["shadow"] else 0
                },
                "SHORT": {
                    "count": len(by_direction["SHORT"]["standard"]),
                    "standard_avg": round(sum(by_direction["SHORT"]["standard"]) / len(by_direction["SHORT"]["standard"]), 2) if by_direction["SHORT"]["standard"] else 0,
                    "shadow_avg": round(sum(by_direction["SHORT"]["shadow"]) / len(by_direction["SHORT"]["shadow"]), 2) if by_direction["SHORT"]["shadow"] else 0
                }
            },
            
            # Recommendation
            "recommendation": {
                "is_statistically_significant": is_statistically_significant,
                "suggested_action": get_shadow_recommendation(avg_shadow, avg_standard, total, shadow_outperformed_count),
                "confidence_level": "high" if total >= 50 else "medium" if total >= 30 else "low"
            },
            
            "last_updated": datetime.now(timezone.utc).isoformat()
        }
        
    except Exception as e:
        logger.error(f"[Shadow Performance] Error calculating comparison: {e}")
        return {"error": str(e)}


def get_shadow_recommendation(shadow_avg: float, standard_avg: float, total: int, outperformed: int) -> str:
    """Generate a recommendation based on comparison data"""
    if total < 20:
        return "Continue collecting data. Minimum 20 signals needed for initial assessment."
    
    if total < 50:
        pct_better = (outperformed / total) * 100
        diff = shadow_avg - standard_avg
        if diff > 0.5 and pct_better > 55:
            return f"Early results favorable for shadow (+{diff:.2f}% avg). Continue to 50 signals for confidence."
        elif diff < -0.5:
            return f"Early results favor standard targets. Shadow underperforming by {abs(diff):.2f}%."
        else:
            return "Results inconclusive so far. Continue data collection."
    
    # 50+ signals
    pct_better = (outperformed / total) * 100
    diff = shadow_avg - standard_avg
    
    if diff > 0.5 and pct_better > 60:
        return f"RECOMMEND SWITCH: Shadow targets showing +{diff:.2f}% avg improvement, outperforming in {pct_better:.0f}% of trades."
    elif diff > 0.3 and pct_better > 55:
        return f"CONSIDER TESTING LIVE: Shadow targets show modest improvement (+{diff:.2f}%), could run parallel live test."
    elif diff < -0.3:
        return f"KEEP STANDARD: Standard targets outperforming shadow by {abs(diff):.2f}%. Shadow approach needs refinement."
    else:
        return "NO CLEAR WINNER: Both systems performing similarly. Consider other factors for decision."


# ═══════════════════════════════════════════════════════════════════════════════════════
# SHADOW VALIDATION ENGINE v1.0
# 
# Complete shadow validation system that evaluates V3 signals WITHOUT modifying live logic.
# Runs in parallel, logs everything, makes no production changes.
#
# Components:
# 1. Hard Risk Filter - R:R and conflict validation
# 2. Setup Classification - LOW/MID/HIGH quality categorization
# 3. Hybrid Exit Simulation - Standard vs Shadow vs Hybrid comparison
# 4. Performance Tracking - Full metrics for 30-day observation
# 5. Promotion Readiness - Data-driven switch recommendations
# ═══════════════════════════════════════════════════════════════════════════════════════

class ShadowValidationStatus(str, Enum):
    """Shadow validation result status"""
    VALID = "VALID"              # Signal passes all shadow checks
    LOW_QUALITY = "LOW_QUALITY"  # Signal has issues but not rejected
    REJECTED = "REJECTED"        # Signal would be filtered out

class SetupQualityClass(str, Enum):
    """Setup quality classification"""
    LOW = "LOW"
    MID = "MID"
    HIGH = "HIGH"

class ExitModel(str, Enum):
    """Exit strategy models for comparison"""
    STANDARD = "STANDARD"   # Current V3 targets
    SHADOW = "SHADOW"       # Liquidity-based targets
    HYBRID = "HYBRID"       # 50% standard T1, 50% shadow T2


def calculate_risk_reward_ratio(
    entry_price: float,
    stop_loss: float,
    target: float,
    direction: str
) -> float:
    """Calculate R:R ratio for a trade setup"""
    if direction == "LONG":
        risk = entry_price - stop_loss
        reward = target - entry_price
    else:
        risk = stop_loss - entry_price
        reward = entry_price - target
    
    if risk <= 0:
        return 0.0
    
    return round(reward / risk, 2)


async def perform_shadow_risk_validation(
    setup: Dict[str, Any],
    current_price: float,
    whale_direction: Optional[str] = None,
    liquidity_direction: Optional[str] = None,
    data_freshness: Optional[Dict[str, Any]] = None
) -> Dict[str, Any]:
    """
    TASK 1: Hard Risk Filter (Shadow Mode)
    
    Evaluates each V3 signal BEFORE it would be considered tradable.
    Does NOT block live signals - only logs and evaluates.
    
    Rules:
    - Reject if R:R < 1.0
    - Flag as LOW_QUALITY if R:R < 1.3
    - Block if: high risk + quality_score < 70
    - Block if: data freshness degraded
    - Block if: conflicting whale vs liquidity signals
    
    Returns validation result for logging.
    """
    validation_result = {
        "shadow_validation": {
            "status": ShadowValidationStatus.VALID.value,
            "reasons": [],
            "risk_flags": [],
            "computed_rr": 0,
            "quality_assessment": "",
            "conflict_detected": False,
            "data_quality_ok": True,
            "would_be_tradable": True,
            "timestamp": datetime.now(timezone.utc).isoformat()
        }
    }
    
    try:
        direction = setup.get("direction", "LONG")
        entry_price = setup.get("zone_low", current_price) if direction == "LONG" else setup.get("zone_high", current_price)
        stop_loss = setup.get("stop_loss", 0)
        target_1 = setup.get("target_1", 0)
        target_2 = setup.get("target_2", 0)
        quality_score = setup.get("quality_score", 50)
        
        reasons = []
        risk_flags = []
        
        # ═══════════════════════════════════════════════════════════════════
        # 1. R:R VALIDATION
        # ═══════════════════════════════════════════════════════════════════
        if target_1 and stop_loss:
            rr_t1 = calculate_risk_reward_ratio(entry_price, stop_loss, target_1, direction)
            validation_result["shadow_validation"]["computed_rr"] = rr_t1
            
            if rr_t1 < 1.0:
                validation_result["shadow_validation"]["status"] = ShadowValidationStatus.REJECTED.value
                reasons.append(f"R:R too low ({rr_t1:.2f} < 1.0 minimum)")
                risk_flags.append("CRITICAL_RR")
                validation_result["shadow_validation"]["would_be_tradable"] = False
            
            elif rr_t1 < 1.3:
                if validation_result["shadow_validation"]["status"] != ShadowValidationStatus.REJECTED.value:
                    validation_result["shadow_validation"]["status"] = ShadowValidationStatus.LOW_QUALITY.value
                reasons.append(f"R:R below ideal ({rr_t1:.2f} < 1.3)")
                risk_flags.append("LOW_RR")
        else:
            validation_result["shadow_validation"]["status"] = ShadowValidationStatus.REJECTED.value
            reasons.append("Missing target or stop loss data")
            risk_flags.append("INCOMPLETE_DATA")
            validation_result["shadow_validation"]["would_be_tradable"] = False
        
        # ═══════════════════════════════════════════════════════════════════
        # 2. QUALITY + RISK COMBINATION CHECK
        # ═══════════════════════════════════════════════════════════════════
        if quality_score < 70:
            risk_flags.append("LOW_QUALITY_SCORE")
            if validation_result["shadow_validation"]["computed_rr"] < 1.3:
                validation_result["shadow_validation"]["status"] = ShadowValidationStatus.REJECTED.value
                reasons.append(f"Low quality ({quality_score}) combined with poor R:R")
                validation_result["shadow_validation"]["would_be_tradable"] = False
        
        # ═══════════════════════════════════════════════════════════════════
        # 3. CONFLICT DETECTION (Whale vs Liquidity)
        # ═══════════════════════════════════════════════════════════════════
        if whale_direction and liquidity_direction:
            # Normalize directions
            whale_bull = whale_direction.upper() in ["BUY", "LONG", "BULLISH"]
            whale_bear = whale_direction.upper() in ["SELL", "SHORT", "BEARISH"]
            liq_up = liquidity_direction.upper() in ["UP", "ABOVE", "LONG", "BULLISH"]
            liq_down = liquidity_direction.upper() in ["DOWN", "BELOW", "SHORT", "BEARISH"]
            
            # Check for conflict
            if (whale_bull and liq_down) or (whale_bear and liq_up):
                validation_result["shadow_validation"]["conflict_detected"] = True
                risk_flags.append("WHALE_LIQ_CONFLICT")
                
                if validation_result["shadow_validation"]["status"] != ShadowValidationStatus.REJECTED.value:
                    validation_result["shadow_validation"]["status"] = ShadowValidationStatus.LOW_QUALITY.value
                reasons.append(f"Conflicting signals: Whale={whale_direction}, Liquidity={liquidity_direction}")
        
        # ═══════════════════════════════════════════════════════════════════
        # 4. DATA FRESHNESS CHECK
        # ═══════════════════════════════════════════════════════════════════
        if data_freshness:
            stale_sources = []
            for source, info in data_freshness.items():
                if isinstance(info, dict):
                    status = info.get("status", "fresh")
                    if status in ["stale", "critical", "unavailable"]:
                        stale_sources.append(source)
            
            if len(stale_sources) >= 2:
                validation_result["shadow_validation"]["data_quality_ok"] = False
                risk_flags.append("STALE_DATA")
                
                if "price" in stale_sources or "candles" in stale_sources:
                    validation_result["shadow_validation"]["status"] = ShadowValidationStatus.REJECTED.value
                    reasons.append(f"Critical data stale: {stale_sources}")
                    validation_result["shadow_validation"]["would_be_tradable"] = False
                else:
                    reasons.append(f"Data freshness degraded: {stale_sources}")
        
        # ═══════════════════════════════════════════════════════════════════
        # 5. GENERATE QUALITY ASSESSMENT
        # ═══════════════════════════════════════════════════════════════════
        rr = validation_result["shadow_validation"]["computed_rr"]
        if rr >= 1.5 and quality_score >= 80 and not validation_result["shadow_validation"]["conflict_detected"]:
            validation_result["shadow_validation"]["quality_assessment"] = "EXCELLENT - Strong setup with good R:R"
        elif rr >= 1.3 and quality_score >= 70:
            validation_result["shadow_validation"]["quality_assessment"] = "GOOD - Tradable setup"
        elif rr >= 1.0 and quality_score >= 60:
            validation_result["shadow_validation"]["quality_assessment"] = "MARGINAL - Reduced position size recommended"
        else:
            validation_result["shadow_validation"]["quality_assessment"] = "POOR - Would be filtered in optimized system"
        
        validation_result["shadow_validation"]["reasons"] = reasons
        validation_result["shadow_validation"]["risk_flags"] = risk_flags
        
        return validation_result
        
    except Exception as e:
        logger.error(f"[Shadow Risk Filter] Error: {e}")
        validation_result["shadow_validation"]["status"] = ShadowValidationStatus.REJECTED.value
        validation_result["shadow_validation"]["reasons"].append(f"Validation error: {str(e)}")
        return validation_result


def classify_setup_quality(
    quality_score: float,
    rr_ratio: float,
    whale_aligned: bool,
    liquidity_aligned: bool,
    regime: str,
    conflict_detected: bool = False
) -> Dict[str, Any]:
    """
    TASK 3: Setup Classification
    
    Classifies each signal into LOW_QUALITY, MID_QUALITY, or HIGH_QUALITY.
    
    Scoring:
    - Quality Score: 0-100 (primary factor)
    - R:R Ratio: < 1.0 = penalty, > 1.5 = bonus
    - Whale Alignment: +15 if aligned
    - Liquidity Alignment: +15 if aligned
    - Regime Clarity: TRENDING = +10, COMPRESSION = +5
    - Conflicts: -20 if detected
    
    Returns classification with reasoning.
    """
    classification = {
        "setup_class": SetupQualityClass.MID.value,
        "composite_score": 0,
        "factors": {
            "quality_score_contribution": 0,
            "rr_contribution": 0,
            "whale_contribution": 0,
            "liquidity_contribution": 0,
            "regime_contribution": 0,
            "conflict_penalty": 0
        },
        "reasoning": []
    }
    
    composite = 0
    
    # Quality score contribution (0-50 points)
    quality_contribution = min(50, quality_score * 0.5)
    composite += quality_contribution
    classification["factors"]["quality_score_contribution"] = round(quality_contribution, 1)
    
    # R:R contribution (-20 to +20 points)
    if rr_ratio >= 2.0:
        rr_contribution = 20
        classification["reasoning"].append("Excellent R:R (≥2.0)")
    elif rr_ratio >= 1.5:
        rr_contribution = 15
        classification["reasoning"].append("Good R:R (≥1.5)")
    elif rr_ratio >= 1.3:
        rr_contribution = 10
        classification["reasoning"].append("Acceptable R:R (≥1.3)")
    elif rr_ratio >= 1.0:
        rr_contribution = 0
        classification["reasoning"].append("Marginal R:R (≥1.0)")
    else:
        rr_contribution = -20
        classification["reasoning"].append("Poor R:R (<1.0)")
    
    composite += rr_contribution
    classification["factors"]["rr_contribution"] = rr_contribution
    
    # Whale alignment (+15)
    if whale_aligned:
        composite += 15
        classification["factors"]["whale_contribution"] = 15
        classification["reasoning"].append("Whale flow aligned")
    
    # Liquidity alignment (+15)
    if liquidity_aligned:
        composite += 15
        classification["factors"]["liquidity_contribution"] = 15
        classification["reasoning"].append("Liquidity direction aligned")
    
    # Regime contribution
    regime_upper = (regime or "").upper()
    if regime_upper in ["TRENDING", "TREND"]:
        composite += 10
        classification["factors"]["regime_contribution"] = 10
        classification["reasoning"].append("Clear trending regime")
    elif regime_upper == "COMPRESSION":
        composite += 5
        classification["factors"]["regime_contribution"] = 5
        classification["reasoning"].append("Compression (breakout potential)")
    elif regime_upper in ["VOLATILE", "CHOPPY"]:
        composite -= 5
        classification["factors"]["regime_contribution"] = -5
        classification["reasoning"].append("Volatile regime (higher risk)")
    
    # Conflict penalty
    if conflict_detected:
        composite -= 20
        classification["factors"]["conflict_penalty"] = -20
        classification["reasoning"].append("Signal conflict detected")
    
    classification["composite_score"] = round(composite, 1)
    
    # Final classification
    if composite >= 75:
        classification["setup_class"] = SetupQualityClass.HIGH.value
    elif composite >= 50:
        classification["setup_class"] = SetupQualityClass.MID.value
    else:
        classification["setup_class"] = SetupQualityClass.LOW.value
    
    return classification


async def simulate_hybrid_exit(
    entry_price: float,
    direction: str,
    stop_loss: float,
    standard_t1: float,
    standard_t2: float,
    shadow_t1: Optional[float],
    shadow_t2: Optional[float],
    price_history: List[Dict[str, Any]]
) -> Dict[str, Any]:
    """
    TASK 2: Hybrid Exit Simulation
    
    Simulates three exit models and compares results:
    
    1. STANDARD: 100% exit at standard T1 or T2
    2. SHADOW: 100% exit at shadow T1 or T2
    3. HYBRID: 50% at standard T1, 50% left running toward shadow T2
    
    Returns comparison of all three models.
    """
    simulation = {
        "models": {
            "standard": {
                "realized_r": 0,
                "exit_price": None,
                "exit_reason": None,
                "partial_exits": []
            },
            "shadow": {
                "realized_r": 0,
                "exit_price": None,
                "exit_reason": None,
                "partial_exits": []
            },
            "hybrid": {
                "realized_r": 0,
                "weighted_exit_price": None,
                "partial_exits": []
            }
        },
        "comparison": {
            "best_model": None,
            "worst_model": None,
            "standard_vs_shadow_delta": 0,
            "standard_vs_hybrid_delta": 0,
            "shadow_vs_hybrid_delta": 0
        },
        "price_analysis": {
            "mfe": 0,
            "mfe_price": None,
            "mae": 0,
            "mae_price": None,
            "standard_exit_too_early": False,
            "shadow_missed_profit": False
        }
    }
    
    if not price_history:
        return simulation
    
    prices = [p.get("price", 0) for p in price_history if p.get("price", 0) > 0]
    if not prices:
        return simulation
    
    # Calculate risk (for R:R computation)
    if direction == "LONG":
        risk = entry_price - stop_loss
        mfe_price = max(prices)
        mae_price = min(prices)
        mfe_pct = ((mfe_price - entry_price) / entry_price) * 100
        mae_pct = ((entry_price - mae_price) / entry_price) * 100
    else:
        risk = stop_loss - entry_price
        mfe_price = min(prices)
        mae_price = max(prices)
        mfe_pct = ((entry_price - mfe_price) / entry_price) * 100
        mae_pct = ((mae_price - entry_price) / entry_price) * 100
    
    simulation["price_analysis"]["mfe"] = round(mfe_pct, 2)
    simulation["price_analysis"]["mfe_price"] = mfe_price
    simulation["price_analysis"]["mae"] = round(mae_pct, 2)
    simulation["price_analysis"]["mae_price"] = mae_price
    
    # Helper to check if target hit
    def was_hit(target: float, direction: str, prices: List[float]) -> bool:
        if not target:
            return False
        if direction == "LONG":
            return any(p >= target for p in prices)
        else:
            return any(p <= target for p in prices)
    
    # Helper to calculate R:R
    def calc_r(exit_price: float, entry: float, risk: float, direction: str) -> float:
        if risk <= 0:
            return 0
        if direction == "LONG":
            return (exit_price - entry) / risk
        else:
            return (entry - exit_price) / risk
    
    # ═══════════════════════════════════════════════════════════════════
    # STANDARD MODEL
    # ═══════════════════════════════════════════════════════════════════
    std_hit_t1 = was_hit(standard_t1, direction, prices)
    std_hit_t2 = was_hit(standard_t2, direction, prices)
    std_hit_stop = was_hit(stop_loss, direction if direction == "SHORT" else ("SHORT" if direction == "LONG" else "LONG"), prices)
    
    if std_hit_t2:
        simulation["models"]["standard"]["exit_price"] = standard_t2
        simulation["models"]["standard"]["exit_reason"] = "T2_HIT"
        simulation["models"]["standard"]["realized_r"] = calc_r(standard_t2, entry_price, risk, direction)
    elif std_hit_t1:
        simulation["models"]["standard"]["exit_price"] = standard_t1
        simulation["models"]["standard"]["exit_reason"] = "T1_HIT"
        simulation["models"]["standard"]["realized_r"] = calc_r(standard_t1, entry_price, risk, direction)
    elif std_hit_stop:
        simulation["models"]["standard"]["exit_price"] = stop_loss
        simulation["models"]["standard"]["exit_reason"] = "STOP_LOSS"
        simulation["models"]["standard"]["realized_r"] = -1.0
    else:
        # Expired - use last price
        simulation["models"]["standard"]["exit_price"] = prices[-1]
        simulation["models"]["standard"]["exit_reason"] = "EXPIRED"
        simulation["models"]["standard"]["realized_r"] = calc_r(prices[-1], entry_price, risk, direction)
    
    # ═══════════════════════════════════════════════════════════════════
    # SHADOW MODEL
    # ═══════════════════════════════════════════════════════════════════
    if shadow_t1 and shadow_t2:
        shd_hit_t1 = was_hit(shadow_t1, direction, prices)
        shd_hit_t2 = was_hit(shadow_t2, direction, prices)
        
        if shd_hit_t2:
            simulation["models"]["shadow"]["exit_price"] = shadow_t2
            simulation["models"]["shadow"]["exit_reason"] = "T2_HIT"
            simulation["models"]["shadow"]["realized_r"] = calc_r(shadow_t2, entry_price, risk, direction)
        elif shd_hit_t1:
            simulation["models"]["shadow"]["exit_price"] = shadow_t1
            simulation["models"]["shadow"]["exit_reason"] = "T1_HIT"
            simulation["models"]["shadow"]["realized_r"] = calc_r(shadow_t1, entry_price, risk, direction)
        elif std_hit_stop:
            simulation["models"]["shadow"]["exit_price"] = stop_loss
            simulation["models"]["shadow"]["exit_reason"] = "STOP_LOSS"
            simulation["models"]["shadow"]["realized_r"] = -1.0
        else:
            simulation["models"]["shadow"]["exit_price"] = prices[-1]
            simulation["models"]["shadow"]["exit_reason"] = "EXPIRED"
            simulation["models"]["shadow"]["realized_r"] = calc_r(prices[-1], entry_price, risk, direction)
    else:
        # No shadow targets - copy standard
        simulation["models"]["shadow"] = simulation["models"]["standard"].copy()
    
    # ═══════════════════════════════════════════════════════════════════
    # HYBRID MODEL (50% standard T1, 50% toward shadow T2)
    # ═══════════════════════════════════════════════════════════════════
    hybrid_r = 0
    partial_exits = []
    
    # First 50%: Exit at standard T1 if hit
    if std_hit_t1:
        first_exit_r = calc_r(standard_t1, entry_price, risk, direction) * 0.5
        partial_exits.append({
            "portion": 0.5,
            "exit_price": standard_t1,
            "reason": "STANDARD_T1"
        })
        hybrid_r += first_exit_r
        
        # Second 50%: Try to reach shadow T2
        if shadow_t2 and was_hit(shadow_t2, direction, prices):
            second_exit_r = calc_r(shadow_t2, entry_price, risk, direction) * 0.5
            partial_exits.append({
                "portion": 0.5,
                "exit_price": shadow_t2,
                "reason": "SHADOW_T2"
            })
            hybrid_r += second_exit_r
        elif std_hit_stop:
            partial_exits.append({
                "portion": 0.5,
                "exit_price": stop_loss,
                "reason": "STOP_LOSS"
            })
            hybrid_r += -0.5  # -1R * 0.5
        else:
            # Trail to best available
            second_exit_r = calc_r(prices[-1], entry_price, risk, direction) * 0.5
            partial_exits.append({
                "portion": 0.5,
                "exit_price": prices[-1],
                "reason": "TRAIL_EXIT"
            })
            hybrid_r += second_exit_r
    elif std_hit_stop:
        # Full stop loss
        hybrid_r = -1.0
        partial_exits.append({
            "portion": 1.0,
            "exit_price": stop_loss,
            "reason": "STOP_LOSS"
        })
    else:
        # Expired
        hybrid_r = calc_r(prices[-1], entry_price, risk, direction)
        partial_exits.append({
            "portion": 1.0,
            "exit_price": prices[-1],
            "reason": "EXPIRED"
        })
    
    simulation["models"]["hybrid"]["realized_r"] = round(hybrid_r, 2)
    simulation["models"]["hybrid"]["partial_exits"] = partial_exits
    if partial_exits:
        weighted_price = sum(p["exit_price"] * p["portion"] for p in partial_exits)
        simulation["models"]["hybrid"]["weighted_exit_price"] = round(weighted_price, 2)
    
    # ═══════════════════════════════════════════════════════════════════
    # COMPARISON
    # ═══════════════════════════════════════════════════════════════════
    std_r = simulation["models"]["standard"]["realized_r"]
    shd_r = simulation["models"]["shadow"]["realized_r"]
    hyb_r = simulation["models"]["hybrid"]["realized_r"]
    
    results = {"STANDARD": std_r, "SHADOW": shd_r, "HYBRID": hyb_r}
    best = max(results, key=results.get)
    worst = min(results, key=results.get)
    
    simulation["comparison"]["best_model"] = best
    simulation["comparison"]["worst_model"] = worst
    simulation["comparison"]["standard_vs_shadow_delta"] = round(std_r - shd_r, 2)
    simulation["comparison"]["standard_vs_hybrid_delta"] = round(std_r - hyb_r, 2)
    simulation["comparison"]["shadow_vs_hybrid_delta"] = round(shd_r - hyb_r, 2)
    
    # Analysis: Did standard exit too early?
    if std_hit_t1 and mfe_pct > (standard_t1 - entry_price) / entry_price * 100 * 1.5:
        simulation["price_analysis"]["standard_exit_too_early"] = True
    
    # Analysis: Did shadow miss profit?
    if shadow_t2 and not was_hit(shadow_t2, direction, prices) and was_hit(standard_t2, direction, prices):
        simulation["price_analysis"]["shadow_missed_profit"] = True
    
    return simulation


async def store_shadow_validation_result(
    signal_id: str,
    setup_dict: Dict[str, Any],
    risk_validation: Dict[str, Any],
    setup_classification: Dict[str, Any],
    hybrid_simulation: Optional[Dict[str, Any]] = None
) -> bool:
    """
    Store comprehensive shadow validation results for analysis.
    """
    try:
        collection = db["shadow_validation_logs"]
        
        doc = {
            "signal_id": signal_id,
            "created_at": datetime.now(timezone.utc),
            "direction": setup_dict.get("direction"),
            "entry_price": setup_dict.get("zone_low") if setup_dict.get("direction") == "LONG" else setup_dict.get("zone_high"),
            "standard_targets": {
                "stop_loss": setup_dict.get("stop_loss"),
                "target_1": setup_dict.get("target_1"),
                "target_2": setup_dict.get("target_2")
            },
            "quality_score": setup_dict.get("quality_score"),
            "risk_validation": risk_validation,
            "setup_classification": setup_classification,
            "hybrid_simulation": hybrid_simulation,
            "outcome": {
                "status": "pending",  # Will be updated when signal closes
                "final_result": None,
                "actual_exit_price": None,
                "actual_r_realized": None
            }
        }
        
        await collection.update_one(
            {"signal_id": signal_id},
            {"$set": doc},
            upsert=True
        )
        
        logger.info(f"[Shadow Validation] Stored validation for {signal_id[:8]}: "
                   f"Status={risk_validation['shadow_validation']['status']}, "
                   f"Class={setup_classification['setup_class']}, "
                   f"R:R={risk_validation['shadow_validation']['computed_rr']}")
        
        return True
        
    except Exception as e:
        logger.error(f"[Shadow Validation] Error storing result: {e}")
        return False


async def get_promotion_readiness_report() -> Dict[str, Any]:
    """
    TASK 6: Promotion Readiness System
    
    After enough data collected, classifies overall performance and
    provides recommendation for system changes.
    
    Returns:
    - Which model performed best (STANDARD / SHADOW / HYBRID)
    - Confidence level
    - Recommendation (KEEP / TEST_LONGER / READY_FOR_ROLLOUT)
    """
    try:
        # Get all completed validations
        collection = db["shadow_validation_logs"]
        completed = await collection.find(
            {"outcome.status": "completed"},
            {"_id": 0}
        ).to_list(1000)
        
        if not completed:
            return {
                "status": "insufficient_data",
                "signals_analyzed": 0,
                "minimum_required": 30,
                "message": "No completed signals yet. Continue data collection."
            }
        
        total = len(completed)
        
        # Aggregate performance by model
        model_stats = {
            "STANDARD": {"total_r": 0, "wins": 0, "count": 0},
            "SHADOW": {"total_r": 0, "wins": 0, "count": 0},
            "HYBRID": {"total_r": 0, "wins": 0, "count": 0}
        }
        
        # Track which model won each trade
        model_wins = {"STANDARD": 0, "SHADOW": 0, "HYBRID": 0}
        
        # Quality class breakdown
        quality_performance = {
            "LOW": {"count": 0, "wins": 0, "avg_r": 0, "r_sum": 0},
            "MID": {"count": 0, "wins": 0, "avg_r": 0, "r_sum": 0},
            "HIGH": {"count": 0, "wins": 0, "avg_r": 0, "r_sum": 0}
        }
        
        # Validation filter effectiveness
        would_have_rejected = 0
        rejected_outcomes = {"wins": 0, "losses": 0}
        
        for sig in completed:
            sim = sig.get("hybrid_simulation", {})
            classification = sig.get("setup_classification", {})
            validation = sig.get("risk_validation", {}).get("shadow_validation", {})
            
            if sim and sim.get("models"):
                models = sim["models"]
                
                std_r = models.get("standard", {}).get("realized_r", 0)
                shd_r = models.get("shadow", {}).get("realized_r", 0)
                hyb_r = models.get("hybrid", {}).get("realized_r", 0)
                
                model_stats["STANDARD"]["total_r"] += std_r
                model_stats["SHADOW"]["total_r"] += shd_r
                model_stats["HYBRID"]["total_r"] += hyb_r
                
                model_stats["STANDARD"]["count"] += 1
                model_stats["SHADOW"]["count"] += 1
                model_stats["HYBRID"]["count"] += 1
                
                if std_r > 0:
                    model_stats["STANDARD"]["wins"] += 1
                if shd_r > 0:
                    model_stats["SHADOW"]["wins"] += 1
                if hyb_r > 0:
                    model_stats["HYBRID"]["wins"] += 1
                
                # Track best model per trade
                best = sim.get("comparison", {}).get("best_model")
                if best in model_wins:
                    model_wins[best] += 1
            
            # Quality class analysis
            q_class = classification.get("setup_class", "MID")
            if q_class in quality_performance:
                quality_performance[q_class]["count"] += 1
                actual_r = sig.get("outcome", {}).get("actual_r_realized", 0) or 0
                quality_performance[q_class]["r_sum"] += actual_r
                if actual_r > 0:
                    quality_performance[q_class]["wins"] += 1
            
            # Validation filter analysis
            if validation.get("status") == "REJECTED":
                would_have_rejected += 1
                actual_r = sig.get("outcome", {}).get("actual_r_realized", 0) or 0
                if actual_r > 0:
                    rejected_outcomes["wins"] += 1
                else:
                    rejected_outcomes["losses"] += 1
        
        # Calculate averages
        for model in model_stats:
            if model_stats[model]["count"] > 0:
                model_stats[model]["avg_r"] = round(model_stats[model]["total_r"] / model_stats[model]["count"], 2)
                model_stats[model]["win_rate"] = round((model_stats[model]["wins"] / model_stats[model]["count"]) * 100, 1)
        
        for q in quality_performance:
            if quality_performance[q]["count"] > 0:
                quality_performance[q]["avg_r"] = round(quality_performance[q]["r_sum"] / quality_performance[q]["count"], 2)
                quality_performance[q]["win_rate"] = round((quality_performance[q]["wins"] / quality_performance[q]["count"]) * 100, 1)
        
        # Determine best model
        best_model = max(model_stats, key=lambda x: model_stats[x]["avg_r"])
        best_model_win_pct = (model_wins[best_model] / total) * 100 if total > 0 else 0
        
        # Calculate expectancy for each model
        def calc_expectancy(win_rate, avg_r):
            return (win_rate / 100) * avg_r - (1 - win_rate / 100) * 1.0
        
        expectancies = {
            model: calc_expectancy(model_stats[model].get("win_rate", 50), model_stats[model].get("avg_r", 0))
            for model in model_stats
        }
        
        best_expectancy_model = max(expectancies, key=expectancies.get)
        
        # Risk filter effectiveness
        filter_accuracy = 0
        if would_have_rejected > 0:
            filter_accuracy = (rejected_outcomes["losses"] / would_have_rejected) * 100
        
        # Generate recommendation
        if total < 30:
            recommendation = "TEST_LONGER"
            recommendation_reason = f"Need more data ({total}/30 minimum)"
            confidence = "LOW"
        elif total < 50:
            if expectancies[best_expectancy_model] > expectancies["STANDARD"] + 0.1:
                recommendation = "PROMISING"
                recommendation_reason = f"{best_expectancy_model} showing edge. Continue to 50 signals."
            else:
                recommendation = "TEST_LONGER"
                recommendation_reason = "No clear winner yet"
            confidence = "MEDIUM"
        else:
            best_exp = expectancies[best_expectancy_model]
            std_exp = expectancies["STANDARD"]
            
            if best_expectancy_model != "STANDARD" and best_exp > std_exp + 0.15:
                recommendation = "READY_FOR_ROLLOUT"
                recommendation_reason = f"{best_expectancy_model} has +{(best_exp - std_exp):.2f} expectancy advantage"
                confidence = "HIGH"
            elif best_expectancy_model != "STANDARD" and best_exp > std_exp + 0.05:
                recommendation = "PARTIAL_ROLLOUT"
                recommendation_reason = f"{best_expectancy_model} has modest edge. Consider gradual transition."
                confidence = "MEDIUM"
            else:
                recommendation = "KEEP_CURRENT"
                recommendation_reason = "Standard system performing well"
                confidence = "HIGH"
        
        return {
            "status": "complete",
            "signals_analyzed": total,
            "minimum_required": 30,
            "observation_phase": "30_DAY" if total >= 30 else "COLLECTING",
            
            "model_performance": model_stats,
            "model_expectancies": {k: round(v, 3) for k, v in expectancies.items()},
            "model_win_counts": model_wins,
            
            "best_performer": {
                "model": best_model,
                "avg_r": model_stats[best_model]["avg_r"],
                "win_rate": model_stats[best_model].get("win_rate", 0),
                "won_pct_of_trades": round(best_model_win_pct, 1)
            },
            
            "best_expectancy": {
                "model": best_expectancy_model,
                "expectancy": round(expectancies[best_expectancy_model], 3)
            },
            
            "quality_class_analysis": quality_performance,
            
            "risk_filter_analysis": {
                "would_have_rejected": would_have_rejected,
                "rejected_that_won": rejected_outcomes["wins"],
                "rejected_that_lost": rejected_outcomes["losses"],
                "filter_accuracy_pct": round(filter_accuracy, 1)
            },
            
            "recommendation": {
                "action": recommendation,
                "reason": recommendation_reason,
                "confidence": confidence,
                "best_model_for_production": best_expectancy_model
            },
            
            "timestamp": datetime.now(timezone.utc).isoformat()
        }
        
    except Exception as e:
        logger.error(f"[Promotion Readiness] Error: {e}")
        return {"error": str(e)}


async def log_telegram_shadow_context(
    signal_id: str,
    setup_dict: Dict[str, Any],
    shadow_targets: Optional[Dict[str, Any]],
    hybrid_projection: Optional[Dict[str, Any]]
) -> None:
    """
    TASK 5: Telegram Shadow Extension (Internal Logging Only)
    
    Logs what the shadow/hybrid system would have produced.
    Does NOT modify actual Telegram messages.
    """
    try:
        collection = db["telegram_shadow_logs"]
        
        doc = {
            "signal_id": signal_id,
            "timestamp": datetime.now(timezone.utc),
            "live_message_sent": True,
            "shadow_context": {
                "shadow_t1": shadow_targets.get("liquidity_targets", {}).get("target_1") if shadow_targets else None,
                "shadow_t2": shadow_targets.get("liquidity_targets", {}).get("target_2") if shadow_targets else None,
                "shadow_t1_source": shadow_targets.get("liquidity_targets", {}).get("target_1_source") if shadow_targets else None,
                "shadow_confidence": shadow_targets.get("suggested_exit_plan", {}).get("confidence") if shadow_targets else None,
                "hybrid_would_exit": hybrid_projection.get("suggested_exit_plan") if hybrid_projection else None
            },
            "comparison_at_send_time": {
                "standard_t1": setup_dict.get("target_1"),
                "standard_t2": setup_dict.get("target_2"),
                "t1_difference": None,
                "t2_difference": None
            }
        }
        
        # Calculate differences
        if shadow_targets and shadow_targets.get("liquidity_targets"):
            std_t1 = setup_dict.get("target_1", 0)
            shd_t1 = shadow_targets.get("liquidity_targets", {}).get("target_1", 0)
            if std_t1 and shd_t1:
                doc["comparison_at_send_time"]["t1_difference"] = round(((shd_t1 - std_t1) / std_t1) * 100, 2)
            
            std_t2 = setup_dict.get("target_2", 0)
            shd_t2 = shadow_targets.get("liquidity_targets", {}).get("target_2", 0)
            if std_t2 and shd_t2:
                doc["comparison_at_send_time"]["t2_difference"] = round(((shd_t2 - std_t2) / std_t2) * 100, 2)
        
        await collection.insert_one(doc)
        logger.debug(f"[Telegram Shadow Log] Logged shadow context for {signal_id[:8]}")
        
    except Exception as e:
        logger.error(f"[Telegram Shadow Log] Error: {e}")


async def _perform_full_shadow_validation(
    signal_id: str,
    setup_data: Dict[str, Any],
    current_price: float,
    market_context: Optional[Dict[str, Any]] = None
) -> None:
    """
    Orchestrates full shadow validation for a V3 signal.
    
    This is called asynchronously when a V3 ENTRY_READY signal is generated.
    It does NOT affect the live signal - purely for data collection and analysis.
    
    Steps:
    1. Perform risk validation (R:R, conflicts, data quality)
    2. Classify setup quality (LOW/MID/HIGH)
    3. Store validation result for later comparison
    4. Log Telegram shadow context
    """
    try:
        logger.debug(f"[Shadow Validation] Starting full validation for {signal_id[:8]}")
        
        # Extract market context
        whale_direction = market_context.get("whale_direction") if market_context else None
        liquidity_direction = market_context.get("liquidity_direction") if market_context else None
        market_regime = setup_data.get("market_regime") or (market_context.get("market_regime") if market_context else None)
        
        # Get data freshness status
        data_freshness = get_all_data_freshness()
        
        # ═══════════════════════════════════════════════════════════════════
        # STEP 1: Risk Validation
        # ═══════════════════════════════════════════════════════════════════
        risk_validation = await perform_shadow_risk_validation(
            setup=setup_data,
            current_price=current_price,
            whale_direction=whale_direction,
            liquidity_direction=liquidity_direction,
            data_freshness=data_freshness
        )
        
        # ═══════════════════════════════════════════════════════════════════
        # STEP 2: Setup Classification
        # ═══════════════════════════════════════════════════════════════════
        direction = setup_data.get("direction", "LONG")
        quality_score = setup_data.get("quality_score", 50)
        rr_ratio = risk_validation.get("shadow_validation", {}).get("computed_rr", 1.0)
        
        # Determine alignments
        whale_aligned = False
        if whale_direction:
            whale_upper = whale_direction.upper()
            whale_aligned = (
                (direction == "LONG" and whale_upper in ["BUY", "LONG", "BULLISH"]) or
                (direction == "SHORT" and whale_upper in ["SELL", "SHORT", "BEARISH"])
            )
        
        liquidity_aligned = False
        if liquidity_direction:
            liq_upper = liquidity_direction.upper()
            liquidity_aligned = (
                (direction == "LONG" and liq_upper in ["UP", "ABOVE", "LONG"]) or
                (direction == "SHORT" and liq_upper in ["DOWN", "BELOW", "SHORT"])
            )
        
        conflict_detected = risk_validation.get("shadow_validation", {}).get("conflict_detected", False)
        
        setup_classification = classify_setup_quality(
            quality_score=quality_score,
            rr_ratio=rr_ratio,
            whale_aligned=whale_aligned,
            liquidity_aligned=liquidity_aligned,
            regime=market_regime or "",
            conflict_detected=conflict_detected
        )
        
        # ═══════════════════════════════════════════════════════════════════
        # STEP 3: Store Validation Result
        # ═══════════════════════════════════════════════════════════════════
        await store_shadow_validation_result(
            signal_id=signal_id,
            setup_dict=setup_data,
            risk_validation=risk_validation,
            setup_classification=setup_classification,
            hybrid_simulation=None  # Will be computed when outcome is known
        )
        
        # ═══════════════════════════════════════════════════════════════════
        # STEP 4: Log Telegram Shadow Context
        # ═══════════════════════════════════════════════════════════════════
        # Get shadow targets if already computed
        shadow_collection = db["shadow_liquidity_targets"]
        shadow_targets = await shadow_collection.find_one({"signal_id": signal_id}, {"_id": 0})
        
        await log_telegram_shadow_context(
            signal_id=signal_id,
            setup_dict=setup_data,
            shadow_targets=shadow_targets,
            hybrid_projection={
                "suggested_exit_plan": shadow_targets.get("suggested_exit_plan") if shadow_targets else None
            }
        )
        
        # Log summary
        status = risk_validation.get("shadow_validation", {}).get("status", "UNKNOWN")
        setup_class = setup_classification.get("setup_class", "MID")
        logger.info(f"[Shadow Validation] Complete for {signal_id[:8]}: "
                   f"Status={status}, Class={setup_class}, R:R={rr_ratio:.2f}")
        
    except Exception as e:
        logger.error(f"[Shadow Validation] Error in full validation: {e}")
        import traceback
        logger.error(traceback.format_exc())


async def _calculate_and_store_shadow_targets(
    signal_id: str,
    direction: str,
    entry_price: float,
    standard_targets: Dict[str, Any],
    market_context: Optional[Dict] = None
):
    """
    Internal helper to fetch market data and calculate shadow liquidity targets.
    Runs asynchronously without blocking the main signal flow.
    """
    try:
        # Fetch required data for shadow analysis
        # These are lightweight calls that reuse cached data where possible
        
        # 1. Get liquidation data from CoinGlass (cached)
        liq_data = await fetch_coinglass_liquidation()
        liquidation_levels = liq_data.get("liquidation_levels", []) if liq_data else []
        
        # 2. Get aggregated orderbook (cached)
        orderbook = await get_aggregated_orderbook()
        
        # 3. Get liquidity clusters from existing cache
        ticker = await fetch_kraken_ticker()
        current_price = ticker["price"] if ticker else entry_price
        candles = await fetch_kraken_ohlc(240)  # 4H candles
        
        clusters = []
        if candles and orderbook:
            clusters, _ = generate_liquidity_clusters_enhanced(candles, current_price, orderbook)
        
        # 4. Get magnet data
        magnet_data = None
        if market_context:
            magnet_data = {
                "nearest_magnet_price": market_context.get("nearest_magnet_price"),
                "magnet_score": market_context.get("magnet_score", 0),
                "magnet_direction": market_context.get("magnet_direction")
            }
        
        # Calculate shadow targets
        shadow_result = await calculate_shadow_liquidity_targets(
            direction=direction,
            entry_price=entry_price,
            current_price=current_price,
            standard_targets=standard_targets,
            magnet_data=magnet_data,
            liquidation_levels=liquidation_levels,
            orderbook_data=orderbook,
            liquidity_clusters=clusters
        )
        
        # Store in database
        await store_shadow_targets(signal_id, shadow_result)
        
        # Log summary
        liq_t1 = shadow_result.get("liquidity_targets", {}).get("target_1")
        std_t1 = standard_targets.get("target_1")
        quality = shadow_result.get("data_quality", {}).get("overall_quality", 0)
        
        logger.info(f"[Shadow Liquidity] Signal {signal_id[:8]}: "
                   f"Std T1=${std_t1:,.0f} vs Liq T1=${liq_t1:,.0f if liq_t1 else 0} | "
                   f"Quality: {quality}%")
        
    except Exception as e:
        logger.error(f"[Shadow Liquidity] Error in shadow calculation for {signal_id[:8]}: {e}")



# ═══════════════════════════════════════════════════════════════════════════════
# V3.4 SIGNAL VALIDATION SYSTEM - CONFLICT DETECTION & QUALITY FILTERS
# ═══════════════════════════════════════════════════════════════════════════════
# PURPOSE: Eliminate contradictory signals and prevent low-quality trades
# 
# FILTERS:
# 1. R:R Minimum (HARD BLOCK: R:R < 0.5)
# 2. Magnet Direction Conflict (BLOCK if signal != magnet direction)
# 3. Squeeze Risk Filter (BLOCK same-direction trades when overcrowded)
# 4. Decision Hierarchy (Regime → Bias → Magnet → Energy)
# 5. Range Regime Constraint (no breakouts in RANGE)
# ═══════════════════════════════════════════════════════════════════════════════

class SignalBlockReason:
    """Enumeration of signal block reasons for V3.4 validation"""
    LOW_RR = "LOW_RR"
    NO_VALID_CLUSTERS = "NO_VALID_CLUSTERS"
    MAGNET_CONFLICT = "MAGNET_CONFLICT"
    SQUEEZE_RISK = "SQUEEZE_RISK"
    BIAS_CONFLICT = "BIAS_CONFLICT"
    RANGE_BREAKOUT = "RANGE_BREAKOUT"
    ENERGY_INSUFFICIENT = "ENERGY_INSUFFICIENT"
    HIERARCHY_CONFLICT = "HIERARCHY_CONFLICT"


# ═══════════════════════════════════════════════════════════════════════════════
# V3.5 CONTRARIAN LOGIC - TRAP DETECTION SYSTEM
# ═══════════════════════════════════════════════════════════════════════════════
# 
# PURPOSE: When a V3 signal is BLOCKED, detect if the market is setting up a trap
# and generate a CONTRARIAN signal only if multiple high-conviction conditions align.
#
# ACTIVATION: Only when original V3 signal was BLOCKED (not a general reversal engine)
# 
# SAFETY: Contrarian signals must be RARE and HIGH-QUALITY
# ═══════════════════════════════════════════════════════════════════════════════

# V3.5 Contrarian signal tracking
v3_5_contrarian_signals: Dict[str, datetime] = {}  # Tracks contrarian signals sent

# Block reasons that can trigger contrarian evaluation
CONTRARIAN_ELIGIBLE_BLOCKS = [
    "BLOCKED_MAGNET_CONFLICT",
    "BLOCKED_SQUEEZE_RISK", 
    "BLOCKED_UPSTREAM_BIAS_CONFLICT",
    "BLOCKED_UPSTREAM_MAGNET_CONFLICT"
]


async def evaluate_v3_5_contrarian_opportunity(
    blocked_direction: str,
    block_reason: str,
    current_price: float,
    setup_data: dict,
    market_context: dict
) -> Optional[Dict[str, Any]]:
    """
    V3.5 CONTRARIAN LOGIC - Evaluates if a blocked signal presents a trap/contrarian opportunity.
    
    ACTIVATION PRECONDITION: Original V3 signal MUST be BLOCKED.
    
    This function is called ONLY when a V3 signal is blocked, to check if:
    1. The market is setting up a trap
    2. The opposite direction has high conviction
    3. All safety conditions are met
    
    Returns:
        None if no valid contrarian opportunity
        Dict with contrarian signal data if opportunity is valid
    """
    
    # ═══════════════════════════════════════════════════════════════════════════
    # PRECONDITION: Must be an eligible block reason
    # ═══════════════════════════════════════════════════════════════════════════
    is_eligible_block = any(eligible in block_reason for eligible in CONTRARIAN_ELIGIBLE_BLOCKS)
    
    if not is_eligible_block:
        logger.debug(f"[V3.5 Contrarian] Block reason '{block_reason}' not eligible for contrarian evaluation")
        return None
    
    logger.info(f"[V3.5 Contrarian] Evaluating contrarian opportunity for blocked {blocked_direction}")
    
    # Determine contrarian direction
    contrarian_direction = "LONG" if blocked_direction == "SHORT" else "SHORT"
    
    # Extract market context
    magnet_direction = market_context.get("magnet_direction") if market_context else None
    energy_score = market_context.get("energy_score", 0) if market_context else 0
    compression_level = market_context.get("compression_level", "MEDIUM") if market_context else "MEDIUM"
    derivatives_context = market_context.get("derivatives_context") if market_context else None
    market_regime = setup_data.get("market_regime", "UNKNOWN")
    market_bias = market_context.get("market_bias", "NEUTRAL") if market_context else "NEUTRAL"
    
    # Track failed conditions for logging
    failed_conditions = []
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONDITION 1: Magnet direction MUST clearly support contrarian direction
    # ═══════════════════════════════════════════════════════════════════════════
    magnet_supports_contrarian = False
    
    if magnet_direction and magnet_direction not in ["BALANCED", "NONE", None]:
        if contrarian_direction == "LONG" and magnet_direction == "UP":
            magnet_supports_contrarian = True
        elif contrarian_direction == "SHORT" and magnet_direction == "DOWN":
            magnet_supports_contrarian = True
    
    if not magnet_supports_contrarian:
        failed_conditions.append(f"Magnet ({magnet_direction}) does not support {contrarian_direction}")
        logger.debug(f"[V3.5 Contrarian] ❌ Condition 1 failed: Magnet not aligned")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONDITION 2: Squeeze risk MUST support the contrarian move
    # ═══════════════════════════════════════════════════════════════════════════
    squeeze_supports_contrarian = False
    squeeze_context = None
    
    if derivatives_context and derivatives_context.get("data_available"):
        ls_ratio = derivatives_context.get("long_short_ratio", {})
        funding_rate = derivatives_context.get("funding_rate")
        
        if ls_ratio:
            global_ratio = ls_ratio.get("global_ratio", 1.0)
            
            # Shorts overcrowded (ratio > 1.5) + contrarian LONG = squeeze setup
            # Longs overcrowded (ratio < 0.67) + contrarian SHORT = squeeze setup
            shorts_overcrowded = global_ratio > 1.5
            longs_overcrowded = global_ratio < 0.67
            
            extreme_negative_funding = funding_rate is not None and funding_rate < -0.05
            extreme_positive_funding = funding_rate is not None and funding_rate > 0.05
            
            if contrarian_direction == "LONG" and (shorts_overcrowded or extreme_negative_funding):
                squeeze_supports_contrarian = True
                squeeze_context = {
                    "overcrowded_side": "SHORTS",
                    "global_ratio": global_ratio,
                    "funding_rate": funding_rate,
                    "squeeze_probability": "HIGH" if global_ratio > 1.8 else "MODERATE"
                }
            elif contrarian_direction == "SHORT" and (longs_overcrowded or extreme_positive_funding):
                squeeze_supports_contrarian = True
                squeeze_context = {
                    "overcrowded_side": "LONGS",
                    "global_ratio": global_ratio,
                    "funding_rate": funding_rate,
                    "squeeze_probability": "HIGH" if global_ratio < 0.55 else "MODERATE"
                }
    
    if not squeeze_supports_contrarian:
        failed_conditions.append("Squeeze risk does not support contrarian direction")
        logger.debug(f"[V3.5 Contrarian] ❌ Condition 2 failed: No squeeze setup")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONDITION 3: Market Energy - STRICTER REQUIREMENT
    # V3.5 Adjustment: MEDIUM only allowed with HIGH squeeze probability
    #                  Otherwise require HIGH energy
    # ═══════════════════════════════════════════════════════════════════════════
    squeeze_is_strong = squeeze_context and squeeze_context.get("squeeze_probability") == "HIGH"
    
    # HIGH energy always sufficient
    energy_high = energy_score >= 60 or compression_level in ["HIGH", "VERY_HIGH"]
    # MEDIUM energy only with strong squeeze
    energy_medium_with_squeeze = energy_score >= 40 and squeeze_is_strong
    
    energy_sufficient = energy_high or energy_medium_with_squeeze
    
    if not energy_sufficient:
        if energy_score >= 40 and not squeeze_is_strong:
            failed_conditions.append(f"Energy MEDIUM ({energy_score}) requires HIGH squeeze probability")
        else:
            failed_conditions.append(f"Energy too low ({energy_score}, compression={compression_level})")
        logger.debug(f"[V3.5 Contrarian] ❌ Condition 3 failed: Energy insufficient")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONDITION 4: Regime MUST be compatible (RANGE, COMPRESSION - NOT strong TREND)
    # ═══════════════════════════════════════════════════════════════════════════
    regime_compatible = market_regime in ["RANGE", "COMPRESSION", "EXPANSION"]
    
    # Block if strong directional TREND
    if market_regime == "TREND":
        regime_compatible = False
    
    if not regime_compatible:
        failed_conditions.append(f"Regime '{market_regime}' not compatible for contrarian")
        logger.debug(f"[V3.5 Contrarian] ❌ Condition 4 failed: Regime not compatible")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONDITION 5: Contrarian target MUST have valid R:R >= 0.5
    # ═══════════════════════════════════════════════════════════════════════════
    # For contrarian, we need to calculate R:R in the opposite direction
    # Use existing swing levels but inverted
    swing_high = setup_data.get("swing_high", current_price * 1.02)
    swing_low = setup_data.get("swing_low", current_price * 0.98)
    
    if contrarian_direction == "LONG":
        # For LONG contrarian: stop below swing low, target at swing high or above
        contrarian_stop = swing_low * 0.998  # Slight buffer below swing low
        contrarian_target = swing_high * 1.002  # Slight buffer above swing high
        contrarian_risk = current_price - contrarian_stop
        contrarian_reward = contrarian_target - current_price
    else:
        # For SHORT contrarian: stop above swing high, target at swing low or below
        contrarian_stop = swing_high * 1.002  # Slight buffer above swing high
        contrarian_target = swing_low * 0.998  # Slight buffer below swing low
        contrarian_risk = contrarian_stop - current_price
        contrarian_reward = current_price - contrarian_target
    
    contrarian_rr = contrarian_reward / contrarian_risk if contrarian_risk > 0 else 0
    
    # V3.5 Adjustment: Stricter R:R requirement (0.7 instead of 0.5)
    MIN_CONTRARIAN_RR = 0.7
    rr_valid = contrarian_rr >= MIN_CONTRARIAN_RR
    
    if not rr_valid:
        failed_conditions.append(f"Contrarian R:R too low ({contrarian_rr:.2f} < {MIN_CONTRARIAN_RR})")
        logger.debug(f"[V3.5 Contrarian] ❌ Condition 5 failed: R:R={contrarian_rr:.2f}")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONDITION 6: Contrarian MUST have meaningful cluster target
    # V3.5 Adjustment: Increased from 0.3% to 0.5% (consistent with V3 cluster logic)
    # ═══════════════════════════════════════════════════════════════════════════
    # Check if there's a valid target cluster in contrarian direction
    MIN_TARGET_DISTANCE_PCT = 0.005  # 0.5% minimum distance
    target_distance_pct = abs(contrarian_target - current_price) / current_price
    has_contrarian_target = target_distance_pct >= MIN_TARGET_DISTANCE_PCT
    
    if not has_contrarian_target:
        failed_conditions.append(f"Target distance too close ({target_distance_pct*100:.2f}% < 0.5%)")
        logger.debug(f"[V3.5 Contrarian] ❌ Condition 6 failed: Target too close")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FINAL DECISION: ALL conditions must pass
    # ═══════════════════════════════════════════════════════════════════════════
    all_conditions_met = (
        magnet_supports_contrarian and
        squeeze_supports_contrarian and
        energy_sufficient and
        regime_compatible and
        rr_valid and
        has_contrarian_target
    )
    
    if not all_conditions_met:
        logger.info(f"[V3.5 Contrarian] ❌ No valid contrarian opportunity. Failed conditions: {failed_conditions}")
        return None
    
    # ═══════════════════════════════════════════════════════════════════════════
    # CONTRARIAN OPPORTUNITY VALID - Generate signal
    # ═══════════════════════════════════════════════════════════════════════════
    contrarian_signal = {
        "contrarian_active": True,
        "contrarian_direction": f"CONTRARIAN_{contrarian_direction}",
        "original_blocked_direction": blocked_direction,
        "blocked_original_signal_reason": block_reason,
        
        # Contrarian trade parameters
        "contrarian_entry": current_price,
        "contrarian_stop": round(contrarian_stop, 2),
        "contrarian_target_1": round(contrarian_target, 2),
        "contrarian_rr": round(contrarian_rr, 2),
        
        # Supporting context
        "contrarian_magnet_direction": magnet_direction,
        "squeeze_context": squeeze_context,
        "energy_score": energy_score,
        "market_regime": market_regime,
        
        # Reasoning
        "contrarian_reason": _build_contrarian_reason(
            contrarian_direction, 
            blocked_direction, 
            block_reason, 
            squeeze_context, 
            magnet_direction
        ),
        
        # Risk warning
        "risk_warning": "CONTRARIAN SETUP: This is a trap-based reversal trade. Higher risk than standard signals.",
        
        # Quality metrics
        "contrarian_quality": _calculate_contrarian_quality(
            squeeze_context, 
            energy_score, 
            contrarian_rr, 
            magnet_direction
        ),
        
        "timestamp": datetime.now(timezone.utc).isoformat()
    }
    
    logger.info(f"[V3.5 Contrarian] ✅ CONTRARIAN_{contrarian_direction} signal generated! "
               f"R:R={contrarian_rr:.2f}, Squeeze={squeeze_context.get('overcrowded_side') if squeeze_context else 'N/A'}")
    
    return contrarian_signal


def _build_contrarian_reason(
    contrarian_direction: str,
    blocked_direction: str,
    block_reason: str,
    squeeze_context: Optional[dict],
    magnet_direction: str
) -> str:
    """Build human-readable contrarian reason"""
    
    squeeze_text = ""
    if squeeze_context:
        side = squeeze_context.get("overcrowded_side", "").lower()
        prob = squeeze_context.get("squeeze_probability", "MODERATE")
        squeeze_text = f" {side} overcrowded ({prob} squeeze probability)"
    
    return (
        f"Original {blocked_direction} signal blocked due to {block_reason}. "
        f"Market shows trap setup:{squeeze_text}, "
        f"liquidity magnet points {magnet_direction}, "
        f"favoring CONTRARIAN {contrarian_direction}."
    )


def _calculate_contrarian_quality(
    squeeze_context: Optional[dict],
    energy_score: float,
    contrarian_rr: float,
    magnet_direction: str
) -> int:
    """Calculate contrarian signal quality score (0-100)"""
    
    quality = 40  # Base score for meeting all conditions
    
    # Squeeze probability bonus
    if squeeze_context:
        if squeeze_context.get("squeeze_probability") == "HIGH":
            quality += 20
        else:
            quality += 10
    
    # Energy bonus
    if energy_score >= 60:
        quality += 15
    elif energy_score >= 40:
        quality += 5
    
    # R:R bonus
    if contrarian_rr >= 1.5:
        quality += 15
    elif contrarian_rr >= 1.0:
        quality += 10
    elif contrarian_rr >= 0.7:
        quality += 5
    
    # Magnet strength bonus
    if magnet_direction in ["UP", "DOWN"]:
        quality += 10
    
    return min(100, quality)


async def record_v3_5_contrarian_signal(
    contrarian_data: Dict[str, Any],
    setup_data: Dict[str, Any],
    current_price: float
) -> Dict[str, Any]:
    """
    Record a V3.5 Contrarian signal to the database.
    
    Contrarian signals are tracked SEPARATELY from normal V3 signals.
    """
    global v3_5_contrarian_signals
    
    try:
        signal_id = str(uuid.uuid4())
        contrarian_direction = contrarian_data.get("contrarian_direction", "UNKNOWN")
        
        # Create contrarian history entry
        history_entry = {
            "signal_id": signal_id,
            "timestamp": datetime.now(timezone.utc),
            "direction": contrarian_direction,
            "signal_engine_version": "v3.5_contrarian",
            "signal_type": "CONTRARIAN",
            
            # Trade parameters
            "btc_price": current_price,
            "entry_zone_low": current_price * 0.998,
            "entry_zone_high": current_price * 1.002,
            "stop_loss": contrarian_data.get("contrarian_stop"),
            "target_1": contrarian_data.get("contrarian_target_1"),
            "target_2": None,  # Contrarian signals use single target
            "risk_reward_ratio": contrarian_data.get("contrarian_rr"),
            
            # Contrarian context
            "contrarian_active": True,
            "original_blocked_direction": contrarian_data.get("original_blocked_direction"),
            "blocked_original_signal_reason": contrarian_data.get("blocked_original_signal_reason"),
            "contrarian_reason": contrarian_data.get("contrarian_reason"),
            "squeeze_context": contrarian_data.get("squeeze_context"),
            "contrarian_magnet_direction": contrarian_data.get("contrarian_magnet_direction"),
            
            # Quality
            "confidence": contrarian_data.get("contrarian_quality", 50),
            "quality_score": contrarian_data.get("contrarian_quality", 50),
            
            # Setup reference
            "v3_setup_id": setup_data.get("setup_id"),
            "market_regime": contrarian_data.get("market_regime"),
            
            # Outcome tracking
            "outcome": "PENDING",
            "outcome_timestamp": None,
            "outcome_price": None,
            "target_1_hit": False,
            "stop_hit": False,
            
            # Warnings
            "warnings": [contrarian_data.get("risk_warning")],
            "reasoning_summary": contrarian_data.get("contrarian_reason")
        }
        
        # Insert into signal history
        await signal_history_collection.insert_one(history_entry)
        
        # Track for deduplication
        v3_5_contrarian_signals[signal_id] = datetime.now(timezone.utc)
        
        # Cleanup old entries
        if len(v3_5_contrarian_signals) > 50:
            v3_5_contrarian_signals = dict(list(v3_5_contrarian_signals.items())[-50:])
        
        logger.info(f"[V3.5 Contrarian] ✅ Recorded {contrarian_direction} signal {signal_id[:8]}")
        
        return {
            "recorded": True,
            "signal_id": signal_id,
            "contrarian_direction": contrarian_direction,
            "contrarian_rr": contrarian_data.get("contrarian_rr"),
            "contrarian_quality": contrarian_data.get("contrarian_quality")
        }
        
    except Exception as e:
        logger.error(f"[V3.5 Contrarian] Error recording signal: {e}")
        return {"recorded": False, "reason": str(e)}


async def get_v3_5_contrarian_stats() -> Dict[str, Any]:
    """Get statistics for V3.5 contrarian signals"""
    
    try:
        # Query contrarian signals
        cursor = signal_history_collection.find({
            "signal_engine_version": "v3.5_contrarian"
        })
        
        signals = []
        async for doc in cursor:
            doc.pop("_id", None)
            signals.append(doc)
        
        if not signals:
            return {
                "total_contrarian_signals": 0,
                "message": "No contrarian signals generated yet",
                "stats": None
            }
        
        # Calculate stats
        total = len(signals)
        wins = len([s for s in signals if s.get("outcome") == "WIN"])
        losses = len([s for s in signals if s.get("outcome") == "LOSS"])
        pending = len([s for s in signals if s.get("outcome") == "PENDING"])
        expired = len([s for s in signals if s.get("outcome") == "EXPIRED"])
        t1_hits = len([s for s in signals if s.get("target_1_hit")])
        
        win_rate = (wins / (wins + losses) * 100) if (wins + losses) > 0 else 0
        t1_rate = (t1_hits / total * 100) if total > 0 else 0
        
        avg_rr = sum(s.get("risk_reward_ratio", 0) for s in signals) / total if total > 0 else 0
        avg_quality = sum(s.get("quality_score", 0) for s in signals) / total if total > 0 else 0
        
        # By direction
        longs = [s for s in signals if "LONG" in s.get("direction", "")]
        shorts = [s for s in signals if "SHORT" in s.get("direction", "")]
        
        return {
            "total_contrarian_signals": total,
            "stats": {
                "win_rate": round(win_rate, 1),
                "t1_hit_rate": round(t1_rate, 1),
                "average_rr": round(avg_rr, 2),
                "average_quality": round(avg_quality, 1),
                "outcomes": {
                    "wins": wins,
                    "losses": losses,
                    "expired": expired,
                    "pending": pending
                },
                "by_direction": {
                    "contrarian_long": len(longs),
                    "contrarian_short": len(shorts)
                }
            },
            "recent_signals": [
                {
                    "signal_id": s.get("signal_id", "")[:8],
                    "direction": s.get("direction"),
                    "outcome": s.get("outcome"),
                    "rr": s.get("risk_reward_ratio"),
                    "timestamp": s.get("timestamp").isoformat() if s.get("timestamp") else None
                }
                for s in sorted(signals, key=lambda x: x.get("timestamp", datetime.min), reverse=True)[:5]
            ]
        }
        
    except Exception as e:
        logger.error(f"[V3.5 Contrarian] Error getting stats: {e}")
        return {"error": str(e)}


async def validate_v3_signal_quality(
    direction: str,
    current_price: float,
    stop_loss: float,
    target_1: float,
    has_valid_targets: bool,
    market_regime: str,
    market_bias: str,
    bias_confidence: float,
    liquidity_magnet_direction: str = None,
    magnet_strength: str = None,
    cluster_validated: bool = None,
    energy_state: str = None,
    fuel_score: float = None,
    derivatives_context: dict = None,
    funding_rate: float = None,
    lang: str = "it"
) -> Dict[str, Any]:
    """
    V3.4 Comprehensive Signal Quality Validation
    
    Applies strict filters to eliminate contradictory signals:
    1. R:R Minimum (HARD: >= 0.5)
    2. Magnet Direction Alignment (signal must match magnet)
    3. Squeeze Risk (don't trade overcrowded side)
    4. Hierarchy Validation (Regime → Bias → Magnet → Energy)
    5. Range Constraint (no breakouts in RANGE)
    """
    block_reasons = []
    warnings = []
    quality_score = 50
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FILTER 1: HARD R:R MINIMUM (CRITICAL)
    # ═══════════════════════════════════════════════════════════════════════════
    MIN_RR_THRESHOLD = 0.5
    
    risk = abs(current_price - stop_loss) if stop_loss else 0
    reward = abs(target_1 - current_price) if target_1 else 0
    rr_ratio = reward / risk if risk > 0 else 0
    
    if rr_ratio < MIN_RR_THRESHOLD:
        block_reasons.append(f"{SignalBlockReason.LOW_RR}_{rr_ratio:.2f}")
        logger.warning(f"[V3.4 Validate] ❌ BLOCKED: R:R {rr_ratio:.2f} < {MIN_RR_THRESHOLD}")
    elif rr_ratio < 0.7:
        warnings.append(f"Low R:R ({rr_ratio:.2f})")
    else:
        quality_score += 10
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FILTER 2: NO VALID CLUSTERS
    # ═══════════════════════════════════════════════════════════════════════════
    if not has_valid_targets:
        block_reasons.append(SignalBlockReason.NO_VALID_CLUSTERS)
        logger.warning(f"[V3.4 Validate] ❌ BLOCKED: No valid liquidity clusters")
    else:
        quality_score += 10
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FILTER 3: MAGNET DIRECTION CONFLICT (CRITICAL)
    # ═══════════════════════════════════════════════════════════════════════════
    if liquidity_magnet_direction and liquidity_magnet_direction not in ["BALANCED", "NONE", None]:
        signal_wants_up = direction == "LONG"
        magnet_points_up = liquidity_magnet_direction == "UP"
        
        if signal_wants_up != magnet_points_up:
            block_reasons.append(f"{SignalBlockReason.MAGNET_CONFLICT}_{direction}_vs_{liquidity_magnet_direction}")
            logger.warning(f"[V3.4 Validate] ❌ BLOCKED: {direction} signal but magnet points {liquidity_magnet_direction}")
        else:
            quality_score += 15
            if cluster_validated:
                quality_score += 10
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FILTER 4: SQUEEZE RISK (Funding + Positioning)
    # ═══════════════════════════════════════════════════════════════════════════
    if derivatives_context and derivatives_context.get("data_available"):
        ls_ratio = derivatives_context.get("long_short_ratio", {})
        
        if ls_ratio:
            global_ratio = ls_ratio.get("global_ratio", 1.0)
            
            shorts_overcrowded = global_ratio > 1.5
            longs_overcrowded = global_ratio < 0.67
            
            extreme_negative_funding = funding_rate is not None and funding_rate < -0.05
            extreme_positive_funding = funding_rate is not None and funding_rate > 0.05
            
            if direction == "SHORT" and (shorts_overcrowded or extreme_negative_funding):
                block_reasons.append(f"{SignalBlockReason.SQUEEZE_RISK}_SHORTS_OVERCROWDED")
                logger.warning(f"[V3.4 Validate] ❌ BLOCKED: SHORT but shorts overcrowded (ratio={global_ratio:.2f})")
            
            elif direction == "LONG" and (longs_overcrowded or extreme_positive_funding):
                block_reasons.append(f"{SignalBlockReason.SQUEEZE_RISK}_LONGS_OVERCROWDED")
                logger.warning(f"[V3.4 Validate] ❌ BLOCKED: LONG but longs overcrowded (ratio={global_ratio:.2f})")
            
            elif direction == "SHORT" and global_ratio > 1.3:
                warnings.append("Shorts getting crowded - squeeze risk")
            elif direction == "LONG" and global_ratio < 0.77:
                warnings.append("Longs getting crowded - squeeze risk")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FILTER 5: BIAS CONFLICT (Signal vs Strong Bias)
    # ═══════════════════════════════════════════════════════════════════════════
    if bias_confidence >= 70:
        bias_bullish = market_bias == "BULLISH"
        signal_bullish = direction == "LONG"
        
        if bias_bullish != signal_bullish:
            block_reasons.append(f"{SignalBlockReason.BIAS_CONFLICT}_{direction}_vs_{market_bias}")
            logger.warning(f"[V3.4 Validate] ❌ BLOCKED: {direction} conflicts with strong {market_bias} bias ({bias_confidence}%)")
        else:
            quality_score += 15
    elif bias_confidence >= 55:
        bias_bullish = market_bias == "BULLISH"
        signal_bullish = direction == "LONG"
        
        if bias_bullish != signal_bullish:
            warnings.append(f"Conflicts with moderate {market_bias} bias")
        else:
            quality_score += 5
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FILTER 6: RANGE REGIME CONSTRAINT
    # ═══════════════════════════════════════════════════════════════════════════
    if market_regime == "RANGE":
        warnings.append("RANGE regime - bounded targets only")
        quality_score -= 10
        
        if energy_state == "LOW" and (fuel_score is None or fuel_score < 30):
            block_reasons.append(f"{SignalBlockReason.RANGE_BREAKOUT}_LOW_ENERGY")
            logger.warning(f"[V3.4 Validate] ❌ BLOCKED: Breakout in RANGE with low energy")
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FILTER 7: ENERGY CHECK
    # ═══════════════════════════════════════════════════════════════════════════
    if energy_state == "LOW" and (fuel_score is None or fuel_score < 20):
        if market_regime in ["TREND", "EXPANSION"]:
            warnings.append("Low energy may limit move")
            quality_score -= 5
    
    # ═══════════════════════════════════════════════════════════════════════════
    # FINAL DECISION
    # ═══════════════════════════════════════════════════════════════════════════
    is_valid = len(block_reasons) == 0
    quality_score = max(0, min(100, quality_score))
    
    if not is_valid:
        recommended_action = "BLOCKED"
    elif len(warnings) >= 3:
        recommended_action = "WAIT"
    elif quality_score >= 60:
        recommended_action = "EXECUTE"
    else:
        recommended_action = "WAIT"
    
    logger.info(f"[V3.4 Validate] {direction}: valid={is_valid}, quality={quality_score}, "
               f"action={recommended_action}, blocks={len(block_reasons)}, warnings={len(warnings)}")
    
    return {
        "is_valid": is_valid,
        "block_reasons": block_reasons,
        "warnings": warnings,
        "quality_score": quality_score,
        "recommended_action": recommended_action,
        "rr_ratio": round(rr_ratio, 2),
        "validation_timestamp": datetime.now(timezone.utc).isoformat()
    }



async def create_setup_event(
    event: Dict[str, Any],
    current_price: float,
    market_regime: str,
    market_bias: str,
    whale_direction: Optional[str],
    whale_strength: Optional[float],
    liquidity_above: float,
    liquidity_below: float,
    resistances: List,
    supports: List,
    lang: str = "it"
) -> SetupEvent:
    """
    Create a new SetupEvent from a detected 4H event.
    Calculates stop loss and targets, then saves to database.
    
    V2.0: Now uses liquidity cluster-based targets instead of fixed percentages.
    """
    direction = event["direction"]
    swing_high = event.get("swing_high", current_price * 1.01)
    swing_low = event.get("swing_low", current_price * 0.99)
    sweep_level = event.get("sweep_level")
    
    # Calculate structure-based stop loss
    stop_info = calculate_v3_stop_loss(
        direction=direction,
        swing_high=swing_high,
        swing_low=swing_low,
        sweep_level=sweep_level,
        current_price=current_price
    )
    
    # ═══════════════════════════════════════════════════════════════════════════
    # V2.0: Fetch liquidity data for cluster-based targets
    # ═══════════════════════════════════════════════════════════════════════════
    try:
        # Get aggregated orderbook (cached)
        aggregated_orderbook = await get_aggregated_orderbook()
        
        # Get liquidity clusters
        candles = await fetch_kraken_ohlc(240)  # 4H candles
        liquidity_clusters = []
        if candles and aggregated_orderbook:
            liquidity_clusters, _ = generate_liquidity_clusters_enhanced(
                candles, current_price, aggregated_orderbook, lang
            )
    except Exception as e:
        logger.warning(f"[V3 Setup] Failed to fetch liquidity data: {e}")
        aggregated_orderbook = None
        liquidity_clusters = []
    
    # Calculate liquidity-cluster-based targets (V2.0)
    target_info = calculate_v3_targets(
        direction=direction,
        entry_price=current_price,
        liquidity_above=liquidity_above,
        liquidity_below=liquidity_below,
        resistances=resistances,
        supports=supports,
        swing_high=swing_high,
        swing_low=swing_low,
        liquidity_clusters=liquidity_clusters,
        aggregated_orderbook=aggregated_orderbook
    )
    
    # Calculate R:R
    risk = abs(current_price - stop_info["stop_loss"])
    reward = abs(target_info["target_1"] - current_price) if target_info.get("has_valid_targets") else 0
    rr_ratio = reward / risk if risk > 0 else 0
    
    # ═══════════════════════════════════════════════════════════════════════════
    # V3.4: COMPREHENSIVE SIGNAL VALIDATION
    # Includes: R:R, Clusters, Magnet Conflict, Squeeze Risk, Bias Conflict
    # ═══════════════════════════════════════════════════════════════════════════
    MIN_RR_THRESHOLD = 0.5
    has_valid_targets = target_info.get("has_valid_targets", False)
    
    # Determine block reasons
    block_reasons = []
    
    # 1. R:R Check
    if rr_ratio < MIN_RR_THRESHOLD:
        block_reasons.append(f"LOW_RR_{rr_ratio:.2f}")
        logger.warning(f"[V3 Setup] ❌ R:R {rr_ratio:.2f} < {MIN_RR_THRESHOLD} - BLOCKED")
    
    # 2. Valid Clusters Check
    if not has_valid_targets:
        block_reasons.append("NO_VALID_CLUSTERS")
        logger.warning(f"[V3 Setup] ❌ NO_VALID_CLUSTERS - BLOCKED")
    
    # 3. Bias Conflict Check (Strong bias must align with direction)
    # market_bias is passed as string "BULLISH"/"BEARISH"/"NEUTRAL"
    if market_bias in ["BULLISH", "BEARISH"]:
        bias_bullish = market_bias == "BULLISH"
        signal_bullish = direction == "LONG"
        
        # Only block if there's a strong bias conflict
        # Note: We don't have bias_confidence here, so we'll use a simpler check
        if bias_bullish != signal_bullish:
            block_reasons.append(f"BIAS_CONFLICT_{direction}_vs_{market_bias}")
            logger.warning(f"[V3 Setup] ❌ {direction} conflicts with {market_bias} bias - BLOCKED")
    
    # Combine block reasons
    is_blocked = len(block_reasons) > 0
    block_reason = block_reasons[0] if block_reasons else None
    
    if not is_blocked:
        logger.info(f"[V3 Setup] ✅ Valid setup: T1=${target_info['target_1']:,.0f}, R:R={rr_ratio:.2f}")
    
    # Log target details
    logger.info(f"[V3 Setup] Direction={direction}, Entry=${current_price:,.0f}")
    logger.info(f"[V3 Setup] T1=${target_info['target_1']:,.0f} ({target_info.get('target_1_type', 'N/A')}), "
               f"T2=${target_info['target_2']:,.0f} ({target_info.get('target_2_type', 'N/A')})")
    logger.info(f"[V3 Setup] Clusters analyzed: {target_info.get('clusters_analyzed', 0)}, "
               f"Valid targets: {has_valid_targets}, R:R: {rr_ratio:.2f}, Blocked: {is_blocked}")
    
    # Calculate quality score - PENALIZE heavily if blocked
    quality_score = 50  # Base score
    
    if is_blocked:
        quality_score = 15  # Very low quality if blocked
    else:
        # Bonus for cluster-based targets
        if target_info.get("targets_from_clusters"):
            quality_score += 15
        
        if whale_direction and ((direction == "LONG" and whale_direction == "BUY") or 
                                (direction == "SHORT" and whale_direction == "SELL")):
            quality_score += 15
        if market_regime in ["TREND", "EXPANSION"]:
            quality_score += 10
        if rr_ratio >= 1.5:
            quality_score += 15
        elif rr_ratio >= 1.0:
            quality_score += 10
        elif rr_ratio >= 0.7:
            quality_score += 5
        if event.get("strength", 0) >= 70:
            quality_score += 10
    
    quality_score = max(0, min(100, quality_score))
    
    # Create setup event
    setup = SetupEvent(
        expires_at=datetime.now(timezone.utc) + timedelta(hours=V3_SETUP_VALIDITY_HOURS),
        phase=SetupEventPhase.SETUP_DETECTED.value,
        phase_history=[{
            "phase": SetupEventPhase.SETUP_DETECTED.value,
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "reason": event.get("signal", "Event detected")
        }],
        event_type=event["type"],
        direction=direction,
        zone_high=event["zone_high"],
        zone_low=event["zone_low"],
        event_price=event["event_price"],
        current_price=current_price,
        swing_high=swing_high,
        swing_low=swing_low,
        sweep_level=sweep_level,
        stop_loss=stop_info["stop_loss"],
        stop_type=stop_info["stop_type"],
        buffer_percent=stop_info["buffer_percent"],
        target_1=target_info["target_1"],
        target_1_type=target_info["target_1_type"],
        target_2=target_info["target_2"],
        target_2_type=target_info["target_2_type"],
        target_1_cluster=target_info.get("target_1_cluster"),
        target_2_cluster=target_info.get("target_2_cluster"),
        targets_from_clusters=target_info.get("targets_from_clusters", False),
        clusters_analyzed=target_info.get("clusters_analyzed", 0),
        has_valid_targets=target_info.get("has_valid_targets", True),
        target_block_reason=block_reason,
        risk_reward_ratio=round(rr_ratio, 2),
        market_regime=market_regime,
        market_bias=market_bias,
        whale_direction=whale_direction,
        whale_strength=whale_strength,
        liquidity_above=liquidity_above,
        liquidity_below=liquidity_below,
        quality_score=quality_score,
        confidence=event.get("strength", 50),
        signals_detected=[event.get("signal", "")],
        reasoning=f"V3 Setup: {event['type']} - {event.get('signal', '')}"
    )
    
    # Save to database
    await setup_events_collection.insert_one(setup.model_dump())
    logger.info(f"[V3] Created setup event: {setup.setup_id} - {setup.event_type} {setup.direction}")
    
    return setup


async def update_setup_phase(
    setup_id: str,
    new_phase: str,
    reason: str,
    confirmation: Optional[Dict[str, Any]] = None
):
    """Update a setup's phase in the database."""
    # Build the $set part
    set_data = {
        "phase": new_phase,
        "updated_at": datetime.now(timezone.utc)
    }
    
    # Build the $push part
    push_data = {
        "phase_history": {
            "phase": new_phase,
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "reason": reason
        }
    }
    
    if confirmation and new_phase == SetupEventPhase.ENTRY_READY.value:
        set_data["confirmation_type"] = confirmation["type"]
        set_data["confirmation_time"] = datetime.now(timezone.utc)
        set_data["confirmation_price"] = confirmation["price"]
        set_data["confirmation_details"] = confirmation.get("details")
    
    # Properly combine $set and $push
    await setup_events_collection.update_one(
        {"setup_id": setup_id},
        {
            "$set": set_data,
            "$push": push_data
        }
    )
    logger.info(f"[V3] Updated setup {setup_id[:8]} to phase: {new_phase}")


async def get_active_setups() -> List[Dict[str, Any]]:
    """Get all active (non-expired, non-invalidated) setups."""
    active_phases = [
        SetupEventPhase.SETUP_DETECTED.value,
        SetupEventPhase.WAITING_FOR_RETEST.value,
        SetupEventPhase.ENTRY_READY.value
    ]
    
    cursor = setup_events_collection.find({
        "phase": {"$in": active_phases},
        "expires_at": {"$gt": datetime.now(timezone.utc)}
    }).sort("created_at", -1)
    
    setups = []
    async for doc in cursor:
        doc.pop("_id", None)
        setups.append(doc)
    
    return setups


async def process_v3_signal(
    current_price: float,
    candles_4h: List[dict],
    candles_5m: List[dict],
    supports: List,
    resistances: List,
    market_regime: str,
    market_bias: str,
    bias_confidence: float,
    whale_direction: Optional[str],
    whale_strength: Optional[float],
    liquidity_above: float,
    liquidity_below: float,
    lang: str = "it",
    # V3.4 Validation Context (NEW)
    magnet_direction: Optional[str] = None,
    magnet_score: Optional[float] = None,
    derivatives_context: Optional[Dict[str, Any]] = None,
    energy_score: Optional[float] = None,
    compression_level: Optional[str] = None
) -> SignalV3:
    """
    Main V3 signal processor.
    
    1. Check for new 4H events
    2. Update existing setups based on price action
    3. Check for 5M confirmations on active setups
    4. Return consolidated V3 signal
    """
    fetch_start = datetime.now(timezone.utc)
    
    # Get active setups from database
    active_setups = await get_active_setups()
    
    setups_detected = len([s for s in active_setups if s["phase"] == SetupEventPhase.SETUP_DETECTED.value])
    setups_waiting = len([s for s in active_setups if s["phase"] == SetupEventPhase.WAITING_FOR_RETEST.value])
    setups_ready = len([s for s in active_setups if s["phase"] == SetupEventPhase.ENTRY_READY.value])
    
    # ===== 1. DETECT NEW 4H EVENTS =====
    new_events = detect_4h_events(
        candles_4h=candles_4h,
        current_price=current_price,
        supports=supports,
        resistances=resistances,
        liquidity_above=liquidity_above,
        liquidity_below=liquidity_below,
        market_regime=market_regime,
        market_bias=market_bias,
        lang=lang
    )
    
    # Create setup events for new detections (avoid duplicates)
    for event in new_events:
        # Check if similar setup already exists
        existing = [s for s in active_setups 
                   if s["event_type"] == event["type"] and 
                      s["direction"] == event["direction"] and
                      abs(s["zone_low"] - event["zone_low"]) / event["zone_low"] < 0.005]
        
        if not existing:
            new_setup = await create_setup_event(
                event=event,
                current_price=current_price,
                market_regime=market_regime,
                market_bias=market_bias,
                whale_direction=whale_direction,
                whale_strength=whale_strength,
                liquidity_above=liquidity_above,
                liquidity_below=liquidity_below,
                resistances=resistances,
                supports=supports,
                lang=lang
            )
            active_setups.append(new_setup.model_dump())
            setups_detected += 1
    
    # ===== 2. UPDATE EXISTING SETUPS =====
    primary_setup = None
    retest_in_progress = False
    retest_distance = None
    
    for setup_dict in active_setups:
        setup_id = setup_dict["setup_id"]
        phase = setup_dict["phase"]
        zone_high = setup_dict["zone_high"]
        zone_low = setup_dict["zone_low"]
        direction = setup_dict["direction"]
        
        # Calculate distance to zone
        if direction == "LONG":
            zone_center = zone_low
            distance_percent = ((current_price - zone_center) / zone_center) * 100
        else:
            zone_center = zone_high
            distance_percent = ((zone_center - current_price) / zone_center) * 100
        
        # Check if price is approaching/in retest zone
        in_retest_zone = zone_low * 0.998 <= current_price <= zone_high * 1.002
        approaching_zone = abs(distance_percent) < 0.5  # Within 0.5% of zone
        
        # Phase transitions
        if phase == SetupEventPhase.SETUP_DETECTED.value:
            if approaching_zone or in_retest_zone:
                await update_setup_phase(
                    setup_id, 
                    SetupEventPhase.WAITING_FOR_RETEST.value,
                    f"Price approaching zone (distance: {distance_percent:.2f}%)"
                )
                setup_dict["phase"] = SetupEventPhase.WAITING_FOR_RETEST.value
                retest_in_progress = True
                retest_distance = distance_percent
        
        elif phase == SetupEventPhase.WAITING_FOR_RETEST.value:
            retest_in_progress = True
            retest_distance = distance_percent
            
            # Check for 5M confirmation
            if candles_5m and len(candles_5m) >= 5:
                # Create temporary SetupEvent for confirmation check
                temp_setup = SetupEvent(**setup_dict)
                confirmation = detect_5m_confirmation(candles_5m, temp_setup, current_price)
                
                if confirmation:
                    await update_setup_phase(
                        setup_id,
                        SetupEventPhase.ENTRY_READY.value,
                        confirmation.get("signal", "5M confirmation"),
                        confirmation
                    )
                    setup_dict["phase"] = SetupEventPhase.ENTRY_READY.value
                    setup_dict["confirmation_type"] = confirmation["type"]
                    setup_dict["confirmation_details"] = confirmation.get("details")
                    setups_ready += 1
                    
                    # Add market context to setup_dict for recording
                    setup_dict["market_regime"] = market_regime
                    
                    # CRITICAL: Record V3 signal to main signal_history collection
                    # This ensures V3 signals are tracked, measured, and outcome-processed
                    # V3.4: Now includes magnet_direction and derivatives_context for validation
                    market_context = {
                        "market_bias": market_bias,
                        "whale_direction": whale_direction,
                        "whale_strength": whale_strength,
                        "liquidity_direction": "UP" if liquidity_above > liquidity_below * 1.3 else ("DOWN" if liquidity_below > liquidity_above * 1.3 else "BALANCED"),
                        "magnet_direction": magnet_direction,  # V3.4: For Magnet Conflict validation
                        "magnet_score": magnet_score,
                        "energy_score": energy_score,
                        "compression_level": compression_level,
                        "derivatives_context": derivatives_context  # V3.4: For Squeeze Risk validation
                    }
                    
                    # Record signal first - this includes SAME_DIRECTION_LOCK check
                    record_result = await record_v3_entry_signal(setup_dict, current_price, market_context)
                    
                    # ONLY send Telegram alert if signal was successfully recorded
                    # This prevents notifications for blocked signals (SAME_DIRECTION_LOCKED, DUPLICATE_BLOCKED)
                    if record_result.get("recorded", False):
                        asyncio.create_task(send_v3_entry_alert(setup_dict, current_price))
                    else:
                        block_reason = record_result.get("reason", "unknown")
                        logger.info(f"[V3 Signal] Telegram alert SKIPPED - Signal not recorded ({block_reason})")
            
            # Check for invalidation (price moved too far from zone)
            if abs(distance_percent) > 2.0:  # More than 2% from zone
                await update_setup_phase(
                    setup_id,
                    SetupEventPhase.INVALIDATED.value,
                    f"Price moved too far from zone ({distance_percent:.2f}%)"
                )
                setup_dict["phase"] = SetupEventPhase.INVALIDATED.value
        
        # Select primary setup (highest quality ENTRY_READY or WAITING)
        if setup_dict["phase"] in [SetupEventPhase.ENTRY_READY.value, SetupEventPhase.WAITING_FOR_RETEST.value]:
            if not primary_setup or setup_dict["quality_score"] > primary_setup.get("quality_score", 0):
                primary_setup = setup_dict
    
    # ===== 3. DETERMINE RECOMMENDED ACTION =====
    recommended_action = "WAIT"
    context_summary = ""
    
    if setups_ready > 0:
        recommended_action = "ENTRY_NOW"
        context_summary = f"ENTRY READY: {setups_ready} setup(s) con conferma 5M"
    elif retest_in_progress:
        recommended_action = "PREPARE_ENTRY"
        context_summary = f"Retest in corso - distanza dalla zona: {retest_distance:.2f}%"
    elif setups_detected > 0:
        recommended_action = "MONITOR_SETUP"
        context_summary = f"{setups_detected} setup rilevato/i - attendere retest"
    else:
        context_summary = f"Nessun setup attivo - Regime: {market_regime}, Bias: {market_bias}"
    
    # Calculate overall quality
    overall_quality = primary_setup["quality_score"] if primary_setup else 0
    
    # Build response
    fetch_time = int((datetime.now(timezone.utc) - fetch_start).total_seconds() * 1000)
    
    return SignalV3(
        current_price=current_price,
        market_regime=market_regime,
        market_bias=market_bias,
        bias_confidence=bias_confidence,
        has_active_setup=primary_setup is not None,
        active_setup=SetupEvent(**primary_setup) if primary_setup else None,
        setups_detected_count=setups_detected,
        setups_waiting_count=setups_waiting,
        setups_ready_count=setups_ready,
        candles_5m_loaded=candles_5m is not None and len(candles_5m) > 0,
        last_5m_update=v3_5m_cache.get("last_update"),
        retest_in_progress=retest_in_progress,
        retest_zone_distance_percent=retest_distance,
        overall_quality=overall_quality,
        context_summary=context_summary,
        recommended_action=recommended_action,
        data_freshness={
            "signal_generation_time_ms": fetch_time,
            "5m_cache_age_s": (datetime.now(timezone.utc) - v3_5m_cache["last_update"]).seconds if v3_5m_cache.get("last_update") else None,
            "4h_data": "from_main_cache"
        }
    )


# ============== LIQUIDITY MAGNET ENGINE ==============

def analyze_liquidity_magnet(
    current_price: float,
    aggregated_orderbook: dict,
    liquidity_clusters: List = None,
    liquidation_data: dict = None,
    open_interest_data: dict = None,
    market_energy_data: dict = None,  # For context scoring
    derivatives_context: dict = None,  # V3.3: For cluster validation
    lang: str = "it"
) -> LiquidityMagnet:
    """
    Liquidity Magnet Score v2.1 - STRENGTH-BASED SELECTION + DERIVATIVES VALIDATION
    
    V3.3 ENHANCEMENTS:
    - Validates liquidity clusters using CoinGlass derivatives pressure
    - Checks if liquidation pressure supports movement toward cluster
    - Checks if buy/sell aggression supports the directional move
    - Returns cluster_validated flag for target selection
    
    CRITICAL CHANGE: Selects STRONGEST liquidity clusters, not nearest.
    This produces more realistic targets with better R:R.
    
    Algorithm:
    1. FILTER: Ignore clusters with value < $5M or distance < 0.2%
    2. VALUE SCORE (0-50): log10(value) * 10
    3. DISTANCE SCORE (0-30): Optimal range 0.5-2.5% = max score
    4. CONTEXT SCORE (0-20): OI change, compression, breakout prob, volume
    5. DERIVATIVES VALIDATION: Check if derivatives support the cluster
    6. TOTAL = value + distance + context
    7. SELECT: Primary = highest validated score, Secondary = second highest
    
    Returns magnet score, target direction, validation status, and likely sweep expectation.
    """
    import math
    
    signals = []
    
    # ======== CONFIGURATION ========
    # Detection thresholds (keep low to capture all data)
    MIN_LIQUIDITY_VALUE = 1_000_000  # $1M minimum for detection
    MIN_DISTANCE_PCT = 0.01  # 0.01% minimum for detection
    MAX_DISTANCE_PCT = 5.0  # 5% maximum distance
    
    # Target selection thresholds (higher for quality)
    WEAK_DISTANCE_THRESHOLD = 0.3  # Below this = weak/noise
    OPTIMAL_DISTANCE_MIN = 0.5  # Optimal range start
    OPTIMAL_DISTANCE_MAX = 3.0  # Optimal range end
    
    # HARD RULE: No direction if liquidity too close on BOTH sides
    NO_MAGNET_THRESHOLD = 0.1  # If both sides within 0.1% = NO CLEAR MAGNET
    
    # ======== 1. AGGREGATE LIQUIDITY DATA ========
    liquidity_above_total = 0
    liquidity_below_total = 0
    above_zones = []
    below_zones = []
    
    # From liquidity clusters
    if liquidity_clusters:
        for cluster in liquidity_clusters:
            if hasattr(cluster, 'side'):
                zone = {
                    "price": cluster.price if hasattr(cluster, 'price') else 0,
                    "value": cluster.estimated_value if hasattr(cluster, 'estimated_value') else 0,
                    "strength": cluster.strength if hasattr(cluster, 'strength') else "minor",
                    "distance_pct": abs(cluster.distance_percent) if hasattr(cluster, 'distance_percent') else 0,
                    "source": "liquidity_cluster"
                }
                
                if cluster.side == "above":
                    liquidity_above_total += zone["value"]
                    above_zones.append(zone)
                else:
                    liquidity_below_total += zone["value"]
                    below_zones.append(zone)
    
    # From order book analysis
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        
        # Analyze ask-side walls (resistance/liquidity above)
        if asks:
            ask_volumes = [(float(a[0]), float(a[1])) for a in asks[:50]]
            avg_ask = sum(v for _, v in ask_volumes) / len(ask_volumes) if ask_volumes else 0
            
            for price, volume in ask_volumes:
                if volume > avg_ask * 2.5:  # Significant wall
                    distance_pct = ((price - current_price) / current_price) * 100
                    if distance_pct > 0 and distance_pct < MAX_DISTANCE_PCT:
                        zone = {
                            "price": price,
                            "value": volume * price,
                            "strength": "major" if volume > avg_ask * 5 else "moderate",
                            "distance_pct": distance_pct,
                            "source": "orderbook_ask"
                        }
                        above_zones.append(zone)
                        liquidity_above_total += zone["value"]
        
        # Analyze bid-side walls (support/liquidity below)
        if bids:
            bid_volumes = [(float(b[0]), float(b[1])) for b in bids[:50]]
            avg_bid = sum(v for _, v in bid_volumes) / len(bid_volumes) if bid_volumes else 0
            
            for price, volume in bid_volumes:
                if volume > avg_bid * 2.5:  # Significant wall
                    distance_pct = ((current_price - price) / current_price) * 100
                    if distance_pct > 0 and distance_pct < MAX_DISTANCE_PCT:
                        zone = {
                            "price": price,
                            "value": volume * price,
                            "strength": "major" if volume > avg_bid * 5 else "moderate",
                            "distance_pct": distance_pct,
                            "source": "orderbook_bid"
                        }
                        below_zones.append(zone)
                        liquidity_below_total += zone["value"]
    
    # From liquidation data (CoinGlass)
    if liquidation_data:
        liq_levels = liquidation_data.get("liquidation_levels", [])
        for level in liq_levels:
            if isinstance(level, dict):
                liq_price = level.get("price", 0)
                liq_value = level.get("value", 0)
                
                if liq_price > current_price:
                    distance_pct = ((liq_price - current_price) / current_price) * 100
                    if distance_pct < MAX_DISTANCE_PCT:
                        zone = {
                            "price": liq_price,
                            "value": liq_value,
                            "strength": "major" if liq_value > 10000000 else "moderate",
                            "distance_pct": distance_pct,
                            "source": "liquidation"
                        }
                        above_zones.append(zone)
                        liquidity_above_total += liq_value
                elif liq_price < current_price:
                    distance_pct = ((current_price - liq_price) / current_price) * 100
                    if distance_pct < MAX_DISTANCE_PCT:
                        zone = {
                            "price": liq_price,
                            "value": liq_value,
                            "strength": "major" if liq_value > 10000000 else "moderate",
                            "distance_pct": distance_pct,
                            "source": "liquidation"
                        }
                        below_zones.append(zone)
                        liquidity_below_total += liq_value
    
    # ======== 2. EXTRACT MARKET CONTEXT FOR SCORING ========
    oi_change_24h = 0
    compression_level = 0
    breakout_probability = "LOW"
    
    if open_interest_data:
        oi_change_24h = open_interest_data.get("change_24h", 0)
    
    if market_energy_data:
        compression_level = market_energy_data.get("compression_level", 0) if isinstance(market_energy_data.get("compression_level"), (int, float)) else 0
        breakout_probability = market_energy_data.get("breakout_probability", "LOW")
    
    # ======== 3. CALCULATE STRENGTH SCORE FOR EACH ZONE ========
    def calculate_strength_score(zone: dict) -> dict:
        """
        Calculate total strength score for a zone.
        
        Returns zone with score breakdown:
        - value_score (0-50): Based on liquidity value
        - distance_score (0-30): Optimal range scoring
        - context_score (0-20): Market context bonus
        - total_score: Sum of all scores
        - significance: STRONG/WEAK flag
        """
        value = zone.get("value", 0)
        distance = zone.get("distance_pct", 0)
        
        # ═══ STEP 1: FILTER - Skip if below detection thresholds ═══
        if value < MIN_LIQUIDITY_VALUE or distance < MIN_DISTANCE_PCT:
            zone["value_score"] = 0
            zone["distance_score"] = 0
            zone["context_score"] = 0
            zone["total_score"] = 0
            zone["filtered_out"] = True
            zone["significance"] = "FILTERED"
            return zone
        
        zone["filtered_out"] = False
        
        # ═══ STEP 2: VALUE SCORE (0-60) - DOMINANT FACTOR ═══
        # Increased from 0-50 to 0-60 to prioritize liquidity size
        # log10 scaling: $1M = 60, $10M = 70, $100M = 80
        if value > 0:
            value_score = min(60, math.log10(value) * 10)
        else:
            value_score = 0
        zone["value_score"] = round(value_score, 1)
        
        # ═══ STEP 3: DISTANCE SCORE (0-25) - OPTIMAL RANGE PREFERRED ═══
        # NEW: Heavily penalize too-close targets, reward optimal range
        # Optimal range: 0.5% - 3.0% = MAX points
        # Too close (< 0.3%): MINIMAL points (noise)
        # Close but weak (0.3-0.5%): LOW points
        # Extended (3-4%): MEDIUM points
        # Very far (>4%): LOW points
        
        if distance < WEAK_DISTANCE_THRESHOLD:
            # Too close - this is noise, not a real target
            distance_score = 3  # Minimal score
            zone["is_noise"] = True
        elif WEAK_DISTANCE_THRESHOLD <= distance < OPTIMAL_DISTANCE_MIN:
            # Close but not noise - weak target
            distance_score = 10
            zone["is_noise"] = False
        elif OPTIMAL_DISTANCE_MIN <= distance <= OPTIMAL_DISTANCE_MAX:
            # OPTIMAL RANGE - maximum score
            distance_score = 25
            zone["is_noise"] = False
        elif OPTIMAL_DISTANCE_MAX < distance <= 4.0:
            # Extended but achievable
            distance_score = 18
            zone["is_noise"] = False
        else:
            # Very far
            distance_score = 8
            zone["is_noise"] = False
        
        zone["distance_score"] = distance_score
        
        # ═══ STEP 4: CONTEXT SCORE (0-15) - Reduced weight ═══
        context_score = 0
        
        # OI change supporting movement
        if oi_change_24h > 3:
            context_score += 4
        
        # Compression suggesting breakout
        if compression_level > 70 or compression_level == "HIGH":
            context_score += 4
        
        # High breakout probability
        if breakout_probability == "HIGH":
            context_score += 4
        
        # Major strength zones get bonus
        if zone.get("strength") == "major":
            context_score += 3
        
        zone["context_score"] = min(15, context_score)
        
        # ═══ STEP 5: TOTAL SCORE ═══
        zone["total_score"] = zone["value_score"] + zone["distance_score"] + zone["context_score"]
        
        # ═══ STEP 6: SIGNIFICANCE FLAG ═══
        # STRONG: Optimal distance + good value
        # WEAK: Too close (noise) or low value
        if distance < WEAK_DISTANCE_THRESHOLD:
            zone["significance"] = "WEAK"
        elif distance >= OPTIMAL_DISTANCE_MIN and distance <= OPTIMAL_DISTANCE_MAX and value >= 3_000_000:
            zone["significance"] = "STRONG"
        elif value >= 5_000_000:
            zone["significance"] = "MODERATE"
        else:
            zone["significance"] = "WEAK"
        
        return zone
    
    # Score all zones
    above_zones = [calculate_strength_score(z) for z in above_zones]
    below_zones = [calculate_strength_score(z) for z in below_zones]
    
    # ======== 4. INTELLIGENT TARGET SELECTION ========
    # Priority: OPTIMAL distance zones > STRONG zones > any valid zones
    valid_above = [z for z in above_zones if not z.get("filtered_out", True)]
    valid_below = [z for z in below_zones if not z.get("filtered_out", True)]
    
    # Separate zones by quality tier
    def categorize_zones(zones):
        optimal = []  # Distance 0.5-3%, value > $3M
        good = []     # Distance 0.3-0.5% or 3-4%, value > $1M
        noise = []    # Distance < 0.3%
        
        for z in zones:
            dist = z.get("distance_pct", 0)
            val = z.get("value", 0)
            
            if OPTIMAL_DISTANCE_MIN <= dist <= OPTIMAL_DISTANCE_MAX and val >= 3_000_000:
                optimal.append(z)
            elif dist < WEAK_DISTANCE_THRESHOLD:
                noise.append(z)
            else:
                good.append(z)
        
        return optimal, good, noise
    
    optimal_above, good_above, noise_above = categorize_zones(valid_above)
    optimal_below, good_below, noise_below = categorize_zones(valid_below)
    
    # Sort each tier by VALUE (not total_score) - value is dominant
    for tier in [optimal_above, good_above, noise_above, optimal_below, good_below, noise_below]:
        tier.sort(key=lambda z: z.get("value", 0), reverse=True)
    
    # ======== 5. SELECT PRIMARY MAGNET ========
    # Priority: optimal > good > noise
    all_optimal = optimal_above + optimal_below
    all_good = good_above + good_below
    all_noise = noise_above + noise_below
    
    # Sort combined lists by value
    all_optimal.sort(key=lambda z: z.get("value", 0), reverse=True)
    all_good.sort(key=lambda z: z.get("value", 0), reverse=True)
    all_noise.sort(key=lambda z: z.get("value", 0), reverse=True)
    
    # Select primary magnet from best available tier
    if all_optimal:
        primary_magnet = all_optimal[0]
        primary_magnet["selection_reason"] = "optimal_range"
    elif all_good:
        primary_magnet = all_good[0]
        primary_magnet["selection_reason"] = "good_range"
    elif all_noise:
        primary_magnet = all_noise[0]
        primary_magnet["selection_reason"] = "fallback_noise"
        primary_magnet["significance"] = "WEAK"  # Override to weak
    else:
        primary_magnet = {"price": current_price, "value": 0, "distance_pct": 0, "total_score": 0, "side": "above", "significance": "NONE"}
    
    primary_side = primary_magnet.get("side", "above")
    
    # Add side info
    for z in valid_above:
        z["side"] = "above"
    for z in valid_below:
        z["side"] = "below"
    
    # Select secondary magnet (prefer opposite side)
    secondary_magnet = None
    opposite_optimal = optimal_below if primary_side == "above" else optimal_above
    opposite_good = good_below if primary_side == "above" else good_above
    opposite_noise = noise_below if primary_side == "above" else noise_above
    
    if opposite_optimal:
        secondary_magnet = opposite_optimal[0]
    elif opposite_good:
        secondary_magnet = opposite_good[0]
    elif opposite_noise:
        secondary_magnet = opposite_noise[0]
    
    # Log selection for debugging
    logger.debug(f"[Magnet v2.1] Selection: optimal={len(all_optimal)}, good={len(all_good)}, noise={len(all_noise)}")
    logger.debug(f"[Magnet v2.1] Primary: ${primary_magnet.get('value', 0)/1e6:.1f}M @ {primary_magnet.get('distance_pct', 0):.2f}% [{primary_magnet.get('significance', 'UNKNOWN')}]")
    
    # ══════════════════════════════════════════════════════════════════════
    # HARD RULE: NO MAGNET IF LIQUIDITY TOO CLOSE ON BOTH SIDES
    # If both above and below have nearest liquidity within 0.1%, this is
    # NOT a magnet - price is already inside liquidity, no movement to capture
    # ══════════════════════════════════════════════════════════════════════
    
    # Find closest liquidity on each side
    closest_above_dist = min([z.get("distance_pct", 999) for z in valid_above], default=999)
    closest_below_dist = min([z.get("distance_pct", 999) for z in valid_below], default=999)
    
    no_clear_magnet = False
    
    if closest_above_dist <= NO_MAGNET_THRESHOLD and closest_below_dist <= NO_MAGNET_THRESHOLD:
        # BOTH sides have liquidity within 0.1% - NO CLEAR MAGNET
        no_clear_magnet = True
        logger.info(f"[Magnet v2.2] NO CLEAR MAGNET - liquidity too close on both sides "
                   f"(above: {closest_above_dist:.2f}%, below: {closest_below_dist:.2f}%)")
        signals.clear()
        signals.append("NO CLEAR MAGNET - LIQUIDITY TOO CLOSE")
    
    # ======== 6. DETERMINE TARGET DIRECTION ========
    total_above_score = sum(z.get("value", 0) for z in valid_above)  # Use VALUE for direction
    total_below_score = sum(z.get("value", 0) for z in valid_below)
    total_score = total_above_score + total_below_score
    
    if no_clear_magnet:
        # HARD RULE: No direction when liquidity too close on both sides
        target_direction = "NEUTRAL"
        score_ratio = 1.0
    elif total_score > 0:
        score_ratio = total_above_score / total_below_score if total_below_score > 0 else 10.0
        
        if score_ratio > 1.3:
            target_direction = "UP"
            signals.append(get_translation("magnet_stronger_above", lang, score_ratio))
        elif score_ratio < 0.77 and score_ratio > 0:
            target_direction = "DOWN"
            inverse_ratio = 1/score_ratio if score_ratio > 0 else 1.0
            signals.append(get_translation("magnet_stronger_below", lang, inverse_ratio))
        else:
            target_direction = "BALANCED"
            signals.append(get_translation("magnet_balanced", lang))
    else:
        target_direction = "BALANCED"
        score_ratio = 1.0
        signals.append(get_translation("magnet_balanced", lang))
    
    # ======== 7. CALCULATE OVERALL MAGNET SCORE ========
    # Based on the strength of the primary magnet AND its significance
    primary_significance = primary_magnet.get("significance", "UNKNOWN")
    
    # HARD RULE: If no clear magnet, force LOW score
    if no_clear_magnet:
        magnet_score = 25  # Very low score - non-actionable
        primary_significance = "NON_ACTIONABLE"
    elif primary_magnet.get("total_score", 0) > 0:
        raw_score = primary_magnet.get("total_score", 0)
        
        # Penalize score if primary is WEAK (noise)
        if primary_significance == "WEAK":
            raw_score = raw_score * 0.6  # 40% penalty
        
        if target_direction == "BALANCED":
            magnet_score = 40 + min(raw_score / 5, 20)
        else:
            magnet_score = min(raw_score + 20, 100)
            if raw_score > 50 and primary_significance != "WEAK":
                magnet_score = max(magnet_score, 70)
    else:
        magnet_score = 45  # Neutral when no valid data
    
    # ======== 8. DETERMINE MAGNET STRENGTH (based on significance) ========
    # HARD RULE: No clear magnet = LOW strength, non-actionable
    if no_clear_magnet:
        magnet_strength = "LOW"
        # Clear any previous signals and set the warning
        signals = ["NO CLEAR MAGNET - LIQUIDITY TOO CLOSE"]
    elif primary_significance == "WEAK":
        magnet_strength = "WEAK"
        signals.append(get_translation("magnet_weak_distance", lang) if hasattr(get_translation, '__call__') else "Target too close - low significance")
    elif target_direction == "BALANCED":
        magnet_strength = "MODERATE"
    elif primary_significance == "STRONG" and magnet_score >= 65:
        magnet_strength = "VERY_STRONG"
        signals.append(get_translation("magnet_very_strong", lang))
    elif magnet_score >= 65:
        magnet_strength = "STRONG"
        signals.append(get_translation("magnet_strong", lang))
    elif magnet_score >= 40:
        magnet_strength = "MODERATE"
    else:
        magnet_strength = "WEAK"
    
    # ======== 9. SWEEP EXPECTATION ========
    sweep_expectation = "NO_CLEAR_SWEEP"
    
    # HARD RULE: No sweep expectation if no clear magnet
    if no_clear_magnet:
        sweep_expectation = "NON_ACTIONABLE"
    elif primary_significance != "WEAK":
        if target_direction == "UP" and secondary_magnet and secondary_magnet.get("side") == "below":
            if secondary_magnet.get("value", 0) > MIN_LIQUIDITY_VALUE and secondary_magnet.get("distance_pct", 0) < 2:
                sweep_expectation = "SWEEP_DOWN_FIRST"
                signals.append(get_translation("sweep_down_first", lang, secondary_magnet["price"]))
        elif target_direction == "DOWN" and secondary_magnet and secondary_magnet.get("side") == "above":
            if secondary_magnet.get("value", 0) > MIN_LIQUIDITY_VALUE and secondary_magnet.get("distance_pct", 0) < 2:
                sweep_expectation = "SWEEP_UP_FIRST"
                signals.append(get_translation("sweep_up_first", lang, secondary_magnet["price"]))
        
        if magnet_score >= 70 and target_direction not in ["BALANCED", "NEUTRAL"]:
            if target_direction == "UP":
                sweep_expectation = "SWEEP_UP_FIRST"
            else:
                sweep_expectation = "SWEEP_DOWN_FIRST"
    
    # ======== 10. BUILD EXPLANATION ========
    primary_distance = primary_magnet.get("distance_pct", 0)
    if primary_side == "below":
        primary_distance = -primary_distance  # Negative for below
    
    # Build explanation - special case for NO CLEAR MAGNET
    if no_clear_magnet:
        explanation = "NO CLEAR MAGNET - Price is inside liquidity on both sides. No directional attraction. Wait for price to move away from immediate liquidity before taking action."
    else:
        explanation = _build_magnet_explanation(
            magnet_score, target_direction, magnet_strength,
            primary_magnet.get("price", current_price), primary_distance,
            liquidity_above_total, liquidity_below_total,
            sweep_expectation, lang
        )
    
    # Log selection details
    if no_clear_magnet:
        logger.info(f"[Magnet v2.2] NO CLEAR MAGNET - both sides within {NO_MAGNET_THRESHOLD}% "
                   f"(above: {closest_above_dist:.2f}%, below: {closest_below_dist:.2f}%)")
    else:
        logger.debug(f"[Magnet v2.2] Primary: ${primary_magnet.get('value', 0)/1e6:.1f}M @ {primary_magnet.get('distance_pct', 0):.2f}% "
                    f"[{primary_significance}] (score={primary_magnet.get('total_score', 0):.0f}), Dir={target_direction}")
    
    # ======== 11. V3.3 DERIVATIVES CLUSTER VALIDATION ========
    # Validate primary cluster using derivatives pressure
    cluster_validated = False
    derivatives_support = "WEAK"
    liquidation_pressure_direction = "BALANCED"
    buy_sell_aggression = "BALANCED"
    cluster_validation_reason = None
    
    if derivatives_context and derivatives_context.get("data_available") and not no_clear_magnet:
        validation_score = 0
        validation_reasons = []
        
        # 1. Liquidation Pressure Analysis
        liq_data = derivatives_context.get("liquidation", {})
        if liq_data:
            long_liq = liq_data.get("long_liquidation_24h", 0)
            short_liq = liq_data.get("short_liquidation_24h", 0)
            total_liq = long_liq + short_liq
            
            if total_liq > 0:
                long_pct = (long_liq / total_liq) * 100
                
                if long_pct > 60:
                    liquidation_pressure_direction = "DOWN"
                    if target_direction == "DOWN":
                        validation_score += 30
                        validation_reasons.append("liquidation_pressure_supports_down")
                    elif target_direction == "UP":
                        validation_score -= 15
                        validation_reasons.append("liquidation_pressure_against_up")
                elif long_pct < 40:
                    liquidation_pressure_direction = "UP"
                    if target_direction == "UP":
                        validation_score += 30
                        validation_reasons.append("short_squeeze_supports_up")
                    elif target_direction == "DOWN":
                        validation_score -= 15
                        validation_reasons.append("short_squeeze_against_down")
                else:
                    liquidation_pressure_direction = "BALANCED"
        
        # 2. Buy/Sell Aggression Analysis
        buy_sell_data = derivatives_context.get("buy_sell", {})
        if buy_sell_data:
            buy_ratio = buy_sell_data.get("buy_ratio", 50)
            pressure = buy_sell_data.get("pressure_direction", "BALANCED")
            
            if pressure == "BUY":
                buy_sell_aggression = "BUYING"
                if target_direction == "UP":
                    validation_score += 25
                    validation_reasons.append("aggressive_buying_supports_up")
                elif target_direction == "DOWN":
                    validation_score -= 10
                    validation_reasons.append("buying_against_down")
            elif pressure == "SELL":
                buy_sell_aggression = "SELLING"
                if target_direction == "DOWN":
                    validation_score += 25
                    validation_reasons.append("aggressive_selling_supports_down")
                elif target_direction == "UP":
                    validation_score -= 10
                    validation_reasons.append("selling_against_up")
            else:
                buy_sell_aggression = "BALANCED"
        
        # 3. OI Context
        oi_data = derivatives_context.get("open_interest", {})
        if oi_data:
            oi_change = oi_data.get("change_24h", 0)
            if oi_change > 2:
                validation_score += 15
                validation_reasons.append("oi_expansion_adds_fuel")
            elif oi_change < -2:
                validation_score -= 5
        
        # 4. Top Traders Alignment
        ls_ratio = derivatives_context.get("long_short_ratio", {})
        if ls_ratio:
            top_ratio = ls_ratio.get("top_trader_ratio", 1.0)
            if target_direction == "UP" and top_ratio > 1.2:
                validation_score += 20
                validation_reasons.append("top_traders_long")
            elif target_direction == "DOWN" and top_ratio < 0.83:
                validation_score += 20
                validation_reasons.append("top_traders_short")
        
        # Determine validation status
        if validation_score >= 50:
            cluster_validated = True
            derivatives_support = "STRONG"
            cluster_validation_reason = get_translation("cluster_strong_support", lang) if lang != "en" else f"Cluster strongly supported by derivatives ({', '.join(validation_reasons[:2])})"
        elif validation_score >= 25:
            cluster_validated = True
            derivatives_support = "MODERATE"
            cluster_validation_reason = get_translation("cluster_moderate_support", lang) if lang != "en" else f"Cluster moderately supported ({', '.join(validation_reasons[:2])})"
        elif validation_score >= 0:
            cluster_validated = False
            derivatives_support = "WEAK"
            cluster_validation_reason = get_translation("cluster_weak_support", lang) if lang != "en" else "Cluster has weak derivatives support - lower probability of being hit"
        else:
            cluster_validated = False
            derivatives_support = "CONFLICTING"
            cluster_validation_reason = get_translation("cluster_conflicting_pressure", lang) if lang != "en" else f"Derivatives pressure CONFLICTS with cluster direction ({', '.join(validation_reasons[:2])})"
        
        logger.debug(f"[Magnet v3.3] Derivatives validation: score={validation_score}, "
                    f"validated={cluster_validated}, support={derivatives_support}, "
                    f"reasons={validation_reasons}")
    else:
        # No derivatives data - validation unknown
        cluster_validation_reason = "No derivatives data available for validation"
    
    # Build data source string
    if no_clear_magnet:
        data_source_str = "Multi-Exchange + CoinGlass (v2.2, NON_ACTIONABLE - liquidity too close)"
    else:
        data_source_str = f"Multi-Exchange + CoinGlass (v3.3, significance={primary_significance}, deriv_support={derivatives_support})"
    
    # When no_clear_magnet is True, use current_price and 0.0 as placeholders
    # (Pydantic model requires float, not None for these required fields)
    if no_clear_magnet:
        nearest_price = round(current_price, 2)
        nearest_distance = 0.0
        nearest_value = 0.0
    else:
        nearest_price = round(primary_magnet.get("price", current_price), 2)
        nearest_distance = round(primary_distance, 2)
        nearest_value = round(primary_magnet.get("value", 0), 0)
    
    return LiquidityMagnet(
        magnet_score=round(magnet_score, 1),
        target_direction=target_direction,
        magnet_strength=magnet_strength,
        nearest_magnet_price=nearest_price,
        nearest_magnet_distance_percent=nearest_distance,
        nearest_magnet_value=nearest_value,
        secondary_magnet_price=round(secondary_magnet["price"], 2) if secondary_magnet and not no_clear_magnet else None,
        secondary_magnet_distance_percent=round(-secondary_magnet["distance_pct"] if secondary_magnet.get("side") == "below" else secondary_magnet["distance_pct"], 2) if secondary_magnet and not no_clear_magnet else None,
        secondary_magnet_value=round(secondary_magnet["value"], 0) if secondary_magnet else None,
        liquidity_above_total=round(liquidity_above_total, 0),
        liquidity_below_total=round(liquidity_below_total, 0),
        sweep_expectation=sweep_expectation,
        attraction_ratio=round(score_ratio, 2),
        signals=signals[:5],
        explanation=explanation,
        data_source=data_source_str,
        # V3.3: Derivatives validation
        cluster_validated=cluster_validated if not no_clear_magnet else False,
        derivatives_support=derivatives_support if not no_clear_magnet else "NONE",
        liquidation_pressure_direction=liquidation_pressure_direction,
        buy_sell_aggression=buy_sell_aggression,
        cluster_validation_reason=cluster_validation_reason
    )


def _build_magnet_explanation(
    score: float, direction: str, strength: str,
    magnet_price: float, distance: float,
    liq_above: float, liq_below: float,
    sweep: str, lang: str
) -> str:
    """Build comprehensive explanation for liquidity magnet."""
    
    if strength == "VERY_STRONG":
        if direction == "UP":
            return get_translation("magnet_explanation_very_strong_up", lang, magnet_price, abs(distance))
        elif direction == "DOWN":
            return get_translation("magnet_explanation_very_strong_down", lang, magnet_price, abs(distance))
        else:
            return get_translation("magnet_explanation_very_strong_balanced", lang)
    
    elif strength == "STRONG":
        if direction == "UP":
            return get_translation("magnet_explanation_strong_up", lang, magnet_price)
        elif direction == "DOWN":
            return get_translation("magnet_explanation_strong_down", lang, magnet_price)
        else:
            return get_translation("magnet_explanation_strong_balanced", lang)
    
    elif strength == "MODERATE":
        if direction == "UP":
            return get_translation("magnet_explanation_moderate_up", lang)
        elif direction == "DOWN":
            return get_translation("magnet_explanation_moderate_down", lang)
        else:
            return get_translation("magnet_explanation_moderate_balanced", lang)
    
    else:  # WEAK
        return get_translation("magnet_explanation_weak", lang)


# ═══════════════════════════════════════════════════════════════════════════════
# LIQUIDITY ZONE ENGINE (PREVIEW MODE)
# ═══════════════════════════════════════════════════════════════════════════════
# Zone-based liquidity detection - groups nearby levels into clusters
# This is a PARALLEL enhancement - does NOT modify existing magnet logic
# 
# Key difference from point-based magnet:
# - Groups levels within 0.3% into zones
# - Evaluates clusters, not single points
# - Produces more realistic targets (0.5% - 3%)
# ═══════════════════════════════════════════════════════════════════════════════

def analyze_liquidity_zones(
    current_price: float,
    aggregated_orderbook: dict,
    liquidity_clusters: List = None,
    liquidation_data: dict = None,
    open_interest_data: dict = None,
    market_energy_data: dict = None,
    legacy_magnet: LiquidityMagnet = None,
    lang: str = "it"
) -> LiquidityZoneEngineResult:
    """
    Liquidity Zone Engine v1.0 - ZONE-BASED detection (PREVIEW)
    
    Groups nearby liquidity levels into zones/clusters for more realistic
    target detection that aligns with real market heatmap behavior.
    
    Key Algorithm:
    1. Collect all liquidity levels from multiple sources
    2. Group levels within 0.3% price distance into zones
    3. Calculate zone metrics (top, bottom, center, strength, density)
    4. Filter weak zones (<$5M, too close, too far)
    5. Score zones (0-100) based on strength, distance, context
    6. Return primary/secondary zones with full metadata
    
    IMPORTANT: This runs in PARALLEL with legacy magnet for comparison.
    Does NOT modify any live trading logic.
    
    Args:
        current_price: Current BTC price
        aggregated_orderbook: Multi-exchange orderbook data
        liquidity_clusters: Pre-detected liquidity clusters
        liquidation_data: CoinGlass liquidation data
        open_interest_data: Open interest metrics
        market_energy_data: Market energy/compression data
        legacy_magnet: Result from legacy point-based magnet (for comparison)
        lang: Language for explanations
        
    Returns:
        LiquidityZoneEngineResult with detected zones and analysis
    """
    import math
    import uuid
    
    # ════════════════ CONFIGURATION ════════════════
    ZONE_GROUPING_THRESHOLD_PCT = 0.3  # Group levels within 0.3% distance
    MIN_ZONE_LIQUIDITY = 1_000_000  # $1M minimum for detection
    MIN_DISTANCE_PCT = 0.01  # 0.01% minimum for detection
    MAX_DISTANCE_PCT = 5.0  # Ignore zones too far
    
    # Selection thresholds (for quality targets)
    WEAK_DISTANCE_THRESHOLD = 0.3  # Below this = weak/noise
    OPTIMAL_DISTANCE_MIN = 0.5
    OPTIMAL_DISTANCE_MAX = 3.0
    
    # ════════════════ STEP 1: COLLECT ALL LIQUIDITY LEVELS ════════════════
    all_levels_above = []  # List of {price, value, source}
    all_levels_below = []
    
    # From liquidity clusters
    if liquidity_clusters:
        for cluster in liquidity_clusters:
            if hasattr(cluster, 'side'):
                level = {
                    "price": cluster.price if hasattr(cluster, 'price') else 0,
                    "value": cluster.estimated_value if hasattr(cluster, 'estimated_value') else 0,
                    "source": "cluster"
                }
                if level["value"] > 0:
                    if cluster.side == "above":
                        all_levels_above.append(level)
                    else:
                        all_levels_below.append(level)
    
    # From order book
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        
        # Asks (above price)
        if asks:
            ask_volumes = [(float(a[0]), float(a[1])) for a in asks[:100]]
            avg_ask = sum(v for _, v in ask_volumes) / len(ask_volumes) if ask_volumes else 0
            
            for price, volume in ask_volumes:
                if volume > avg_ask * 2:  # Significant level
                    distance_pct = ((price - current_price) / current_price) * 100
                    if 0 < distance_pct < MAX_DISTANCE_PCT:
                        all_levels_above.append({
                            "price": price,
                            "value": volume * price,
                            "source": "orderbook"
                        })
        
        # Bids (below price)
        if bids:
            bid_volumes = [(float(b[0]), float(b[1])) for b in bids[:100]]
            avg_bid = sum(v for _, v in bid_volumes) / len(bid_volumes) if bid_volumes else 0
            
            for price, volume in bid_volumes:
                if volume > avg_bid * 2:  # Significant level
                    distance_pct = ((current_price - price) / current_price) * 100
                    if 0 < distance_pct < MAX_DISTANCE_PCT:
                        all_levels_below.append({
                            "price": price,
                            "value": volume * price,
                            "source": "orderbook"
                        })
    
    # From liquidation data
    if liquidation_data:
        liq_levels = liquidation_data.get("liquidation_levels", [])
        for level in liq_levels:
            if isinstance(level, dict):
                liq_price = level.get("price", 0)
                liq_value = level.get("value", 0)
                
                if liq_price > current_price:
                    distance_pct = ((liq_price - current_price) / current_price) * 100
                    if distance_pct < MAX_DISTANCE_PCT:
                        all_levels_above.append({
                            "price": liq_price,
                            "value": liq_value,
                            "source": "liquidation"
                        })
                elif liq_price < current_price:
                    distance_pct = ((current_price - liq_price) / current_price) * 100
                    if distance_pct < MAX_DISTANCE_PCT:
                        all_levels_below.append({
                            "price": liq_price,
                            "value": liq_value,
                            "source": "liquidation"
                        })
    
    # ════════════════ STEP 2: GROUP LEVELS INTO ZONES ════════════════
    def group_levels_into_zones(levels: List[dict], direction: str) -> List[dict]:
        """
        Group nearby liquidity levels into zones.
        Levels within ZONE_GROUPING_THRESHOLD_PCT are grouped together.
        """
        if not levels:
            return []
        
        # Sort by price (ascending for above, descending for below)
        sorted_levels = sorted(levels, key=lambda x: x["price"], reverse=(direction == "DOWN"))
        
        zones = []
        current_zone_levels = [sorted_levels[0]]
        
        for level in sorted_levels[1:]:
            # Check if this level is within threshold of zone anchor
            zone_anchor_price = current_zone_levels[0]["price"]
            distance_pct = abs(level["price"] - zone_anchor_price) / zone_anchor_price * 100
            
            if distance_pct <= ZONE_GROUPING_THRESHOLD_PCT:
                # Add to current zone
                current_zone_levels.append(level)
            else:
                # Close current zone and start new one
                if current_zone_levels:
                    zones.append(current_zone_levels)
                current_zone_levels = [level]
        
        # Don't forget last zone
        if current_zone_levels:
            zones.append(current_zone_levels)
        
        return zones
    
    zones_above_raw = group_levels_into_zones(all_levels_above, "UP")
    zones_below_raw = group_levels_into_zones(all_levels_below, "DOWN")
    
    # ════════════════ STEP 3: CALCULATE ZONE METRICS ════════════════
    def calculate_zone_metrics(zone_levels: List[dict], direction: str) -> dict:
        """
        Calculate metrics for a zone:
        - zone_top, zone_bottom, zone_center (weighted)
        - zone_strength (total liquidity)
        - zone_density (liquidity per price range)
        - distance_pct from current price
        """
        if not zone_levels:
            return None
        
        prices = [l["price"] for l in zone_levels]
        values = [l["value"] for l in zone_levels]
        total_value = sum(values)
        
        zone_top = max(prices)
        zone_bottom = min(prices)
        price_range = zone_top - zone_bottom if zone_top != zone_bottom else 1
        
        # Weighted center by liquidity
        if total_value > 0:
            zone_center = sum(p * v for p, v in zip(prices, values)) / total_value
        else:
            zone_center = (zone_top + zone_bottom) / 2
        
        # Density (liquidity per dollar of price range)
        zone_density = total_value / price_range if price_range > 0 else total_value
        
        # Distance from current price
        if direction == "UP":
            distance_pct = ((zone_center - current_price) / current_price) * 100
        else:
            distance_pct = ((current_price - zone_center) / current_price) * 100
        
        return {
            "zone_top": zone_top,
            "zone_bottom": zone_bottom,
            "zone_center": zone_center,
            "zone_strength": total_value,
            "zone_density": zone_density,
            "distance_pct": distance_pct,
            "num_levels": len(zone_levels),
            "levels": zone_levels,
            "direction": direction
        }
    
    # Calculate metrics for all zones
    zones_above_metrics = [calculate_zone_metrics(z, "UP") for z in zones_above_raw]
    zones_below_metrics = [calculate_zone_metrics(z, "DOWN") for z in zones_below_raw]
    
    # Filter out None values
    zones_above_metrics = [z for z in zones_above_metrics if z is not None]
    zones_below_metrics = [z for z in zones_below_metrics if z is not None]
    
    # ════════════════ STEP 4: FILTER WEAK ZONES ════════════════
    def is_valid_zone(zone: dict) -> bool:
        """Filter out zones that don't meet criteria"""
        zone["filter_reason"] = None
        if zone["zone_strength"] < MIN_ZONE_LIQUIDITY:
            zone["filter_reason"] = f"strength {zone['zone_strength']/1e6:.1f}M < {MIN_ZONE_LIQUIDITY/1e6:.0f}M"
            return False
        if zone["distance_pct"] < MIN_DISTANCE_PCT:
            zone["filter_reason"] = f"distance {zone['distance_pct']:.2f}% < {MIN_DISTANCE_PCT}%"
            return False
        if zone["distance_pct"] > MAX_DISTANCE_PCT:
            zone["filter_reason"] = f"distance {zone['distance_pct']:.2f}% > {MAX_DISTANCE_PCT}%"
            return False
        return True
    
    # Debug: log zones before filtering
    logger.debug(f"[Zone Engine] Before filtering: {len(zones_above_metrics)} above, {len(zones_below_metrics)} below")
    for z in zones_above_metrics[:3]:
        logger.debug(f"[Zone Engine] Above zone: ${z['zone_center']:,.0f}, strength=${z['zone_strength']/1e6:.1f}M, dist={z['distance_pct']:.2f}%")
    for z in zones_below_metrics[:3]:
        logger.debug(f"[Zone Engine] Below zone: ${z['zone_center']:,.0f}, strength=${z['zone_strength']/1e6:.1f}M, dist={z['distance_pct']:.2f}%")
    
    valid_zones_above = [z for z in zones_above_metrics if is_valid_zone(z)]
    valid_zones_below = [z for z in zones_below_metrics if is_valid_zone(z)]
    
    # Log filtered out zones
    filtered_out_above = [z for z in zones_above_metrics if not is_valid_zone(z)]
    filtered_out_below = [z for z in zones_below_metrics if not is_valid_zone(z)]
    if filtered_out_above or filtered_out_below:
        logger.debug(f"[Zone Engine] Filtered out: {len(filtered_out_above)} above, {len(filtered_out_below)} below")
        for z in (filtered_out_above + filtered_out_below)[:5]:
            logger.debug(f"[Zone Engine] Filtered: ${z['zone_center']:,.0f} - reason: {z.get('filter_reason', 'unknown')}")
    
    # ════════════════ STEP 5: SCORE ZONES ════════════════
    # Extract market context
    oi_change_24h = 0
    compression_level = 0
    breakout_probability = "LOW"
    
    if open_interest_data:
        oi_change_24h = open_interest_data.get("change_24h", 0)
    
    if market_energy_data:
        compression_level = market_energy_data.get("compression_level", 0)
        if isinstance(compression_level, str):
            compression_level = {"LOW": 30, "MEDIUM": 50, "HIGH": 80}.get(compression_level, 50)
        breakout_probability = market_energy_data.get("breakout_probability", "LOW")
    
    def score_zone(zone: dict) -> dict:
        """
        Calculate zone score (0-100) with significance flag:
        - Liquidity strength (0-60): DOMINANT factor
        - Distance optimality (0-25): Optimal range preferred
        - Context alignment (0-15)
        - significance: STRONG/MODERATE/WEAK
        """
        strength = zone["zone_strength"]
        distance = zone["distance_pct"]
        
        # ═══ LIQUIDITY STRENGTH SCORE (0-60) - DOMINANT ═══
        if strength > 0:
            strength_score = min(60, math.log10(strength) * 10)
        else:
            strength_score = 0
        
        # ═══ DISTANCE SCORE (0-25) - OPTIMAL RANGE PREFERRED ═══
        # Heavily penalize too-close zones (noise)
        if distance < WEAK_DISTANCE_THRESHOLD:
            distance_score = 3  # Noise - minimal score
            zone["is_noise"] = True
        elif WEAK_DISTANCE_THRESHOLD <= distance < OPTIMAL_DISTANCE_MIN:
            distance_score = 10  # Close but not noise
            zone["is_noise"] = False
        elif OPTIMAL_DISTANCE_MIN <= distance <= OPTIMAL_DISTANCE_MAX:
            distance_score = 25  # OPTIMAL range
            zone["is_noise"] = False
        elif OPTIMAL_DISTANCE_MAX < distance <= 4.0:
            distance_score = 18  # Extended
            zone["is_noise"] = False
        else:
            distance_score = 5  # Very far
            zone["is_noise"] = False
        
        # ═══ CONTEXT SCORE (0-15) ═══
        context_score = 0
        
        if oi_change_24h > 3:
            context_score += 5
        elif oi_change_24h > 0:
            context_score += 2
        
        if compression_level > 70:
            context_score += 5
        elif compression_level > 50:
            context_score += 3
        
        if breakout_probability == "HIGH":
            context_score += 5
        
        context_score = min(15, context_score)
        
        # ═══ TOTAL SCORE ═══
        zone["score"] = round(strength_score + distance_score + context_score, 1)
        zone["score_breakdown"] = {
            "strength": round(strength_score, 1),
            "distance": round(distance_score, 1),
            "context": round(context_score, 1)
        }
        
        # ═══ SIGNIFICANCE FLAG ═══
        if distance < WEAK_DISTANCE_THRESHOLD:
            zone["significance"] = "WEAK"
        elif OPTIMAL_DISTANCE_MIN <= distance <= OPTIMAL_DISTANCE_MAX and strength >= 3_000_000:
            zone["significance"] = "STRONG"
        elif strength >= 5_000_000:
            zone["significance"] = "MODERATE"
        else:
            zone["significance"] = "WEAK"
        
        return zone
    
    # Score all valid zones
    valid_zones_above = [score_zone(z) for z in valid_zones_above]
    valid_zones_below = [score_zone(z) for z in valid_zones_below]
    
    # ════════════════ STEP 6: INTELLIGENT ZONE SELECTION ════════════════
    # Separate zones by quality tier
    def categorize_zones(zones):
        optimal = []  # Optimal distance + good value
        good = []     # Acceptable range
        noise = []    # Too close
        
        for z in zones:
            if z.get("significance") == "STRONG":
                optimal.append(z)
            elif z.get("is_noise", False) or z.get("significance") == "WEAK":
                noise.append(z)
            else:
                good.append(z)
        
        # Sort each tier by VALUE (strength)
        optimal.sort(key=lambda z: z.get("zone_strength", 0), reverse=True)
        good.sort(key=lambda z: z.get("zone_strength", 0), reverse=True)
        noise.sort(key=lambda z: z.get("zone_strength", 0), reverse=True)
        
        return optimal, good, noise
    
    optimal_above, good_above, noise_above = categorize_zones(valid_zones_above)
    optimal_below, good_below, noise_below = categorize_zones(valid_zones_below)
    
    # Combine for selection
    all_optimal = optimal_above + optimal_below
    all_good = good_above + good_below
    all_noise = noise_above + noise_below
    
    # Sort by value
    all_optimal.sort(key=lambda z: z.get("zone_strength", 0), reverse=True)
    all_good.sort(key=lambda z: z.get("zone_strength", 0), reverse=True)
    all_noise.sort(key=lambda z: z.get("zone_strength", 0), reverse=True)
    
    # Select primary zone from best available tier
    primary_zone_dict = None
    if all_optimal:
        primary_zone_dict = all_optimal[0]
    elif all_good:
        primary_zone_dict = all_good[0]
    elif all_noise:
        primary_zone_dict = all_noise[0]
        primary_zone_dict["significance"] = "WEAK"  # Force weak flag
    
    # Select secondary from opposite side
    secondary_zone_dict = None
    if primary_zone_dict:
        primary_side = primary_zone_dict.get("direction")
        opposite_optimal = [z for z in all_optimal if z.get("direction") != primary_side]
        opposite_good = [z for z in all_good if z.get("direction") != primary_side]
        opposite_noise = [z for z in all_noise if z.get("direction") != primary_side]
        
        if opposite_optimal:
            secondary_zone_dict = opposite_optimal[0]
        elif opposite_good:
            secondary_zone_dict = opposite_good[0]
        elif opposite_noise:
            secondary_zone_dict = opposite_noise[0]
    
    # Log selection
    logger.debug(f"[Zone v1.1] Selection: optimal={len(all_optimal)}, good={len(all_good)}, noise={len(all_noise)}")
    if primary_zone_dict:
        logger.debug(f"[Zone v1.1] Primary: ${primary_zone_dict.get('zone_strength', 0)/1e6:.1f}M @ {primary_zone_dict.get('distance_pct', 0):.2f}% [{primary_zone_dict.get('significance', 'UNKNOWN')}]")
    
    # ════════════════ STEP 7: BUILD OUTPUT ZONES ════════════════
    def build_liquidity_zone(zone: dict, zone_id: str) -> LiquidityZone:
        """Convert zone dict to LiquidityZone model"""
        return LiquidityZone(
            zone_id=zone_id,
            direction=zone["direction"],
            zone_top=round(zone["zone_top"], 2),
            zone_bottom=round(zone["zone_bottom"], 2),
            zone_center=round(zone["zone_center"], 2),
            zone_strength=round(zone["zone_strength"], 0),
            zone_density=round(zone["zone_density"], 0),
            distance_pct=round(zone["distance_pct"], 2),
            num_levels=zone["num_levels"],
            levels=[LiquidityZoneLevel(
                price=round(l["price"], 2),
                value=round(l["value"], 0),
                source=l["source"]
            ) for l in zone.get("levels", [])[:10]],  # Limit to 10 levels
            score=zone["score"],
            score_breakdown=zone["score_breakdown"]
        )
    
    # Build zone lists (all valid zones for display)
    zones_above_output = [build_liquidity_zone(z, f"zone_up_{i}") for i, z in enumerate(valid_zones_above)]
    zones_below_output = [build_liquidity_zone(z, f"zone_down_{i}") for i, z in enumerate(valid_zones_below)]
    
    # ════════════════ STEP 8: BUILD PRIMARY & SECONDARY FROM SELECTION ════════════════
    primary_zone = build_liquidity_zone(primary_zone_dict, "primary") if primary_zone_dict else None
    secondary_zone = build_liquidity_zone(secondary_zone_dict, "secondary") if secondary_zone_dict else None
    
    # ════════════════ STEP 9: DETERMINE DOMINANT DIRECTION ════════════════
    total_above = sum(z.zone_strength for z in zones_above_output)
    total_below = sum(z.zone_strength for z in zones_below_output)
    
    if total_above > total_below * 1.3:
        dominant_direction = "UP"
    elif total_below > total_above * 1.3:
        dominant_direction = "DOWN"
    else:
        dominant_direction = "BALANCED"
    
    # ════════════════ STEP 9: COMPARE WITH LEGACY MAGNET ════════════════
    zone_vs_legacy_aligned = True
    legacy_direction = None
    legacy_score = None
    
    if legacy_magnet:
        legacy_direction = legacy_magnet.target_direction
        legacy_score = legacy_magnet.magnet_score
        
        if primary_zone:
            # Check if zone and legacy agree on direction
            if primary_zone.direction == "UP" and legacy_direction == "DOWN":
                zone_vs_legacy_aligned = False
            elif primary_zone.direction == "DOWN" and legacy_direction == "UP":
                zone_vs_legacy_aligned = False
    
    # ════════════════ STEP 10: BUILD RESULT ════════════════
    zones_detected_count = len(zones_above_output) + len(zones_below_output)
    
    logger.debug(f"[Zone Engine] Detected {zones_detected_count} zones: "
                f"{len(zones_above_output)} above, {len(zones_below_output)} below. "
                f"Primary: {primary_zone.zone_center if primary_zone else 'None'} "
                f"@ {primary_zone.distance_pct if primary_zone else 0:.2f}% "
                f"(${primary_zone.zone_strength/1e6 if primary_zone else 0:.1f}M)")
    
    return LiquidityZoneEngineResult(
        timestamp=datetime.now(timezone.utc),
        current_price=current_price,
        primary_liquidity_zone=primary_zone,
        secondary_liquidity_zone=secondary_zone,
        zones_above=zones_above_output,
        zones_below=zones_below_output,
        zones_detected_count=zones_detected_count,
        dominant_direction=dominant_direction,
        total_liquidity_above=round(total_above, 0),
        total_liquidity_below=round(total_below, 0),
        legacy_magnet_direction=legacy_direction,
        legacy_magnet_score=legacy_score,
        zone_vs_legacy_aligned=zone_vs_legacy_aligned,
        engine_version="zone_v1.0",
        data_source="Multi-Exchange + CoinGlass (Zone-Based)"
    )


# ============== WHALE ALERT ENGINE ==============

def analyze_whale_activity(
    candles: List[dict],
    current_price: float,
    aggregated_orderbook: dict,
    liquidation_data: dict = None,
    open_interest_data: dict = None,
    lang: str = "it"
) -> WhaleActivity:
    """
    Advanced Whale Alert Engine v2.0 - Professional large player behavior detection.
    
    Analyzes:
    1. Volume spikes and absorption patterns
    2. Order book buy/sell pressure imbalance
    3. OI Divergence Analysis (price vs OI)
    4. Accumulation/Distribution detection
    5. Liquidation cluster targeting
    6. Smart money behavior inference
    
    Returns direction (BUY/SELL/NEUTRAL), strength score, and detailed explanation.
    """
    
    signals = []
    buy_pressure = 0
    sell_pressure = 0
    
    # Initialize new analysis fields
    oi_divergence = None
    oi_divergence_strength = 0
    accumulation_distribution = None
    absorption_detected = False
    liquidation_zones = []
    whale_behavior = "unknown"
    
    # ======== 1. VOLUME ANALYSIS WITH ABSORPTION DETECTION ========
    volume_spike = False
    volume_ratio = 1.0
    price_volatility = 0
    
    if candles and len(candles) >= 20:
        recent_volumes = [c["volume"] for c in candles[-20:]]
        avg_volume = sum(recent_volumes) / len(recent_volumes) if recent_volumes else 0
        current_volume = candles[-1]["volume"] if candles else 0
        
        # Calculate price volatility for absorption detection
        if len(candles) >= 5:
            recent_ranges = [(c["high"] - c["low"]) / c["low"] * 100 for c in candles[-5:]]
            price_volatility = sum(recent_ranges) / len(recent_ranges)
        
        if avg_volume > 0:
            volume_ratio = current_volume / avg_volume
            
            # High volume analysis
            if volume_ratio >= 2.5:
                volume_spike = True
                candle = candles[-1]
                is_bullish = candle["close"] > candle["open"]
                body_size = abs(candle["close"] - candle["open"])
                total_range = candle["high"] - candle["low"]
                body_ratio = body_size / total_range if total_range > 0 else 0
                
                # ABSORPTION DETECTION: High volume + small body = orders being absorbed
                if body_ratio < 0.3 and volume_ratio >= 2.0:
                    absorption_detected = True
                    # Determine absorption direction from wicks
                    upper_wick = candle["high"] - max(candle["open"], candle["close"])
                    lower_wick = min(candle["open"], candle["close"]) - candle["low"]
                    
                    if upper_wick > lower_wick * 2:
                        # Long upper wick = selling absorbed, bullish
                        buy_pressure += 25
                        accumulation_distribution = "accumulation"
                        signals.append(get_translation("absorption_bullish", lang, volume_ratio))
                    elif lower_wick > upper_wick * 2:
                        # Long lower wick = buying absorbed, bearish
                        sell_pressure += 25
                        accumulation_distribution = "distribution"
                        signals.append(get_translation("absorption_bearish", lang, volume_ratio))
                    else:
                        signals.append(get_translation("absorption_neutral", lang, volume_ratio))
                else:
                    # Normal volume spike with direction
                    if is_bullish:
                        buy_pressure += 25
                        signals.append(get_translation("large_bullish_volume", lang, volume_ratio))
                    else:
                        sell_pressure += 25
                        signals.append(get_translation("large_bearish_volume", lang, volume_ratio))
                        
            elif volume_ratio >= 1.5:
                if candles[-1]["close"] > candles[-1]["open"]:
                    buy_pressure += 10
                else:
                    sell_pressure += 10
    
    # ======== 2. OI DIVERGENCE ANALYSIS ========
    if open_interest_data and candles and len(candles) >= 5:
        oi_change_1h = open_interest_data.get("change_1h", 0)
        oi_change_24h = open_interest_data.get("change_24h", 0)
        
        # Calculate price change over same period
        price_change_1h = 0
        if len(candles) >= 4:
            price_change_1h = (candles[-1]["close"] - candles[-4]["close"]) / candles[-4]["close"] * 100
        
        price_change_5c = (candles[-1]["close"] - candles[-5]["close"]) / candles[-5]["close"] * 100 if len(candles) >= 5 else 0
        
        # OI DIVERGENCE INTERPRETATION
        # Price UP + OI DOWN = Short Closing (bullish continuation likely)
        # Price DOWN + OI DOWN = Long Closing (bearish continuation likely)
        # Price UP + OI UP = New Longs Opening (strong bullish)
        # Price DOWN + OI UP = New Shorts Opening (strong bearish)
        
        oi_threshold = 0.3  # Minimum OI change to consider
        price_threshold = 0.15  # Minimum price change to consider
        
        if abs(oi_change_1h) > oi_threshold and abs(price_change_1h) > price_threshold:
            if price_change_1h > price_threshold and oi_change_1h < -oi_threshold:
                # Price up + OI down = Short Closing
                oi_divergence = "short_closing"
                oi_divergence_strength = min(100, abs(price_change_1h) * 20 + abs(oi_change_1h) * 15)
                buy_pressure += 20
                signals.append(get_translation("oi_div_short_closing", lang, price_change_1h, oi_change_1h))
                
            elif price_change_1h < -price_threshold and oi_change_1h < -oi_threshold:
                # Price down + OI down = Long Closing
                oi_divergence = "long_closing"
                oi_divergence_strength = min(100, abs(price_change_1h) * 20 + abs(oi_change_1h) * 15)
                sell_pressure += 20
                signals.append(get_translation("oi_div_long_closing", lang, price_change_1h, oi_change_1h))
                
            elif price_change_1h > price_threshold and oi_change_1h > oi_threshold:
                # Price up + OI up = New Longs Opening
                oi_divergence = "long_opening"
                oi_divergence_strength = min(100, price_change_1h * 25 + oi_change_1h * 20)
                buy_pressure += 30
                signals.append(get_translation("oi_div_long_opening", lang, price_change_1h, oi_change_1h))
                
            elif price_change_1h < -price_threshold and oi_change_1h > oi_threshold:
                # Price down + OI up = New Shorts Opening
                oi_divergence = "short_opening"
                oi_divergence_strength = min(100, abs(price_change_1h) * 25 + oi_change_1h * 20)
                sell_pressure += 30
                signals.append(get_translation("oi_div_short_opening", lang, price_change_1h, oi_change_1h))
    
    # ======== 3. ORDER BOOK PRESSURE ANALYSIS ========
    orderbook_aggression = None
    
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        
        total_bid_depth = aggregated_orderbook.get("total_bid_depth", 0)
        total_ask_depth = aggregated_orderbook.get("total_ask_depth", 0)
        
        if total_bid_depth + total_ask_depth > 0:
            ob_imbalance = ((total_bid_depth - total_ask_depth) / (total_bid_depth + total_ask_depth)) * 100
            
            if ob_imbalance > 25:
                buy_pressure += 30
                orderbook_aggression = "aggressive_buying"
                signals.append(get_translation("heavy_buy_orderbook", lang, ob_imbalance))
            elif ob_imbalance > 15:
                buy_pressure += 15
                signals.append(get_translation("buy_orderbook_dominance", lang, ob_imbalance))
            elif ob_imbalance < -25:
                sell_pressure += 30
                orderbook_aggression = "aggressive_selling"
                signals.append(get_translation("heavy_sell_orderbook", lang, abs(ob_imbalance)))
            elif ob_imbalance < -15:
                sell_pressure += 15
                signals.append(get_translation("sell_orderbook_dominance", lang, abs(ob_imbalance)))
        
        # Detect large whale walls
        if bids:
            bid_volumes = [(float(b[0]), float(b[1])) for b in bids[:30]]
            avg_bid = sum(v[1] for v in bid_volumes) / len(bid_volumes) if bid_volumes else 0
            large_bid_walls = [(price, vol) for price, vol in bid_volumes if vol > avg_bid * 4]
            if large_bid_walls:
                buy_pressure += 10
                wall_price = large_bid_walls[0][0]
                wall_distance = ((current_price - wall_price) / current_price) * 100
                signals.append(get_translation("bid_wall_detected", lang, len(large_bid_walls), wall_price))
                liquidation_zones.append({
                    "type": "bid_wall",
                    "price": wall_price,
                    "distance_percent": -wall_distance,
                    "strength": "high"
                })
        
        if asks:
            ask_volumes = [(float(a[0]), float(a[1])) for a in asks[:30]]
            avg_ask = sum(v[1] for v in ask_volumes) / len(ask_volumes) if ask_volumes else 0
            large_ask_walls = [(price, vol) for price, vol in ask_volumes if vol > avg_ask * 4]
            if large_ask_walls:
                sell_pressure += 10
                wall_price = large_ask_walls[0][0]
                wall_distance = ((wall_price - current_price) / current_price) * 100
                signals.append(get_translation("ask_wall_detected", lang, len(large_ask_walls), wall_price))
                liquidation_zones.append({
                    "type": "ask_wall",
                    "price": wall_price,
                    "distance_percent": wall_distance,
                    "strength": "high"
                })
    
    # ======== 4. LIQUIDATION DATA ANALYSIS ========
    liquidation_bias = None
    
    if liquidation_data:
        long_liq_24h = liquidation_data.get("long_liquidation_usd_24h", 0)
        short_liq_24h = liquidation_data.get("short_liquidation_usd_24h", 0)
        total_liq = long_liq_24h + short_liq_24h
        
        if total_liq > 0:
            long_ratio = long_liq_24h / total_liq
            short_ratio = short_liq_24h / total_liq
            
            if long_ratio > 0.65:
                sell_pressure += 20
                liquidation_bias = "longs_liquidated"
                signals.append(get_translation("heavy_long_liquidations", lang, long_ratio * 100))
            elif long_ratio > 0.55:
                sell_pressure += 10
                signals.append(get_translation("more_longs_liquidated_signal", lang))
            elif short_ratio > 0.65:
                buy_pressure += 20
                liquidation_bias = "shorts_liquidated"
                signals.append(get_translation("heavy_short_liquidations", lang, short_ratio * 100))
            elif short_ratio > 0.55:
                buy_pressure += 10
                signals.append(get_translation("more_shorts_liquidated_signal", lang))
        
        # LIQUIDATION CLUSTER TARGETING
        # Identify where major liquidation zones are based on recent liquidation data
        if candles and len(candles) >= 10:
            recent_high = max(c["high"] for c in candles[-10:])
            recent_low = min(c["low"] for c in candles[-10:])
            
            # Estimate liquidation clusters based on typical leverage
            # Long liquidations cluster below recent lows
            # Short liquidations cluster above recent highs
            long_liq_zone = recent_low * 0.98  # -2% below recent low
            short_liq_zone = recent_high * 1.02  # +2% above recent high
            
            long_liq_distance = ((current_price - long_liq_zone) / current_price) * 100
            short_liq_distance = ((short_liq_zone - current_price) / current_price) * 100
            
            # Determine which zone is more attractive to hunt
            if long_liq_distance < short_liq_distance and long_liq_distance < 3:
                # Long liquidation zone is closer - price may hunt it
                liquidation_zones.append({
                    "type": "long_liquidation_cluster",
                    "price": round(long_liq_zone, 0),
                    "distance_percent": round(-long_liq_distance, 2),
                    "strength": "major",
                    "target_type": "stop_hunt"
                })
                if long_liq_distance < 1.5:
                    signals.append(get_translation("long_liq_zone_near", lang, long_liq_zone, long_liq_distance))
                    
            if short_liq_distance < long_liq_distance and short_liq_distance < 3:
                # Short liquidation zone is closer - price may hunt it
                liquidation_zones.append({
                    "type": "short_liquidation_cluster",
                    "price": round(short_liq_zone, 0),
                    "distance_percent": round(short_liq_distance, 2),
                    "strength": "major",
                    "target_type": "stop_hunt"
                })
                if short_liq_distance < 1.5:
                    signals.append(get_translation("short_liq_zone_near", lang, short_liq_zone, short_liq_distance))
    
    # ======== 5. DETERMINE WHALE BEHAVIOR ========
    # Infer what large players are doing based on combined signals
    
    if absorption_detected:
        if accumulation_distribution == "accumulation":
            whale_behavior = "accumulating"
        elif accumulation_distribution == "distribution":
            whale_behavior = "distributing"
        else:
            whale_behavior = "absorbing"
    elif oi_divergence in ["long_opening", "short_opening"]:
        whale_behavior = "position_building"
    elif oi_divergence in ["long_closing", "short_closing"]:
        whale_behavior = "position_closing"
    elif liquidation_zones and any(z.get("target_type") == "stop_hunt" for z in liquidation_zones):
        whale_behavior = "hunting_stops"
    elif buy_pressure > sell_pressure + 30:
        whale_behavior = "accumulating"
    elif sell_pressure > buy_pressure + 30:
        whale_behavior = "distributing"
    
    # ======== 6. CALCULATE FINAL DIRECTION ========
    total_pressure = buy_pressure + sell_pressure
    strength = min(100, total_pressure)
    
    # More nuanced direction calculation - reduce NEUTRAL tendency
    pressure_diff = buy_pressure - sell_pressure
    
    if pressure_diff > 15:  # Lowered from 20
        direction = "BUY"
        confidence = min(95, 50 + pressure_diff * 0.8)
    elif pressure_diff < -15:  # Lowered from 20
        direction = "SELL"
        confidence = min(95, 50 + abs(pressure_diff) * 0.8)
    else:
        # Even in "neutral" range, lean toward the stronger side
        if buy_pressure > sell_pressure:
            direction = "BUY"
            confidence = max(40, 50 + pressure_diff)
        elif sell_pressure > buy_pressure:
            direction = "SELL"
            confidence = max(40, 50 + abs(pressure_diff))
        else:
            direction = "NEUTRAL"
            confidence = 50
    
    # Boost confidence if multiple strong signals align
    strong_signal_count = sum(1 for s in signals if any(word in s.lower() for word in ["heavy", "large", "major", "forte", "grande", "massiccio"]))
    if strong_signal_count >= 2:
        confidence = min(95, confidence + 10)
    
    # ======== 7. BUILD COMPREHENSIVE EXPLANATION ========
    explanation = _build_whale_explanation(
        direction, whale_behavior, oi_divergence, oi_divergence_strength,
        accumulation_distribution, absorption_detected, liquidation_bias,
        volume_spike, orderbook_aggression, signals, lang
    )
    
    return WhaleActivity(
        direction=direction,
        strength=round(strength, 1),
        confidence=round(confidence, 1),
        signals=signals[:6],  # Limit to 6 most important signals
        explanation=explanation,
        volume_spike=volume_spike,
        volume_ratio=round(volume_ratio, 2),
        buy_pressure=round(buy_pressure, 1),
        sell_pressure=round(sell_pressure, 1),
        liquidation_bias=liquidation_bias,
        orderbook_aggression=orderbook_aggression,
        oi_divergence=oi_divergence,
        oi_divergence_strength=round(oi_divergence_strength, 1),
        accumulation_distribution=accumulation_distribution,
        absorption_detected=absorption_detected,
        liquidation_zones=liquidation_zones[:3],  # Limit to 3 nearest zones
        whale_behavior=whale_behavior,
        data_source="Multi-Exchange + CoinGlass"
    )


def _build_whale_explanation(
    direction: str, whale_behavior: str, oi_divergence: str, oi_div_strength: float,
    accum_dist: str, absorption: bool, liq_bias: str,
    vol_spike: bool, ob_aggression: str, signals: List[str], lang: str
) -> str:
    """Build a comprehensive explanation of whale activity."""
    
    parts = []
    
    # Primary behavior explanation
    if whale_behavior == "accumulating":
        parts.append(get_translation("whale_accumulating", lang))
    elif whale_behavior == "distributing":
        parts.append(get_translation("whale_distributing", lang))
    elif whale_behavior == "hunting_stops":
        parts.append(get_translation("whale_hunting_stops", lang))
    elif whale_behavior == "position_building":
        parts.append(get_translation("whale_position_building", lang))
    elif whale_behavior == "position_closing":
        parts.append(get_translation("whale_position_closing", lang))
    elif whale_behavior == "absorbing":
        parts.append(get_translation("whale_absorbing", lang))
    
    # OI Divergence context
    if oi_divergence and oi_div_strength > 40:
        if oi_divergence == "short_closing":
            parts.append(get_translation("oi_context_short_closing", lang))
        elif oi_divergence == "long_closing":
            parts.append(get_translation("oi_context_long_closing", lang))
        elif oi_divergence == "long_opening":
            parts.append(get_translation("oi_context_long_opening", lang))
        elif oi_divergence == "short_opening":
            parts.append(get_translation("oi_context_short_opening", lang))
    
    # Absorption context
    if absorption:
        if accum_dist == "accumulation":
            parts.append(get_translation("absorption_context_bullish", lang))
        elif accum_dist == "distribution":
            parts.append(get_translation("absorption_context_bearish", lang))
    
    # Volume and orderbook context
    if vol_spike and ob_aggression:
        if ob_aggression == "aggressive_buying":
            parts.append(get_translation("vol_ob_bullish", lang))
        else:
            parts.append(get_translation("vol_ob_bearish", lang))
    
    # Liquidation context
    if liq_bias:
        if liq_bias == "shorts_liquidated":
            parts.append(get_translation("liq_context_bullish", lang))
        else:
            parts.append(get_translation("liq_context_bearish", lang))
    
    # Build final explanation
    if parts:
        return " ".join(parts)
    elif direction == "BUY":
        return get_translation("moderate_whale_buying", lang)
    elif direction == "SELL":
        return get_translation("moderate_whale_selling", lang)
    else:
        return get_translation("no_whale_bias", lang)

# ============== LIQUIDITY LADDER ==============

def build_liquidity_ladder(
    current_price: float,
    sr_levels: List[SupportResistanceLevel],
    liquidity_clusters: List[LiquidityCluster],
    aggregated_orderbook: dict = None,
    lang: str = "it"
) -> LiquidityLadder:
    """
    Build a Liquidity Ladder showing the sequence of important liquidity levels
    above and below current price.
    
    Identifies:
    - Stop clusters (where traders likely have stops)
    - Resistance liquidity (sell orders above)
    - Support liquidity (buy orders below)
    - Whale levels (large single orders)
    
    Ranks by distance, strength, and exchange confirmation.
    """
    
    ladder_above = []
    ladder_below = []
    
    # Get active exchanges
    active_exchanges = []
    if aggregated_orderbook:
        active_exchanges = aggregated_orderbook.get("exchanges_active", ["Kraken"])
    
    # 1. ADD S/R LEVELS TO LADDER
    for level in sr_levels:
        distance_pct = ((level.price - current_price) / current_price) * 100
        
        if level.level_type == "resistance" and level.price > current_price:
            ladder_above.append(LiquidityLevel(
                price=level.price,
                distance_percent=round(distance_pct, 2),
                strength="major" if level.strength == "strong" else "moderate" if level.strength == "moderate" else "minor",
                type="resistance_liquidity" if level.timeframe == "Multi-Exchange" else "stop_cluster",
                estimated_value=level.volume_at_level or 0,
                exchanges=level.exchanges or active_exchanges,
                explanation=level.explanation or f"Resistance at ${level.price:,.0f}"
            ))
        elif level.level_type == "support" and level.price < current_price:
            ladder_below.append(LiquidityLevel(
                price=level.price,
                distance_percent=round(distance_pct, 2),
                strength="major" if level.strength == "strong" else "moderate" if level.strength == "moderate" else "minor",
                type="support_liquidity" if level.timeframe == "Multi-Exchange" else "stop_cluster",
                estimated_value=level.volume_at_level or 0,
                exchanges=level.exchanges or active_exchanges,
                explanation=level.explanation or f"Support at ${level.price:,.0f}"
            ))
    
    # 2. ADD LIQUIDITY CLUSTERS TO LADDER
    for cluster in liquidity_clusters:
        distance_pct = ((cluster.price - current_price) / current_price) * 100
        
        # Check if this level is already in ladder (within 0.1%)
        is_duplicate = False
        target_list = ladder_above if cluster.side == "above" else ladder_below
        for existing in target_list:
            if abs(existing.price - cluster.price) / cluster.price < 0.001:
                # Merge - take higher value
                if cluster.estimated_value > existing.estimated_value:
                    existing.estimated_value = cluster.estimated_value
                is_duplicate = True
                break
        
        if not is_duplicate:
            level_type = "resistance_liquidity" if cluster.side == "above" else "support_liquidity"
            
            if cluster.side == "above":
                ladder_above.append(LiquidityLevel(
                    price=cluster.price,
                    distance_percent=round(distance_pct, 2),
                    strength=cluster.strength if cluster.strength in ["major", "moderate", "minor"] else "moderate",
                    type=level_type,
                    estimated_value=cluster.estimated_value,
                    exchanges=cluster.exchanges or active_exchanges,
                    explanation=cluster.explanation or f"Liquidity cluster at ${cluster.price:,.0f}"
                ))
            else:
                ladder_below.append(LiquidityLevel(
                    price=cluster.price,
                    distance_percent=round(distance_pct, 2),
                    strength=cluster.strength if cluster.strength in ["major", "moderate", "minor"] else "moderate",
                    type=level_type,
                    estimated_value=cluster.estimated_value,
                    exchanges=cluster.exchanges or active_exchanges,
                    explanation=cluster.explanation or f"Liquidity cluster at ${cluster.price:,.0f}"
                ))
    
    # 3. ADD ORDER BOOK WHALE LEVELS (large single orders)
    if aggregated_orderbook:
        bids = aggregated_orderbook.get("bids", [])
        asks = aggregated_orderbook.get("asks", [])
        
        # Find whale bid levels (top 3 largest)
        if bids:
            bid_list = [(float(b[0]), float(b[1])) for b in bids[:50]]
            bid_list_sorted = sorted(bid_list, key=lambda x: x[1], reverse=True)[:3]
            
            for price, qty in bid_list_sorted:
                if price < current_price:
                    distance_pct = ((price - current_price) / current_price) * 100
                    value = price * qty
                    
                    # Only add if significant value
                    if value > 500000:  # $500k+
                        ladder_below.append(LiquidityLevel(
                            price=round(price, 2),
                            distance_percent=round(distance_pct, 2),
                            strength="major" if value > 2000000 else "moderate",
                            type="whale_level",
                            estimated_value=round(value, 0),
                            exchanges=active_exchanges,
                            explanation=f"Whale bid: ${value/1000000:.1f}M ({qty:.2f} BTC)"
                        ))
        
        # Find whale ask levels
        if asks:
            ask_list = [(float(a[0]), float(a[1])) for a in asks[:50]]
            ask_list_sorted = sorted(ask_list, key=lambda x: x[1], reverse=True)[:3]
            
            for price, qty in ask_list_sorted:
                if price > current_price:
                    distance_pct = ((price - current_price) / current_price) * 100
                    value = price * qty
                    
                    if value > 500000:
                        ladder_above.append(LiquidityLevel(
                            price=round(price, 2),
                            distance_percent=round(distance_pct, 2),
                            strength="major" if value > 2000000 else "moderate",
                            type="whale_level",
                            estimated_value=round(value, 0),
                            exchanges=active_exchanges,
                            explanation=f"Whale ask: ${value/1000000:.1f}M ({qty:.2f} BTC)"
                        ))
    
    # 4. SORT AND DEDUPE LADDERS
    ladder_above = sorted(ladder_above, key=lambda x: x.distance_percent)
    ladder_below = sorted(ladder_below, key=lambda x: abs(x.distance_percent))
    
    # Remove duplicates (keep strongest)
    def dedupe_ladder(ladder):
        seen_prices = {}
        result = []
        for level in ladder:
            rounded = round(level.price, -1)  # Round to nearest $10
            if rounded not in seen_prices:
                seen_prices[rounded] = level
                result.append(level)
            else:
                # Keep the one with higher value
                if level.estimated_value > seen_prices[rounded].estimated_value:
                    result.remove(seen_prices[rounded])
                    seen_prices[rounded] = level
                    result.append(level)
        return sorted(result, key=lambda x: abs(x.distance_percent))
    
    ladder_above = dedupe_ladder(ladder_above)[:8]
    ladder_below = dedupe_ladder(ladder_below)[:8]
    
    # 5. IDENTIFY KEY LEVELS
    nearest_above = ladder_above[0] if ladder_above else None
    nearest_below = ladder_below[0] if ladder_below else None
    
    major_above = next((l for l in ladder_above if l.strength == "major"), nearest_above)
    major_below = next((l for l in ladder_below if l.strength == "major"), nearest_below)
    
    # 6. DETERMINE WHICH SIDE IS MORE ATTRACTIVE
    above_total_value = sum(l.estimated_value for l in ladder_above)
    below_total_value = sum(l.estimated_value for l in ladder_below)
    
    above_major_count = sum(1 for l in ladder_above if l.strength == "major")
    below_major_count = sum(1 for l in ladder_below if l.strength == "major")
    
    # More liquidity = more attractive for price to sweep that direction
    if above_total_value > below_total_value * 1.5 or above_major_count > below_major_count:
        more_attractive_side = "above"
    elif below_total_value > above_total_value * 1.5 or below_major_count > above_major_count:
        more_attractive_side = "below"
    else:
        more_attractive_side = "balanced"
    
    # 7. DETERMINE SWEEP EXPECTATION
    # Price tends to seek liquidity - if one side has much more, expect sweep there first
    if nearest_above and nearest_below:
        above_dist = nearest_above.distance_percent
        below_dist = abs(nearest_below.distance_percent)
        
        # If much more liquidity above and closer, expect upward sweep first
        if more_attractive_side == "above" and above_dist < below_dist * 1.5:
            sweep_expectation = "sweep_above_first"
            path_analysis = get_translation("upper_ladder_stronger", lang, above_total_value/1000000, below_total_value/1000000, nearest_above.price)
        elif more_attractive_side == "below" and below_dist < above_dist * 1.5:
            sweep_expectation = "sweep_below_first"
            path_analysis = get_translation("lower_ladder_stronger", lang, below_total_value/1000000, above_total_value/1000000, nearest_below.price)
        elif more_attractive_side == "balanced":
            sweep_expectation = "balanced"
            path_analysis = get_translation("balanced_distribution", lang)
        else:
            sweep_expectation = "no_clear_sweep"
            path_analysis = get_translation("no_clear_sweep", lang)
    else:
        sweep_expectation = "no_clear_sweep"
        path_analysis = get_translation("insufficient_data", lang)
    
    return LiquidityLadder(
        current_price=round(current_price, 2),
        ladder_above=ladder_above,
        ladder_below=ladder_below,
        nearest_above=nearest_above,
        nearest_below=nearest_below,
        major_above=major_above,
        major_below=major_below,
        more_attractive_side=more_attractive_side,
        sweep_expectation=sweep_expectation,
        path_analysis=path_analysis,
        data_source=f"{', '.join(active_exchanges) or 'Kraken'} ({len(active_exchanges) or 1} source{'s' if len(active_exchanges) > 1 else ''})"
    )

# ============== TRADE SIGNAL GENERATOR ==============

# ============== DYNAMIC SIGNAL TIMING ==============

def calculate_signal_timing(
    direction: str,
    confidence: float,
    current_price: float,
    entry_zone_low: float,
    entry_zone_high: float,
    setup_type: str,
    market_energy: Optional[Any] = None,
    liquidity_magnet: Optional[Any] = None,
    whale_activity: Optional[Any] = None,
    signal_state: str = "NO_TRADE",
    lang: str = "it"
) -> Dict[str, Any]:
    """
    Calculate dynamic signal urgency and validity window.
    
    Base Rule: 4H timeframe = 90 minutes default validity
    
    Factors that REDUCE validity (more urgent):
    - High confidence (>75%)
    - High Market Energy
    - Strong directional Liquidity Magnet
    - Price close to entry zone (<0.5%)
    - sweep_reversal setup type
    - Whale activity confirms direction
    - High volatility
    
    Factors that INCREASE validity (less urgent):
    - Moderate confidence (50-70%)
    - Low/Medium Market Energy
    - Price far from entry zone (>1%)
    - continuation setup type
    - Balanced magnet
    - Low market volatility
    
    Returns:
    - signal_urgency: LOW / MEDIUM / HIGH
    - valid_for_minutes: 30-150 minutes
    - setup_status: SETUP_IN_CONFIRMATION / OPERATIONAL / EXPIRED / INVALIDATED
    - urgency_reason: Explanation text
    - entry_distance_percent: Distance from entry
    - time_sensitivity: URGENT / NORMAL / RELAXED
    """
    
    # Base validity for 4H timeframe
    BASE_VALIDITY_MINUTES = 90
    
    # Calculate entry zone center and distance
    entry_center = (entry_zone_low + entry_zone_high) / 2
    entry_distance_percent = abs((current_price - entry_center) / current_price) * 100
    
    # Initialize scoring
    urgency_score = 0  # Higher = more urgent
    validity_adjustment = 0  # Negative = shorter validity
    reasons = []
    
    # ======== NO TRADE signals ========
    if direction == "NO TRADE":
        return {
            "signal_urgency": "LOW",
            "valid_for_minutes": 0,
            "setup_status": "NO_TRADE",
            "urgency_reason": get_translation("no_trade_no_urgency", lang),
            "entry_distance_percent": 0,
            "time_sensitivity": "NORMAL"
        }
    
    # ======== CONFIDENCE FACTOR ========
    if confidence >= 80:
        urgency_score += 3
        validity_adjustment -= 30  # 30 min shorter
        reasons.append(get_translation("urgency_high_confidence", lang))
    elif confidence >= 70:
        urgency_score += 2
        validity_adjustment -= 15
        reasons.append(get_translation("urgency_good_confidence", lang))
    elif confidence >= 55:
        urgency_score += 1
        # No validity change
    else:
        validity_adjustment += 15  # Less urgent, more time
    
    # ======== ENTRY DISTANCE FACTOR ========
    if entry_distance_percent <= 0.3:
        urgency_score += 3
        validity_adjustment -= 30  # Very close - act fast
        reasons.append(get_translation("urgency_price_at_entry", lang))
    elif entry_distance_percent <= 0.7:
        urgency_score += 2
        validity_adjustment -= 15
        reasons.append(get_translation("urgency_price_near_entry", lang))
    elif entry_distance_percent <= 1.5:
        urgency_score += 1
        # Normal distance
    else:
        validity_adjustment += 20  # Far from entry, more time to position
        reasons.append(get_translation("urgency_entry_far", lang))
    
    # ======== MARKET ENERGY FACTOR ========
    if market_energy:
        energy_score = getattr(market_energy, 'energy_score', 0)
        compression = getattr(market_energy, 'compression_level', 'LOW')
        expansion_ready = getattr(market_energy, 'expansion_readiness', 'LOW')
        
        if energy_score >= 70 or compression == "HIGH":
            urgency_score += 2
            validity_adjustment -= 20
            reasons.append(get_translation("urgency_high_energy", lang))
        elif energy_score >= 50 or compression == "MEDIUM":
            urgency_score += 1
            validity_adjustment -= 10
        else:
            validity_adjustment += 10  # Low energy = more time
        
        # Expansion readiness boosts urgency
        if expansion_ready == "HIGH":
            urgency_score += 1
            validity_adjustment -= 10
            reasons.append(get_translation("urgency_expansion_imminent", lang))
    
    # ======== LIQUIDITY MAGNET FACTOR ========
    if liquidity_magnet:
        magnet_score = getattr(liquidity_magnet, 'magnet_score', 0)
        magnet_direction = getattr(liquidity_magnet, 'target_direction', 'BALANCED')
        magnet_strength = getattr(liquidity_magnet, 'magnet_strength', 'WEAK')
        
        # Check if magnet aligns with signal direction
        magnet_aligns = (
            (direction == "LONG" and magnet_direction == "UP") or
            (direction == "SHORT" and magnet_direction == "DOWN")
        )
        
        if magnet_aligns and magnet_strength in ["STRONG", "VERY_STRONG"]:
            urgency_score += 2
            validity_adjustment -= 15
            reasons.append(get_translation("urgency_strong_magnet_aligned", lang))
        elif magnet_aligns and magnet_strength == "MODERATE":
            urgency_score += 1
            validity_adjustment -= 5
        elif magnet_direction == "BALANCED":
            validity_adjustment += 10  # Less directional pull
    
    # ======== SETUP TYPE FACTOR ========
    if setup_type == "sweep_reversal":
        urgency_score += 2
        validity_adjustment -= 20  # Sweep setups need quick action
        reasons.append(get_translation("urgency_sweep_setup", lang))
    elif setup_type == "continuation":
        validity_adjustment += 15  # Continuation has more time
    # standard = no adjustment
    
    # ======== WHALE ACTIVITY FACTOR ========
    if whale_activity:
        whale_direction = getattr(whale_activity, 'direction', 'NEUTRAL')
        whale_strength = getattr(whale_activity, 'strength', 0)
        
        # Check if whale confirms signal
        whale_confirms = (
            (direction == "LONG" and whale_direction == "BULLISH") or
            (direction == "SHORT" and whale_direction == "BEARISH")
        )
        
        if whale_confirms and whale_strength >= 50:
            urgency_score += 2
            validity_adjustment -= 15
            reasons.append(get_translation("urgency_whale_confirms", lang))
        elif whale_confirms:
            urgency_score += 1
        elif whale_direction == "NEUTRAL":
            validity_adjustment += 5  # No whale pressure
    
    # ======== CALCULATE FINAL VALUES ========
    
    # Calculate final validity (bounded between 30 and 150 minutes)
    final_validity = max(30, min(150, BASE_VALIDITY_MINUTES + validity_adjustment))
    
    # Determine urgency level based on score
    if urgency_score >= 8:
        signal_urgency = "HIGH"
        time_sensitivity = "URGENT"
    elif urgency_score >= 4:
        signal_urgency = "MEDIUM"
        time_sensitivity = "NORMAL"
    else:
        signal_urgency = "LOW"
        time_sensitivity = "RELAXED"
    
    # Determine setup_status
    if signal_state == "OPERATIONAL":
        setup_status = "OPERATIONAL"
    elif signal_state == "SETUP_IN_CONFIRMATION":
        setup_status = "SETUP_IN_CONFIRMATION"
    elif direction in ["LONG", "SHORT"]:
        setup_status = "OPERATIONAL"  # Default for valid signals
    else:
        setup_status = "NO_TRADE"
    
    # Build urgency reason text
    if not reasons:
        if signal_urgency == "LOW":
            reasons.append(get_translation("urgency_standard_setup", lang))
        else:
            reasons.append(get_translation("urgency_factors_aligned", lang))
    
    urgency_reason = " ".join(reasons[:3])  # Max 3 reasons
    
    return {
        "signal_urgency": signal_urgency,
        "valid_for_minutes": final_validity,
        "setup_status": setup_status,
        "urgency_reason": urgency_reason,
        "entry_distance_percent": round(entry_distance_percent, 2),
        "time_sensitivity": time_sensitivity
    }


# ============== SIGNAL ENGINE VERSION ==============
# v1 = Original sweep reversal only (STABLE) - DISABLED FOR OPERATIONAL USE
# v2 = Sweep reversal + Trend continuation (DEV) - DISABLED FOR OPERATIONAL USE  
# v3 = Multi-timeframe with cluster targets (ACTIVE) - ONLY OPERATIONAL ENGINE
SIGNAL_ENGINE_VERSION = os.environ.get("SIGNAL_ENGINE_VERSION", "v3")  # Default to v3

# V3-ONLY MODE: When True, only V3 signals are recorded to operational history
# V1/V2 remain available for educational/diagnostic purposes only
V3_ONLY_OPERATIONAL_MODE = True


def detect_trend_continuation_setup(
    current_price: float,
    market_bias: MarketBias,
    market_energy: MarketEnergy,
    liquidity_magnet: dict,
    whale_activity: WhaleActivity,
    sr_levels: List[SupportResistanceLevel],
    candles: List[dict] = None
) -> dict:
    """
    Detect TREND CONTINUATION setup conditions (CryptoRadar v2).
    
    This detects valid continuation setups where price is trending
    and conditions favor continuation rather than reversal.
    
    LONG CONTINUATION conditions:
    - Market Bias: BULLISH (score > 55)
    - Market Energy: MEDIUM or HIGH (>= 40)
    - Liquidity Magnet: UP direction
    - Whale Activity: BULLISH or NEUTRAL
    - Price breaks/reclaims resistance
    
    SHORT CONTINUATION conditions:
    - Market Bias: BEARISH (score < 45)
    - Market Energy: MEDIUM or HIGH (>= 40)
    - Liquidity Magnet: DOWN direction
    - Whale Activity: BEARISH or NEUTRAL
    - Price breaks/loses support
    
    Returns:
        dict with is_valid, direction, confidence, reasoning
    """
    result = {
        "is_valid": False,
        "direction": None,
        "confidence": 0,
        "reasoning": [],
        "conditions_met": {},
        "setup_type": "trend_continuation"
    }
    
    # Extract values safely
    bias = market_bias.bias if market_bias else "NEUTRAL"
    bias_confidence = market_bias.confidence if market_bias else 50
    
    energy_score = 0
    energy_state = "unknown"
    if market_energy:
        energy_score = getattr(market_energy, 'energy_score', 0) or 0
        energy_state = getattr(market_energy, 'compression_level', 'unknown') or 'unknown'
    
    liq_direction = "BALANCED"
    liq_score = 50
    if liquidity_magnet:
        liq_direction = liquidity_magnet.get("target_direction", "BALANCED")
        liq_score = liquidity_magnet.get("attraction_score", 50)
    
    whale_dir = "NEUTRAL"
    whale_confidence = 0
    if whale_activity:
        whale_dir = getattr(whale_activity, 'direction', 'NEUTRAL') or 'NEUTRAL'
        whale_confidence = getattr(whale_activity, 'confidence', 0) or 0
    
    # Organize S/R levels
    supports = sorted([l for l in sr_levels if l.level_type == "support"], 
                     key=lambda x: abs(x.distance_percent))
    resistances = sorted([l for l in sr_levels if l.level_type == "resistance"], 
                        key=lambda x: abs(x.distance_percent))
    
    # ============ CHECK LONG CONTINUATION ============
    long_conditions = {
        "market_bias_bullish": bias == "BULLISH" and bias_confidence > 55,
        "energy_sufficient": energy_score >= 40 or energy_state.lower() in ['expansion', 'moderate', 'high'],
        "liquidity_up": liq_direction == "UP" and liq_score > 50,
        "whale_not_bearish": whale_dir in ["BULLISH", "NEUTRAL", "ACCUMULATION"],
        "near_breakout": len(resistances) > 0 and abs(resistances[0].distance_percent) < 1.0
    }
    
    long_score = sum(1 for v in long_conditions.values() if v)
    long_valid = long_score >= 4  # Need 4 out of 5 conditions
    
    # ============ CHECK SHORT CONTINUATION ============
    short_conditions = {
        "market_bias_bearish": bias == "BEARISH" and bias_confidence > 55,
        "energy_sufficient": energy_score >= 40 or energy_state.lower() in ['expansion', 'moderate', 'high'],
        "liquidity_down": liq_direction == "DOWN" and liq_score > 50,
        "whale_not_bullish": whale_dir in ["BEARISH", "NEUTRAL", "DISTRIBUTION"],
        "near_breakdown": len(supports) > 0 and abs(supports[0].distance_percent) < 1.0
    }
    
    short_score = sum(1 for v in short_conditions.values() if v)
    short_valid = short_score >= 4  # Need 4 out of 5 conditions
    
    # ============ DETERMINE DIRECTION ============
    if long_valid and (not short_valid or long_score > short_score):
        result["is_valid"] = True
        result["direction"] = "LONG"
        result["conditions_met"] = long_conditions
        
        # Calculate confidence for LONG continuation
        base_conf = 40
        base_conf += min(15, (bias_confidence - 50) * 0.3) if bias == "BULLISH" else 0
        base_conf += min(15, energy_score * 0.15) if energy_score > 0 else 0
        base_conf += min(10, (liq_score - 50) * 0.2) if liq_direction == "UP" else 0
        base_conf += 10 if whale_dir == "BULLISH" else 5 if whale_dir == "NEUTRAL" else 0
        base_conf += 5 if long_conditions["near_breakout"] else 0
        
        result["confidence"] = min(85, base_conf)
        result["reasoning"] = [
            f"Market bias BULLISH ({bias_confidence:.0f}%)",
            f"Market energy: {energy_score:.0f} ({energy_state})",
            f"Liquidity magnet pointing UP ({liq_score:.0f})",
            f"Whale activity: {whale_dir}",
            "Near resistance breakout zone" if long_conditions["near_breakout"] else "Away from key levels"
        ]
        
    elif short_valid:
        result["is_valid"] = True
        result["direction"] = "SHORT"
        result["conditions_met"] = short_conditions
        
        # Calculate confidence for SHORT continuation
        base_conf = 40
        base_conf += min(15, (50 - bias_confidence) * 0.3) if bias == "BEARISH" else 0
        base_conf += min(15, energy_score * 0.15) if energy_score > 0 else 0
        base_conf += min(10, (liq_score - 50) * 0.2) if liq_direction == "DOWN" else 0
        base_conf += 10 if whale_dir == "BEARISH" else 5 if whale_dir == "NEUTRAL" else 0
        base_conf += 5 if short_conditions["near_breakdown"] else 0
        
        result["confidence"] = min(85, base_conf)
        result["reasoning"] = [
            f"Market bias BEARISH ({bias_confidence:.0f}%)",
            f"Market energy: {energy_score:.0f} ({energy_state})",
            f"Liquidity magnet pointing DOWN ({liq_score:.0f})",
            f"Whale activity: {whale_dir}",
            "Near support breakdown zone" if short_conditions["near_breakdown"] else "Away from key levels"
        ]
    
    return result


def detect_simple_market_regime(candles: List[dict], lookback: int = 20) -> str:
    """
    Detect if market is TRENDING or RANGING (simple version for internal use).
    
    Uses:
    - Price vs moving averages
    - Higher highs / lower lows pattern
    - Volatility expansion/contraction
    
    Returns: "TRENDING_UP", "TRENDING_DOWN", or "RANGING"
    """
    if not candles or len(candles) < lookback:
        return "RANGING"
    
    recent = candles[-lookback:]
    closes = [c.get('close', 0) for c in recent]
    highs = [c.get('high', 0) for c in recent[-10:]]
    lows = [c.get('low', 0) for c in recent[-10:]]
    
    if not all(closes):
        return "RANGING"
    
    # Simple moving average
    sma_20 = sum(closes) / len(closes)
    sma_10 = sum(closes[-10:]) / 10 if len(closes) >= 10 else sma_20
    
    current_price = closes[-1]
    
    # Check for trending conditions
    above_ma = current_price > sma_20 and current_price > sma_10
    below_ma = current_price < sma_20 and current_price < sma_10
    
    # Check higher highs / lower lows
    higher_highs_count = sum(1 for i in range(1, len(highs)) if highs[i] > highs[i-1])
    lower_lows_count = sum(1 for i in range(1, len(lows)) if lows[i] < lows[i-1])
    
    if above_ma and higher_highs_count >= 5:
        return "TRENDING_UP"
    elif below_ma and lower_lows_count >= 5:
        return "TRENDING_DOWN"
    
    return "RANGING"


def generate_trade_signal(
    current_price: float,
    market_bias: MarketBias,
    liquidity_direction: LiquidityDirection,
    sr_levels: List[SupportResistanceLevel],
    funding_rate: FundingRate,
    open_interest: OpenInterest,
    patterns: List[PatternDetection],
    whale_alerts: List[WhaleAlert],
    exchange_comparison: Dict[str, Any],
    whale_activity: WhaleActivity = None,
    liquidity_ladder: LiquidityLadder = None,
    market_energy: MarketEnergy = None,
    liquidity_magnet: LiquidityMagnet = None,
    lang: str = "it"
) -> TradeSignal:
    """
    Generate a final actionable trading signal by synthesizing all intelligence.
    
    ENHANCED BTC TRADING LOGIC (v1.9.5 - Market Energy Integration):
    1. Minimum move filter: No signal if estimated move < 0.50%
    2. Smart stop placement: Beyond liquidity sweep zones
    3. Liquidity sweep detection: Identify sweep-and-reversal setups
    4. Setup type classification: continuation vs sweep_reversal
    5. Whale Activity Engine: Confirms direction with whale pressure
    6. Liquidity Ladder: Path analysis for sweep expectations
    7. Market Energy: Confidence adjustment based on compression state
    
    Scoring System:
    - Market Bias: +/-3 points
    - Liquidity Direction: +/-2 points  
    - Exchange Consensus: +/-2 points
    - Funding Rate: +/-1 point
    - Open Interest Trend: +/-1 point
    - Pattern Signals: +/-2 points
    - Whale Alerts (legacy): +/-1 point
    - Whale Activity Engine: +/-2 points (NEW)
    - Liquidity Ladder Path: +/-1 point (NEW)
    
    Total range: -15 to +15
    Signal thresholds:
    - LONG: score >= 4
    - SHORT: score <= -4
    - NO TRADE: -3 to +3 (or move < 0.40%)
    """
    
    # ================== 4H TIMEFRAME CALIBRATION v2.9.2 ==================
    # BTC 4H realistic move ranges (RELAXED for high-quality setups):
    # - Very small move: < 0.25% (weak signal, but allowed if quality high)
    # - Normal tradable move: 0.25% – 1.2%
    # - Strong 4H move: 1.2% – 2.5%
    # - Exceptional: > 2.5% (rare, don't assume as default)
    
    MINIMUM_MOVE_PERCENT = 0.25  # Reduced from 0.40 - allow smaller high-quality moves
    MINIMUM_MOVE_HIGH_QUALITY = 0.15  # Even lower threshold if quality >= 80
    NORMAL_MOVE_MIN = 0.30      # Reduced from 0.50
    NORMAL_MOVE_MAX = 1.20      # Maximum for typical 4H move
    STRONG_MOVE_THRESHOLD = 1.20  # Above this = strong move
    EXCEPTIONAL_MOVE_THRESHOLD = 2.50  # Above this = exceptional (cap targets)
    
    # 4H Target ranges (percentage from entry)
    TARGET_1_MIN = 0.40  # Reduced from 0.50 for micro-moves
    TARGET_1_MAX = 0.90  # Maximum T1: 0.9% (normal conditions)
    TARGET_1_STRONG = 1.20  # T1 for strong conditions
    TARGET_2_MIN = 0.80  # Reduced from 1.00
    TARGET_2_MAX = 1.80  # Maximum T2: 1.8% (normal conditions)
    TARGET_2_STRONG = 2.50  # T2 for exceptional conditions
    
    # Risk/Reward requirements for 4H - ADAPTIVE based on quality
    # Quality >= 80: Allow R:R >= 0.6
    # Quality >= 60: Allow R:R >= 0.8
    # Quality < 60:  Require R:R >= 1.0
    MIN_RISK_REWARD_HIGH_QUALITY = 0.6  # If quality >= 80
    MIN_RISK_REWARD_GOOD_QUALITY = 0.8  # If quality >= 60
    MIN_RISK_REWARD = 1.0  # Default minimum R:R
    GOOD_RISK_REWARD = 1.2  # Good R:R threshold
    IDEAL_RISK_REWARD = 1.5  # Ideal R:R threshold
    
    LIQUIDITY_SWEEP_BUFFER = 0.003  # 0.3% beyond obvious levels for stop placement
    
    # Helper function to check for strong market conditions (extended targets allowed)
    def is_strong_market_condition(market_energy_obj, liquidity_ladder_obj, setup_type_str):
        """
        Returns True if market conditions justify extended targets.
        Strong conditions:
        - Market energy is HIGH
        - Liquidity magnet is STRONG
        - Trend continuation setup detected
        """
        is_high_energy = False
        is_strong_magnet = False
        is_continuation = setup_type_str == "trend_continuation"
        
        if market_energy_obj:
            is_high_energy = (
                market_energy_obj.compression_level == "HIGH" or 
                market_energy_obj.energy_score >= 70 or
                market_energy_obj.breakout_probability == "HIGH"
            )
        
        if liquidity_ladder_obj:
            magnet_score = getattr(liquidity_ladder_obj, 'magnet_score', 0) or 0
            is_strong_magnet = magnet_score >= 70
        
        return is_high_energy or is_strong_magnet or is_continuation
    
    # ================== TRADE QUALITY VALIDATION FUNCTIONS ==================
    
    def validate_directional_consistency(direction, entry_low, entry_high, stop, t1, t2, current_price, lang="it"):
        """
        Validates that trade parameters are consistent with direction.
        Returns (is_valid, issues_list)
        """
        issues = []
        
        # User-friendly messages by language
        msgs = {
            "it": {
                "t1_above_entry": "Target 1 non valido per LONG (sotto entry)",
                "t2_above_t1": "Target 2 non valido (sotto Target 1)",
                "stop_below_entry": "Stop loss non valido per LONG (sopra entry)",
                "t1_above_price": "Target 1 sotto il prezzo attuale",
                "t1_below_entry": "Target 1 non valido per SHORT (sopra entry)",
                "t2_below_t1": "Target 2 non valido (sopra Target 1)",
                "stop_above_entry": "Stop loss non valido per SHORT (sotto entry)",
                "t1_below_price": "Target 1 sopra il prezzo attuale"
            },
            "en": {
                "t1_above_entry": "Target 1 invalid for LONG (below entry)",
                "t2_above_t1": "Target 2 invalid (below Target 1)",
                "stop_below_entry": "Stop loss invalid for LONG (above entry)",
                "t1_above_price": "Target 1 below current price",
                "t1_below_entry": "Target 1 invalid for SHORT (above entry)",
                "t2_below_t1": "Target 2 invalid (above Target 1)",
                "stop_above_entry": "Stop loss invalid for SHORT (below entry)",
                "t1_below_price": "Target 1 above current price"
            },
            "de": {
                "t1_above_entry": "Target 1 ungültig für LONG (unter Entry)",
                "t2_above_t1": "Target 2 ungültig (unter Target 1)",
                "stop_below_entry": "Stop Loss ungültig für LONG (über Entry)",
                "t1_above_price": "Target 1 unter aktuellem Preis",
                "t1_below_entry": "Target 1 ungültig für SHORT (über Entry)",
                "t2_below_t1": "Target 2 ungültig (über Target 1)",
                "stop_above_entry": "Stop Loss ungültig für SHORT (unter Entry)",
                "t1_below_price": "Target 1 über aktuellem Preis"
            },
            "pl": {
                "t1_above_entry": "Target 1 nieprawidłowy dla LONG (poniżej entry)",
                "t2_above_t1": "Target 2 nieprawidłowy (poniżej Target 1)",
                "stop_below_entry": "Stop loss nieprawidłowy dla LONG (powyżej entry)",
                "t1_above_price": "Target 1 poniżej aktualnej ceny",
                "t1_below_entry": "Target 1 nieprawidłowy dla SHORT (powyżej entry)",
                "t2_below_t1": "Target 2 nieprawidłowy (powyżej Target 1)",
                "stop_above_entry": "Stop loss nieprawidłowy dla SHORT (poniżej entry)",
                "t1_below_price": "Target 1 powyżej aktualnej ceny"
            }
        }
        
        m = msgs.get(lang, msgs["en"])
        
        if direction == "LONG":
            # LONG: targets above entry, stop below entry
            if t1 <= entry_high and t1 > 0:
                issues.append(m["t1_above_entry"])
            if t2 <= t1 and t2 > 0:
                issues.append(m["t2_above_t1"])
            if stop >= entry_low and stop > 0:
                issues.append(m["stop_below_entry"])
            if t1 <= current_price and t1 > 0:
                issues.append(m["t1_above_price"])
                
        elif direction == "SHORT":
            # SHORT: targets below entry, stop above entry
            if t1 >= entry_low and t1 > 0:
                issues.append(m["t1_below_entry"])
            if t2 >= t1 and t2 > 0:
                issues.append(m["t2_below_t1"])
            if stop <= entry_high and stop > 0:
                issues.append(m["stop_above_entry"])
            if t1 >= current_price and t1 > 0:
                issues.append(m["t1_below_price"])
        
        return len(issues) == 0, issues
    
    def validate_sweep_direction_alignment(sweep_expectation, signal_direction, sweep_detected):
        """
        Validates that sweep expectation aligns with signal direction.
        - Sweep below first → should support later LONG reversal (not immediate LONG)
        - Sweep above first → should support later SHORT reversal (not immediate SHORT)
        Returns (is_aligned, reason)
        """
        if not sweep_expectation or sweep_expectation == "N/A" or not sweep_detected:
            return True, "No sweep alignment check needed"
        
        sweep_below = "below" in str(sweep_expectation).lower()
        sweep_above = "above" in str(sweep_expectation).lower()
        
        # If sweep below is expected first, immediate LONG is risky (price may dip first)
        if sweep_below and signal_direction == "LONG":
            return False, "Sweep below atteso prima - LONG immediato rischioso, attendere sweep"
        
        # If sweep above is expected first, immediate SHORT is risky (price may spike first)
        if sweep_above and signal_direction == "SHORT":
            return False, "Sweep above atteso prima - SHORT immediato rischioso, attendere sweep"
        
        return True, "Sweep alignment OK"
    
    def calculate_trade_quality_score(
        direction, rr_ratio, move_percent, 
        whale_confirms, liquidity_path_aligned,
        trap_risk, factors_aligned, total_factors,
        sweep_aligned, directional_consistent
    ):
        """
        Calculates overall trade quality score (0-100).
        Returns (quality_score, quality_level, issues_list)
        
        Quality levels:
        - EXCELLENT: >= 80 (green light)
        - GOOD: 60-79 (proceed with caution)
        - WEAK: 40-59 (confirmation only)
        - POOR: < 40 (NO TRADE)
        """
        score = 0
        issues = []
        
        # Directional consistency (CRITICAL - 25 points)
        if directional_consistent:
            score += 25
        else:
            issues.append("Inconsistenza direzionale nei parametri")
        
        # Risk/Reward (20 points) - v2.9.2: More lenient scoring
        if rr_ratio >= 1.5:
            score += 20
        elif rr_ratio >= 1.2:
            score += 18
        elif rr_ratio >= 1.0:
            score += 15
        elif rr_ratio >= 0.8:
            score += 12  # Acceptable with good quality
        elif rr_ratio >= 0.6:
            score += 8   # Acceptable only with excellent quality
            issues.append(f"R:R basso ({rr_ratio:.2f}) - richiede qualità alta")
        else:
            score += 3   # Very low but don't zero out
            issues.append(f"R:R molto basso ({rr_ratio:.2f})")
        
        # Expected move (15 points) - v2.9.2: More lenient for micro-moves
        abs_move = abs(move_percent)
        if abs_move >= 0.5:
            score += 15
        elif abs_move >= 0.3:
            score += 12
        elif abs_move >= 0.25:
            score += 10
        elif abs_move >= 0.15:
            score += 7  # Still give points for very small high-quality moves
            issues.append(f"Movimento atteso piccolo ({abs_move:.2f}%)")
        else:
            score += 3
            issues.append(f"Movimento troppo piccolo ({abs_move:.2f}%)")
        
        # Whale confirmation (10 points)
        if whale_confirms:
            score += 10
        else:
            issues.append("Whale activity non conferma direzione")
        
        # Liquidity path alignment (10 points)
        if liquidity_path_aligned:
            score += 10
        else:
            issues.append("Liquidità non allineata con direzione")
        
        # Sweep alignment (10 points)
        if sweep_aligned:
            score += 10
        else:
            issues.append("Sweep atteso non allineato con timing segnale")
        
        # Factor alignment (10 points)
        if total_factors > 0:
            alignment_ratio = factors_aligned / total_factors
            score += int(alignment_ratio * 10)
            if alignment_ratio < 0.5:
                issues.append(f"Fattori non allineati ({factors_aligned}/{total_factors})")
        
        # Determine quality level
        if score >= 80:
            quality_level = "EXCELLENT"
        elif score >= 60:
            quality_level = "GOOD"
        elif score >= 40:
            quality_level = "WEAK"
        else:
            quality_level = "POOR"
        
        return score, quality_level, issues
    
    def apply_trade_quality_gate(
        direction, quality_level, quality_score, issues,
        rr_ratio, trap_risk_high, sweep_aligned
    ):
        """
        Final quality gate that determines if signal should be published.
        v2.9.2: Adaptive R:R thresholds based on quality
        Returns (final_direction, final_setup_type, gate_passed, gate_reason)
        """
        # Determine adaptive R:R threshold based on quality
        if quality_level == "EXCELLENT":
            min_rr_threshold = MIN_RISK_REWARD_HIGH_QUALITY  # 0.6
        elif quality_level == "GOOD":
            min_rr_threshold = MIN_RISK_REWARD_GOOD_QUALITY  # 0.8
        else:
            min_rr_threshold = MIN_RISK_REWARD  # 1.0
        
        # POOR quality = always NO TRADE
        if quality_level == "POOR":
            return "NO TRADE", "no_setup", False, f"Quality gate fallito (score: {quality_score}): {', '.join(issues[:2])}"
        
        # Check R:R against adaptive threshold
        if rr_ratio < min_rr_threshold:
            if quality_level == "EXCELLENT":
                # Even excellent quality can't save very low R:R
                return "NO TRADE", "no_setup", False, f"R:R troppo basso ({rr_ratio:.2f}) anche per qualità eccellente (min: {min_rr_threshold})"
            else:
                return "NO TRADE", "no_setup", False, f"R:R ({rr_ratio:.2f}) sotto soglia adattiva ({min_rr_threshold})"
        
        # High trap risk = only block if quality is not EXCELLENT
        if trap_risk_high and quality_level != "EXCELLENT":
            return "NO TRADE", "no_setup", False, "Alto rischio trappola con qualità non eccellente"
        
        # Sweep misalignment - only confirmation for WEAK quality
        if not sweep_aligned and quality_level == "WEAK":
            return direction, "setup_in_confirmation", False, "Sweep non allineato - richiede conferma"
        
        # WEAK quality = confirmation only
        if quality_level == "WEAK":
            return direction, "setup_in_confirmation", False, f"Qualità debole (score: {quality_score}) - richiede conferma"
        
        # GOOD quality with low R:R = confirmation (but not blocked)
        if rr_ratio < 1.0 and quality_level == "GOOD":
            return direction, "setup_in_confirmation", False, f"R:R basso ({rr_ratio:.2f}) con qualità buona - richiede conferma"
        
        # All checks passed
        return direction, None, True, f"Quality gate superato (score: {quality_score})"
    
    score = 0
    factors = {}
    reasoning_parts = []
    warnings = []
    signal_state = "NO_TRADE"  # Initialize signal state
    
    # Organize S/R levels
    supports = sorted([l for l in sr_levels if l.level_type == "support"], key=lambda x: abs(x.distance_percent))
    resistances = sorted([l for l in sr_levels if l.level_type == "resistance"], key=lambda x: abs(x.distance_percent))
    
    # Find obvious stop levels (where most traders place stops)
    obvious_long_stop = supports[0].price if supports else current_price * 0.99
    obvious_short_stop = resistances[0].price if resistances else current_price * 1.01
    
    # Calculate liquidity sweep zones (just beyond obvious stops)
    long_sweep_zone = obvious_long_stop * (1 - LIQUIDITY_SWEEP_BUFFER)  # Below obvious support
    short_sweep_zone = obvious_short_stop * (1 + LIQUIDITY_SWEEP_BUFFER)  # Above obvious resistance
    
    # Safe invalidation levels (beyond sweep zone)
    safe_long_invalidation = supports[1].price * 0.995 if len(supports) > 1 else current_price * 0.975
    safe_short_invalidation = resistances[1].price * 1.005 if len(resistances) > 1 else current_price * 1.025
    
    # ================== LIQUIDITY SWEEP DETECTION ==================
    sweep_detected = False
    sweep_analysis = None
    setup_type = "standard"
    
    # Check for potential liquidity sweep setup
    # A sweep setup occurs when:
    # 1. Price is near a key level (within 0.5%)
    # 2. There's significant liquidity just beyond that level
    # 3. The broader bias suggests reversal after the sweep
    
    nearest_support_dist = abs(supports[0].distance_percent) if supports else 100
    nearest_resistance_dist = abs(resistances[0].distance_percent) if resistances else 100
    
    # Detect if price is approaching liquidity sweep zone
    approaching_support_sweep = nearest_support_dist < 0.5 and supports
    approaching_resistance_sweep = nearest_resistance_dist < 0.5 and resistances
    
    if approaching_support_sweep:
        # Price near support - potential long sweep then reversal up
        support_level = supports[0]
        liquidity_below = sum(c.estimated_value for c in [LiquidityCluster(
            price=support_level.price * 0.99,
            strength="medium",
            distance_percent=-1,
            side="below",
            estimated_value=support_level.volume_at_level or 100000
        )] if hasattr(support_level, 'volume_at_level'))
        
        if market_bias.bias == "BULLISH" and market_bias.confidence >= 60:
            sweep_detected = True
            setup_type = "sweep_reversal"
            sweep_analysis = get_translation("approaching_support", lang, support_level.price, long_sweep_zone, support_level.price)
    
    elif approaching_resistance_sweep:
        # Price near resistance - potential short sweep then reversal down
        resistance_level = resistances[0]
        
        if market_bias.bias == "BEARISH" and market_bias.confidence >= 60:
            sweep_detected = True
            setup_type = "sweep_reversal"
            sweep_analysis = get_translation("approaching_resistance", lang, resistance_level.price, short_sweep_zone, resistance_level.price)
    
    # ================== FACTOR SCORING ==================
    
    # 1. Market Bias Analysis (+/-3)
    bias_score = 0
    if market_bias.bias == "BULLISH":
        bias_score = 3 if market_bias.confidence >= 70 else 2 if market_bias.confidence >= 55 else 1
    elif market_bias.bias == "BEARISH":
        bias_score = -3 if market_bias.confidence >= 70 else -2 if market_bias.confidence >= 55 else -1
    
    score += bias_score
    factors["market_bias"] = {
        "bias": market_bias.bias,
        "confidence": market_bias.confidence,
        "score": bias_score,
        "max": 3
    }
    
    if bias_score > 0:
        reasoning_parts.append(get_translation("market_bias_is", lang, market_bias.bias, market_bias.confidence))
    elif bias_score < 0:
        reasoning_parts.append(get_translation("market_bias_is", lang, market_bias.bias, market_bias.confidence))
    
    # 2. Liquidity Direction (+/-2)
    liq_score = 0
    if liquidity_direction.direction == "UP":
        liq_score = 2 if liquidity_direction.imbalance_ratio > 1.5 else 1
    elif liquidity_direction.direction == "DOWN":
        liq_score = -2 if liquidity_direction.imbalance_ratio < 0.67 else -1
    
    score += liq_score
    factors["liquidity"] = {
        "direction": liquidity_direction.direction,
        "target": liquidity_direction.next_target,
        "imbalance_ratio": liquidity_direction.imbalance_ratio,
        "score": liq_score,
        "max": 2
    }
    
    if liq_score != 0:
        reasoning_parts.append(get_translation("liquidity_points", lang, liquidity_direction.direction, liquidity_direction.next_target))
    
    # 3. Exchange Consensus (+/-2)
    exchange_score = 0
    if exchange_comparison and "exchanges" in exchange_comparison:
        bullish_count = sum(1 for ex in exchange_comparison["exchanges"].values() if ex.get("bias") == "BULLISH")
        bearish_count = sum(1 for ex in exchange_comparison["exchanges"].values() if ex.get("bias") == "BEARISH")
        total = len(exchange_comparison["exchanges"])
        
        if bullish_count >= 2:
            exchange_score = 2 if bullish_count == total else 1
        elif bearish_count >= 2:
            exchange_score = -2 if bearish_count == total else -1
        
        consensus_text = f"{bullish_count}/{total} exchange bullish, {bearish_count}/{total} bearish"
    else:
        consensus_text = "Dati exchange non disponibili"
    
    score += exchange_score
    factors["exchange_consensus"] = {
        "description": consensus_text,
        "score": exchange_score,
        "max": 2
    }
    
    if exchange_score > 0:
        reasoning_parts.append(get_translation("exchange_consensus_bullish", lang, consensus_text))
    elif exchange_score < 0:
        reasoning_parts.append(get_translation("exchange_consensus_bearish", lang, consensus_text))
    
    # 4. Funding Rate (+/-1)
    funding_score = 0
    if funding_rate:
        if funding_rate.sentiment == "bullish":
            funding_score = 1
        elif funding_rate.sentiment == "bearish":
            funding_score = -1
        
        # Overcrowded = potential squeeze = reversal opportunity
        if funding_rate.overcrowded:
            if funding_rate.overcrowded == "longs":
                warnings.append("⚠️ " + get_translation("longs_overcrowded", lang))
                funding_score -= 1
            elif funding_rate.overcrowded == "shorts":
                warnings.append("⚠️ " + get_translation("shorts_overcrowded", lang))
                funding_score += 1
    
    score += funding_score
    factors["funding_rate"] = {
        "rate": funding_rate.current_rate if funding_rate else 0,
        "sentiment": funding_rate.sentiment if funding_rate else "unknown",
        "score": funding_score,
        "max": 1
    }
    
    if funding_score != 0:
        reasoning_parts.append(get_translation("funding_sentiment", lang, funding_rate.sentiment))
    
    # 5. Open Interest Trend (+/-1)
    oi_score = 0
    if open_interest:
        if open_interest.trend == "increasing":
            if score > 0:
                oi_score = 1
                reasoning_parts.append(get_translation("oi_increasing_bullish", lang))
            elif score < 0:
                oi_score = -1
                reasoning_parts.append(get_translation("oi_increasing_bearish", lang))
        elif open_interest.trend == "decreasing":
            if score > 0:
                warnings.append("⚠️ " + get_translation("oi_decreasing_profit", lang))
            elif score < 0:
                warnings.append("⚠️ " + get_translation("oi_decreasing_covering", lang))
    
    score += oi_score
    factors["open_interest"] = {
        "total": open_interest.total_oi if open_interest else 0,
        "trend": open_interest.trend if open_interest else "unknown",
        "change_24h": open_interest.change_24h if open_interest else 0,
        "score": oi_score,
        "max": 1
    }
    
    # 6. Pattern Signals (+/-2)
    pattern_score = 0
    if patterns:
        for pattern in patterns[:2]:
            if pattern.direction == "BULLISH" and pattern.confidence >= 65:
                pattern_score += 1
                reasoning_parts.append(get_translation("pattern_detected", lang, pattern.pattern, "bullish", pattern.confidence))
            elif pattern.direction == "BEARISH" and pattern.confidence >= 65:
                pattern_score -= 1
                reasoning_parts.append(get_translation("pattern_detected", lang, pattern.pattern, "bearish", pattern.confidence))
    
    pattern_score = max(-2, min(2, pattern_score))
    score += pattern_score
    factors["patterns"] = {
        "count": len(patterns),
        "top_pattern": patterns[0].pattern if patterns else None,
        "score": pattern_score,
        "max": 2
    }
    
    # 7. Whale Alerts (+/-1)
    whale_score = 0
    if whale_alerts:
        long_signals = sum(1 for w in whale_alerts if w.signal == "LONG")
        short_signals = sum(1 for w in whale_alerts if w.signal == "SHORT")
        
        if long_signals > short_signals:
            whale_score = 1
            reasoning_parts.append(get_translation("whale_favors_longs", lang, long_signals, short_signals))
        elif short_signals > long_signals:
            whale_score = -1
            reasoning_parts.append(get_translation("whale_favors_shorts", lang, short_signals, long_signals))
    
    score += whale_score
    factors["whale_alerts"] = {
        "count": len(whale_alerts),
        "score": whale_score,
        "max": 1
    }
    
    # 8. WHALE ACTIVITY ENGINE (+/-2) - NEW
    whale_engine_score = 0
    whale_confirms_direction = False
    
    if whale_activity:
        if whale_activity.direction == "BUY" and whale_activity.strength >= 40:
            whale_engine_score = 2 if whale_activity.strength >= 70 else 1
            reasoning_parts.append(get_translation("whale_engine_buy", lang, whale_activity.strength, whale_activity.explanation))
        elif whale_activity.direction == "SELL" and whale_activity.strength >= 40:
            whale_engine_score = -2 if whale_activity.strength >= 70 else -1
            reasoning_parts.append(get_translation("whale_engine_sell", lang, whale_activity.strength, whale_activity.explanation))
        
        # Add specific whale signals as warnings/context
        if whale_activity.volume_spike:
            warnings.append("🐋 " + get_translation("volume_spike", lang, whale_activity.volume_ratio))
        if whale_activity.liquidation_bias == "longs_liquidated":
            warnings.append("🐋 " + get_translation("long_liquidation_cascade", lang))
        elif whale_activity.liquidation_bias == "shorts_liquidated":
            warnings.append("🐋 " + get_translation("short_squeeze_progress", lang))
        if whale_activity.orderbook_aggression:
            if whale_activity.orderbook_aggression == "aggressive_buying":
                warnings.append("🐋 " + get_translation("orderbook_aggressive_buy", lang))
            else:
                warnings.append("🐋 " + get_translation("orderbook_aggressive_sell", lang))
    
    score += whale_engine_score
    factors["whale_engine"] = {
        "direction": whale_activity.direction if whale_activity else "N/A",
        "strength": whale_activity.strength if whale_activity else 0,
        "buy_pressure": whale_activity.buy_pressure if whale_activity else 0,
        "sell_pressure": whale_activity.sell_pressure if whale_activity else 0,
        "score": whale_engine_score,
        "max": 2
    }
    
    # 9. LIQUIDITY LADDER PATH (+/-1) - NEW
    ladder_score = 0
    sweep_first_expected = False
    
    if liquidity_ladder:
        # If ladder shows more attractive liquidity in one direction, that's where price will seek
        if liquidity_ladder.more_attractive_side == "above":
            ladder_score = 1  # Bullish - price seeks upside liquidity
            if liquidity_ladder.major_above:
                reasoning_parts.append(get_translation("ladder_more_above", lang, liquidity_ladder.major_above.price))
            else:
                reasoning_parts.append(get_translation("ladder_favors_upside", lang))
        elif liquidity_ladder.more_attractive_side == "below":
            ladder_score = -1  # Bearish - price seeks downside liquidity
            if liquidity_ladder.major_below:
                reasoning_parts.append(get_translation("ladder_more_below", lang, liquidity_ladder.major_below.price))
            else:
                reasoning_parts.append(get_translation("ladder_favors_downside", lang))
        
        # Determine sweep expectation
        if liquidity_ladder.sweep_expectation == "sweep_below_first":
            sweep_first_expected = True
            if score > 0:  # Currently bullish
                if liquidity_ladder.nearest_below:
                    warnings.append("⚠️ " + get_translation("sweep_expected_down", lang, liquidity_ladder.nearest_below.price))
                else:
                    warnings.append("⚠️ " + get_translation("possible_dip", lang))
        elif liquidity_ladder.sweep_expectation == "sweep_above_first":
            sweep_first_expected = True
            if score < 0:  # Currently bearish
                if liquidity_ladder.nearest_above:
                    warnings.append("⚠️ " + get_translation("sweep_expected_up", lang, liquidity_ladder.nearest_above.price))
                else:
                    warnings.append("⚠️ " + get_translation("possible_spike", lang))
    
    score += ladder_score
    factors["liquidity_ladder"] = {
        "more_attractive_side": liquidity_ladder.more_attractive_side if liquidity_ladder else "N/A",
        "sweep_expectation": liquidity_ladder.sweep_expectation if liquidity_ladder else "N/A",
        "nearest_above": liquidity_ladder.nearest_above.price if liquidity_ladder and liquidity_ladder.nearest_above else None,
        "nearest_below": liquidity_ladder.nearest_below.price if liquidity_ladder and liquidity_ladder.nearest_below else None,
        "score": ladder_score,
        "max": 1
    }
    
    # 10. Trap Risk Assessment
    if market_bias.trap_risk == "high":
        warnings.append("⚠️ " + get_translation("high_trap_risk", lang))
    
    # ================== DETERMINE DIRECTION ==================
    
    # First, check for sweep reversal setup (v1 logic)
    sweep_direction = None
    if score >= 4:
        sweep_direction = "LONG"
    elif score <= -4:
        sweep_direction = "SHORT"
    
    # v2: Also check for trend continuation setup
    continuation_setup = None
    if SIGNAL_ENGINE_VERSION == "v2":
        # Prepare liquidity magnet data for continuation detection
        liq_magnet_data = None
        if liquidity_ladder:
            liq_magnet_data = {
                "target_direction": liquidity_ladder.more_attractive_side.upper() if liquidity_ladder.more_attractive_side else "BALANCED",
                "attraction_score": 60 if liquidity_ladder.more_attractive_side else 50
            }
        
        # Detect trend continuation setup
        continuation_setup = detect_trend_continuation_setup(
            current_price=current_price,
            market_bias=market_bias,
            market_energy=market_energy,
            liquidity_magnet=liq_magnet_data,
            whale_activity=whale_activity,
            sr_levels=sr_levels
        )
        
        # Log continuation detection for debugging
        if continuation_setup.get("is_valid"):
            logger.info(f"[v2] Trend Continuation detected: {continuation_setup.get('direction')} @ {continuation_setup.get('confidence'):.0f}%")
    
    # ================== SELECT BEST SETUP ==================
    # Priority logic when both setups are valid:
    # 1. If only one setup is valid, use it
    # 2. If both valid, compare confidence and market regime
    # 3. Prefer the setup with higher confidence
    
    direction = "NO TRADE"
    
    if sweep_direction and not (continuation_setup and continuation_setup.get("is_valid")):
        # Only sweep reversal is valid
        direction = sweep_direction
        setup_type = "sweep_reversal" if sweep_detected else "standard"
        
    elif not sweep_direction and continuation_setup and continuation_setup.get("is_valid"):
        # Only trend continuation is valid
        direction = continuation_setup["direction"]
        setup_type = "trend_continuation"
        # Add continuation reasoning to the signal
        reasoning_parts.extend(continuation_setup.get("reasoning", []))
        
    elif sweep_direction and continuation_setup and continuation_setup.get("is_valid"):
        # Both setups are valid - choose the better one
        # Calculate sweep reversal confidence for comparison
        sweep_raw_conf = (abs(score) / 12) * 100
        cont_conf = continuation_setup.get("confidence", 0)
        
        # Prefer trend continuation if it has higher confidence (with 5% buffer)
        if cont_conf > sweep_raw_conf + 5:
            direction = continuation_setup["direction"]
            setup_type = "trend_continuation"
            reasoning_parts.extend(continuation_setup.get("reasoning", []))
            reasoning_parts.append(f"[v2] Continuation setup chosen over sweep reversal ({cont_conf:.0f}% vs {sweep_raw_conf:.0f}%)")
        else:
            direction = sweep_direction
            setup_type = "sweep_reversal" if sweep_detected else "standard"
            reasoning_parts.append(f"[v2] Sweep reversal chosen over continuation ({sweep_raw_conf:.0f}% vs {cont_conf:.0f}%)")
    else:
        # No valid setup
        direction = "NO TRADE"
        setup_type = "no_setup"
    
    # ================== CALCULATE TRADE PARAMETERS ==================
    # 4H CALIBRATED TARGETS AND STOPS
    
    # Check if we have strong market conditions for extended targets
    strong_conditions = is_strong_market_condition(market_energy, liquidity_ladder, setup_type)
    
    if direction == "LONG":
        if setup_type == "trend_continuation":
            # TREND CONTINUATION LONG: Tighter entry zone
            entry_zone_low = current_price * 0.998   # Tighter entry
            entry_zone_high = current_price * 1.002
            
            # Stop below recent swing low or nearest support
            stop_loss = supports[0].price * 0.995 if supports else current_price * 0.985
            invalidation_reason = get_translation("continuation_stop", lang) if 'continuation_stop' in BACKEND_TRANSLATIONS.get(lang, {}) else f"Stop below swing low: ${stop_loss:,.0f}"
            
            # 4H CALIBRATED TARGETS for continuation (allowed extended due to trend)
            if strong_conditions:
                # Strong conditions: use extended targets
                t1_pct = TARGET_1_STRONG / 100  # 1.2%
                t2_pct = TARGET_2_STRONG / 100  # 2.5%
            else:
                # Normal conditions: conservative targets
                t1_pct = TARGET_1_MAX / 100  # 0.9%
                t2_pct = TARGET_2_MAX / 100  # 1.8%
            
            target_1 = current_price * (1 + t1_pct)
            target_2 = current_price * (1 + t2_pct)
            
            # Cap targets to S/R levels if they are closer
            if resistances and resistances[0].price < target_1:
                target_1 = resistances[0].price
            if len(resistances) > 1 and resistances[1].price < target_2:
                target_2 = resistances[1].price
            
            # Ensure targets are above entry
            if target_1 <= current_price:
                target_1 = current_price * (1 + TARGET_1_MIN / 100)
            if target_2 <= target_1:
                target_2 = target_1 * 1.005
            
            estimated_move = ((target_1 - current_price) / current_price) * 100
            liquidity_sweep_zone = None  # No sweep expected in continuation
            safe_invalidation = stop_loss
            
        else:
            # SWEEP REVERSAL LONG (original v1 logic with 4H calibration)
            entry_zone_low = supports[0].price if supports else current_price * 0.995
            entry_zone_high = current_price
            
            # SMART STOP LOSS: Beyond the liquidity sweep zone, not at obvious level
            if len(supports) > 1:
                stop_loss = safe_long_invalidation
                invalidation_reason = get_translation("true_invalidation_below", lang, stop_loss, obvious_long_stop)
            else:
                stop_loss = long_sweep_zone * 0.995
                invalidation_reason = get_translation("stop_beyond_sweep_below", lang, stop_loss, long_sweep_zone)
            
            # 4H CALIBRATED TARGETS for sweep reversal
            if strong_conditions:
                # Strong conditions: use extended targets
                t1_pct = TARGET_1_STRONG / 100  # 1.2%
                t2_pct = TARGET_2_STRONG / 100  # 2.5%
            else:
                # Normal 4H conditions: realistic targets
                t1_pct = (TARGET_1_MIN + TARGET_1_MAX) / 2 / 100  # ~0.7%
                t2_pct = (TARGET_2_MIN + TARGET_2_MAX) / 2 / 100  # ~1.4%
            
            target_1 = current_price * (1 + t1_pct)
            target_2 = current_price * (1 + t2_pct)
            
            # Cap targets to S/R levels if they are closer
            if resistances and resistances[0].price < target_1:
                target_1 = resistances[0].price
            if len(resistances) > 1 and resistances[1].price < target_2:
                target_2 = resistances[1].price
            
            # Ensure minimum target distance
            if target_1 <= current_price:
                target_1 = current_price * (1 + TARGET_1_MIN / 100)
            if target_2 <= target_1:
                target_2 = target_1 * 1.005
            
            estimated_move = ((target_1 - current_price) / current_price) * 100
            liquidity_sweep_zone = long_sweep_zone
            safe_invalidation = stop_loss
        
    elif direction == "SHORT":
        if setup_type == "trend_continuation":
            # TREND CONTINUATION SHORT: Tighter entry zone
            entry_zone_low = current_price * 0.998
            entry_zone_high = current_price * 1.002
            
            # Stop above recent swing high or nearest resistance
            stop_loss = resistances[0].price * 1.005 if resistances else current_price * 1.015
            invalidation_reason = get_translation("continuation_stop", lang) if 'continuation_stop' in BACKEND_TRANSLATIONS.get(lang, {}) else f"Stop above swing high: ${stop_loss:,.0f}"
            
            # 4H CALIBRATED TARGETS for continuation (allowed extended due to trend)
            if strong_conditions:
                # Strong conditions: use extended targets
                t1_pct = TARGET_1_STRONG / 100  # 1.2%
                t2_pct = TARGET_2_STRONG / 100  # 2.5%
            else:
                # Normal conditions: conservative targets
                t1_pct = TARGET_1_MAX / 100  # 0.9%
                t2_pct = TARGET_2_MAX / 100  # 1.8%
            
            target_1 = current_price * (1 - t1_pct)
            target_2 = current_price * (1 - t2_pct)
            
            # Cap targets to S/R levels if they are closer
            if supports and supports[0].price > target_1:
                target_1 = supports[0].price
            if len(supports) > 1 and supports[1].price > target_2:
                target_2 = supports[1].price
            
            # Ensure targets are below entry
            if target_1 >= current_price:
                target_1 = current_price * (1 - TARGET_1_MIN / 100)
            if target_2 >= target_1:
                target_2 = target_1 * 0.995
            
            estimated_move = ((target_1 - current_price) / current_price) * 100  # Will be negative for SHORT
            liquidity_sweep_zone = None
            safe_invalidation = stop_loss
            
        else:
            # SWEEP REVERSAL SHORT (original v1 logic with 4H calibration)
            entry_zone_low = current_price
            entry_zone_high = resistances[0].price if resistances else current_price * 1.005
            
            if len(resistances) > 1:
                stop_loss = safe_short_invalidation
                invalidation_reason = get_translation("true_invalidation_above", lang, stop_loss, obvious_short_stop)
            else:
                stop_loss = short_sweep_zone * 1.005
                invalidation_reason = get_translation("stop_beyond_sweep_above", lang, stop_loss, short_sweep_zone)
            
            # 4H CALIBRATED TARGETS for sweep reversal
            if strong_conditions:
                # Strong conditions: use extended targets
                t1_pct = TARGET_1_STRONG / 100  # 1.2%
                t2_pct = TARGET_2_STRONG / 100  # 2.5%
            else:
                # Normal 4H conditions: realistic targets
                t1_pct = (TARGET_1_MIN + TARGET_1_MAX) / 2 / 100  # ~0.7%
                t2_pct = (TARGET_2_MIN + TARGET_2_MAX) / 2 / 100  # ~1.4%
            
            target_1 = current_price * (1 - t1_pct)
            target_2 = current_price * (1 - t2_pct)
            
            # Cap targets to S/R levels if they are closer
            if supports and supports[0].price > target_1:
                target_1 = supports[0].price
            if len(supports) > 1 and supports[1].price > target_2:
                target_2 = supports[1].price
            
            # Ensure minimum target distance
            if target_1 >= current_price:
                target_1 = current_price * (1 - TARGET_1_MIN / 100)
            if target_2 >= target_1:
                target_2 = target_1 * 0.995
            
            estimated_move = ((target_1 - current_price) / current_price) * 100  # Will be negative for SHORT
            liquidity_sweep_zone = short_sweep_zone
            safe_invalidation = stop_loss
        
    else:  # NO TRADE
        entry_zone_low = current_price * 0.99
        entry_zone_high = current_price * 1.01
        stop_loss = 0
        invalidation_reason = get_translation("mixed_signals", lang)
        target_1 = 0
        target_2 = 0
        estimated_move = 0
        liquidity_sweep_zone = None
        safe_invalidation = None
    
    # ================== 4H MINIMUM MOVE FILTER (v2.9.2 - RELAXED) ==================
    # Adaptive thresholds based on setup quality
    # High-quality setups can proceed with smaller moves
    
    no_trade_reason = None
    move_quality = "normal"  # "weak", "normal", "strong", "exceptional"
    high_quality_override = False  # Will be set if all conditions align
    
    if direction != "NO TRADE":
        abs_move = abs(estimated_move)
        
        # Check if this could be a high-quality setup (preliminary check)
        # Full quality check happens later, but we need to know for move filtering
        # Use market_bias directly for preliminary quality assessment
        bias_strong_prelim = market_bias.confidence >= 60 and market_bias.bias in ["BULLISH", "BEARISH"]
        preliminary_quality_high = (
            bias_strong_prelim and 
            whale_confirms_direction and 
            (not any("trappola" in w.lower() or "trap" in w.lower() for w in warnings))
        )
        
        # Determine effective minimum threshold based on quality
        effective_min_move = MINIMUM_MOVE_HIGH_QUALITY if preliminary_quality_high else MINIMUM_MOVE_PERCENT
        
        if abs_move < effective_min_move:
            # Move too small even for high-quality - reject signal
            no_trade_reason = get_translation("move_below_threshold", lang, abs_move, effective_min_move)
            direction = "NO TRADE"
            setup_type = "no_setup"
            warnings.append("⚠️ " + get_translation("move_too_small", lang, abs_move, effective_min_move))
            move_quality = "weak"
        elif abs_move < MINIMUM_MOVE_PERCENT:
            # Move below standard threshold but allowed due to high quality
            high_quality_override = True
            if lang == 'it':
                warnings.append(f"✅ Movimento piccolo ({abs_move:.2f}%) accettato per alta qualità setup")
            else:
                warnings.append(f"✅ Small move ({abs_move:.2f}%) accepted due to high quality setup")
            move_quality = "weak"
        elif abs_move < NORMAL_MOVE_MIN:
            # Move weak but acceptable - add warning, keep in confirmation
            if lang == 'it':
                warnings.append(f"⚠️ Movimento atteso basso ({abs_move:.2f}%) - richiede conferma extra")
            elif lang == 'de':
                warnings.append(f"⚠️ Erwartete Bewegung niedrig ({abs_move:.2f}%) - erfordert extra Bestätigung")
            elif lang == 'pl':
                warnings.append(f"⚠️ Oczekiwany ruch niski ({abs_move:.2f}%) - wymaga dodatkowego potwierdzenia")
            else:
                warnings.append(f"⚠️ Expected move low ({abs_move:.2f}%) - requires extra confirmation")
            move_quality = "weak"
        elif abs_move <= NORMAL_MOVE_MAX:
            # Normal 4H move - ideal
            move_quality = "normal"
        elif abs_move <= EXCEPTIONAL_MOVE_THRESHOLD:
            # Strong move - good setup
            move_quality = "strong"
        else:
            # Exceptional move - cap expectations
            if lang == 'it':
                warnings.append(f"⚠️ Movimento atteso molto alto ({abs_move:.2f}%) - target potrebbero essere ottimistici")
            elif lang == 'de':
                warnings.append(f"⚠️ Erwartete Bewegung sehr hoch ({abs_move:.2f}%) - Ziele könnten optimistisch sein")
            elif lang == 'pl':
                warnings.append(f"⚠️ Oczekiwany ruch bardzo wysoki ({abs_move:.2f}%) - cele mogą być optymistyczne")
            else:
                warnings.append(f"⚠️ Expected move very high ({abs_move:.2f}%) - targets may be optimistic")
            move_quality = "exceptional"
    
    # ================== 4H RISK/REWARD FILTER (v2.9.2 - ADAPTIVE) ==================
    # Adaptive R:R based on quality:
    # - Quality >= 80: Allow R:R >= 0.6
    # - Quality >= 60: Allow R:R >= 0.8
    # - Quality < 60:  Require R:R >= 1.0
    
    if direction != "NO TRADE" and stop_loss > 0:
        risk = abs(current_price - stop_loss)
        reward = abs(target_1 - current_price)
        risk_reward_ratio = reward / risk if risk > 0 else 0
        
        # Note: Actual R:R enforcement happens in Quality Gate with adaptive thresholds
        # Here we just add warnings
        if risk_reward_ratio < MIN_RISK_REWARD_HIGH_QUALITY:
            # Very low R:R - warn regardless of quality
            if lang == 'it':
                warnings.append(f"⚠️ R:R molto basso ({risk_reward_ratio:.2f}) - rischio elevato")
            else:
                warnings.append(f"⚠️ R:R very low ({risk_reward_ratio:.2f}) - high risk")
        elif risk_reward_ratio < MIN_RISK_REWARD:
            # Low R:R - may be acceptable if quality high
            if lang == 'it':
                warnings.append(f"⚠️ R:R basso ({risk_reward_ratio:.2f}) - accettabile solo con alta qualità")
            else:
                warnings.append(f"⚠️ R:R low ({risk_reward_ratio:.2f}) - acceptable only with high quality")
        elif risk_reward_ratio < GOOD_RISK_REWARD:
            if lang == 'it':
                warnings.append(f"⚠️ R:R moderato ({risk_reward_ratio:.2f}) - ideale >= {GOOD_RISK_REWARD}")
            else:
                warnings.append(f"⚠️ R:R moderate ({risk_reward_ratio:.2f}) - ideal >= {GOOD_RISK_REWARD}")
    else:
        risk_reward_ratio = 0
    
    # ================== TRADE QUALITY GATE ==================
    # Final validation before publishing signal
    
    quality_gate_passed = True
    quality_gate_reason = ""
    quality_score = 100
    quality_level = "EXCELLENT"
    
    if direction != "NO TRADE":
        # 1. Validate directional consistency
        dir_consistent, dir_issues = validate_directional_consistency(
            direction, entry_zone_low, entry_zone_high, stop_loss, target_1, target_2, current_price, lang
        )
        
        if not dir_consistent:
            for issue in dir_issues:
                warnings.append(f"⚠️ {issue}")
            logger.warning(f"[QUALITY GATE] Directional inconsistency: {dir_issues}")
        
        # 2. Validate sweep-direction alignment
        sweep_expectation = liquidity_ladder.sweep_expectation if liquidity_ladder else None
        sweep_aligned, sweep_align_reason = validate_sweep_direction_alignment(
            sweep_expectation, direction, sweep_detected
        )
        
        if not sweep_aligned:
            warnings.append(f"⚠️ {sweep_align_reason}")
            logger.info(f"[QUALITY GATE] Sweep alignment issue: {sweep_align_reason}")
        
        # 3. Check whale confirmation
        whale_confirms_dir = whale_confirms_direction if 'whale_confirms_direction' in dir() else False
        
        # 4. Check liquidity path alignment
        liq_path_aligned = True
        if liquidity_direction:
            if direction == "LONG" and liquidity_direction.direction == "DOWN":
                liq_path_aligned = False
            elif direction == "SHORT" and liquidity_direction.direction == "UP":
                liq_path_aligned = False
        
        # 5. Check trap risk
        trap_risk_high = any("trappola" in w.lower() or "trap" in w.lower() for w in warnings)
        
        # 6. Calculate aligned factors
        aligned_factors = sum(1 for f in factors.values() if isinstance(f, dict) and f.get("score", 0) * score > 0)
        total_factors = len([f for f in factors.values() if isinstance(f, dict) and f.get("score", 0) != 0])
        
        # 7. Calculate quality score
        quality_score, quality_level, quality_issues = calculate_trade_quality_score(
            direction=direction,
            rr_ratio=risk_reward_ratio,
            move_percent=estimated_move,
            whale_confirms=whale_confirms_dir,
            liquidity_path_aligned=liq_path_aligned,
            trap_risk=trap_risk_high,
            factors_aligned=aligned_factors,
            total_factors=total_factors,
            sweep_aligned=sweep_aligned,
            directional_consistent=dir_consistent
        )
        
        # 8. Apply quality gate
        final_direction, gate_setup_type, quality_gate_passed, quality_gate_reason = apply_trade_quality_gate(
            direction=direction,
            quality_level=quality_level,
            quality_score=quality_score,
            issues=quality_issues,
            rr_ratio=risk_reward_ratio,
            trap_risk_high=trap_risk_high,
            sweep_aligned=sweep_aligned
        )
        
        # Apply gate decisions
        if not quality_gate_passed:
            if final_direction == "NO TRADE":
                direction = "NO TRADE"
                setup_type = "no_setup"
                no_trade_reason = quality_gate_reason
            elif gate_setup_type == "setup_in_confirmation":
                # Keep direction but mark as needing confirmation
                setup_type = gate_setup_type
                warnings.append(f"🔄 {quality_gate_reason}")
            
            logger.info(f"[QUALITY GATE] {quality_gate_reason} (score: {quality_score}, level: {quality_level})")
        else:
            logger.info(f"[QUALITY GATE] PASSED - score: {quality_score}, level: {quality_level}")
        
        # Add quality info to reasoning
        reasoning_parts.append(f"Quality Score: {quality_score}/100 ({quality_level})")
    
    # ================== CALCULATE CONFIDENCE ==================
    
    max_score = 12
    raw_confidence = (abs(score) / max_score) * 100
    
    aligned_factors = sum(1 for f in factors.values() if isinstance(f, dict) and f.get("score", 0) * score > 0)
    total_factors = len([f for f in factors.values() if isinstance(f, dict) and f.get("score", 0) != 0])
    
    if total_factors > 0:
        alignment_bonus = (aligned_factors / total_factors) * 15
        confidence = min(95, raw_confidence + alignment_bonus)
    else:
        confidence = raw_confidence
    
    # Adjust confidence for sweep setups (higher confidence if sweep + reversal confirmed)
    if sweep_detected and setup_type == "sweep_reversal":
        confidence = min(95, confidence + 5)  # Bonus for recognizing sweep pattern
    
    # ================== MARKET ENERGY INTEGRATION ==================
    energy_context = None
    
    if market_energy:
        # Adjust confidence based on market energy
        if market_energy.compression_level == "HIGH" and market_energy.breakout_probability == "HIGH":
            if direction != "NO TRADE":
                confidence = min(95, confidence + 10)  # High energy boosts confidence
                energy_context = get_translation("energy_boosts_confidence", lang)
                warnings.append(f"⚡ {get_translation('high_energy_expansion', lang, market_energy.energy_score)}")
            else:
                # High energy but no trade = wait for direction confirmation
                warnings.append(f"⚡ {get_translation('high_energy_wait', lang, market_energy.energy_score)}")
                
        elif market_energy.compression_level == "LOW" and market_energy.breakout_probability == "LOW":
            if direction != "NO TRADE":
                confidence = max(40, confidence - 10)  # Low energy reduces confidence
                energy_context = get_translation("energy_reduces_confidence", lang)
                warnings.append(f"💤 {get_translation('low_energy_caution', lang)}")
        
        # If compression is high with liquidity on both sides - expansion warning
        if market_energy.expansion_warning:
            if direction != "NO TRADE":
                reasoning_parts.append(get_translation("expansion_likely_direction", lang, market_energy.expected_direction or "UNCLEAR"))
            else:
                warnings.append(f"⚡ {get_translation('expansion_likely_no_direction', lang)}")
    
    # ================== LIQUIDITY MAGNET INTEGRATION ==================
    # Note: Liquidity Magnet is calculated inline here since we have all the data
    # This provides directional context based on liquidity attraction
    
    magnet_context = None
    
    if liquidity_ladder:
        # Use liquidity ladder data to determine magnet effect
        more_attractive = liquidity_ladder.more_attractive_side
        
        if more_attractive == "above":
            # Strong upward magnet
            if direction == "LONG":
                confidence = min(95, confidence + 5)  # Aligns with direction
                magnet_context = get_translation("magnet_bullish_contribution", lang)
            elif direction == "SHORT":
                confidence = max(35, confidence - 5)  # Contradicts direction
                warnings.append("🧲 Liquidity magnet suggests upward pressure")
        elif more_attractive == "below":
            # Strong downward magnet
            if direction == "SHORT":
                confidence = min(95, confidence + 5)  # Aligns with direction
                magnet_context = get_translation("magnet_bearish_contribution", lang)
            elif direction == "LONG":
                confidence = max(35, confidence - 5)  # Contradicts direction
                warnings.append("🧲 Liquidity magnet suggests downward pressure")
        # balanced = no adjustment
        
        if magnet_context:
            reasoning_parts.append(magnet_context)
    
    # ================== CONFLICT HANDLING ==================
    # Be more conservative when indicators conflict
    # HIGH Energy + BALANCED Magnet + NEUTRAL Whale = Uncertainty -> prefer NO TRADE or SETUP_IN_CONFIRMATION
    
    conflict_detected = False
    
    if market_energy and liquidity_ladder and whale_activity:
        energy_is_high = market_energy.compression_level == "HIGH" or market_energy.energy_score >= 60
        magnet_is_balanced = liquidity_ladder.more_attractive_side == "balanced"
        whale_is_neutral = whale_activity.direction == "NEUTRAL" or whale_activity.strength < 30
        
        if energy_is_high and magnet_is_balanced and whale_is_neutral:
            conflict_detected = True
            
            if direction in ["LONG", "SHORT"]:
                # Downgrade active signal to SETUP_IN_CONFIRMATION or reduce confidence significantly
                if signal_state == "OPERATIONAL":
                    signal_state = "SETUP_IN_CONFIRMATION"
                    warnings.append(f"⚠️ {get_translation('conflict_high_energy_no_direction', lang)}")
                
                # Reduce confidence significantly due to conflict
                confidence = max(35, confidence - 15)
                reasoning_parts.append(get_translation("conflict_conservative_mode", lang))
            
            elif direction == "NO TRADE":
                # Reinforce NO TRADE decision
                warnings.append(f"⚠️ {get_translation('conflict_wait_for_clarity', lang)}")
    
    if direction == "NO TRADE":
        confidence = max(30, 60 - abs(score) * 5)
    
    # ================== BUILD REASONING TEXT ==================
    
    if direction == "NO TRADE":
        if no_trade_reason:
            reasoning = f"⚠️ {get_translation('no_trade_insufficient', lang)}\n\n{no_trade_reason}\n\n"
        else:
            reasoning = f"⚠️ {get_translation('mixed_signals_no_setup', lang)}\n\n"
        
        reasoning += f"{get_translation('factors_not_aligned', lang)}\n"
        for part in reasoning_parts:
            reasoning += f"• {part}\n"
        
        if sweep_analysis:
            reasoning += f"\n📊 {sweep_analysis}\n"
        
        reasoning += f"\n{get_translation('wait_clearer_bias', lang)}"
        
    else:
        dir_emoji = "🟢" if direction == "LONG" else "🔴"
        
        if setup_type == "sweep_reversal":
            reasoning = f"{dir_emoji} {direction} - {get_translation('sweep_reversal_setup', lang)}\n\n"
        else:
            reasoning = f"{dir_emoji} {direction} - {get_translation('continuation_setup', lang)}\n\n"
        
        # Move size assessment
        if abs(estimated_move) >= 2.0:
            reasoning += f"✅ {get_translation('large_move_potential', lang, abs(estimated_move))}\n\n"
        elif abs(estimated_move) >= 1.0:
            reasoning += f"✅ {get_translation('decent_move_potential', lang, abs(estimated_move))}\n\n"
        else:
            reasoning += f"⚠️ {get_translation('small_move', lang, abs(estimated_move), MINIMUM_MOVE_PERCENT)}\n\n"
        
        reasoning += f"{get_translation('key_factors', lang)}\n"
        for part in reasoning_parts:
            reasoning += f"• {part}\n"
        
        # Liquidity sweep context
        reasoning += f"\n📊 {get_translation('liquidity_stop_placement', lang)}\n"
        if direction == "LONG":
            reasoning += f"• {get_translation('obvious_stop_zone', lang, long_sweep_zone)}\n"
            reasoning += f"• {get_translation('safe_invalidation', lang, safe_long_invalidation)}\n"
            reasoning += f"• {get_translation('stop_placed_at', lang, stop_loss)}\n"
        else:
            reasoning += f"• {get_translation('obvious_stop_zone_above', lang, short_sweep_zone)}\n"
            reasoning += f"• {get_translation('safe_invalidation', lang, safe_short_invalidation)}\n"
            reasoning += f"• {get_translation('stop_placed_at', lang, stop_loss)}\n"
        
        if sweep_analysis:
            reasoning += f"\n🔄 {get_translation('sweep_analysis', lang)}\n{sweep_analysis}\n"
        
        # Add liquidity ladder path analysis
        if liquidity_ladder and liquidity_ladder.path_analysis:
            reasoning += f"\n🪜 {get_translation('liquidity_path', lang)}\n{liquidity_ladder.path_analysis}\n"
        
        # Add whale activity summary
        if whale_activity and whale_activity.direction != "NEUTRAL":
            reasoning += f"\n🐋 {get_translation('whale_activity_section', lang)}\n{whale_activity.explanation}\n"
        
        if warnings:
            reasoning += f"\n⚠️ {get_translation('risk_warnings', lang)}\n"
            for warning in warnings:
                reasoning += f"{warning}\n"
        
        reasoning += f"\n📈 Risk/Reward: {risk_reward_ratio:.1f}:1"
    
    # Check if whale confirms direction
    if whale_activity:
        if direction == "LONG" and whale_activity.direction == "BUY":
            whale_confirms_direction = True
        elif direction == "SHORT" and whale_activity.direction == "SELL":
            whale_confirms_direction = True
    
    # Build whale activity summary for response
    whale_activity_summary = None
    if whale_activity:
        whale_activity_summary = {
            "direction": whale_activity.direction,
            "strength": whale_activity.strength,
            "confidence": whale_activity.confidence,
            "explanation": whale_activity.explanation,
            "volume_spike": whale_activity.volume_spike,
            "volume_ratio": whale_activity.volume_ratio,
            "buy_pressure": whale_activity.buy_pressure,
            "sell_pressure": whale_activity.sell_pressure,
            "liquidation_bias": whale_activity.liquidation_bias,
            "orderbook_aggression": whale_activity.orderbook_aggression,
            "signals": whale_activity.signals
        }
    
    # Build liquidity ladder summary for response
    liquidity_ladder_summary = None
    if liquidity_ladder:
        liquidity_ladder_summary = {
            "current_price": liquidity_ladder.current_price,
            "more_attractive_side": liquidity_ladder.more_attractive_side,
            "sweep_expectation": liquidity_ladder.sweep_expectation,
            "path_analysis": liquidity_ladder.path_analysis,
            "nearest_above": {
                "price": liquidity_ladder.nearest_above.price,
                "distance_percent": liquidity_ladder.nearest_above.distance_percent,
                "strength": liquidity_ladder.nearest_above.strength,
                "type": liquidity_ladder.nearest_above.type
            } if liquidity_ladder.nearest_above else None,
            "nearest_below": {
                "price": liquidity_ladder.nearest_below.price,
                "distance_percent": liquidity_ladder.nearest_below.distance_percent,
                "strength": liquidity_ladder.nearest_below.strength,
                "type": liquidity_ladder.nearest_below.type
            } if liquidity_ladder.nearest_below else None,
            "major_above": {
                "price": liquidity_ladder.major_above.price,
                "strength": liquidity_ladder.major_above.strength
            } if liquidity_ladder.major_above else None,
            "major_below": {
                "price": liquidity_ladder.major_below.price,
                "strength": liquidity_ladder.major_below.strength
            } if liquidity_ladder.major_below else None,
            "levels_above_count": len(liquidity_ladder.ladder_above),
            "levels_below_count": len(liquidity_ladder.ladder_below)
        }
    
    # ================== DYNAMIC SIGNAL TIMING ==================
    # Calculate urgency, validity window, and setup status
    timing = calculate_signal_timing(
        direction=direction,
        confidence=confidence,
        current_price=current_price,
        entry_zone_low=entry_zone_low,
        entry_zone_high=entry_zone_high,
        setup_type=setup_type,
        market_energy=market_energy,
        liquidity_magnet=liquidity_ladder,  # Using liquidity_ladder as magnet proxy
        whale_activity=whale_activity,
        signal_state=signal_state,
        lang=lang
    )
    
    # Add timing info to reasoning for active signals
    if direction != "NO TRADE":
        urgency_emoji = "🔥" if timing["signal_urgency"] == "HIGH" else "⏱️" if timing["signal_urgency"] == "MEDIUM" else "⌛"
        reasoning += f"\n{urgency_emoji} {get_translation('urgency_' + timing['signal_urgency'].lower() + ('_act_fast' if timing['signal_urgency'] == 'HIGH' else '_good_window' if timing['signal_urgency'] == 'MEDIUM' else '_time_available'), lang)}\n"
        reasoning += f"• {get_translation('valid_for', lang)}: {timing['valid_for_minutes']} min\n"
        reasoning += f"• {timing['urgency_reason']}\n"
    
    # ================== MARKET REGIME DETECTION ==================
    # Detect market regime for context (does NOT change signal logic)
    market_regime_data = None
    
    try:
        # Check for trap risk in warnings
        trap_risk_detected = any("trappola" in w.lower() or "trap" in w.lower() for w in warnings)
        
        # Get OI data
        oi_data = {
            "change_1h": open_interest.change_1h if open_interest else 0,
            "change_24h": open_interest.change_24h if open_interest else 0
        }
        
        market_regime = detect_market_regime(
            market_bias=market_bias,
            market_energy=market_energy,
            liquidity_magnet=liquidity_magnet,
            liquidity_ladder=liquidity_ladder,
            whale_activity=whale_activity,
            open_interest_data=oi_data,
            expected_move=estimated_move,
            trap_risk_detected=trap_risk_detected,
            current_price=current_price,
            supports=supports,
            resistances=resistances,
            lang=lang
        )
        
        # Convert to dict for JSON response
        market_regime_data = {
            "regime": market_regime.regime,
            "regime_strength": market_regime.regime_strength,
            "directional_bias": market_regime.directional_bias,
            "suggested_setup": market_regime.suggested_setup,
            "setup_explanation": market_regime.setup_explanation,
            "trend_score": market_regime.trend_score,
            "range_score": market_regime.range_score,
            "compression_score": market_regime.compression_score,
            "expansion_score": market_regime.expansion_score,
            "bias_alignment": market_regime.bias_alignment,
            "whale_alignment": market_regime.whale_alignment,
            "liquidity_alignment": market_regime.liquidity_alignment,
            "energy_state": market_regime.energy_state,
            "oi_supportive": market_regime.oi_supportive,
            "trap_risk": market_regime.trap_risk,
            "distance_to_sr": market_regime.distance_to_sr,
            "signals": market_regime.signals,
            "explanation": market_regime.explanation
        }
    except Exception as regime_err:
        logger.warning(f"Market regime detection failed: {regime_err}")
        market_regime_data = None
    
    return TradeSignal(
        direction=direction,
        confidence=round(confidence, 1),
        estimated_move=round(estimated_move, 2),
        entry_zone_low=round(entry_zone_low, 2),
        entry_zone_high=round(entry_zone_high, 2),
        stop_loss=round(stop_loss, 2),
        invalidation_reason=invalidation_reason,
        target_1=round(target_1, 2),
        target_2=round(target_2, 2),
        risk_reward_ratio=round(risk_reward_ratio, 2),
        reasoning=reasoning,
        factors=factors,
        timestamp=datetime.now(timezone.utc),
        valid_for="4H",
        warnings=warnings,
        setup_type=setup_type,
        signal_engine_version="v2",  # Current engine version
        liquidity_sweep_zone=round(liquidity_sweep_zone, 2) if liquidity_sweep_zone else None,
        safe_invalidation=round(safe_invalidation, 2) if safe_invalidation else None,
        sweep_detected=sweep_detected,
        sweep_analysis=sweep_analysis,
        whale_activity=whale_activity_summary,
        liquidity_ladder_summary=liquidity_ladder_summary,
        sweep_first_expected=sweep_first_expected,
        whale_confirms_direction=whale_confirms_direction,
        # NEW v2.3: Dynamic Signal Timing
        signal_urgency=timing["signal_urgency"],
        valid_for_minutes=timing["valid_for_minutes"],
        setup_status=timing["setup_status"],
        urgency_reason=timing["urgency_reason"],
        entry_distance_percent=timing["entry_distance_percent"],
        time_sensitivity=timing["time_sensitivity"],
        # NEW v2.7: Trade Quality Gate
        quality_score=quality_score,
        quality_level=quality_level,
        quality_gate_passed=quality_gate_passed,
        # NEW v2.9: Market Regime
        market_regime=market_regime_data,
        # NEW v3.0.1: Data Freshness - Transparent data integrity
        data_freshness=get_all_data_freshness()
    )

