@api_router.get("/v3/signal-lock-status")
async def get_v3_signal_lock_status():
    """
    Get current same-direction signal lock status.
    
    Shows which directions are currently LOCKED due to open signals.
    A direction is LOCKED if there's an OPEN signal in that direction.
    
    OPEN statuses (trade still active, blocks new signals):
      - ENTRY_READY, ACTIVE, PENDING, T1_HIT_WAITING_T2, PARTIAL_WIN
    
    CLOSED statuses (trade complete, unlocks direction):
      - WIN, LOSS, EXPIRED, CANCELLED, FULL_WIN
    
    NOTE: PARTIAL_WIN = T1 hit but still holding for T2 = STILL OPEN
    """
    OPEN_SIGNAL_STATUSES = ["ENTRY_READY", "ACTIVE", "PENDING", "T1_HIT_WAITING_T2", "PARTIAL_WIN"]
    CLOSED_SIGNAL_STATUSES = ["WIN", "LOSS", "EXPIRED", "CANCELLED", "FULL_WIN"]
    
    # Check for open LONG signal
    open_long = await signal_history_collection.find_one({
        "signal_engine_version": "v3",
        "direction": "LONG",
        "outcome": {"$in": OPEN_SIGNAL_STATUSES}
    }, sort=[("timestamp", -1)])
    
    # Check for open SHORT signal
    open_short = await signal_history_collection.find_one({
        "signal_engine_version": "v3",
        "direction": "SHORT",
        "outcome": {"$in": OPEN_SIGNAL_STATUSES}
    }, sort=[("timestamp", -1)])
    
    # Build lock status
    long_locked = open_long is not None
    short_locked = open_short is not None
    
    result = {
        "long_locked": long_locked,
        "short_locked": short_locked,
        "open_statuses": OPEN_SIGNAL_STATUSES,
        "closed_statuses": CLOSED_SIGNAL_STATUSES,
        "open_signals": {
            "LONG": {
                "locked": long_locked,
                "signal_id": open_long.get("signal_id")[:8] if open_long else None,
                "outcome": open_long.get("outcome") if open_long else None,
                "timestamp": str(open_long.get("timestamp")) if open_long else None,
                "entry_price": open_long.get("btc_price") if open_long else None
            } if long_locked else None,
            "SHORT": {
                "locked": short_locked,
                "signal_id": open_short.get("signal_id")[:8] if open_short else None,
                "outcome": open_short.get("outcome") if open_short else None,
                "timestamp": str(open_short.get("timestamp")) if open_short else None,
                "entry_price": open_short.get("btc_price") if open_short else None
            } if short_locked else None
        },
        "can_generate": {
            "LONG": not long_locked,
            "SHORT": not short_locked
        },
        "note": "New signals in locked directions will be blocked and logged as SAME_DIRECTION_LOCKED"
    }
    
    return result


@api_router.post("/v3/close-signal/{signal_id}")
async def close_v3_signal(signal_id: str, outcome: str = Query(..., description="WIN, LOSS, EXPIRED, or CANCELLED")):
    """
    Manually close/update a V3 signal outcome.
    
    This unlocks the direction for new signals.
    
    Valid outcomes: WIN, LOSS, EXPIRED, CANCELLED, PARTIAL_WIN, FULL_WIN
    """
    VALID_CLOSED_OUTCOMES = ["WIN", "LOSS", "EXPIRED", "CANCELLED", "PARTIAL_WIN", "FULL_WIN"]
    
    if outcome not in VALID_CLOSED_OUTCOMES:
        return {"error": f"Invalid outcome. Must be one of: {VALID_CLOSED_OUTCOMES}"}
    
    # Find the signal
    signal = await signal_history_collection.find_one({"signal_id": signal_id})
    
    if not signal:
        # Try partial match
        signal = await signal_history_collection.find_one({"signal_id": {"$regex": f"^{signal_id}"}})
    
    if not signal:
        return {"error": f"Signal not found: {signal_id}"}
    
    old_outcome = signal.get("outcome")
    direction = signal.get("direction")
    
    # Update the signal
    result = await signal_history_collection.update_one(
        {"signal_id": signal.get("signal_id")},
        {"$set": {
            "outcome": outcome,
            "outcome_timestamp": datetime.now(timezone.utc),
            "outcome_notes": f"Manually closed from {old_outcome} to {outcome}"
        }}
    )
    
    if result.modified_count > 0:
        logger.info(f"[V3 Signal] Manually closed signal {signal_id[:8]} - {direction}: {old_outcome} → {outcome}")
        return {
            "success": True,
            "signal_id": signal.get("signal_id"),
            "direction": direction,
            "old_outcome": old_outcome,
            "new_outcome": outcome,
            "direction_now_unlocked": True
        }
    
    return {"error": "Failed to update signal"}


@api_router.get("/v3/shadow-tracking-status")
async def get_shadow_tracking_status():
    """
    Get REAL-TIME status of shadow outcome tracking system.
    
    Shows:
    - Active signals being tracked in memory
    - Current tracking loop status
    - Recent price checks
    - Performance of tracking system
    """
    global active_shadow_tracking, shadow_tracking_task
    
    now = datetime.now(timezone.utc)
    
    # Get all active tracking data
    active_signals = []
    for sig_id, tracking in active_shadow_tracking.items():
        created = tracking.get("created_at")
        if created and created.tzinfo is None:
            created = created.replace(tzinfo=timezone.utc)
        age_seconds = (now - created).total_seconds() if created else 0
        
        # Calculate current MFE/MAE
        entry = tracking.get("entry_price", 0)
        direction = tracking.get("direction", "LONG")
        max_fav = tracking.get("max_favorable_price", entry)
        max_adv = tracking.get("max_adverse_price", entry)
        
        if direction == "LONG" and entry:
            current_mfe = ((max_fav - entry) / entry) * 100
            current_mae = ((max_adv - entry) / entry) * 100
        elif entry:
            current_mfe = ((entry - max_fav) / entry) * 100
            current_mae = ((entry - max_adv) / entry) * 100
        else:
            current_mfe = 0
            current_mae = 0
        
        active_signals.append({
            "signal_id": sig_id,
            "direction": direction,
            "entry_price": round(entry, 2),
            "stop_loss": round(tracking.get("stop_loss", 0), 2),
            "target_1": round(tracking.get("target_1", 0), 2),
            "target_2": round(tracking.get("target_2", 0), 2),
            "age_minutes": round(age_seconds / 60, 1),
            "price_checks": tracking.get("price_checks", 0),
            "t1_hit": tracking.get("target_1_hit", False),
            "t2_hit": tracking.get("target_2_hit", False),
            "stop_hit": tracking.get("stop_hit", False),
            "current_mfe_pct": round(current_mfe, 2),
            "current_mae_pct": round(current_mae, 2),
            "max_favorable_price": round(max_fav, 2),
            "max_adverse_price": round(max_adv, 2),
            "outcome": tracking.get("outcome", "PENDING")
        })
    
    # Check tracking loop status
    loop_running = shadow_tracking_task is not None and not shadow_tracking_task.done()
    
    # Get validated count from DB
    validated_count = await db["shadow_liquidity_targets"].count_documents({"validation.status": "completed"})
    pending_count = await db["shadow_liquidity_targets"].count_documents({"validation.status": "pending"})
    
    return {
        "status": "ACTIVE" if loop_running else "STOPPED",
        "tracking_loop_running": loop_running,
        "check_interval_seconds": 10,
        "expiry_hours": 4,
        
        "active_tracking": {
            "count": len(active_signals),
            "signals": active_signals
        },
        
        "database_status": {
            "validated_signals": validated_count,
            "pending_signals": pending_count
        },
        
        "note": "Tracking loop checks price every 10 seconds. Signals expire after 4 hours without outcome."
    }


