@dataclass
class BacktestConfig:
    """Configuration for a backtest run"""
    symbol: str = "BTCUSD"
    date_from: str = ""  # ISO format
    date_to: str = ""    # ISO format
    engine_version: str = "v3.5.1"
    v34_validation_enabled: bool = True
    v35_contrarian_enabled: bool = True
    
    # Data sources
    ohlc_source: str = "kraken"  # Primary OHLC source
    use_coinglass_historical: bool = False  # When available
    multi_exchange_context: bool = False    # Aggregate from multiple exchanges
    
    # Timeframes
    context_timeframe: str = "4H"
    trigger_timeframe: str = "5M"
    
    # Expiry settings
    setup_expiry_candles_4h: int = 6  # Max 4H candles to wait for trigger
    signal_expiry_candles_5m: int = 24  # Max 5M candles after entry ready
    
    # ═══════════════════════════════════════════════════════════════════════════
    # BACKTEST DEBUG MODES (do NOT affect production)
    # ═══════════════════════════════════════════════════════════════════════════
    
    # NORMAL: Use exact same 5M confirmation logic as production
    # RELAXED: Loosen 5M trigger conditions (more signals for analysis)
    # FORCE_ENTRY: Bypass 5M confirmation entirely (test 4H setup edge)
    confirmation_mode: str = "NORMAL"  # NORMAL | RELAXED | FORCE_ENTRY
    
    # Debug logging for confirmation analysis
    debug_confirmation: bool = False  # Log detailed 5M confirmation attempts
    
    # Disable R:R filter to analyze actual price behavior
    # When True, signals are NOT blocked for low R:R - allows MFE/MAE analysis
    disable_rr_filter: bool = False
    
    # Track all signals regardless of validation (for edge analysis)
    track_all_signals: bool = False
    
    # ═══════════════════════════════════════════════════════════════════════════
    # EXPERIMENTAL STOP MODEL (for stop optimization testing)
    # ═══════════════════════════════════════════════════════════════════════════
    
    # Stop model: ORIGINAL | MAE_CONSERVATIVE | MAE_BALANCED | MAE_AGGRESSIVE | CUSTOM
    stop_model: str = "ORIGINAL"
    
    # Custom stop parameters (when stop_model = "CUSTOM")
    custom_stop_pct: float = 1.0  # Fixed percentage stop
    
    # MAE-based stop parameters
    mae_percentile: float = 75.0  # Percentile to use (50, 75, 90, 95)
    mae_safety_buffer: float = 0.1  # Additional buffer on top of MAE percentile


# MAE percentile data (calibrated from 90-day backtest analysis 2026-04-16)
# Based on 99 signals from Jan 15 - Apr 15 2026
# Structure: {direction: {regime: {setup_type: {percentile: value}}}}
MAE_PERCENTILE_DATA = {
    "LONG": {
        "default": {
            "default": {
                "50": 0.27,   # 50th percentile MAE for LONG
                "75": 0.95,   # 75th percentile
                "90": 1.61,   # 90th percentile (interpolated)
                "95": 1.88    # 95th percentile
            }
        }
    },
    "SHORT": {
        "default": {
            "default": {
                "50": 0.56,   # 50th percentile MAE for SHORT
                "75": 1.03,   # 75th percentile
                "90": 2.20,   # 90th percentile (interpolated)
                "95": 2.59    # 95th percentile
            }
        }
    },
    # Overall (for when direction is unknown)
    "default": {
        "default": {
            "default": {
                "50": 0.48,
                "75": 0.95,
                "90": 1.61,
                "95": 2.59
            }
        }
    }
}

# Updated stop model presets based on real data
# Old values were too aggressive (based on 14 signals)
STOP_MODEL_PRESETS = {
    "MAE_CONSERVATIVE": {"percentile": 95, "buffer": 0.20},  # 95th + 0.20% = ~2.8% (safe)
    "MAE_BALANCED": {"percentile": 75, "buffer": 0.15},      # 75th + 0.15% = ~1.1% (balanced)
    "MAE_AGGRESSIVE": {"percentile": 50, "buffer": 0.10}     # 50th + 0.10% = ~0.6% (risky)
}


def get_mae_based_stop(
    direction: str,
    entry_price: float,
    regime: str = "default",
    setup_type: str = "default",
    percentile: float = 75.0,
    safety_buffer: float = 0.15
) -> Dict[str, Any]:
    """
    Calculate stop loss based on historical MAE distribution.
    
    CALIBRATED DATA (90-day backtest, 99 signals, 2026-04-16):
    
    Overall MAE Distribution:
    - P50: 0.48%  (50% of trades have MAE ≤ this)
    - P75: 0.95%  (75% of trades have MAE ≤ this)
    - P90: 1.61%  (90% of trades have MAE ≤ this)
    - P95: 2.59%  (95% of trades have MAE ≤ this)
    - Max: 6.44%  (worst case, LONG direction)
    
    By Direction:
    - LONG: P50=0.27%, P75=0.95%, P95=1.88%, Max=6.44%
    - SHORT: P50=0.56%, P75=1.03%, P95=2.59%, Max=2.76%
    
    Recommended stops (with safety buffer):
    - Conservative (P95): 2.59% + 0.20% = 2.79% (5% stop hit rate)
    - Balanced (P75): 0.95% + 0.15% = 1.10% (25% stop hit rate)
    - Aggressive (P50): 0.48% + 0.10% = 0.58% (50% stop hit rate)
    
    Note: LONG positions have higher tail risk (max 6.44% MAE)
    """
    # Get base direction
    dir_key = direction.replace("CONTRARIAN_", "")
    
    # Look up MAE percentile data (with fallbacks)
    dir_data = MAE_PERCENTILE_DATA.get(dir_key, MAE_PERCENTILE_DATA.get("LONG"))
    regime_data = dir_data.get(regime, dir_data.get("default"))
    setup_data = regime_data.get(setup_type, regime_data.get("default"))
    
    # Get percentile value
    percentile_key = str(int(percentile))
    mae_pct = setup_data.get(percentile_key, setup_data.get("75", 0.25))
    
    # Calculate stop with safety buffer
    total_stop_pct = mae_pct + safety_buffer
    
    if dir_key == "LONG":
        stop_loss = entry_price * (1 - total_stop_pct / 100)
    else:  # SHORT
        stop_loss = entry_price * (1 + total_stop_pct / 100)
    
    return {
        "stop_loss": round(stop_loss, 2),
        "stop_type": f"mae_p{int(percentile)}",
        "mae_percentile": mae_pct,
        "safety_buffer": safety_buffer,
        "total_stop_pct": total_stop_pct,
        "methodology": f"MAE P{int(percentile)} ({mae_pct:.2f}%) + buffer ({safety_buffer:.2f}%)"
    }


# Stop model presets
STOP_MODEL_PRESETS = {
    "MAE_CONSERVATIVE": {"percentile": 95, "buffer": 0.15},  # 95th percentile + 0.15%
    "MAE_BALANCED": {"percentile": 75, "buffer": 0.10},      # 75th percentile + 0.10%
    "MAE_AGGRESSIVE": {"percentile": 50, "buffer": 0.05}     # 50th percentile + 0.05%
}


class ConfirmationDebugStats:
    """Track why 5M confirmations succeed or fail"""
    
    def __init__(self):
        self.total_attempts = 0
        self.success_count = 0
        self.failure_reasons = {
            "insufficient_candles": 0,
            "not_in_zone": 0,
            "no_rejection_candle": 0,
            "no_stabilization": 0,
            "no_micro_structure_break": 0,
            "zone_too_far": 0
        }
        self.by_setup = {}  # setup_id -> list of attempt details
    
    def log_attempt(self, setup_id: str, candles_count: int, 
                    in_zone: bool, zone_distance_pct: float,
                    rejection_check: bool, stabilization_check: bool,
                    micro_break_check: bool, success: bool, reason: str = None):
        """Log a confirmation attempt with details"""
        self.total_attempts += 1
        
        if success:
            self.success_count += 1
        elif reason:
            if reason in self.failure_reasons:
                self.failure_reasons[reason] += 1
        
        # Track per-setup
        if setup_id not in self.by_setup:
            self.by_setup[setup_id] = []
        
        self.by_setup[setup_id].append({
            "candles": candles_count,
            "in_zone": in_zone,
            "zone_distance_pct": round(zone_distance_pct, 3),
            "rejection_ok": rejection_check,
            "stabilization_ok": stabilization_check,
            "micro_break_ok": micro_break_check,
            "success": success,
            "reason": reason
        })
    
    def get_summary(self) -> Dict[str, Any]:
        return {
            "total_attempts": self.total_attempts,
            "success_count": self.success_count,
            "success_rate": round(self.success_count / self.total_attempts * 100, 1) if self.total_attempts > 0 else 0,
            "failure_reasons": self.failure_reasons,
            "setups_analyzed": len(self.by_setup)
        }


@dataclass
class BacktestDataQuality:
    """Track data quality for each signal"""
    completeness_score: float = 100.0  # 0-100
    context_quality: str = DataQuality.COMPLETE.value
    degraded_mode: bool = False
    
    # What's available
    has_ohlc: bool = True
    has_volume: bool = True
    has_orderbook_context: bool = False
    has_derivatives_context: bool = False
    has_liquidation_data: bool = False
    has_funding_data: bool = False
    
    # Data gaps
    ohlc_gaps: int = 0
    context_gaps: List[str] = field(default_factory=list)
    
    def calculate_score(self):
        """Calculate completeness score based on available data"""
        score = 0
        if self.has_ohlc: score += 40
        if self.has_volume: score += 15
        if self.has_orderbook_context: score += 15
        if self.has_derivatives_context: score += 15
        if self.has_liquidation_data: score += 10
        if self.has_funding_data: score += 5
        
        # Penalize gaps
        score -= self.ohlc_gaps * 5
        score -= len(self.context_gaps) * 2
        
        self.completeness_score = max(0, min(100, score))
        
        # Determine quality level
        if self.completeness_score >= 80:
            self.context_quality = DataQuality.COMPLETE.value
        elif self.completeness_score >= 60:
            self.context_quality = DataQuality.PARTIAL.value
        elif self.completeness_score >= 40:
            self.context_quality = DataQuality.DEGRADED.value
            self.degraded_mode = True
        else:
            self.context_quality = DataQuality.MINIMAL.value
            self.degraded_mode = True
        
        return self.completeness_score


