# --- Outcome Tracker ---

class OutcomeTracker:
    """Tracks post-signal reality for a single signal"""
    
    def __init__(self, signal: BacktestSignal):
        self.signal = signal
        self.entry_price = signal.targets.entry
        self.stop_loss = signal.targets.stop_loss
        self.target_1 = signal.targets.target_1
        self.target_2 = signal.targets.target_2
        self.direction = signal.direction.replace("CONTRARIAN_", "")  # LONG or SHORT
        
        # Tracking state
        self.outcome = BacktestOutcome()
        self.entry_timestamp = datetime.fromisoformat(signal.timestamp.replace('Z', '+00:00'))
        self.candles_processed = 0
        self.price_history: List[Tuple[float, float]] = []  # (high, low) per candle
        
        # For path analysis
        self.first_move_direction: Optional[str] = None
        self.max_adverse_before_target = 0.0
        
    def process_candle(self, candle: Dict[str, Any]) -> bool:
        """
        Process a candle and update outcome tracking.
        Returns True if outcome is resolved.
        """
        self.candles_processed += 1
        
        high = candle.get("high", candle.get("h", 0))
        low = candle.get("low", candle.get("l", 0))
        close = candle.get("close", candle.get("c", 0))
        timestamp = candle.get("timestamp", candle.get("time", ""))
        
        if isinstance(timestamp, (int, float)):
            timestamp = datetime.fromtimestamp(timestamp, tz=timezone.utc).isoformat()
        
        self.price_history.append((high, low))
        
        # Calculate excursions
        if self.direction == "LONG":
            favorable = (high - self.entry_price) / self.entry_price * 100
            adverse = (self.entry_price - low) / self.entry_price * 100
        else:  # SHORT
            favorable = (self.entry_price - low) / self.entry_price * 100
            adverse = (high - self.entry_price) / self.entry_price * 100
        
        # Update MFE/MAE
        if favorable > self.outcome.mfe:
            self.outcome.mfe = favorable
            self.outcome.mfe_timestamp = timestamp
        
        if adverse > self.outcome.mae:
            self.outcome.mae = adverse
            self.outcome.mae_timestamp = timestamp
        
        # Track first significant move (>0.5%)
        if self.first_move_direction is None:
            if favorable > 0.5:
                self.first_move_direction = "favorable"
                self.outcome.first_significant_move = "favorable"
            elif adverse > 0.5:
                self.first_move_direction = "adverse"
                self.outcome.first_significant_move = "adverse"
        
        # Check target/stop hits
        resolved = False
        
        if self.direction == "LONG":
            # Check T1
            if not self.outcome.t1_hit and high >= self.target_1:
                self.outcome.t1_hit = True
                self.outcome.t1_timestamp = timestamp
                self.outcome.time_to_t1_minutes = self._time_diff_minutes(timestamp)
                
                # Check if adverse before target
                if self.outcome.mae > 0.3:
                    self.outcome.adverse_before_target = True
            
            # Check T2
            if self.target_2 and not self.outcome.t2_hit and high >= self.target_2:
                self.outcome.t2_hit = True
                self.outcome.t2_timestamp = timestamp
                self.outcome.time_to_t2_minutes = self._time_diff_minutes(timestamp)
            
            # Check exceeded T2
            if self.target_2 and high > self.target_2 * 1.01:
                self.outcome.exceeded_t2 = True
            
            # Check stop
            if not self.outcome.stop_hit and low <= self.stop_loss:
                self.outcome.stop_hit = True
                self.outcome.stop_timestamp = timestamp
                self.outcome.time_to_stop_minutes = self._time_diff_minutes(timestamp)
                
        else:  # SHORT
            # Check T1
            if not self.outcome.t1_hit and low <= self.target_1:
                self.outcome.t1_hit = True
                self.outcome.t1_timestamp = timestamp
                self.outcome.time_to_t1_minutes = self._time_diff_minutes(timestamp)
                
                if self.outcome.mae > 0.3:
                    self.outcome.adverse_before_target = True
            
            # Check T2
            if self.target_2 and not self.outcome.t2_hit and low <= self.target_2:
                self.outcome.t2_hit = True
                self.outcome.t2_timestamp = timestamp
                self.outcome.time_to_t2_minutes = self._time_diff_minutes(timestamp)
            
            # Check exceeded T2
            if self.target_2 and low < self.target_2 * 0.99:
                self.outcome.exceeded_t2 = True
            
            # Check stop
            if not self.outcome.stop_hit and high >= self.stop_loss:
                self.outcome.stop_hit = True
                self.outcome.stop_timestamp = timestamp
                self.outcome.time_to_stop_minutes = self._time_diff_minutes(timestamp)
        
        # Determine resolution
        if self.outcome.stop_hit:
            if self.outcome.t1_hit:
                self.outcome.result = "PARTIAL_WIN"
            else:
                self.outcome.result = "LOSS"
            resolved = True
            
        elif self.outcome.t2_hit:
            self.outcome.result = "WIN"
            resolved = True
            
        elif self.outcome.t1_hit and self.candles_processed >= 24:  # 2 hours at 5M
            # T1 hit but not T2 within reasonable time
            self.outcome.result = "PARTIAL_WIN"
            resolved = True
        
        if resolved:
            self.outcome.resolution_timestamp = timestamp
            self.outcome.resolution_price = close
            self.outcome.candles_to_resolution = self.candles_processed
            self._classify_path()
        
        return resolved
    
    def expire(self, timestamp: str, price: float):
        """Mark signal as expired"""
        self.outcome.result = "EXPIRED"
        self.outcome.resolution_timestamp = timestamp
        self.outcome.resolution_price = price
        self.outcome.candles_to_resolution = self.candles_processed
        self._classify_path()
    
    def _time_diff_minutes(self, timestamp: str) -> float:
        """Calculate minutes from entry to timestamp"""
        try:
            ts = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
            return (ts - self.entry_timestamp).total_seconds() / 60
        except:
            return 0.0
    
    def _classify_path(self):
        """Classify post-signal price behavior"""
        o = self.outcome
        
        # Stop hit then reversal (would have been profitable)
        if o.stop_hit and o.t1_hit and o.time_to_stop_minutes and o.time_to_t1_minutes:
            if o.time_to_stop_minutes < o.time_to_t1_minutes:
                o.path_type = PostSignalPath.STOP_THEN_REVERSAL.value
                o.path_description = "Stop hit first, then price reached target"
                return
        
        # Immediate follow-through
        if o.t1_hit and o.mae < 0.3 and o.first_significant_move == "favorable":
            if o.exceeded_t2:
                o.path_type = PostSignalPath.EXTENDED_MOVE.value
                o.path_description = "Direct move exceeded T2"
            else:
                o.path_type = PostSignalPath.IMMEDIATE_FOLLOW_THROUGH.value
                o.path_description = "Clean move to target with minimal drawdown"
            return
        
        # Adverse then recovery
        if o.t1_hit and o.adverse_before_target:
            if o.mae > o.mfe * 0.5:
                o.path_type = PostSignalPath.SWEEP_THEN_TARGET.value
                o.path_description = f"Swept {o.mae:.1f}% adverse before recovering to target"
            else:
                o.path_type = PostSignalPath.ADVERSE_THEN_RECOVERY.value
                o.path_description = f"Minor adverse move ({o.mae:.1f}%) then target"
            return
        
        # Fake breakout
        if o.stop_hit and not o.t1_hit and o.mfe > 0.3:
            o.path_type = PostSignalPath.FAKE_BREAKOUT.value
            o.path_description = f"Initial favorable move ({o.mfe:.1f}%) then reversal to stop"
            return
        
        # Chop/dead market
        if o.result == "EXPIRED" and o.mfe < 0.5 and o.mae < 0.5:
            o.path_type = PostSignalPath.CHOP_DEAD_MARKET.value
            o.path_description = "No significant movement in either direction"
            return
        
        # Default
        o.path_type = PostSignalPath.UNKNOWN.value
        o.path_description = f"MFE: {o.mfe:.1f}%, MAE: {o.mae:.1f}%, Result: {o.result}"


# --- Historical Data Loader ---

class HistoricalDataLoader:
    """Load historical OHLC data from multiple sources"""
    
    def __init__(self, config: BacktestConfig):
        self.config = config
        self.cache: Dict[str, List[Dict]] = {}
    
    async def load_candles(
        self, 
        timeframe: str, 
        start_ts: int, 
        end_ts: int
    ) -> Tuple[List[Dict], BacktestDataQuality]:
        """
        Load candles for a timeframe.
        Returns (candles, data_quality)
        """
        quality = BacktestDataQuality()
        candles = []
        
        # Primary source: Kraken
        if self.config.ohlc_source == "kraken":
            candles = await self._fetch_kraken_ohlc(timeframe, start_ts, end_ts)
            quality.has_ohlc = len(candles) > 0
            quality.has_volume = len(candles) > 0
        
        # Calculate expected candle count
        interval_seconds = self._timeframe_to_seconds(timeframe)
        expected_candles = (end_ts - start_ts) // interval_seconds
        
        if expected_candles > 0:
            quality.ohlc_gaps = max(0, expected_candles - len(candles))
        
        # Add context quality tracking
        if not self.config.use_coinglass_historical:
            quality.context_gaps.append("no_coinglass_historical")
        
        if not self.config.multi_exchange_context:
            quality.context_gaps.append("single_exchange_only")
        
        quality.calculate_score()
        
        return candles, quality
    
    async def _fetch_kraken_ohlc(
        self, 
        timeframe: str, 
        start_ts: int, 
        end_ts: int
    ) -> List[Dict]:
        """Fetch OHLC from Kraken"""
        interval_map = {
            "1M": 1, "5M": 5, "15M": 15, "30M": 30,
            "1H": 60, "4H": 240, "1D": 1440
        }
        interval = interval_map.get(timeframe, 5)
        
        all_candles = []
        current_start = start_ts
        
        try:
            while current_start < end_ts:
                url = f"https://api.kraken.com/0/public/OHLC?pair=XBTUSD&interval={interval}&since={current_start}"
                
                async with httpx.AsyncClient(timeout=30) as client:
                    response = await client.get(url)
                    data = response.json()
                
                if data.get("error") and len(data["error"]) > 0:
                    logger.warning(f"[Backtest] Kraken error: {data['error']}")
                    break
                
                result = data.get("result", {})
                ohlc_data = result.get("XXBTZUSD", result.get("XBTUSD", []))
                
                if not ohlc_data:
                    break
                
                for item in ohlc_data:
                    ts = int(item[0])
                    if ts >= end_ts:
                        break
                    
                    candle = {
                        "timestamp": datetime.fromtimestamp(ts, tz=timezone.utc).isoformat(),
                        "time": ts,
                        "open": float(item[1]),
                        "high": float(item[2]),
                        "low": float(item[3]),
                        "close": float(item[4]),
                        "volume": float(item[6]),
                        "trades": int(item[7]) if len(item) > 7 else 0
                    }
                    all_candles.append(candle)
                
                # Move to next batch
                if ohlc_data:
                    current_start = int(ohlc_data[-1][0]) + 1
                else:
                    break
                
                # Rate limiting - Kraken has strict limits
                await asyncio.sleep(1.5)
            
            return sorted(all_candles, key=lambda x: x["time"])
            
        except Exception as e:
            logger.error(f"[Backtest] Error fetching Kraken data: {e}")
            return []
    
    def _timeframe_to_seconds(self, tf: str) -> int:
        mapping = {
            "1M": 60, "5M": 300, "15M": 900, "30M": 1800,
            "1H": 3600, "4H": 14400, "1D": 86400
        }
        return mapping.get(tf, 300)


# --- V3 Replay Engine ---

# Full V3 Config Snapshot for backtest reproducibility
def get_v3_config_snapshot() -> Dict[str, Any]:
    """
    Capture full V3 configuration at runtime for backtest reproducibility.
    This ensures we can compare V3.5.1 vs future versions without ambiguity.
    """
    return {
        "engine_version": "v3.5.1",
        "timestamp": datetime.now(timezone.utc).isoformat(),
        
        # V3 Core Settings
        "setup_validity_hours": V3_SETUP_VALIDITY_HOURS,
        "stop_buffer_min": V3_STOP_BUFFER_MIN,
        "stop_buffer_max": V3_STOP_BUFFER_MAX,
        
        # V3.4 Validation Thresholds
        "v34_min_rr_threshold": 0.5,
        "v34_magnet_conflict_enabled": True,
        "v34_squeeze_risk_enabled": True,
        "v34_bias_conflict_enabled": True,
        "v34_shorts_overcrowded_threshold": 1.5,
        "v34_longs_overcrowded_threshold": 0.67,
        "v34_extreme_funding_threshold": 0.05,
        
        # V3.5.1 Contrarian Settings
        "v35_enabled": True,
        "v35_min_rr_threshold": 0.7,
        "v35_min_target_distance_pct": 0.005,
        "v35_eligible_blocks": CONTRARIAN_ELIGIBLE_BLOCKS,
        "v35_energy_high_threshold": 60,
        "v35_energy_medium_threshold": 40,
        "v35_compatible_regimes": ["RANGE", "COMPRESSION", "EXPANSION"],
        
        # Detection Settings
        "pivot_lookback_candles": 10,
        "event_zone_buffer_pct": 0.002,
        "confirmation_rejection_ratio": 1.0,
        "confirmation_stabilization_candles": 2,
    }


class V3ReplayEngine:
    """
    Event-driven replay engine that simulates V3 logic on historical data.
    
    CRITICAL DESIGN PRINCIPLES:
    1. REUSE SAME V3 LOGIC: Calls exact same functions used in production
    2. NO LOOK-AHEAD BIAS: Only uses data available at that exact candle
    3. CONFIG SNAPSHOT: Stores full config for version comparison
    4. EXPLICIT LIFECYCLE: Tracks all signal state transitions
    
    DEBUG MODES:
    - NORMAL: Exact same 5M confirmation as production
    - RELAXED: Looser 5M conditions (zone buffer, stabilization)
    - FORCE_ENTRY: Bypass 5M, generate signal from 4H setup directly
    """
    
    def __init__(self, run_id: str, config: BacktestConfig):
        self.run_id = run_id
        self.config = config
        self.data_loader = HistoricalDataLoader(config)
        
        # Frozen config snapshot at run start
        self.config_snapshot = get_v3_config_snapshot()
        self.config_snapshot["confirmation_mode"] = config.confirmation_mode
        self.config_snapshot["debug_confirmation"] = config.debug_confirmation
        
        # Debug stats for confirmation analysis
        self.confirmation_debug = ConfirmationDebugStats()
        
        # State
        self.current_state = SignalLifecycle.SETUP_GENERATED
        self.active_setups: List[Dict[str, Any]] = []  # Pending setups waiting for confirmation
        self.active_trackers: List[OutcomeTracker] = []
        self.completed_signals: List[BacktestSignal] = []
        
        # Progress
        self.total_candles = 0
        self.processed_candles = 0
        self.current_timestamp = ""
        self.current_price = 0.0
        
        # Statistics
        self.stats = {
            "total_signals": 0,
            "blocked_signals": 0,
            "executable_signals": 0,
            "contrarian_signals": 0,
            "resolved_signals": 0,
            "setups_detected": 0,
            "setups_expired": 0
        }
    
    async def run(self) -> Dict[str, Any]:
        """
        Execute the backtest replay using SAME V3 logic as production.
        
        CRITICAL: No look-ahead bias - only uses data available at each candle.
        """
        logger.info(f"[Backtest {self.run_id[:8]}] Starting V3 replay from {self.config.date_from} to {self.config.date_to}")
        logger.info(f"[Backtest {self.run_id[:8]}] Engine version: {self.config_snapshot['engine_version']}")
        
        try:
            # Parse dates
            start_dt = datetime.fromisoformat(self.config.date_from.replace('Z', '+00:00'))
            end_dt = datetime.fromisoformat(self.config.date_to.replace('Z', '+00:00'))
            start_ts = int(start_dt.timestamp())
            end_ts = int(end_dt.timestamp())
            
            # Load ALL 4H candles upfront (but we'll only use [:i+1] for no look-ahead)
            candles_4h, quality_4h = await self.data_loader.load_candles("4H", start_ts, end_ts)
            self.total_candles = len(candles_4h)
            
            if not candles_4h:
                raise Exception("No historical data available for the specified period")
            
            logger.info(f"[Backtest {self.run_id[:8]}] Loaded {len(candles_4h)} 4H candles (data quality: {quality_4h.context_quality})")
            
            # Load ALL 5M candles upfront to avoid rate limiting
            # (but we'll only use data up to current 4H candle for no look-ahead)
            candles_5m_all, quality_5m = await self.data_loader.load_candles("5M", start_ts, end_ts)
            logger.info(f"[Backtest {self.run_id[:8]}] Loaded {len(candles_5m_all)} 5M candles")
            
            # Store config snapshot in run document
            await backtest_runs_collection.update_one(
                {"run_id": self.run_id},
                {"$set": {
                    "config_snapshot": self.config_snapshot,
                    "progress.total_candles": self.total_candles
                }}
            )
            
            # Iterate through 4H candles (simulating real-time progression)
            for i, candle_4h in enumerate(candles_4h):
                self.processed_candles = i + 1
                self.current_timestamp = candle_4h["timestamp"]
                self.current_price = candle_4h["close"]
                
                # Update progress in DB every 10 candles
                if i % 10 == 0:
                    await self._update_progress()
                
                # ═══════════════════════════════════════════════════════════════
                # STEP 1: Process active outcome trackers with new candle
                # ═══════════════════════════════════════════════════════════════
                await self._process_active_trackers(candle_4h)
                
                # ═══════════════════════════════════════════════════════════════
                # STEP 2: Expire stale setups (mimic V3_SETUP_VALIDITY_HOURS)
                # ═══════════════════════════════════════════════════════════════
                await self._expire_stale_setups(candle_4h)
                
                # ═══════════════════════════════════════════════════════════════
                # STEP 3: Detect new 4H events using SAME detect_4h_events()
                # NO LOOK-AHEAD: Only pass candles[:i+1]
                # ═══════════════════════════════════════════════════════════════
                history_4h = candles_4h[:i+1]  # CRITICAL: No future data
                
                if len(history_4h) >= 10:  # Need minimum history
                    new_events = await self._detect_4h_events_backtest(
                        history_4h, 
                        self.current_price,
                        quality_4h
                    )
                    
                    for event in new_events:
                        # Create setup (similar to create_setup_event but for backtest)
                        setup = await self._create_backtest_setup(event, candle_4h, quality_4h)
                        if setup:
                            self.stats["setups_detected"] += 1
                            
                            # ═══════════════════════════════════════════════════════════
                            # FORCE_ENTRY_IMMEDIATE: Generate signal directly from 4H setup
                            # This allows collecting MAE data from ALL setups, not just confirmed ones
                            # ═══════════════════════════════════════════════════════════
                            if self.config.confirmation_mode == "FORCE_ENTRY":
                                # Create signal immediately at 4H close price
                                signal = await self._create_and_validate_signal_v3(
                                    setup,
                                    {"type": "force_entry_4h", "price": self.current_price},
                                    candle_4h,  # Use 4H candle as entry point
                                    quality_4h
                                )
                                
                                if signal:
                                    self.stats["total_signals"] += 1
                                    
                                    if signal.lifecycle_state == SignalLifecycle.BLOCKED.value:
                                        self.stats["blocked_signals"] += 1
                                    else:
                                        self.stats["executable_signals"] += 1
                                        # Start outcome tracking
                                        tracker = OutcomeTracker(signal)
                                        self.active_trackers.append(tracker)
                                    
                                    # Save signal
                                    await self._save_signal(signal)
                                    
                                # Don't add to active_setups in FORCE_ENTRY mode
                                # (signal already generated)
                            else:
                                # Normal mode: add to active setups and wait for 5M confirmation
                                self.active_setups.append(setup)
                
                # ═══════════════════════════════════════════════════════════════
                # STEP 4: Filter 5M candles for this 4H window (no extra API calls)
                # NO LOOK-AHEAD: Only use 5M candles within this 4H window
                # ═══════════════════════════════════════════════════════════════
                candle_start_ts = candle_4h["time"]
                candle_end_ts = candle_start_ts + 14400  # 4 hours
                
                # Filter 5M candles for this 4H window from preloaded data
                candles_5m = [c for c in candles_5m_all 
                              if candle_start_ts <= c["time"] < candle_end_ts]
                
                # Process 5M candles sequentially (no look-ahead within 5M)
                for j, candle_5m in enumerate(candles_5m):
                    # Process outcome trackers with 5M granularity
                    await self._process_active_trackers_5m(candle_5m)
                    
                    # Check active setups for confirmation
                    for setup in self.active_setups[:]:  # Copy list to allow removal
                        # CRITICAL: Only use 5M candles up to current index
                        history_5m = candles_5m[:j+1]
                        
                        confirmation = await self._check_5m_confirmation_backtest(
                            setup, 
                            history_5m, 
                            candle_5m,
                            quality_5m
                        )
                        
                        if confirmation:
                            # ═══════════════════════════════════════════════════
                            # STEP 5: Apply V3.4 validation (SAME as production)
                            # ═══════════════════════════════════════════════════
                            signal = await self._create_and_validate_signal_v3(
                                setup, 
                                confirmation,
                                candle_5m, 
                                quality_5m
                            )
                            
                            if signal:
                                self.stats["total_signals"] += 1
                                
                                if signal.lifecycle_state == SignalLifecycle.BLOCKED.value:
                                    self.stats["blocked_signals"] += 1
                                    
                                    # ═══════════════════════════════════════════
                                    # STEP 6: Check V3.5.1 contrarian opportunity
                                    # ═══════════════════════════════════════════
                                    if self.config.v35_contrarian_enabled:
                                        contrarian = await self._evaluate_contrarian_v3_5(
                                            signal, 
                                            setup,
                                            candle_5m
                                        )
                                        if contrarian:
                                            self.stats["contrarian_signals"] += 1
                                            # Save both: blocked original + contrarian
                                            await self._save_signal(signal)
                                            signal = contrarian
                                
                                if signal.lifecycle_state in [
                                    SignalLifecycle.EXECUTABLE.value,
                                    SignalLifecycle.CONTRARIAN_EXECUTABLE.value
                                ]:
                                    self.stats["executable_signals"] += 1
                                    # Start outcome tracking
                                    tracker = OutcomeTracker(signal)
                                    self.active_trackers.append(tracker)
                                
                                # Save signal
                                await self._save_signal(signal)
                                
                                # Remove setup once signal generated
                                if setup in self.active_setups:
                                    self.active_setups.remove(setup)
                                
                                break  # One signal per setup
            
            # Finalize any remaining active trackers
            await self._finalize_trackers()
            
            # Generate summary
            summary = await self._generate_summary()
            
            logger.info(f"[Backtest {self.run_id[:8]}] ✅ Completed. "
                       f"Setups: {self.stats['setups_detected']}, "
                       f"Signals: {self.stats['total_signals']}, "
                       f"Executable: {self.stats['executable_signals']}, "
                       f"Blocked: {self.stats['blocked_signals']}, "
                       f"Contrarian: {self.stats['contrarian_signals']}")
            
            return summary
            
        except Exception as e:
            logger.error(f"[Backtest {self.run_id[:8]}] Failed: {e}")
            import traceback
            logger.error(traceback.format_exc())
            raise
    
    async def _detect_4h_events_backtest(
        self, 
        history_4h: List[Dict],
        current_price: float,
        quality: BacktestDataQuality
    ) -> List[Dict]:
        """
        Detect 4H events using SAME detect_4h_events() function as production.
        
        NO LOOK-AHEAD: Only receives candles available at this point in time.
        
        Note: In backtest, we don't have live S/R levels or derivatives data.
        We use degraded mode with OHLC-only context.
        """
        # Build empty/neutral S/R lists (no live orderbook data in historical)
        supports = []
        resistances = []
        
        # No live derivatives data - use defaults
        liquidity_above = 0.0
        liquidity_below = 0.0
        
        # Estimate market regime/bias from price action only
        market_regime, market_bias = self._estimate_regime_from_candles(history_4h)
        
        # Call the SAME function used in production
        events = detect_4h_events(
            candles_4h=history_4h,
            current_price=current_price,
            supports=supports,
            resistances=resistances,
            liquidity_above=liquidity_above,
            liquidity_below=liquidity_below,
            market_regime=market_regime,
            market_bias=market_bias,
            lang="en"  # English for backtest logs
        )
        
        return events
    
    def _estimate_regime_from_candles(self, candles: List[Dict]) -> Tuple[str, str]:
        """
        Estimate market regime and bias from OHLC data only (degraded mode).
        This is used when no derivatives/live context is available.
        """
        if len(candles) < 10:
            return "UNKNOWN", "NEUTRAL"
        
        recent = candles[-10:]
        
        # Calculate trend
        first_close = recent[0]["close"]
        last_close = recent[-1]["close"]
        change_pct = ((last_close - first_close) / first_close) * 100
        
        # Calculate volatility (range expansion)
        ranges = [c["high"] - c["low"] for c in recent]
        avg_range = sum(ranges) / len(ranges)
        volatility = (avg_range / last_close) * 100
        
        # Determine regime
        if abs(change_pct) > 3:
            regime = "TREND"
        elif volatility < 0.5:
            regime = "COMPRESSION"
        elif volatility > 1.5:
            regime = "EXPANSION"
        else:
            regime = "RANGE"
        
        # Determine bias
        if change_pct > 1:
            bias = "BULLISH"
        elif change_pct < -1:
            bias = "BEARISH"
        else:
            bias = "NEUTRAL"
        
        return regime, bias
    
    async def _create_backtest_setup(
        self, 
        event: Dict, 
        candle_4h: Dict,
        quality: BacktestDataQuality
    ) -> Optional[Dict]:
        """
        Create a setup from detected 4H event.
        
        In backtest mode (no live orderbook), we use SWING-BASED targets
        instead of cluster-based targets.
        
        Target Logic (backtest degraded mode):
        - LONG: T1 = swing_high, T2 = swing_high + 1%
        - SHORT: T1 = swing_low, T2 = swing_low - 1%
        """
        direction = event["direction"]
        current_price = candle_4h["close"]
        swing_high = event.get("swing_high", current_price * 1.02)
        swing_low = event.get("swing_low", current_price * 0.98)
        sweep_level = event.get("sweep_level")
        
        # Use SAME stop loss calculation
        stop_info = calculate_v3_stop_loss(
            direction=direction,
            swing_high=swing_high,
            swing_low=swing_low,
            sweep_level=sweep_level,
            current_price=current_price
        )
        
        # ═══════════════════════════════════════════════════════════════════
        # BACKTEST TARGETS - Use swing-based when no orderbook
        # (In production, we'd use calculate_v3_targets with real clusters)
        # ═══════════════════════════════════════════════════════════════════
        if direction == "LONG":
            # T1 = swing high (natural resistance)
            # T2 = extended beyond swing high
            target_1 = swing_high
            target_2 = swing_high * 1.01  # 1% beyond T1
            target_1_type = "swing_high"
            target_2_type = "extended"
        else:  # SHORT
            # T1 = swing low (natural support)
            # T2 = extended below swing low
            target_1 = swing_low
            target_2 = swing_low * 0.99  # 1% beyond T1
            target_1_type = "swing_low"
            target_2_type = "extended"
        
        # Calculate R:R
        risk = abs(current_price - stop_info["stop_loss"])
        reward = abs(target_1 - current_price)
        rr_ratio = reward / risk if risk > 0 else 0
        
        # Mark as valid targets for backtest (swing-based)
        has_valid_targets = reward > 0
        
        # Store setup for later confirmation
        setup = {
            "setup_id": str(uuid.uuid4()),
            "created_at": candle_4h["timestamp"],
            "expires_at": (datetime.fromisoformat(candle_4h["timestamp"].replace('Z', '+00:00')) + 
                          timedelta(hours=V3_SETUP_VALIDITY_HOURS)).isoformat(),
            "event_type": event["type"],
            "direction": direction,
            "zone_high": event["zone_high"],
            "zone_low": event["zone_low"],
            "event_price": event["event_price"],
            "swing_high": swing_high,
            "swing_low": swing_low,
            "sweep_level": sweep_level,
            "stop_loss": stop_info["stop_loss"],
            "stop_type": stop_info["stop_type"],
            "target_1": round(target_1, 2),
            "target_2": round(target_2, 2),
            "target_1_type": target_1_type,
            "target_2_type": target_2_type,
            "has_valid_targets": has_valid_targets,
            "risk_reward_ratio": round(rr_ratio, 2),
            "strength": event.get("strength", 50),
            "signal": event.get("signal", ""),
            "data_quality": quality
        }
        
        return setup
    
    async def _check_5m_confirmation_backtest(
        self,
        setup: Dict,
        history_5m: List[Dict],
        current_candle_5m: Dict,
        quality: BacktestDataQuality
    ) -> Optional[Dict]:
        """
        Check for 5M confirmation with debug modes.
        
        Modes:
        - NORMAL: Use exact same detect_5m_confirmation() as production
        - RELAXED: Loosen zone buffer and stabilization requirements
        - FORCE_ENTRY: Bypass 5M entirely, always confirm
        
        NO LOOK-AHEAD: Only uses candles up to current index.
        """
        setup_id = setup.get("setup_id", "unknown")[:8]
        current_price = current_candle_5m["close"]
        zone_high = setup["zone_high"]
        zone_low = setup["zone_low"]
        direction = setup["direction"]
        
        # ═══════════════════════════════════════════════════════════════════
        # FORCE_ENTRY MODE: Bypass 5M confirmation entirely
        # ═══════════════════════════════════════════════════════════════════
        if self.config.confirmation_mode == "FORCE_ENTRY":
            if self.config.debug_confirmation:
                logger.info(f"[Backtest Debug] Setup {setup_id}: FORCE_ENTRY mode - bypassing 5M confirmation")
            
            self.confirmation_debug.log_attempt(
                setup_id=setup_id,
                candles_count=len(history_5m),
                in_zone=True,
                zone_distance_pct=0,
                rejection_check=True,
                stabilization_check=True,
                micro_break_check=True,
                success=True,
                reason="force_entry"
            )
            
            return {
                "type": "force_entry",
                "strength": 50,
                "price": current_price,
                "details": {"mode": "FORCE_ENTRY", "bypassed_5m": True},
                "signal": f"FORCE_ENTRY mode - signal from 4H setup at ${current_price:,.0f}"
            }
        
        # Minimum candles check
        if len(history_5m) < 5:
            if self.config.debug_confirmation:
                self.confirmation_debug.log_attempt(
                    setup_id=setup_id,
                    candles_count=len(history_5m),
                    in_zone=False,
                    zone_distance_pct=0,
                    rejection_check=False,
                    stabilization_check=False,
                    micro_break_check=False,
                    success=False,
                    reason="insufficient_candles"
                )
            return None
        
        # Calculate zone distance
        zone_center = (zone_high + zone_low) / 2
        if direction == "LONG":
            zone_distance_pct = ((current_price - zone_low) / zone_low) * 100
        else:
            zone_distance_pct = ((zone_high - current_price) / zone_high) * 100
        
        # Zone check parameters based on mode
        if self.config.confirmation_mode == "RELAXED":
            zone_buffer = 0.01  # 1% buffer (vs 0.2% in production)
            min_stabilization = 1  # 1 candle (vs 2 in production)
        else:  # NORMAL
            zone_buffer = 0.002  # 0.2% buffer
            min_stabilization = 2
        
        # Check if price is in or near zone
        in_zone = zone_low * (1 - zone_buffer) <= current_price <= zone_high * (1 + zone_buffer)
        
        if not in_zone and abs(zone_distance_pct) > (zone_buffer * 100 * 2):
            if self.config.debug_confirmation:
                self.confirmation_debug.log_attempt(
                    setup_id=setup_id,
                    candles_count=len(history_5m),
                    in_zone=False,
                    zone_distance_pct=zone_distance_pct,
                    rejection_check=False,
                    stabilization_check=False,
                    micro_break_check=False,
                    success=False,
                    reason="zone_too_far"
                )
                logger.debug(f"[Backtest Debug] Setup {setup_id}: Zone too far ({zone_distance_pct:.2f}%)")
            return None
        
        # ═══════════════════════════════════════════════════════════════════
        # NORMAL/RELAXED: Use production logic with optional relaxation
        # ═══════════════════════════════════════════════════════════════════
        
        # Get recent 5M candles
        recent_5m = history_5m[-10:]
        last_candle = recent_5m[-1]
        
        # 1. REJECTION CANDLE CHECK
        body = abs(last_candle["close"] - last_candle["open"])
        upper_wick = last_candle["high"] - max(last_candle["close"], last_candle["open"])
        lower_wick = min(last_candle["close"], last_candle["open"]) - last_candle["low"]
        
        rejection_check = False
        rejection_confirmation = None
        
        if direction == "LONG":
            # Relaxed: wick > body (vs wick > body + other_wick in production)
            if self.config.confirmation_mode == "RELAXED":
                if lower_wick > body and lower_wick > 0:
                    rejection_check = True
                    rejection_confirmation = {
                        "type": "rejection_candle_relaxed",
                        "strength": min(100, (lower_wick / (body + 0.01)) * 50),
                        "price": current_price,
                        "details": {"lower_wick": lower_wick, "body": body},
                        "signal": f"Relaxed rejection candle at ${current_price:,.0f}"
                    }
            else:
                if lower_wick > body + upper_wick and lower_wick > 0:
                    rejection_check = True
                    rejection_confirmation = {
                        "type": "rejection_candle",
                        "strength": min(100, (lower_wick / (body + upper_wick + 0.01)) * 100),
                        "price": current_price,
                        "details": {"lower_wick": lower_wick, "body": body, "upper_wick": upper_wick},
                        "signal": f"Rejection candle LONG at ${current_price:,.0f}"
                    }
        else:  # SHORT
            if self.config.confirmation_mode == "RELAXED":
                if upper_wick > body and upper_wick > 0:
                    rejection_check = True
                    rejection_confirmation = {
                        "type": "rejection_candle_relaxed",
                        "strength": min(100, (upper_wick / (body + 0.01)) * 50),
                        "price": current_price,
                        "details": {"upper_wick": upper_wick, "body": body},
                        "signal": f"Relaxed rejection candle at ${current_price:,.0f}"
                    }
            else:
                if upper_wick > body + lower_wick and upper_wick > 0:
                    rejection_check = True
                    rejection_confirmation = {
                        "type": "rejection_candle",
                        "strength": min(100, (upper_wick / (body + lower_wick + 0.01)) * 100),
                        "price": current_price,
                        "details": {"upper_wick": upper_wick, "body": body, "lower_wick": lower_wick},
                        "signal": f"Rejection candle SHORT at ${current_price:,.0f}"
                    }
        
        if rejection_check:
            self.confirmation_debug.log_attempt(
                setup_id=setup_id,
                candles_count=len(history_5m),
                in_zone=in_zone,
                zone_distance_pct=zone_distance_pct,
                rejection_check=True,
                stabilization_check=False,
                micro_break_check=False,
                success=True,
                reason="rejection_candle"
            )
            if self.config.debug_confirmation:
                logger.info(f"[Backtest Debug] Setup {setup_id}: ✅ Rejection candle confirmed")
            return rejection_confirmation
        
        # 2. STABILIZATION CHECK
        candles_in_zone = []
        for c in recent_5m[-5:]:
            candle_mid = (c["high"] + c["low"]) / 2
            zone_low_buffered = zone_low * (1 - zone_buffer)
            zone_high_buffered = zone_high * (1 + zone_buffer)
            if zone_low_buffered <= candle_mid <= zone_high_buffered:
                candles_in_zone.append(c)
        
        stabilization_check = len(candles_in_zone) >= min_stabilization
        stabilization_confirmation = None
        
        if stabilization_check:
            ranges = [c["high"] - c["low"] for c in candles_in_zone]
            is_compressing = len(ranges) >= 2 and ranges[-1] < ranges[0]
            
            if is_compressing or self.config.confirmation_mode == "RELAXED":
                stabilization_confirmation = {
                    "type": "stabilization" if is_compressing else "stabilization_relaxed",
                    "strength": min(100, len(candles_in_zone) * 30),
                    "price": current_price,
                    "details": {
                        "candles_in_zone": len(candles_in_zone),
                        "compressing": is_compressing
                    },
                    "signal": f"Stabilization in zone ({len(candles_in_zone)} candles)"
                }
                
                self.confirmation_debug.log_attempt(
                    setup_id=setup_id,
                    candles_count=len(history_5m),
                    in_zone=in_zone,
                    zone_distance_pct=zone_distance_pct,
                    rejection_check=rejection_check,
                    stabilization_check=True,
                    micro_break_check=False,
                    success=True,
                    reason="stabilization"
                )
                if self.config.debug_confirmation:
                    logger.info(f"[Backtest Debug] Setup {setup_id}: ✅ Stabilization confirmed ({len(candles_in_zone)} candles)")
                return stabilization_confirmation
        
        # 3. MICRO-STRUCTURE BREAK CHECK
        micro_swing_high = max(c["high"] for c in recent_5m[-5:])
        micro_swing_low = min(c["low"] for c in recent_5m[-5:])
        
        micro_break_check = False
        micro_confirmation = None
        
        if direction == "LONG":
            if last_candle["close"] > micro_swing_high:
                micro_break_check = True
                micro_confirmation = {
                    "type": "micro_structure_break",
                    "strength": 70,
                    "price": current_price,
                    "details": {
                        "micro_high": micro_swing_high,
                        "break_level": last_candle["close"]
                    },
                    "signal": f"Micro structure break above ${micro_swing_high:,.0f}"
                }
        else:
            if last_candle["close"] < micro_swing_low:
                micro_break_check = True
                micro_confirmation = {
                    "type": "micro_structure_break",
                    "strength": 70,
                    "price": current_price,
                    "details": {
                        "micro_low": micro_swing_low,
                        "break_level": last_candle["close"]
                    },
                    "signal": f"Micro structure break below ${micro_swing_low:,.0f}"
                }
        
        if micro_break_check:
            self.confirmation_debug.log_attempt(
                setup_id=setup_id,
                candles_count=len(history_5m),
                in_zone=in_zone,
                zone_distance_pct=zone_distance_pct,
                rejection_check=rejection_check,
                stabilization_check=stabilization_check,
                micro_break_check=True,
                success=True,
                reason="micro_structure_break"
            )
            if self.config.debug_confirmation:
                logger.info(f"[Backtest Debug] Setup {setup_id}: ✅ Micro structure break confirmed")
            return micro_confirmation
        
        # NO CONFIRMATION FOUND
        # Determine primary failure reason
        if not in_zone and abs(zone_distance_pct) > 0.5:
            reason = "not_in_zone"
        elif not rejection_check and not stabilization_check and not micro_break_check:
            reason = "no_rejection_candle"  # Most common
        else:
            reason = "no_stabilization"
        
        self.confirmation_debug.log_attempt(
            setup_id=setup_id,
            candles_count=len(history_5m),
            in_zone=in_zone,
            zone_distance_pct=zone_distance_pct,
            rejection_check=rejection_check,
            stabilization_check=stabilization_check,
            micro_break_check=micro_break_check,
            success=False,
            reason=reason
        )
        
        if self.config.debug_confirmation:
            logger.debug(f"[Backtest Debug] Setup {setup_id}: ❌ No confirmation. "
                        f"in_zone={in_zone}, distance={zone_distance_pct:.2f}%, "
                        f"rejection={rejection_check}, stab={stabilization_check}, micro={micro_break_check}")
        
        return None
    
    async def _expire_stale_setups(self, candle_4h: Dict):
        """Remove setups that have expired (V3_SETUP_VALIDITY_HOURS)"""
        current_time = datetime.fromisoformat(candle_4h["timestamp"].replace('Z', '+00:00'))
        
        for setup in self.active_setups[:]:
            expires_at = datetime.fromisoformat(setup["expires_at"].replace('Z', '+00:00'))
            if current_time >= expires_at:
                self.active_setups.remove(setup)
                self.stats["setups_expired"] += 1
    
    async def _create_and_validate_signal_v3(
        self,
        setup: Dict,
        confirmation: Dict,
        candle_5m: Dict,
        quality: BacktestDataQuality
    ) -> BacktestSignal:
        """
        Create signal and apply V3.4 validation using SAME logic as production.
        
        STOP MODEL OPTIONS:
        - ORIGINAL: Use swing-based stop from calculate_v3_stop_loss()
        - MAE_CONSERVATIVE: 95th percentile MAE + buffer
        - MAE_BALANCED: 75th percentile MAE + buffer
        - MAE_AGGRESSIVE: 50th percentile MAE + buffer
        - CUSTOM: Fixed percentage stop
        
        V3.4 Validation includes:
        1. R:R minimum check (0.5)
        2. Magnet conflict check (degraded - uses bias instead)
        3. Squeeze risk check (degraded - no derivatives data)
        4. Bias conflict check
        """
        current_price = candle_5m["close"]
        direction = setup["direction"]
        
        # Create signal with full context
        signal = BacktestSignal(
            signal_id=str(uuid.uuid4()),
            run_id=self.run_id,
            timestamp=candle_5m["timestamp"],
            candle_index=self.processed_candles,
            direction=direction,
            setup_type=setup["event_type"],
            lifecycle_state=SignalLifecycle.WAITING_CONFIRMATION.value,
            data_quality=quality
        )
        
        # ═══════════════════════════════════════════════════════════════════
        # STOP MODEL SELECTION
        # ═══════════════════════════════════════════════════════════════════
        stop_model = self.config.stop_model
        original_stop = setup["stop_loss"]
        
        if stop_model == "ORIGINAL":
            # Use setup's original swing-based stop
            stop_loss = original_stop
            stop_type = setup.get("stop_type", "swing")
            stop_pct = abs(current_price - stop_loss) / current_price * 100
            
        elif stop_model in ["MAE_CONSERVATIVE", "MAE_BALANCED", "MAE_AGGRESSIVE"]:
            # Use MAE-based stop
            preset = STOP_MODEL_PRESETS[stop_model]
            regime = self._estimate_regime_from_candles([candle_5m])[0]
            
            mae_stop = get_mae_based_stop(
                direction=direction,
                entry_price=current_price,
                regime=regime,
                setup_type=setup["event_type"],
                percentile=preset["percentile"],
                safety_buffer=preset["buffer"]
            )
            
            stop_loss = mae_stop["stop_loss"]
            stop_type = mae_stop["stop_type"]
            stop_pct = mae_stop["total_stop_pct"]
            
        elif stop_model == "CUSTOM":
            # Use fixed percentage stop
            stop_pct = self.config.custom_stop_pct
            if direction.replace("CONTRARIAN_", "") == "LONG":
                stop_loss = current_price * (1 - stop_pct / 100)
            else:
                stop_loss = current_price * (1 + stop_pct / 100)
            stop_type = "custom_fixed"
            
        else:
            # Default to original
            stop_loss = original_stop
            stop_type = setup.get("stop_type", "swing")
            stop_pct = abs(current_price - stop_loss) / current_price * 100
        
        # Set targets
        signal.targets.entry = current_price
        signal.targets.stop_loss = round(stop_loss, 2)
        signal.targets.target_1 = setup["target_1"]
        signal.targets.target_2 = setup["target_2"]
        
        # Calculate R:R with selected stop
        risk = abs(current_price - stop_loss)
        reward = abs(setup["target_1"] - current_price)
        signal.targets.rr_ratio = round(reward / risk, 2) if risk > 0 else 0
        signal.targets.risk_pct = stop_pct
        signal.targets.reward_pct = (reward / current_price) * 100 if current_price > 0 else 0
        
        # Store stop model info in context
        signal.context.compression_level = f"{stop_model}_{stop_type}"
        
        # Set context (from degraded OHLC estimation)
        regime, bias = self._estimate_regime_from_candles([candle_5m])  # Minimal
        signal.context.regime = regime
        signal.context.bias = bias
        signal.context.energy_score = 50.0  # Unknown in degraded mode
        signal.context.magnet_direction = "BALANCED"  # Unknown
        
        # Store original stop for comparison
        signal.context.magnet_strength = abs(current_price - original_stop) / current_price * 100  # Repurposed field
        
        # ═══════════════════════════════════════════════════════════════════
        # V3.4 VALIDATION (SAME logic as record_v3_entry_signal)
        # ═══════════════════════════════════════════════════════════════════
        
        block_reasons = []
        
        # 1. R:R Check (SAME threshold as production)
        MIN_RR_THRESHOLD = 0.5
        if signal.targets.rr_ratio < MIN_RR_THRESHOLD:
            block_reasons.append(f"LOW_RR_{signal.targets.rr_ratio:.2f}")
        
        # 2. Has Valid Targets
        if not setup.get("has_valid_targets", True):
            block_reasons.append("NO_VALID_TARGETS")
        
        # 3. Bias Conflict Check (available in degraded mode)
        # Strong bias must align with direction
        if bias in ["BULLISH", "BEARISH"]:
            bias_bullish = bias == "BULLISH"
            signal_bullish = setup["direction"] == "LONG"
            
            if bias_bullish != signal_bullish:
                block_reasons.append(f"BIAS_CONFLICT_{setup['direction']}_vs_{bias}")
        
        # NOTE: Magnet and Squeeze checks are NOT available in historical backtest
        # because we don't have derivatives data. This is tracked via data_quality.
        
        # ═══════════════════════════════════════════════════════════════════
        # DISABLE R:R FILTER MODE (for MFE/MAE analysis)
        # When enabled, signals are NOT blocked for low R:R or invalid targets
        # ═══════════════════════════════════════════════════════════════════
        if self.config.disable_rr_filter:
            # Remove R:R and target validity block reasons - we want to track actual price behavior
            block_reasons = [r for r in block_reasons if not r.startswith("LOW_RR") and not r.startswith("NO_VALID")]
            
            # Store original R:R for analysis
            signal.context.compression_level = f"{stop_model}_RR_{signal.targets.rr_ratio:.2f}"
        
        # Determine if blocked
        if block_reasons:
            signal.lifecycle_state = SignalLifecycle.BLOCKED.value
            signal.block_reason = block_reasons[0]  # Primary reason
            signal.v34_passed = False
        else:
            signal.lifecycle_state = SignalLifecycle.EXECUTABLE.value
            signal.v34_passed = True
        
        return signal
    
    async def _evaluate_contrarian_v3_5(
        self,
        blocked_signal: BacktestSignal,
        setup: Dict,
        candle_5m: Dict
    ) -> Optional[BacktestSignal]:
        """
        Evaluate V3.5.1 contrarian opportunity using SAME logic as production.
        
        In backtest degraded mode:
        - No derivatives data = no squeeze context
        - Limited to bias/regime-based evaluation
        
        This will naturally produce fewer contrarian signals in backtest,
        which is expected behavior when running without derivatives context.
        """
        # Check eligible block reasons (SAME as production)
        if not blocked_signal.block_reason:
            return None
        
        is_eligible = any(
            eligible in blocked_signal.block_reason 
            for eligible in CONTRARIAN_ELIGIBLE_BLOCKS
        )
        
        if not is_eligible:
            return None
        
        # Contrarian direction
        contrarian_direction = "LONG" if blocked_signal.direction == "SHORT" else "SHORT"
        current_price = candle_5m["close"]
        
        # Build contrarian targets (inverted)
        swing_high = setup.get("swing_high", current_price * 1.02)
        swing_low = setup.get("swing_low", current_price * 0.98)
        
        if contrarian_direction == "LONG":
            contrarian_stop = swing_low * 0.998
            contrarian_target = swing_high * 1.002
            risk = current_price - contrarian_stop
            reward = contrarian_target - current_price
        else:
            contrarian_stop = swing_high * 1.002
            contrarian_target = swing_low * 0.998
            risk = contrarian_stop - current_price
            reward = current_price - contrarian_target
        
        contrarian_rr = reward / risk if risk > 0 else 0
        
        # V3.5.1 stricter R:R requirement (SAME as production)
        MIN_CONTRARIAN_RR = 0.7
        if contrarian_rr < MIN_CONTRARIAN_RR:
            return None
        
        # V3.5.1 minimum target distance (SAME as production)
        MIN_TARGET_DISTANCE_PCT = 0.005
        target_distance_pct = abs(contrarian_target - current_price) / current_price
        if target_distance_pct < MIN_TARGET_DISTANCE_PCT:
            return None
        
        # In degraded mode (no derivatives), we can't check:
        # - Magnet alignment
        # - Squeeze support
        # So contrarian signals are RARE in backtest - this is expected
        
        # Check regime compatibility (available in degraded mode)
        regime = blocked_signal.context.regime
        if regime not in ["RANGE", "COMPRESSION", "EXPANSION"]:
            return None
        
        # Create contrarian signal
        contrarian = BacktestSignal(
            signal_id=str(uuid.uuid4()),
            run_id=self.run_id,
            timestamp=candle_5m["timestamp"],
            candle_index=self.processed_candles,
            direction=f"CONTRARIAN_{contrarian_direction}",
            setup_type="contrarian_trap",
            lifecycle_state=SignalLifecycle.CONTRARIAN_EXECUTABLE.value,
            data_quality=blocked_signal.data_quality,
            v34_passed=True,
            contrarian_active=True,
            contrarian_reason=f"Blocked {blocked_signal.direction} due to {blocked_signal.block_reason}"
        )
        
        contrarian.targets.entry = current_price
        contrarian.targets.stop_loss = round(contrarian_stop, 2)
        contrarian.targets.target_1 = round(contrarian_target, 2)
        contrarian.targets.rr_ratio = round(contrarian_rr, 2)
        
        contrarian.context = blocked_signal.context
        
        return contrarian
    
    async def _process_active_trackers(self, candle: Dict):
        """Process outcome tracking with 4H candle"""
        for tracker in self.active_trackers[:]:
            resolved = tracker.process_candle(candle)
            if resolved:
                # Update signal with outcome
                tracker.signal.outcome = tracker.outcome
                tracker.signal.lifecycle_state = SignalLifecycle.RESOLVED.value
                await self._update_signal_outcome(tracker.signal)
                self.active_trackers.remove(tracker)
                self.stats["resolved_signals"] += 1
    
    async def _process_active_trackers_5m(self, candle: Dict):
        """Process outcome tracking with 5M candle (more granular)"""
        for tracker in self.active_trackers[:]:
            resolved = tracker.process_candle(candle)
            if resolved:
                tracker.signal.outcome = tracker.outcome
                tracker.signal.lifecycle_state = SignalLifecycle.RESOLVED.value
                await self._update_signal_outcome(tracker.signal)
                self.active_trackers.remove(tracker)
                self.stats["resolved_signals"] += 1
    
    async def _finalize_trackers(self):
        """Expire remaining active trackers"""
        for tracker in self.active_trackers:
            tracker.expire(self.current_timestamp, tracker.signal.targets.entry)
            tracker.signal.outcome = tracker.outcome
            tracker.signal.lifecycle_state = SignalLifecycle.RESOLVED.value
            await self._update_signal_outcome(tracker.signal)
            self.stats["resolved_signals"] += 1
        self.active_trackers.clear()
    
    async def _save_signal(self, signal: BacktestSignal):
        """Save signal to database"""
        await backtest_signals_collection.insert_one(signal.to_dict())
    
    async def _update_signal_outcome(self, signal: BacktestSignal):
        """Update signal outcome in database"""
        await backtest_signals_collection.update_one(
            {"signal_id": signal.signal_id},
            {"$set": {
                "outcome": asdict(signal.outcome) if signal.outcome else None,
                "lifecycle_state": signal.lifecycle_state
            }}
        )
    
    async def _update_progress(self):
        """Update run progress in database"""
        await backtest_runs_collection.update_one(
            {"run_id": self.run_id},
            {"$set": {
                "progress.processed_candles": self.processed_candles,
                "progress.current_timestamp": self.current_timestamp
            }}
        )
    
    async def _generate_summary(self) -> Dict[str, Any]:
        """Generate backtest summary statistics with config snapshot"""
        
        # Query all signals for this run
        cursor = backtest_signals_collection.find({"run_id": self.run_id})
        signals = await cursor.to_list(None)
        
        # Calculate statistics
        executable_signals = [s for s in signals if s.get("lifecycle_state") in [
            SignalLifecycle.EXECUTABLE.value,
            SignalLifecycle.CONTRARIAN_EXECUTABLE.value,
            SignalLifecycle.RESOLVED.value
        ]]
        
        blocked_signals = [s for s in signals if s.get("lifecycle_state") == SignalLifecycle.BLOCKED.value]
        contrarian_signals = [s for s in signals if s.get("contrarian_active")]
        
        # Block reason breakdown
        block_reason_counts = {}
        for s in blocked_signals:
            reason = s.get("block_reason", "UNKNOWN")
            # Extract base reason (e.g., "LOW_RR_0.45" -> "LOW_RR")
            base_reason = reason.split("_")[0] + "_" + reason.split("_")[1] if "_" in reason else reason
            block_reason_counts[base_reason] = block_reason_counts.get(base_reason, 0) + 1
        
        # Outcome stats
        outcomes = [s.get("outcome", {}) for s in signals if s.get("outcome")]
        wins = len([o for o in outcomes if o.get("result") in ["WIN", "PARTIAL_WIN"]])
        losses = len([o for o in outcomes if o.get("result") == "LOSS"])
        expired = len([o for o in outcomes if o.get("result") == "EXPIRED"])
        
        t1_hits = len([o for o in outcomes if o.get("t1_hit")])
        t2_hits = len([o for o in outcomes if o.get("t2_hit")])
        
        total_resolved = wins + losses + expired
        
        # Averages
        mfes = [o.get("mfe", 0) for o in outcomes if o.get("mfe")]
        maes = [o.get("mae", 0) for o in outcomes if o.get("mae")]
        rrs = [s.get("targets", {}).get("rr_ratio", 0) for s in executable_signals]
        
        # Time to resolution stats
        times_to_t1 = [o.get("time_to_t1_minutes", 0) for o in outcomes if o.get("time_to_t1_minutes")]
        times_to_stop = [o.get("time_to_stop_minutes", 0) for o in outcomes if o.get("time_to_stop_minutes")]
        
        # Path distribution
        path_counts = {}
        for o in outcomes:
            path = o.get("path_type", "unknown")
            path_counts[path] = path_counts.get(path, 0) + 1
        
        # Setup type breakdown
        setup_type_counts = {}
        for s in signals:
            st = s.get("setup_type", "unknown")
            setup_type_counts[st] = setup_type_counts.get(st, 0) + 1
        
        # Direction breakdown
        longs = [s for s in executable_signals if "LONG" in s.get("direction", "")]
        shorts = [s for s in executable_signals if "SHORT" in s.get("direction", "")]
        
        # Lifecycle state breakdown
        lifecycle_counts = {}
        for s in signals:
            state = s.get("lifecycle_state", "unknown")
            lifecycle_counts[state] = lifecycle_counts.get(state, 0) + 1
        
        summary = {
            "run_id": self.run_id,
            "engine_version": self.config_snapshot.get("engine_version", "v3.5.1"),
            "config": asdict(self.config),
            "config_snapshot": self.config_snapshot,  # Full frozen config for reproducibility
            "total_candles_processed": self.processed_candles,
            
            "setups": {
                "detected": self.stats["setups_detected"],
                "expired": self.stats["setups_expired"],
                "by_type": setup_type_counts
            },
            
            "signals": {
                "total": len(signals),
                "executable": len(executable_signals),
                "blocked": len(blocked_signals),
                "contrarian": len(contrarian_signals),
                "resolved": total_resolved
            },
            
            "lifecycle_states": lifecycle_counts,
            
            "block_reasons": block_reason_counts,
            
            "outcomes": {
                "wins": wins,
                "losses": losses,
                "expired": expired,
                "pending": len(signals) - total_resolved
            },
            
            "rates": {
                "win_rate": round((wins / total_resolved * 100) if total_resolved > 0 else 0, 1),
                "t1_hit_rate": round((t1_hits / total_resolved * 100) if total_resolved > 0 else 0, 1),
                "t2_hit_rate": round((t2_hits / total_resolved * 100) if total_resolved > 0 else 0, 1),
                "expired_rate": round((expired / total_resolved * 100) if total_resolved > 0 else 0, 1),
                "block_rate": round((len(blocked_signals) / len(signals) * 100) if signals else 0, 1),
                "contrarian_rate": round((len(contrarian_signals) / len(blocked_signals) * 100) if blocked_signals else 0, 1)
            },
            
            "averages": {
                "avg_rr": round(sum(rrs) / len(rrs) if rrs else 0, 2),
                "avg_mfe": round(sum(mfes) / len(mfes) if mfes else 0, 2),
                "avg_mae": round(sum(maes) / len(maes) if maes else 0, 2),
                "avg_time_to_t1_mins": round(sum(times_to_t1) / len(times_to_t1) if times_to_t1 else 0, 1),
                "avg_time_to_stop_mins": round(sum(times_to_stop) / len(times_to_stop) if times_to_stop else 0, 1)
            },
            
            "path_distribution": path_counts,
            
            "by_direction": {
                "long": {
                    "count": len(longs),
                    "wins": len([s for s in longs if s.get("outcome", {}).get("result") in ["WIN", "PARTIAL_WIN"]]),
                    "win_rate": round(len([s for s in longs if s.get("outcome", {}).get("result") in ["WIN", "PARTIAL_WIN"]]) / len(longs) * 100 if longs else 0, 1)
                },
                "short": {
                    "count": len(shorts),
                    "wins": len([s for s in shorts if s.get("outcome", {}).get("result") in ["WIN", "PARTIAL_WIN"]]),
                    "win_rate": round(len([s for s in shorts if s.get("outcome", {}).get("result") in ["WIN", "PARTIAL_WIN"]]) / len(shorts) * 100 if shorts else 0, 1)
                }
            },
            
            "data_quality": {
                "mode": "degraded" if not self.config.use_coinglass_historical else "full",
                "note": "Historical backtest runs in degraded mode without derivatives data. Magnet/squeeze checks disabled.",
                "avg_completeness": round(
                    sum(s.get("data_quality", {}).get("completeness_score", 0) for s in signals) / len(signals) 
                    if signals else 0, 1
                ),
                "degraded_count": len([s for s in signals if s.get("data_quality", {}).get("degraded_mode")])
            },
            
            # Debug stats for confirmation analysis
            "confirmation_debug": self.confirmation_debug.get_summary() if self.config.debug_confirmation else None,
            "confirmation_mode": self.config.confirmation_mode
        }
        
        return summary


# --- Backtest API Endpoints ---

@api_router.post("/backtest/launch")
async def launch_backtest(
    symbol: str = Query(default="BTCUSD"),
    date_from: str = Query(..., description="Start date ISO format"),
    date_to: str = Query(..., description="End date ISO format"),
    v34_enabled: bool = Query(default=True),
    v35_enabled: bool = Query(default=True),
    confirmation_mode: str = Query(default="NORMAL", description="NORMAL | RELAXED | FORCE_ENTRY"),
    debug_confirmation: bool = Query(default=False, description="Enable detailed 5M debug logging"),
    disable_rr_filter: bool = Query(default=False, description="Disable R:R filter for MFE/MAE analysis"),
    stop_model: str = Query(default="ORIGINAL", description="ORIGINAL | MAE_CONSERVATIVE | MAE_BALANCED | MAE_AGGRESSIVE | CUSTOM"),
    custom_stop_pct: float = Query(default=1.0, description="Custom stop % when stop_model=CUSTOM")
):
    """
    Launch a new V3 backtest run.
    
    Confirmation Modes (for debugging only, do NOT affect production):
    - NORMAL: Exact same 5M confirmation logic as production
    - RELAXED: Loosen zone buffer (1% vs 0.2%) and stabilization (1 vs 2 candles)
    - FORCE_ENTRY: Bypass 5M confirmation entirely, test 4H setup edge
    
    Stop Models:
    - ORIGINAL: Swing-based stop (current V3 logic)
    - MAE_CONSERVATIVE: 95th percentile MAE + 0.15% buffer
    - MAE_BALANCED: 75th percentile MAE + 0.10% buffer
    - MAE_AGGRESSIVE: 50th percentile MAE + 0.05% buffer
    - CUSTOM: Fixed percentage stop (use custom_stop_pct)
    
    Analysis Modes:
    - disable_rr_filter: When True, signals are NOT blocked for low R:R
      This allows tracking actual price behavior (MFE/MAE) regardless of calculated R:R
    
    This is an async operation - returns run_id immediately.
    Use /backtest/run/{run_id} to check progress.
    """
    # Validate confirmation_mode
    valid_modes = ["NORMAL", "RELAXED", "FORCE_ENTRY"]
    if confirmation_mode not in valid_modes:
        raise HTTPException(status_code=400, detail=f"confirmation_mode must be one of {valid_modes}")
    
    # Validate stop_model
    valid_stop_models = ["ORIGINAL", "MAE_CONSERVATIVE", "MAE_BALANCED", "MAE_AGGRESSIVE", "CUSTOM"]
    if stop_model not in valid_stop_models:
        raise HTTPException(status_code=400, detail=f"stop_model must be one of {valid_stop_models}")
    
    run_id = str(uuid.uuid4())
    
    config = BacktestConfig(
        symbol=symbol,
        date_from=date_from,
        date_to=date_to,
        engine_version="v3.5.1",
        v34_validation_enabled=v34_enabled,
        v35_contrarian_enabled=v35_enabled,
        confirmation_mode=confirmation_mode,
        debug_confirmation=debug_confirmation,
        disable_rr_filter=disable_rr_filter,
        stop_model=stop_model,
        custom_stop_pct=custom_stop_pct
    )
    
    # Create run record
    run_doc = {
        "run_id": run_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "completed_at": None,
        "status": BacktestRunStatus.PENDING.value,
        "config": asdict(config),
        "progress": {
            "total_candles": 0,
            "processed_candles": 0,
            "current_timestamp": ""
        },
        "summary": None
    }
    
    await backtest_runs_collection.insert_one(run_doc)
    
    # Start backtest in background
    async def run_backtest():
        try:
            await backtest_runs_collection.update_one(
                {"run_id": run_id},
                {"$set": {"status": BacktestRunStatus.RUNNING.value}}
            )
            
            engine = V3ReplayEngine(run_id, config)
            summary = await engine.run()
            
            await backtest_runs_collection.update_one(
                {"run_id": run_id},
                {"$set": {
                    "status": BacktestRunStatus.COMPLETED.value,
                    "completed_at": datetime.now(timezone.utc).isoformat(),
                    "summary": summary
                }}
            )
        except Exception as e:
            logger.error(f"[Backtest {run_id[:8]}] Failed: {e}")
            await backtest_runs_collection.update_one(
                {"run_id": run_id},
                {"$set": {
                    "status": BacktestRunStatus.FAILED.value,
                    "error": str(e)
                }}
            )
    
    # Run in background
    asyncio.create_task(run_backtest())
    
    return {
        "run_id": run_id,
        "status": "launched",
        "confirmation_mode": confirmation_mode,
        "debug_confirmation": debug_confirmation,
        "message": f"Backtest started ({confirmation_mode} mode). Use /backtest/run/{run_id} to check progress.",
        "config": asdict(config)
    }


@api_router.get("/backtest/runs")
async def list_backtest_runs(limit: int = Query(default=20, le=100)):
    """List all backtest runs"""
    cursor = backtest_runs_collection.find({}, {"_id": 0}).sort("created_at", -1).limit(limit)
    runs = await cursor.to_list(limit)
    return {"runs": runs, "count": len(runs)}


@api_router.get("/backtest/run/{run_id}")
async def get_backtest_run(run_id: str):
    """Get backtest run details and progress"""
    run = await backtest_runs_collection.find_one({"run_id": run_id}, {"_id": 0})
    if not run:
        raise HTTPException(status_code=404, detail="Run not found")
    return run


@api_router.get("/backtest/run/{run_id}/signals")
async def get_backtest_signals(
    run_id: str,
    lifecycle: Optional[str] = Query(default=None),
    direction: Optional[str] = Query(default=None),
    limit: int = Query(default=100, le=500)
):
    """Get signals from a backtest run"""
    query = {"run_id": run_id}
    
    if lifecycle:
        query["lifecycle_state"] = lifecycle
    if direction:
        query["direction"] = {"$regex": direction, "$options": "i"}
    
    cursor = backtest_signals_collection.find(query, {"_id": 0}).sort("timestamp", -1).limit(limit)
    signals = await cursor.to_list(limit)
    
    return {
        "run_id": run_id,
        "count": len(signals),
        "signals": signals
    }


@api_router.get("/backtest/run/{run_id}/summary")
async def get_backtest_summary(run_id: str):
    """Get backtest summary with full breakdowns"""
    run = await backtest_runs_collection.find_one({"run_id": run_id}, {"_id": 0})
    if not run:
        raise HTTPException(status_code=404, detail="Run not found")
    
    if run.get("status") != BacktestRunStatus.COMPLETED.value:
        return {
            "run_id": run_id,
            "status": run.get("status"),
            "message": "Backtest not yet completed",
            "progress": run.get("progress")
        }
    
    return {
        "run_id": run_id,
        "status": "completed",
        "summary": run.get("summary")
    }


@api_router.get("/backtest/run/{run_id}/breakdowns")
async def get_backtest_breakdowns(run_id: str):
    """Get detailed performance breakdowns by condition"""
    
    cursor = backtest_signals_collection.find(
        {"run_id": run_id, "outcome": {"$ne": None}},
        {"_id": 0}
    )
    signals = await cursor.to_list(None)
    
    if not signals:
        return {"run_id": run_id, "message": "No resolved signals found"}
    
    # Build breakdowns
    breakdowns = {
        "by_setup_type": {},
        "by_direction": {"LONG": {"wins": 0, "losses": 0, "total": 0}, "SHORT": {"wins": 0, "losses": 0, "total": 0}},
        "by_path_type": {},
        "by_data_quality": {"complete": {"wins": 0, "total": 0}, "degraded": {"wins": 0, "total": 0}},
        "by_rr_range": {}
    }
    
    for signal in signals:
        outcome = signal.get("outcome", {})
        result = outcome.get("result", "")
        is_win = result in ["WIN", "PARTIAL_WIN"]
        
        # By direction
        direction = signal.get("direction", "").replace("CONTRARIAN_", "")
        if direction in breakdowns["by_direction"]:
            breakdowns["by_direction"][direction]["total"] += 1
            if is_win:
                breakdowns["by_direction"][direction]["wins"] += 1
            else:
                breakdowns["by_direction"][direction]["losses"] += 1
        
        # By setup type
        setup_type = signal.get("setup_type", "unknown")
        if setup_type not in breakdowns["by_setup_type"]:
            breakdowns["by_setup_type"][setup_type] = {"wins": 0, "losses": 0, "total": 0}
        breakdowns["by_setup_type"][setup_type]["total"] += 1
        if is_win:
            breakdowns["by_setup_type"][setup_type]["wins"] += 1
        else:
            breakdowns["by_setup_type"][setup_type]["losses"] += 1
        
        # By path type
        path_type = outcome.get("path_type", "unknown")
        if path_type not in breakdowns["by_path_type"]:
            breakdowns["by_path_type"][path_type] = {"wins": 0, "losses": 0, "total": 0, "avg_mfe": 0, "avg_mae": 0}
        breakdowns["by_path_type"][path_type]["total"] += 1
        if is_win:
            breakdowns["by_path_type"][path_type]["wins"] += 1
        else:
            breakdowns["by_path_type"][path_type]["losses"] += 1
        
        # By data quality
        dq = signal.get("data_quality", {})
        quality_key = "degraded" if dq.get("degraded_mode") else "complete"
        breakdowns["by_data_quality"][quality_key]["total"] += 1
        if is_win:
            breakdowns["by_data_quality"][quality_key]["wins"] += 1
        
        # By R:R range
        rr = signal.get("targets", {}).get("rr_ratio", 0)
        if rr < 0.5:
            rr_range = "<0.5"
        elif rr < 1.0:
            rr_range = "0.5-1.0"
        elif rr < 1.5:
            rr_range = "1.0-1.5"
        elif rr < 2.0:
            rr_range = "1.5-2.0"
        else:
            rr_range = "2.0+"
        
        if rr_range not in breakdowns["by_rr_range"]:
            breakdowns["by_rr_range"][rr_range] = {"wins": 0, "losses": 0, "total": 0}
        breakdowns["by_rr_range"][rr_range]["total"] += 1
        if is_win:
            breakdowns["by_rr_range"][rr_range]["wins"] += 1
        else:
            breakdowns["by_rr_range"][rr_range]["losses"] += 1
    
    # Calculate win rates
    for category in breakdowns.values():
        if isinstance(category, dict):
            for key, stats in category.items():
                if isinstance(stats, dict) and "total" in stats and stats["total"] > 0:
                    stats["win_rate"] = round(stats.get("wins", 0) / stats["total"] * 100, 1)
    
    return {
        "run_id": run_id,
        "total_signals_analyzed": len(signals),
        "breakdowns": breakdowns
    }


@api_router.get("/backtest/run/{run_id}/mfe-mae-analysis")
async def analyze_mfe_mae(run_id: str):
    """
    Analyze MFE (Maximum Favorable Excursion) and MAE (Maximum Adverse Excursion)
    for all signals in a backtest run.
    
    This helps understand:
    - Do signals have edge? (MFE > MAE)
    - Are targets too close? (actual MFE > calculated target distance)
    - Are stops too wide? (MAE vs stop distance)
    - What achievable R:R would be based on actual price behavior?
    """
    # Get all signals with outcomes
    cursor = backtest_signals_collection.find(
        {"run_id": run_id, "outcome": {"$ne": None}},
        {"_id": 0}
    )
    signals = await cursor.to_list(None)
    
    if not signals:
        # Check if run exists
        run = await backtest_runs_collection.find_one({"run_id": run_id})
        if not run:
            raise HTTPException(status_code=404, detail="Run not found")
        
        # Try to get signals without outcomes (for analysis mode)
        cursor = backtest_signals_collection.find({"run_id": run_id}, {"_id": 0})
        signals = await cursor.to_list(None)
        
        if not signals:
            return {
                "run_id": run_id,
                "error": "No signals found",
                "recommendation": "Run backtest with disable_rr_filter=true and confirmation_mode=FORCE_ENTRY"
            }
    
    # Collect MFE/MAE data
    mfe_values = []
    mae_values = []
    rr_calculated = []
    rr_achievable = []
    
    signal_details = []
    
    for s in signals:
        outcome = s.get("outcome", {})
        targets = s.get("targets", {})
        
        mfe = outcome.get("mfe", 0)
        mae = outcome.get("mae", 0)
        
        # Only analyze signals with tracking data
        if mfe > 0 or mae > 0:
            mfe_values.append(mfe)
            mae_values.append(mae)
            
            # Calculated R:R from targets
            calc_rr = targets.get("rr_ratio", 0)
            rr_calculated.append(calc_rr)
            
            # Achievable R:R based on actual price movement
            # Achievable = MFE / MAE (if we used actual excursions)
            if mae > 0:
                achievable = mfe / mae
            else:
                achievable = mfe if mfe > 0 else 0
            rr_achievable.append(achievable)
            
            # Target distance % vs actual MFE
            target_dist_pct = targets.get("reward_pct", 0)
            stop_dist_pct = targets.get("risk_pct", 0)
            
            signal_details.append({
                "signal_id": s.get("signal_id", "")[:8],
                "direction": s.get("direction", ""),
                "entry": targets.get("entry", 0),
                "calculated": {
                    "stop_loss_pct": round(stop_dist_pct, 3),
                    "target_pct": round(target_dist_pct, 3),
                    "rr_ratio": round(calc_rr, 2)
                },
                "actual": {
                    "mfe_pct": round(mfe, 3),
                    "mae_pct": round(mae, 3),
                    "achievable_rr": round(achievable, 2)
                },
                "analysis": {
                    "target_vs_mfe": "TARGET_TOO_CLOSE" if target_dist_pct < mfe * 0.5 else (
                        "TARGET_REASONABLE" if target_dist_pct <= mfe * 1.2 else "TARGET_TOO_FAR"
                    ),
                    "stop_vs_mae": "STOP_TOO_TIGHT" if stop_dist_pct < mae * 0.8 else (
                        "STOP_REASONABLE" if stop_dist_pct <= mae * 1.5 else "STOP_TOO_WIDE"
                    ),
                    "has_edge": mfe > mae
                },
                "result": outcome.get("result", "PENDING"),
                "t1_hit": outcome.get("t1_hit", False)
            })
    
    if not mfe_values:
        return {
            "run_id": run_id,
            "signals_count": len(signals),
            "error": "No signals with MFE/MAE data. Signals may not have been tracked post-entry.",
            "recommendation": "Ensure signals reach EXECUTABLE state and outcome tracking runs."
        }
    
    # Calculate statistics
    avg_mfe = sum(mfe_values) / len(mfe_values)
    avg_mae = sum(mae_values) / len(mae_values)
    avg_calc_rr = sum(rr_calculated) / len(rr_calculated) if rr_calculated else 0
    avg_achievable_rr = sum(rr_achievable) / len(rr_achievable) if rr_achievable else 0
    
    # Distribution buckets
    mfe_distribution = {
        "<0.25%": len([m for m in mfe_values if m < 0.25]),
        "0.25-0.5%": len([m for m in mfe_values if 0.25 <= m < 0.5]),
        "0.5-1%": len([m for m in mfe_values if 0.5 <= m < 1.0]),
        "1-2%": len([m for m in mfe_values if 1.0 <= m < 2.0]),
        "2%+": len([m for m in mfe_values if m >= 2.0])
    }
    
    mae_distribution = {
        "<0.25%": len([m for m in mae_values if m < 0.25]),
        "0.25-0.5%": len([m for m in mae_values if 0.25 <= m < 0.5]),
        "0.5-1%": len([m for m in mae_values if 0.5 <= m < 1.0]),
        "1-2%": len([m for m in mae_values if 1.0 <= m < 2.0]),
        "2%+": len([m for m in mae_values if m >= 2.0])
    }
    
    # Count signals with edge
    signals_with_edge = len([d for d in signal_details if d["analysis"]["has_edge"]])
    edge_rate = signals_with_edge / len(signal_details) * 100 if signal_details else 0
    
    # Target analysis
    target_too_close = len([d for d in signal_details if d["analysis"]["target_vs_mfe"] == "TARGET_TOO_CLOSE"])
    target_too_far = len([d for d in signal_details if d["analysis"]["target_vs_mfe"] == "TARGET_TOO_FAR"])
    
    stop_too_tight = len([d for d in signal_details if d["analysis"]["stop_vs_mae"] == "STOP_TOO_TIGHT"])
    stop_too_wide = len([d for d in signal_details if d["analysis"]["stop_vs_mae"] == "STOP_TOO_WIDE"])
    
    # Generate diagnosis
    diagnosis = []
    
    if avg_mfe < 0.3:
        diagnosis.append("LOW_MFE: Average favorable excursion < 0.3%. Setups may lack edge.")
    
    if avg_mae > avg_mfe:
        diagnosis.append("NEGATIVE_EDGE: Average MAE > MFE. Setups tend to move against before moving for.")
    
    if target_too_close > len(signal_details) * 0.5:
        diagnosis.append("TARGETS_UNDERESTIMATE_MOVE: >50% of signals could have bigger targets based on MFE.")
    
    if stop_too_wide > len(signal_details) * 0.5:
        diagnosis.append("STOPS_TOO_WIDE: >50% of signals have stops wider than actual adverse movement.")
    
    if avg_achievable_rr > avg_calc_rr * 1.5:
        diagnosis.append("MONETIZATION_ISSUE: Achievable R:R significantly higher than calculated. Improve target/stop logic.")
    
    if edge_rate > 60:
        diagnosis.append("POSITIVE_EDGE: >60% of signals show favorable movement exceeding adverse.")
    
    return {
        "run_id": run_id,
        "signals_analyzed": len(signal_details),
        
        "summary": {
            "avg_mfe_pct": round(avg_mfe, 3),
            "avg_mae_pct": round(avg_mae, 3),
            "avg_calculated_rr": round(avg_calc_rr, 2),
            "avg_achievable_rr": round(avg_achievable_rr, 2),
            "edge_rate_pct": round(edge_rate, 1),
            "signals_with_edge": signals_with_edge
        },
        
        "distributions": {
            "mfe": mfe_distribution,
            "mae": mae_distribution
        },
        
        "target_stop_analysis": {
            "targets_too_close": target_too_close,
            "targets_reasonable": len(signal_details) - target_too_close - target_too_far,
            "targets_too_far": target_too_far,
            "stops_too_tight": stop_too_tight,
            "stops_reasonable": len(signal_details) - stop_too_tight - stop_too_wide,
            "stops_too_wide": stop_too_wide
        },
        
        "diagnosis": diagnosis,
        
        "signal_details": signal_details[:20]  # First 20 for inspection
    }


@api_router.post("/backtest/edge-analysis")
async def run_edge_analysis(
    date_from: str = Query(..., description="Start date ISO format"),
    date_to: str = Query(..., description="End date ISO format")
):
    """
    Run a complete edge analysis:
    1. Generate signals with R:R filter disabled
    2. Track actual price behavior (MFE/MAE)
    3. Compare calculated targets vs actual movements
    4. Determine if V3 has edge but poor monetization, or lacks edge
    
    This is a comprehensive diagnostic run.
    """
    run_id = str(uuid.uuid4())
    
    config = BacktestConfig(
        symbol="BTCUSD",
        date_from=date_from,
        date_to=date_to,
        engine_version="v3.5.1",
        v34_validation_enabled=True,
        v35_contrarian_enabled=False,  # Disable contrarian for clean analysis
        confirmation_mode="FORCE_ENTRY",  # Bypass 5M to test 4H edge
        debug_confirmation=True,
        disable_rr_filter=True  # Allow all signals for MFE/MAE tracking
    )
    
    try:
        engine = V3ReplayEngine(run_id, config)
        summary = await engine.run()
        
        # Get MFE/MAE analysis
        cursor = backtest_signals_collection.find(
            {"run_id": run_id},
            {"_id": 0}
        )
        signals = await cursor.to_list(None)
        
        # Analyze outcomes
        mfe_values = []
        mae_values = []
        calc_rr_values = []
        
        for s in signals:
            outcome = s.get("outcome", {})
            targets = s.get("targets", {})
            
            mfe = outcome.get("mfe", 0)
            mae = outcome.get("mae", 0)
            
            if mfe > 0 or mae > 0:
                mfe_values.append(mfe)
                mae_values.append(mae)
                calc_rr_values.append(targets.get("rr_ratio", 0))
        
        # Calculate key metrics
        avg_mfe = sum(mfe_values) / len(mfe_values) if mfe_values else 0
        avg_mae = sum(mae_values) / len(mae_values) if mae_values else 0
        avg_calc_rr = sum(calc_rr_values) / len(calc_rr_values) if calc_rr_values else 0
        
        # Edge determination
        has_edge = avg_mfe > avg_mae
        achievable_rr = avg_mfe / avg_mae if avg_mae > 0 else avg_mfe
        
        # Diagnosis
        if not mfe_values:
            conclusion = "INSUFFICIENT_DATA"
            recommendation = "No signals tracked. Check if outcome tracking is running."
        elif avg_mfe < 0.2:
            conclusion = "NO_EDGE"
            recommendation = "V3 setups show minimal favorable movement. Review setup detection logic."
        elif avg_mae > avg_mfe * 1.5:
            conclusion = "NEGATIVE_EDGE"
            recommendation = "V3 setups move against more than for. Review entry timing or direction logic."
        elif achievable_rr > 1.0 and avg_calc_rr < 0.5:
            conclusion = "EDGE_EXISTS_POOR_MONETIZATION"
            recommendation = f"V3 has edge (achievable R:R {achievable_rr:.2f}) but calculated R:R is too low ({avg_calc_rr:.2f}). Fix target/stop logic."
        elif achievable_rr > 0.7:
            conclusion = "EDGE_EXISTS_MODERATE"
            recommendation = "V3 shows moderate edge. Consider tightening stops or widening targets."
        else:
            conclusion = "MARGINAL_EDGE"
            recommendation = "V3 shows marginal edge. May not be tradeable after fees/slippage."
        
        return {
            "run_id": run_id,
            "period": f"{date_from} to {date_to}",
            "signals_generated": len(signals),
            "signals_tracked": len(mfe_values),
            
            "metrics": {
                "avg_mfe_pct": round(avg_mfe, 3),
                "avg_mae_pct": round(avg_mae, 3),
                "avg_calculated_rr": round(avg_calc_rr, 2),
                "achievable_rr": round(achievable_rr, 2)
            },
            
            "conclusion": conclusion,
            "recommendation": recommendation,
            
            "details": {
                "setups_detected": summary["setups"]["detected"],
                "confirmation_debug": summary.get("confirmation_debug"),
                "block_reasons": summary.get("block_reasons", {})
            }
        }
        
    except Exception as e:
        logger.error(f"[Edge Analysis] Failed: {e}")
        return {
            "run_id": run_id,
            "status": "failed",
            "error": str(e)
        }


@api_router.post("/backtest/compare")
async def compare_backtest_modes(
    date_from: str = Query(..., description="Start date ISO format"),
    date_to: str = Query(..., description="End date ISO format")
):
    """
    Run backtests in all three modes and compare results.
    
    Returns comparison of:
    - NORMAL: Production 5M confirmation logic
    - RELAXED: Looser 5M conditions
    - FORCE_ENTRY: No 5M confirmation (pure 4H setup edge)
    
    WARNING: This is a long-running operation. Use for short periods only.
    """
    results = {}
    modes = ["NORMAL", "RELAXED", "FORCE_ENTRY"]
    
    for mode in modes:
        run_id = str(uuid.uuid4())
        
        config = BacktestConfig(
            symbol="BTCUSD",
            date_from=date_from,
            date_to=date_to,
            engine_version="v3.5.1",
            v34_validation_enabled=True,
            v35_contrarian_enabled=True,
            confirmation_mode=mode,
            debug_confirmation=True
        )
        
        try:
            engine = V3ReplayEngine(run_id, config)
            summary = await engine.run()
            
            results[mode] = {
                "run_id": run_id,
                "status": "completed",
                "setups_detected": summary["setups"]["detected"],
                "setups_expired": summary["setups"]["expired"],
                "signals_generated": summary["signals"]["total"],
                "signals_executable": summary["signals"]["executable"],
                "signals_blocked": summary["signals"]["blocked"],
                "signals_contrarian": summary["signals"]["contrarian"],
                "block_reasons": summary.get("block_reasons", {}),
                "confirmation_debug": summary.get("confirmation_debug"),
                "win_rate": summary["rates"]["win_rate"],
                "t1_hit_rate": summary["rates"]["t1_hit_rate"],
                "avg_rr": summary["averages"]["avg_rr"],
                "avg_mfe": summary["averages"]["avg_mfe"],
                "avg_mae": summary["averages"]["avg_mae"]
            }
        except Exception as e:
            results[mode] = {
                "run_id": run_id,
                "status": "failed",
                "error": str(e)
            }
    
    # Generate comparison summary
    comparison = {
        "period": f"{date_from} to {date_to}",
        "modes": results,
        "analysis": {}
    }
    
    # Calculate mode effectiveness
    if all(r.get("status") == "completed" for r in results.values()):
        normal = results["NORMAL"]
        relaxed = results["RELAXED"]
        force = results["FORCE_ENTRY"]
        
        comparison["analysis"] = {
            "trigger_filter_impact": {
                "normal_vs_force_signals": f"{normal['signals_generated']} vs {force['signals_generated']}",
                "signals_lost_to_trigger": force['signals_generated'] - normal['signals_generated'],
                "trigger_confirmation_rate": round(
                    normal['signals_generated'] / force['signals_generated'] * 100, 1
                ) if force['signals_generated'] > 0 else 0
            },
            "relaxed_vs_normal": {
                "additional_signals": relaxed['signals_generated'] - normal['signals_generated'],
                "improvement_factor": round(
                    relaxed['signals_generated'] / normal['signals_generated'], 2
                ) if normal['signals_generated'] > 0 else "N/A"
            },
            "setup_confirmation_rates": {
                "NORMAL": round(
                    (normal['setups_detected'] - normal['setups_expired']) / normal['setups_detected'] * 100, 1
                ) if normal['setups_detected'] > 0 else 0,
                "RELAXED": round(
                    (relaxed['setups_detected'] - relaxed['setups_expired']) / relaxed['setups_detected'] * 100, 1
                ) if relaxed['setups_detected'] > 0 else 0,
                "FORCE_ENTRY": 100.0  # All setups become signals
            },
            "recommendation": ""
        }
        
        # Generate recommendation
        if force['signals_generated'] == 0:
            comparison["analysis"]["recommendation"] = "No 4H setups detected. Check setup detection logic."
        elif normal['signals_generated'] == 0 and force['signals_generated'] > 0:
            comparison["analysis"]["recommendation"] = "5M trigger is too strict. Consider using RELAXED mode or reviewing zone buffer."
        elif relaxed['signals_generated'] > normal['signals_generated'] * 2:
            comparison["analysis"]["recommendation"] = "5M trigger is very strict. RELAXED mode produces significantly more signals."
        else:
            comparison["analysis"]["recommendation"] = "5M trigger is working as expected."
    
    return comparison


# ============== WEBSOCKET FOR REAL-TIME PRICE ==============

class ConnectionManager:
    def __init__(self):
        self.active_connections: List[WebSocket] = []
    
    async def connect(self, websocket: WebSocket):
        await websocket.accept()
        self.active_connections.append(websocket)
    
    def disconnect(self, websocket: WebSocket):
        self.active_connections.remove(websocket)
    
    async def broadcast(self, message: dict):
        for connection in self.active_connections:
            try:
                await connection.send_json(message)
            except Exception:
                pass

manager = ConnectionManager()


@api_router.post("/backtest/compare-stop-models")
async def compare_stop_models(
    date_from: str = Query(..., description="Start date ISO format"),
    date_to: str = Query(..., description="End date ISO format")
):
    """
    Compare different stop loss models on the same data.
    
    Models tested:
    - ORIGINAL: Current swing-based stop (baseline)
    - MAE_CONSERVATIVE: 95th percentile MAE + 0.15% buffer
    - MAE_BALANCED: 75th percentile MAE + 0.10% buffer
    - MAE_AGGRESSIVE: 50th percentile MAE + 0.05% buffer
    
    All runs use FORCE_ENTRY mode and disable_rr_filter=true
    to ensure we compare stop models on the same signals.
    """
    results = {}
    stop_models = ["ORIGINAL", "MAE_CONSERVATIVE", "MAE_BALANCED", "MAE_AGGRESSIVE"]
    
    for model in stop_models:
        run_id = str(uuid.uuid4())
        
        config = BacktestConfig(
            symbol="BTCUSD",
            date_from=date_from,
            date_to=date_to,
            engine_version="v3.5.1",
            v34_validation_enabled=True,
            v35_contrarian_enabled=False,
            confirmation_mode="FORCE_ENTRY",
            debug_confirmation=False,
            disable_rr_filter=True,
            stop_model=model
        )
        
        try:
            engine = V3ReplayEngine(run_id, config)
            summary = await engine.run()
            
            # Save signals for analysis
            await backtest_runs_collection.insert_one({
                "run_id": run_id,
                "created_at": datetime.now(timezone.utc).isoformat(),
                "status": "completed",
                "config": asdict(config),
                "summary": summary
            })
            
            # Collect detailed metrics
            cursor = backtest_signals_collection.find({"run_id": run_id}, {"_id": 0})
            signals = await cursor.to_list(None)
            
            # Calculate metrics
            wins = 0
            losses = 0
            stop_hits = 0
            t1_hits = 0
            rr_values = []
            mfe_values = []
            mae_values = []
            drawdowns = []
            
            for s in signals:
                outcome = s.get("outcome", {})
                targets = s.get("targets", {})
                
                result = outcome.get("result", "")
                if result in ["WIN", "PARTIAL_WIN"]:
                    wins += 1
                elif result == "LOSS":
                    losses += 1
                
                if outcome.get("stop_hit"):
                    stop_hits += 1
                if outcome.get("t1_hit"):
                    t1_hits += 1
                
                rr = targets.get("rr_ratio", 0)
                if rr > 0:
                    rr_values.append(rr)
                
                mfe = outcome.get("mfe", 0)
                mae = outcome.get("mae", 0)
                if mfe > 0 or mae > 0:
                    mfe_values.append(mfe)
                    mae_values.append(mae)
                    drawdowns.append(mae)
            
            total = wins + losses
            
            results[model] = {
                "run_id": run_id,
                "status": "completed",
                "signals_generated": len(signals),
                "signals_executable": summary["signals"]["executable"],
                
                "outcomes": {
                    "wins": wins,
                    "losses": losses,
                    "total": total
                },
                
                "rates": {
                    "win_rate": round(wins / total * 100, 1) if total > 0 else 0,
                    "stop_hit_rate": round(stop_hits / len(signals) * 100, 1) if signals else 0,
                    "t1_hit_rate": round(t1_hits / len(signals) * 100, 1) if signals else 0
                },
                
                "averages": {
                    "avg_rr": round(sum(rr_values) / len(rr_values), 2) if rr_values else 0,
                    "avg_mfe": round(sum(mfe_values) / len(mfe_values), 3) if mfe_values else 0,
                    "avg_mae": round(sum(mae_values) / len(mae_values), 3) if mae_values else 0,
                    "max_drawdown": round(max(drawdowns), 3) if drawdowns else 0
                },
                
                "stop_info": {
                    "model": model,
                    "preset": STOP_MODEL_PRESETS.get(model, {"percentile": "N/A", "buffer": "N/A"})
                }
            }
            
        except Exception as e:
            logger.error(f"[Stop Model Compare] {model} failed: {e}")
            results[model] = {
                "status": "failed",
                "error": str(e)
            }
    
    # Generate comparison
    comparison = {
        "period": f"{date_from} to {date_to}",
        "models": results,
        "comparison_table": []
    }
    
    # Build comparison table
    for model in stop_models:
        if results[model].get("status") == "completed":
            r = results[model]
            comparison["comparison_table"].append({
                "model": model,
                "win_rate": r["rates"]["win_rate"],
                "avg_rr": r["averages"]["avg_rr"],
                "stop_hit_rate": r["rates"]["stop_hit_rate"],
                "avg_mae": r["averages"]["avg_mae"],
                "max_drawdown": r["averages"]["max_drawdown"]
            })
    
    # Determine best model
    if comparison["comparison_table"]:
        # Score models: win_rate * avg_rr / stop_hit_rate
        best_score = 0
        best_model = None
        
        for row in comparison["comparison_table"]:
            stop_rate = max(row["stop_hit_rate"], 1)  # Avoid division by zero
            score = row["win_rate"] * row["avg_rr"] / stop_rate
            
            if score > best_score:
                best_score = score
                best_model = row["model"]
        
        comparison["recommendation"] = {
            "best_model": best_model,
            "score": round(best_score, 2),
            "reason": f"Highest risk-adjusted performance (WR * RR / StopRate)"
        }
    
    return comparison


@api_router.get("/backtest/mae-distribution")
async def get_mae_distribution():
    """
    Analyze MAE distribution from all historical backtest signals.
    
    Calculates percentiles (50th, 75th, 90th, 95th) separated by:
    - Direction (LONG/SHORT)
    - Regime (TREND/COMPRESSION/RANGE/EXPANSION)
    - Setup type
    
    This data is used to calibrate the MAE-based stop model.
    """
    # Collect all signals with MAE data from all runs
    cursor = backtest_signals_collection.find(
        {"outcome.mae": {"$gt": 0}},
        {"_id": 0, "direction": 1, "setup_type": 1, "context.regime": 1, "outcome.mae": 1}
    )
    signals = await cursor.to_list(None)
    
    if not signals:
        return {
            "error": "No signals with MAE data found",
            "recommendation": "Run backtests with disable_rr_filter=true to collect MAE data"
        }
    
    # Organize MAE values by category
    mae_by_direction = {"LONG": [], "SHORT": []}
    mae_by_regime = {}
    mae_by_setup = {}
    all_mae = []
    
    for s in signals:
        mae = s.get("outcome", {}).get("mae", 0)
        direction = s.get("direction", "UNKNOWN").replace("CONTRARIAN_", "")
        regime = s.get("context", {}).get("regime", "default")
        setup_type = s.get("setup_type", "default")
        
        all_mae.append(mae)
        
        if direction in mae_by_direction:
            mae_by_direction[direction].append(mae)
        
        if regime not in mae_by_regime:
            mae_by_regime[regime] = []
        mae_by_regime[regime].append(mae)
        
        if setup_type not in mae_by_setup:
            mae_by_setup[setup_type] = []
        mae_by_setup[setup_type].append(mae)
    
    def calc_percentiles(values: List[float]) -> Dict[str, float]:
        if not values:
            return {}
        sorted_vals = sorted(values)
        n = len(sorted_vals)
        return {
            "count": n,
            "min": round(sorted_vals[0], 4),
            "max": round(sorted_vals[-1], 4),
            "mean": round(sum(values) / n, 4),
            "p50": round(sorted_vals[int(n * 0.50)], 4),
            "p75": round(sorted_vals[int(n * 0.75)], 4),
            "p90": round(sorted_vals[min(int(n * 0.90), n-1)], 4),
            "p95": round(sorted_vals[min(int(n * 0.95), n-1)], 4)
        }
    
    result = {
        "total_signals": len(signals),
        
        "overall": calc_percentiles(all_mae),
        
        "by_direction": {
            dir_name: calc_percentiles(values) 
            for dir_name, values in mae_by_direction.items() if values
        },
        
        "by_regime": {
            regime: calc_percentiles(values)
            for regime, values in mae_by_regime.items() if values
        },
        
        "by_setup_type": {
            setup: calc_percentiles(values)
            for setup, values in mae_by_setup.items() if values
        },
        
        "recommended_stop_models": {}
    }
    
    # Generate recommended stop values based on data
    if result["overall"]:
        overall = result["overall"]
        result["recommended_stop_models"] = {
            "aggressive_p50": {
                "mae_base": overall["p50"],
                "buffer": 0.10,
                "total_stop": round(overall["p50"] + 0.10, 3),
                "expected_stop_hit_rate": "~50%",
                "description": "50th percentile MAE + 0.10% buffer"
            },
            "balanced_p75": {
                "mae_base": overall["p75"],
                "buffer": 0.15,
                "total_stop": round(overall["p75"] + 0.15, 3),
                "expected_stop_hit_rate": "~25%",
                "description": "75th percentile MAE + 0.15% buffer"
            },
            "conservative_p90": {
                "mae_base": overall["p90"],
                "buffer": 0.20,
                "total_stop": round(overall["p90"] + 0.20, 3),
                "expected_stop_hit_rate": "~10%",
                "description": "90th percentile MAE + 0.20% buffer"
            },
            "very_conservative_p95": {
                "mae_base": overall["p95"],
                "buffer": 0.20,
                "total_stop": round(overall["p95"] + 0.20, 3),
                "expected_stop_hit_rate": "~5%",
                "description": "95th percentile MAE + 0.20% buffer"
            }
        }
    
    return result


@api_router.get("/backtest/robustness-analysis")
async def get_robustness_analysis():
    """
    Comprehensive robustness analysis of backtest results.
    
    Analyzes:
    1. Performance stability across time periods
    2. Worst-case scenarios (high MAE events)
    3. Stop hit rate predictions for different stop models
    4. Regime-specific performance
    5. Direction-specific tail risk
    """
    # Get all signals with outcomes
    cursor = backtest_signals_collection.find(
        {"outcome.mae": {"$gt": 0}},
        {"_id": 0}
    )
    signals = await cursor.to_list(None)
    
    if len(signals) < 20:
        return {
            "error": f"Insufficient data ({len(signals)} signals). Need at least 20 signals.",
            "recommendation": "Run extended backtests with FORCE_ENTRY mode"
        }
    
    # Collect data
    all_mae = []
    all_mfe = []
    by_direction = {"LONG": [], "SHORT": []}
    by_month = {}
    worst_cases = []
    
    for s in signals:
        mae = s.get("outcome", {}).get("mae", 0)
        mfe = s.get("outcome", {}).get("mfe", 0)
        direction = s.get("direction", "UNKNOWN").replace("CONTRARIAN_", "")
        timestamp = s.get("timestamp", "")
        
        all_mae.append(mae)
        all_mfe.append(mfe)
        
        if direction in by_direction:
            by_direction[direction].append({"mae": mae, "mfe": mfe})
        
        # Group by month
        if timestamp:
            month = timestamp[:7]  # YYYY-MM
            if month not in by_month:
                by_month[month] = []
            by_month[month].append({"mae": mae, "mfe": mfe, "direction": direction})
        
        # Track worst cases (MAE > 2%)
        if mae > 2.0:
            worst_cases.append({
                "timestamp": timestamp,
                "direction": direction,
                "mae": round(mae, 3),
                "mfe": round(mfe, 3),
                "setup_type": s.get("setup_type", "unknown")
            })
    
    # Calculate percentiles
    sorted_mae = sorted(all_mae)
    n = len(sorted_mae)
    
    def percentile(data, p):
        idx = int(len(data) * p / 100)
        return data[min(idx, len(data)-1)]
    
    # Stop hit rate predictions
    stop_models = {
        "0.5%": 0.5,
        "1.0%": 1.0,
        "1.5%": 1.5,
        "2.0%": 2.0,
        "2.5%": 2.5,
        "3.0%": 3.0
    }
    
    stop_hit_predictions = {}
    for name, stop_pct in stop_models.items():
        hits = len([m for m in all_mae if m > stop_pct])
        stop_hit_predictions[name] = {
            "stop_pct": stop_pct,
            "predicted_hits": hits,
            "predicted_hit_rate": round(hits / n * 100, 1)
        }
    
    # Monthly performance
    monthly_stats = {}
    for month, data in sorted(by_month.items()):
        maes = [d["mae"] for d in data]
        mfes = [d["mfe"] for d in data]
        monthly_stats[month] = {
            "signals": len(data),
            "avg_mae": round(sum(maes) / len(maes), 3),
            "max_mae": round(max(maes), 3),
            "avg_mfe": round(sum(mfes) / len(mfes), 3),
            "edge_rate": round(len([d for d in data if d["mfe"] > d["mae"]]) / len(data) * 100, 1)
        }
    
    # Direction-specific analysis
    direction_stats = {}
    for dir_name, data in by_direction.items():
        if data:
            maes = [d["mae"] for d in data]
            mfes = [d["mfe"] for d in data]
            sorted_dir_mae = sorted(maes)
            direction_stats[dir_name] = {
                "count": len(data),
                "avg_mae": round(sum(maes) / len(maes), 3),
                "p75_mae": round(percentile(sorted_dir_mae, 75), 3),
                "p95_mae": round(percentile(sorted_dir_mae, 95), 3),
                "max_mae": round(max(maes), 3),
                "avg_mfe": round(sum(mfes) / len(mfes), 3),
                "edge_rate": round(len([d for d in data if d["mfe"] > d["mae"]]) / len(data) * 100, 1)
            }
    
    # Overall stability metrics
    mae_volatility = (max(all_mae) - min(all_mae)) / (sum(all_mae) / len(all_mae)) if all_mae else 0
    
    return {
        "total_signals": n,
        "data_period": f"{min(by_month.keys())} to {max(by_month.keys())}" if by_month else "unknown",
        
        "overall_stats": {
            "avg_mae": round(sum(all_mae) / n, 3),
            "p50_mae": round(percentile(sorted_mae, 50), 3),
            "p75_mae": round(percentile(sorted_mae, 75), 3),
            "p90_mae": round(percentile(sorted_mae, 90), 3),
            "p95_mae": round(percentile(sorted_mae, 95), 3),
            "max_mae": round(max(all_mae), 3),
            "mae_volatility": round(mae_volatility, 2),
            "avg_mfe": round(sum(all_mfe) / n, 3),
            "overall_edge_rate": round(len([i for i in range(n) if all_mfe[i] > all_mae[i]]) / n * 100, 1)
        },
        
        "stop_hit_predictions": stop_hit_predictions,
        
        "monthly_performance": monthly_stats,
        
        "by_direction": direction_stats,
        
        "worst_cases": {
            "count": len(worst_cases),
            "threshold": "MAE > 2%",
            "percentage": round(len(worst_cases) / n * 100, 1),
            "events": sorted(worst_cases, key=lambda x: x["mae"], reverse=True)[:10]
        },
        
        "risk_assessment": {
            "safe_stop_recommendation": f"{round(percentile(sorted_mae, 95) + 0.20, 2)}% (P95 + 0.20% buffer)",
            "moderate_stop_recommendation": f"{round(percentile(sorted_mae, 75) + 0.15, 2)}% (P75 + 0.15% buffer)",
            "tail_risk_warning": f"Max MAE observed: {round(max(all_mae), 2)}% - {len(worst_cases)} events exceeded 2%",
            "direction_warning": "LONG positions show higher tail risk" if direction_stats.get("LONG", {}).get("max_mae", 0) > direction_stats.get("SHORT", {}).get("max_mae", 0) else "SHORT positions show higher tail risk"
        }
    }


@api_router.websocket("/ws/price")
async def websocket_price(websocket: WebSocket):
    """WebSocket endpoint for real-time price updates"""
    await manager.connect(websocket)
    try:
        while True:
            ticker = await fetch_kraken_ticker()
            if ticker:
                await websocket.send_json({
                    "type": "price_update",
                    "data": {
                        "price": ticker["price"],
                        "change_24h": ticker["price_change_percent_24h"],
                        "high_24h": ticker["high_24h"],
                        "low_24h": ticker["low_24h"],
                        "volume_24h": ticker["volume_24h"],
                        "bid": ticker.get("bid", 0),
                        "ask": ticker.get("ask", 0),
                        "timestamp": datetime.now(timezone.utc).isoformat()
                    }
                })
            await asyncio.sleep(5)  # Update every 5 seconds
    except WebSocketDisconnect:
        manager.disconnect(websocket)

